fn lat_bucket(v) {
    if v <= 0 { return 0; }
    # Substrate-routed log bucketing. Was py_call(math, "log10", v)
    # before the substrate-fill-in; routing through the φ-π-fibonacci
    # substrate aligns the bucket cuts with OMC's attractor lattice.
    h logv = log_phi_pi_fibonacci(to_float(v));
    return fold(to_int(logv * 50));
}

fn neg_log_p(freq_dict, bucket, total) {
    h count = dict_get(freq_dict, concat_many("", bucket), 1);
    h p = to_float(count) / total;
    if p <= 0 { p = 1.0 / to_float(total); }
    # Substrate-routed rarity: log_phi_pi_fibonacci(1/p) is a monotonic
    # transform of -ln(p), in φ-π-fibonacci units. Ranking preserved.
    return log_phi_pi_fibonacci(1.0 / p);
}

fn harmonic_md_score(idx) {
    h tot = n_total;
    h r1 = neg_log_p(lat_freq,      lat_bucket(arr_get(all_lat, idx)),         tot);
    h r2 = neg_log_p(status_freq,   status_bucket(arr_get(all_status, idx)),   tot);
    h r3 = neg_log_p(endpoint_freq, endpoint_bucket(arr_get(all_endpoints, idx)), tot);
    h r4 = neg_log_p(hour_freq,     hour_bucket(arr_get(all_hours, idx)),       tot);
    return r1 + r2 + r3 + r4;
}

