    return end - start
}

fn compare_to_baseline(result, history) {
    if !dict_has(history, result["name"]) {
        return {status: "new", baseline: null, delta: null}
    }
    h baseline = history[result["name"]]
    h ratio = result["mean_ms"] / baseline["mean_ms"]
    h status = "ok"
    if ratio > REGRESSION_THRESHOLD { status = "regression" }
    if ratio < 0.8 { status = "improvement" }
    return {
        status: status,
        baseline: baseline["mean_ms"],
        delta: result["mean_ms"] - baseline["mean_ms"],
        ratio: ratio
    }
}

fn print_bench_row(result, comparison) {
    h status_icon = "  "
    if comparison["status"] == "regression" { status_icon = red("!") }
    elif comparison["status"] == "improvement" { status_icon = green("↑") }
    elif comparison["status"] == "new" { status_icon = cyan("*") }
    else { status_icon = green("✓") }

    h baseline_str = "-"
    if comparison["baseline"] != null {
        baseline_str = str_concat(to_string(comparison["baseline"]), "ms")
    }

    h delta_str = ""
    if comparison["delta"] != null {
        h d = comparison["delta"]
        if d > 0 { delta_str = str_concat("+", to_string(d), "ms") }
        else { delta_str = str_concat(to_string(d), "ms") }
    }

    print(str_concat(
        status_icon, " ",
        _pad_right(result["name"], 30), " ",
        _pad_left(to_string(result["mean_ms"]), 8), "ms",
        " baseline=", _pad_left(baseline_str, 10),
        " delta=", _pad_left(delta_str, 10)
    ))
}

fn extract_code(text) {
    if str_contains(text, "```") {
        h parts = str_split(text, "```")
        if arr_len(parts) >= 3 {
            h block = parts[1]
            if str_contains(block, "\n") {
                h lines = str_split(block, "\n")
                h rest = []
                h i = 1
                while i < arr_len(lines) {
                    arr_push(rest, lines[i])
                    i += 1
                }
                return str_trim(arr_join(rest, "\n"))
            }
            return str_trim(block)
        }
    }
    return str_trim(text)
}

fn get_best(scored) {
    if arr_len(scored) == 0 { return null }
    h best_score = -1
    h best_idx = 0
    h i = 0
    while i < arr_len(scored) {
        h entry = scored[i]
        h s = 0
        if dict_has(entry, "score") { s = entry["score"] }
        if s > best_score {
            best_score = s
            best_idx = i
        }
        i += 1
    }
    return {idx: best_idx, score: best_score}
}

fn best_of_n_improve(task, n_candidates, criteria, max_rounds, threshold) {
    print(str_concat("=== Task: ", task, " ==="))
    print(str_concat("N candidates: ", to_string(n_candidates), "  Max rounds: ", to_string(max_rounds)))
    print("")

    h sys = "You are an expert OMC programmer. OMC uses h for variables (h x = 5), fn for functions. Write complete runnable code. Put code in ```omc blocks."
    h best_code = ""
    h best_score = 0

    h round = 0
    while round < max_rounds {
        h prompt = str_concat("Write OMC code to: ", task)
        if best_code != "" {
            prompt = str_concat(prompt,
                "\n\nPrevious best attempt (score ", to_string(best_score), "/10):\n```omc\n",
                best_code, "\n```\nImprove it.")
        }

        print(str_concat("Round ", to_string(round + 1), ": generating ", to_string(n_candidates), " candidates..."))

        h prompts = arr_fill({prompt: prompt, system: sys}, n_candidates)
        h responses = batch_llm_call(prompts)

        h candidates = par_map(responses, fn(r) { return extract_code(r) })

        print("Judging candidates...")
        h scores = llm_judge(candidates, criteria)

        h best = get_best(scores)
        if best == null {
            print("Judge failed to score, skipping round")
            round += 1
            continue
        }

        h new_score = best["score"]
        h new_idx = best["idx"]
        h new_code = candidates[new_idx]

        print(str_concat("Best this round: score=", to_string(new_score), "/10"))
        print(str_concat("Code preview: ", str_slice(new_code, 0, 80)))

        if new_score > best_score {
            best_score = new_score
            best_code = new_code
        }

        if best_score >= threshold {
            print(str_concat("CONVERGED at score ", to_string(best_score), "/10"))
            return {code: best_code, score: best_score, rounds: round + 1}
        }

        round += 1
    }

    print(str_concat("Max rounds reached. Final score: ", to_string(best_score), "/10"))
    return {code: best_code, score: best_score, rounds: max_rounds}
}

fn strip_fences(text) {
    if str_contains(text, "```omc") {
        h a = str_split(text, "```omc")
        h b = str_split(a[1], "```")
        return str_trim(b[0])
    }
    if str_contains(text, "```") {
        h a = str_split(text, "```")
        if arr_len(a) >= 3 { return str_trim(a[1]) }
    }
    return str_trim(text)
}

fn code_score(code) {
    h lines = str_split(code, "\n")
    h n = arr_len(lines)
    h fns = 0
    h comments = 0
    h error_handling = 0
    h returns = 0
    h i = 0
    while i < n {
        h line = str_trim(lines[i])
        if str_starts_with(line, "fn ") { fns += 1}
        if str_starts_with(line, "#") { comments += 1}
        if str_contains(line, "error(") { error_handling += 1}
        if str_contains(line, "return ") { returns += 1}
        i += 1
    }
    return {
        lines: n,
        functions: fns,
        comments: comments,
        error_handling: error_handling,
        returns: returns,
        composite: fns * 10 + comments * 2 + error_handling * 5 + returns * 3
    }
}

fn describe_ancestry(lineage) {
    if arr_len(lineage) == 0 { return "progenitor" }
    h descriptions = []
    h i = 0
    while i < arr_len(lineage) {
        arr_push(descriptions, str_concat("gen", to_string(lineage[i]["generation"])))
        i += 1
    }
    h i2 = 0
    h out = ""
    while i2 < arr_len(descriptions) {
        if i2 > 0 { out = str_concat(out, " → ") }
        out = str_concat(out, descriptions[i2])
        i2 += 1
    }
    return out
}

fn evolve_lineage(seed_code, goal, depth, branches) {
    h seed_score = code_score(seed_code)
    h root = {
        code: seed_code,
        score: seed_score,
        generation: 0,
        branch: 0,
        vector: "seed",
        improvement: 0
    }

    h tree = [root]
    h current_generation = [root]

    h gen = 1
    while gen <= depth {
        print(str_concat("  Generation ", to_string(gen), "..."))
        h next_generation = []
        h pi = 0
        while pi < arr_len(current_generation) {
            h parent = current_generation[pi]
            h bi = 0
            while bi < branches {
                h child = spawn_generation(
                    parent["code"],
                    parent["score"],
                    goal,
                    gen,
                    bi
                )
                arr_push(tree, child)
                arr_push(next_generation, child)
                h delta_sign = "+"
                if child["improvement"] < 0 { delta_sign = "" }
                print(str_concat(
                    "    Branch ", to_string(bi + 1),
                    " | score: ", to_string(child["score"]["composite"]),
                    " (", delta_sign, to_string(child["improvement"]), ")",
                    " | ", child["vector"]
                ))
                bi += 1
            }
            pi += 1
        }
        # Select best from next generation for next round
        h best = next_generation[0]
        h ni = 1
        while ni < arr_len(next_generation) {
            if next_generation[ni]["score"]["composite"] > best["score"]["composite"] {
                best = next_generation[ni]
            }
            ni += 1
        }
        current_generation = [best]
        gen += 1
    }

    # Find overall best
    h best = tree[0]
    h ti = 1
    while ti < arr_len(tree) {
        if tree[ti]["score"]["composite"] > best["score"]["composite"] {
            best = tree[ti]
        }
        ti += 1
    }

    return {tree: tree, best: best, depth: depth}
}

