fn loss_and_grad(w_value, xs, ys) {
    h w = dual(w_value, 1.0);   # seed for d/dw
    h L = dual(0.0, 0.0);
    h n = arr_len(xs);
    h i = 0;
    while i < n {
        h xi = arr_get(xs, i);
        h yi = arr_get(ys, i);
        h pred = dual_mul(w, xi);
        h err = dual_sub(pred, yi);
        L = dual_add(L, dual_mul(err, err));
        i += 1;
    }
    return L;
}

