fn process_omc_file(path, enhance_with_llm) {
    h code = null
    try { code = file_read(path) } catch e {
        print(str_concat("  SKIP (not found): ", path))
        return []
    }
    if code == null { return [] }

    h sigs = extract_fn_signatures(code)
    print(str_concat("  ", path, ": ", to_string(arr_len(sigs)), " functions"))

    h tools = []
    h i = 0
    while i < arr_len(sigs) {
        h sig = sigs[i]
        # skip private helpers (starting with _)
        if str_starts_with(sig["name"], "_") {
            i += 1
            continue
        }
        h tool = signature_to_mcp_tool(sig, path)

        if enhance_with_llm and str_len(tool["description"]) < 10 {
            h context_start = (sig["line"] - 1) * 1
            h lines = str_split(code, "\n")
            h context_lines = []
            h li = sig["line"] - 1
            h max_li = li + 10
            if max_li > arr_len(lines) { max_li = arr_len(lines) }
            while li < max_li {
                arr_push(context_lines, lines[li])
                li += 1
            }
            h context = arr_join(context_lines, "\n")
            tool["description"] = enhance_tool_description(tool, context)
        }
        arr_push(tools, tool)
        i += 1
    }
    return tools
}

fn matmul_naive_omc(A, B) {
    h ar = arr_len(A);
    h ac = arr_len(arr_get(A, 0));
    h bc = arr_len(arr_get(B, 0));
    h C = arr_zeros_2d(ar, bc);
    h i = 0;
    while i < ar {
        h Ai = arr_get(A, i);
        h Ci = arr_get(C, i);
        h j = 0;
        while j < bc {
            h s = 0;
            h k = 0;
            while k < ac {
                h Bk = arr_get(B, k);
                s += arr_get(Ai, k) * arr_get(Bk, j);
                k += 1;
            }
            arr_set(Ci, j, s);
            j += 1;
        }
        i += 1;
    }
    return C;
}

fn build_matrix(n, m) {
    h M = [];
    h i = 0;
    while i < n {
        h row = [];
        h j = 0;
        while j < m {
            arr_push(row, (i + j) % 7);
            j += 1;
        }
        arr_push(M, row);
        i += 1;
    }
    return M;
}

fn softmax_naive_omc(arr) {
    h n = arr_len(arr);
    # Max
    h m = arr_get(arr, 0);
    h i = 1;
    while i < n {
        h v = arr_get(arr, i);
        if v > m { m = v; }
        i += 1;
    }
    # Exp + sum
    h ex = [];
    h s = 0.0;
    i = 0;
    while i < n {
        h e = exp(arr_get(arr, i) - m);
        arr_push(ex, e);
        s += e;
        i += 1;
    }
    # Normalize
    h out = [];
    i = 0;
    while i < n {
        arr_push(out, arr_get(ex, i) / s);
        i += 1;
    }
    return out;
}

