        ))
    )
    h hint = str_concat("\nIMPROVER GUIDANCE:\n", meta_hint)
    return str_concat(base, str_concat(instruction, hint))
}

fn generate_candidates(spec, best_src, best_score, round_num, meta_hint, n) {
    h candidates = []
    h i = 0
    while i < n {
        h prompt = build_improver_prompt(spec, best_src, best_score, round_num, meta_hint)
        h response = llm_call(prompt, MODEL)
        # Extract code block from response
        h src = extract_code_block(response)
        arr_push(candidates, src)
        i += 1
    }
    return candidates
}

fn extract_code_block(text) {
    # Pull out ```omc ... ``` or ``` ... ``` block; fall back to whole text
    h start = str_find(text, "```omc")
    if start >= 0 {
        h suffix = str_slice(text, start + 6, str_len(text))
        h rel_end = str_find(suffix, "```")
        if rel_end >= 0 {
            return str_trim(str_slice(suffix, 0, rel_end))
        }
    }
    h start2 = str_find(text, "```")
    if start2 >= 0 {
        h suffix2 = str_slice(text, start2 + 3, str_len(text))
        h rel_end2 = str_find(suffix2, "```")
        if rel_end2 >= 0 {
            return str_trim(str_slice(suffix2, 0, rel_end2))
        }
    }
    return str_trim(text)
}

fn meta_improve_hint(current_hint, score_history, best_src, spec) {
    h history_str = format_score_history(score_history)
    h prompt = str_concat(
        "You are a meta-optimizer improving an AI code improver.\n\n",
        str_concat(
            "TASK SPEC:\n", str_concat(spec, "\n\n")
        )
    )
    h context = str_concat(
        "CURRENT IMPROVER GUIDANCE:\n",
        str_concat(current_hint, "\n\n")
    )
    h scores = str_concat(
        "SCORE HISTORY (higher=better, target ~80):\n",
        str_concat(history_str, "\n\n")
    )
    h best = str_concat(
        "CURRENT BEST CODE:\n```omc\n",
        str_concat(best_src, "\n```\n\n")
    )
    h instruction = str_concat(
        "Rewrite the improver guidance to produce even better OMC code.\n",
        "Focus on:\n",
        "  - Using OMC substrate primitives (arr_get, dict_get, arr_fold)\n",
        "  - Minimising cyclomatic complexity\n",
        "  - Dense substrate vocabulary (attractor tokens)\n",
        "Return ONLY the new guidance text, no preamble.\n"
    )
    return llm_call(str_concat(prompt, str_concat(context, str_concat(scores, str_concat(best, instruction)))), MODEL)
}

fn format_score_history(history) {
    h out = ""
    h i = 0
    while i < arr_len(history) {
        h entry = history[i]
        out = str_concat(out, str_concat(
            "Round ", str_concat(to_string(entry["round"]),
            str_concat(": score=", str_concat(to_string(entry["score"]),
            str_concat("  ", str_concat(entry["metrics"], "\n")))))
        ))
        i += 1
    }
    return out
}

fn call_claude(prompt) {
    llm_call(prompt, CLAUDE_MODEL,
        "You are an expert OMC programmer. OMC uses 'h' for assignment (h x = 5), fn for functions. Return ONLY runnable OMC code, no markdown fences, no explanation.")
}

fn run_code_safe(code) {
    # Returns {ok: true, value: v} or {ok: false, error: "msg"}
    h result = null
    h err = null
    # eval_omc will throw on parse/runtime error — wrap with err-capture
    h ran = eval_omc(str_concat(
        code, "\n",
        "\"__OK__\""  # sentinel return value
    ))
    {ok: true, value: ran}
}

fn test_suite(code, tests) {
    # tests = [{input: [...], expected: v}, ...]
    # Wraps code in a runner and checks each case
    h failures = []
    for test in tests {
        h runner = str_concat(
            code, "\n",
            "h __result = ", test["call"], "\n",
            "__result"
        )
        h got = eval_omc(runner)
        if got != test["expected"] {
            failures = arr_push(failures,
                str_concat("  call: ", test["call"],
                           "  expected: ", json_stringify(test["expected"]),
                           "  got: ", json_stringify(got)))
        }
    }
    failures
}

fn improve_until_passing(problem, tests, max_iters) {
    print(str_concat("\n🎯 Problem: ", problem))
    print(str_concat("   ", json_stringify(arr_len(tests)), " test cases, up to ", json_stringify(max_iters), " iterations\n"))

    # --- iteration 0: generate initial code ---
    h prompt = str_concat(
        "Write an OMC function that solves this problem:\n\n",
        problem, "\n\n",
        "Return ONLY the function definition(s). Example format:\n",
        "fn solve(n) {\n    # implementation\n}\n"
    )
    h code = extract_code(call_claude(prompt))
    print(str_concat("📝 Generated code (", json_stringify(str_len(code)), " chars)"))

    h iter = 0
    while iter < max_iters {
        iter += 1
        print(str_concat("\n── Iteration ", json_stringify(iter), " ──"))

        h failures = test_suite(code, tests)
        if arr_len(failures) == 0 {
            print("✅ All tests passing!")
            return {success: true, code: code, iterations: iter}
        }

        print(str_concat("❌ ", json_stringify(arr_len(failures)), " failure(s):"))
        for f in failures { print(f) }

        if iter >= max_iters {
            print("⚠️  Max iterations reached.")
            return {success: false, code: code, iterations: iter, failures: failures}
        }

        # --- ask Claude to fix it ---
        h fix_prompt = str_concat(
            "This OMC code:\n\n```\n", code, "\n```\n\n",
            "Failed these tests:\n",
            str_join(failures, "\n"), "\n\n",
            "Problem: ", problem, "\n\n",
            "Rewrite the function(s) to pass all tests. Return ONLY the code."
        )
        h new_code = extract_code(call_claude(fix_prompt))
        print(str_concat("🔧 Claude revised code (", json_stringify(str_len(new_code)), " chars)"))
        code = new_code
    }

    {success: false, code: code, iterations: iter}
}

fn measure_quality(code) {
    h lines = str_split(code, "\n")
    h n = arr_len(lines)
    h fn_count = 0
    h comment_count = 0
    h i = 0
    while i < n {
        h line = str_trim(lines[i])
        if str_starts_with(line, "fn ") { fn_count += 1}
        if str_starts_with(line, "#") { comment_count += 1}
        i += 1
    }
    return {lines: n, functions: fn_count, comments: comment_count}
}

fn pick_best_variant(source, variants) {
    # Include original as baseline (index 0)
    h candidates = [source]
    h vi = 0
    while vi < arr_len(variants) {
        arr_push(candidates, variants[vi])
        vi += 1
    }

    h criteria = str_concat(
        "This is OMC source code for a self-improvement loop. ",
        "Score each version 0-10 on: (1) clarity and documentation, ",
        "(2) correct OMC syntax (h for vars, fn for functions, while for loops), ",
        "(3) completeness (all original functionality preserved), ",
        "(4) improvement quality over the original. ",
        "Penalize heavily for missing functions or broken syntax."
    )

    print(str_concat("Judging ", to_string(arr_len(candidates)), " candidates (including original)..."))
    h scores = llm_judge(candidates, criteria, MODEL)

    # Find best non-original
    h best_idx = 0
    h best_score = -1.0
    h si = 0
    while si < arr_len(scores) {
        h entry = scores[si]
        h idx = entry["idx"]
        h score = entry["score"]
        print(str_concat("  Candidate ", to_string(idx), " score: ", to_string(score)))
        if idx > 0 and score > best_score {
            best_score = score
            best_idx = idx
        }
        si += 1
    }

    h original_score = 0.0
    h oi = 0
    while oi < arr_len(scores) {
        if scores[oi]["idx"] == 0 { original_score = scores[oi]["score"] }
        oi += 1
    }

    print(str_concat("Original score: ", to_string(original_score)))
    print(str_concat("Best variant score: ", to_string(best_score), " (idx=", to_string(best_idx), ")"))

    if best_score > original_score {
        return {improved: true, code: candidates[best_idx], score: best_score, delta: best_score - original_score}
    }
    return {improved: false, code: source, score: original_score, delta: 0.0}
}

fn extract_omc_code(text) {
    # try fenced block first
    if str_contains(text, "```omc") {
        h parts = str_split(text, "```omc")
        h after = parts[1]
        h end_parts = str_split(after, "```")
        return str_trim(end_parts[0])
    }
    if str_contains(text, "```") {
        h parts = str_split(text, "```")
        if arr_len(parts) >= 3 {
            return str_trim(parts[1])
        }
    }
    return str_trim(text)
}

fn safe_eval(code) {
    h result = eval_omc(code)
    return {ok: true, value: result, error: null}
}

fn run_test(code, test_case) {
    h full_code = str_concat(
        code, "\n",
        "h __test_input = ", json_stringify(test_case["input"]), "\n",
        "h __test_result = ", test_case["call"], "(__test_input)\n",
        "__test_result"
    )
    h result = safe_eval(full_code)
    if !result["ok"] {
        return {passed: false, error: result["error"], expected: test_case["expected"], got: null}
    }
    h passed = result["value"] == test_case["expected"]
    return {passed: passed, expected: test_case["expected"], got: result["value"], error: null}
}

fn run_all_tests(code, tests) {
    h failures = []
    h i = 0
    while i < arr_len(tests) {
        h r = run_test(code, tests[i])
        if !r["passed"] {
            arr_push(failures, {
                test_idx: i,
                expected: r["expected"],
                got: r["got"],
                error: r["error"]
            })
        }
        i += 1
    }
    return failures
}

fn generate_solution(problem, tests) {
    h cached = lru_get(SOLUTION_CACHE, problem)
    if cached != null {
        print(str_concat("[cache hit] ", problem))
        return cached
    }

    h sys = str_concat(
        "You are an expert OMC (OmniMCode) programmer. Write clean, correct OMC code.\n",
        "Rules:\n",
        "- Use fn to define functions, h for variable binding\n",
        "- Use arr_push, arr_len, arr_slice for arrays\n",
        "- Use dict_has, dict_keys for dicts\n",
        "- Use str_concat, str_split, str_len, str_contains for strings\n",
        "- Use while loops (no for-in)\n",
        "- Return values explicitly with return\n",
        "- No imports needed for basic builtins\n",
        "Output ONLY the OMC code, no explanation, no markdown fences."
    )

    h prompt = str_concat("Write OMC code for this task:\n\n", problem)
    h code = llm_call(prompt, MODEL, sys)
    code = extract_omc_code(code)

    h attempt = 0
    while attempt < MAX_REPAIR_ATTEMPTS {
        h failures = run_all_tests(code, tests)
        if arr_len(failures) == 0 {
            lru_put(SOLUTION_CACHE, problem, code)
            return {code: code, attempts: attempt + 1, solved: true}
        }

        # Build failure report for Claude
        h failure_report = "Failures:\n"
        h fi = 0
        while fi < arr_len(failures) {
            h f = failures[fi]
            failure_report = str_concat(
                failure_report,
                "  Test ", to_string(f["test_idx"]), ": expected=",
                to_string(f["expected"]), " got=", to_string(f["got"])
            )
            if f["error"] != null {
                failure_report = str_concat(failure_report, " error=", to_string(f["error"]))
            }
            failure_report = str_concat(failure_report, "\n")
            fi += 1
        }

        h fix_prompt = str_concat(
            "This OMC code has test failures. Fix ALL of them.\n\n",
            "Code:\n", code, "\n\n",
            failure_report,
            "\nReturn ONLY the corrected OMC code."
        )
        h fixed = llm_call(fix_prompt, MODEL, sys)
        code = extract_omc_code(fixed)
        attempt += 1
    }

    return {code: code, attempts: MAX_REPAIR_ATTEMPTS, solved: false}
}

fn embed_cached(text) {
    h cached = lru_get(EMBED_CACHE, text)
    if cached != null { return cached }
    h v = substrate_embed(text, 16)
    lru_put(EMBED_CACHE, text, v)
    return v
}

fn cosine_sim(a, b) {
    h dot = 0.0
    h i = 0
    h min_len = arr_len(a)
    if arr_len(b) < min_len { min_len = arr_len(b) }
    while i < min_len {
        dot += a[i] * b[i]
        i += 1
    }
    return dot
}

fn docstore_new() {
    return {docs: [], embeddings: [], metadata: []}
}

fn docstore_add(store, text, meta) {
    h embedding = embed_cached(text)
    arr_push(store["docs"], text)
    arr_push(store["embeddings"], embedding)
    h m = meta
    if m == null { m = {} }
    arr_push(store["metadata"], m)
    return null;
}

fn docstore_search(store, query, top_k) {
    h query_embed = embed_cached(query)
    h scores = []
    h i = 0
    while i < arr_len(store["docs"]) {
        h csim = cosine_sim(query_embed, store["embeddings"][i])
        arr_push(scores, {idx: i, score: csim})
        i += 1
    }
    # bubble-sort descending
    h n = arr_len(scores)
    h si = 0
    while si < n {
        h sj = si + 1
        while sj < n {
            if scores[sj]["score"] > scores[si]["score"] {
                h tmp = scores[si]
                scores[si] = scores[sj]
                scores[sj] = tmp
            }
            sj += 1
        }
        si += 1
    }
    h k = top_k
    if k > n { k = n }
    h results = []
    h ri = 0
    while ri < k {
        h idx = scores[ri]["idx"]
        arr_push(results, {
            text: store["docs"][idx],
            score: scores[ri]["score"],
            metadata: store["metadata"][idx]
        })
        ri += 1
    }
    return results
}

fn rag_answer(store, question, top_k, model) {
    h m = model
    if m == null { m = MODEL }
    h retrieved = docstore_search(store, question, top_k)
    h context_parts = []
    h i = 0
    while i < arr_len(retrieved) {
        arr_push(context_parts, str_concat(
            "[Doc ", to_string(i + 1), " | sim=", to_string(retrieved[i]["score"]), "]\n",
            retrieved[i]["text"]
        ))
        i += 1
    }
    h context = arr_join(context_parts, "\n\n")
    h sys = "You are a helpful assistant. Answer questions based only on the provided context. Be concise."
    h prompt = str_concat(
        "Context:\n", context, "\n\n",
        "Question: ", question, "\n\n",
        "Answer based only on the context above."
    )
    h answer = llm_call(prompt, m, sys)
    return {answer: answer, retrieved: retrieved, question: question}
}

fn closest_doc(query, docs, texts) {
    h qv = substrate_embed(query, 16)
    h best_score = -2.0
    h best_idx = 0
    h i = 0
    while i < arr_len(docs) {
        h score = cosine_sim(qv, docs[i])
        if score > best_score {
            best_score = score
            best_idx = i
        }
        i += 1
    }
    return texts[best_idx]
}

fn calculator(op, a, b) {
    if op == "add" { return a + b }
    if op == "subtract" { return a - b }
    if op == "multiply" { return a * b }
    if op == "divide" {
        if b == 0 { return "Error: division by zero" }
        return a / b
    }
    return "Error: unknown op"
}

fn run_tool(name, input) {
    if name == "calculator" {
        h result = calculator(input["operation"], input["a"], input["b"])
        return to_string(result)
    }
    if name == "rag_search" {
        return closest_doc(input["query"], doc_vecs, knowledge)
    }
    return str_concat("Unknown tool: ", name)
}

fn tool_agent(user_question, max_turns) {
    h messages = [{role: "user", content: user_question}]
    h turn = 0
    while turn < max_turns {
        h result = llm_tools(messages, tools)
        if result["type"] == "text" {
            return result["content"]
        }
        h tool_name = result["name"]
        h tool_input = result["input"]
        h tool_result = run_tool(tool_name, tool_input)
        print(str_concat("  [tool] ", tool_name, " -> ", str_slice(tool_result, 0, 60)))
        arr_push(messages, {role: "assistant", content: str_concat("Called ", tool_name)})
        arr_push(messages, {
            role: "user",
            content: str_concat("Tool result: ", tool_result, ". Now answer the question.")
        })
        turn += 1
    }
    return "Max turns reached"
}

fn extract_choice(text, choices) {
    h i = 0
    while i < arr_len(choices) {
        if str_contains(str_upper(text), str_upper(choices[i])) {
            return choices[i]
        }
        i += 1
    }
    return choices[0]
}

fn tally_votes(votes) {
    h counts = {}
    h i = 0
    while i < arr_len(votes) {
        h v = votes[i]
        if dict_has(counts, v) {
            counts[v] = counts[v] + 1
        } else {
            counts[v] = 1
        }
        i += 1
    }
    return counts
}

fn find_winner(counts) {
    h best = ""
    h best_count = 0
    h keys = dict_keys(counts)
    h i = 0
    while i < arr_len(keys) {
        h k = keys[i]
        if counts[k] > best_count {
            best_count = counts[k]
            best = k
        }
        i += 1
    }
    return best
}

fn vote_ensemble(question, choices, n_agents, system_prompt) {
    print(str_concat("Question: ", question))
    print(str_concat("Choices: ", arr_join(choices, " | ")))
    print(str_concat("Agents: ", to_string(n_agents)))
    print("")

    h choice_str = arr_join(choices, ", ")
    h prompt = str_concat(
        question, "\n\n",
        "Reply with ONLY one of: ", choice_str,
        ". No explanation. Just the choice word."
    )
    h sys = str_concat(
        system_prompt, " ",
        "You must respond with exactly one word from: ", choice_str
    )

    h prompts = arr_fill({prompt: prompt, system: sys}, n_agents)
    h responses = batch_llm_call(prompts)

    h votes = par_map(responses, fn(r) {
        return extract_choice(r, choices)
    })

    h counts = tally_votes(votes)
    h winner = find_winner(counts)

    print("Vote results:")
    h i = 0
    while i < arr_len(choices) {
        h c = choices[i]
        h cnt = 0
        if dict_has(counts, c) { cnt = counts[c] }
        print(str_concat("  ", c, ": ", to_string(cnt), "/", to_string(n_agents)))
        i += 1
    }
    print(str_concat("Winner: ", winner))
    return {winner: winner, counts: counts, votes: votes}
}

fn make_turns(n) {
    # Synthetic conversation: each turn is a substantively-different
    # short message so canonical hashes differ.
    h topics = [
        "user asks about prometheus design",
        "claude explains substrate attention",
        "user requests benchmark numbers",
        "claude shows L0 vs L1 results",
        "user pivots to memory architecture",
        "claude proposes fibonacci tiers",
        "user accepts the proposal",
        "claude builds the prototype",
        "user runs the test suite",
        "claude analyzes the results",
        "user asks for next steps",
        "claude lists three follow-ups",
        "user picks the second one",
        "claude implements the change",
        "user reviews the diff",
        "claude addresses the feedback",
        "user merges the PR",
        "claude celebrates the win",
