# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
h PHI = 1.6180339887498948;
h PHI_INV = 0.6180339887498948;
h GOLDEN_ANGLE = 2.3999632297286533;  # 2π * φ_inv²

# Vocabulary of Fibonacci attractors. Phi-Field LLMs don't have a learned
# vocab — they emit attractor codes from this fixed φ-aligned set.
h F1 = 1;
h F2 = 2;
h F3 = 3;
h F4 = 5;
