# L0 vs L1 head-to-head in OMC — cross-runtime validation.
#
# PyTorch shows L1 (substrate-K) beats L0 (standard QKV) at every
# scale tested. Verify the same ranking holds in OMC's tape-based
# autograd.
#
# Setup:
#   - 200-char English passage (larger than the bigram-cycle but
#     small enough that pure-OMC training finishes in a few minutes)
#   - Single-block transformer (where L1's advantage is largest)
#   - 3 seeds, 300 steps each
#   - AdamW lr=0.01, d_model=16, ff=32
#
# Stop condition: L1 beats L0 on at least 2/3 seeds. If yes,
# the substrate-K finding is cross-runtime (OMC + PyTorch both
# agree). If no, OMC has some runtime-specific behavior to debug.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(variant, vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if variant == "L0" {
        attn = prom_attention_new(d_model, seq_len, s2);
        dict_set(attn, "alpha", 0.0);
        s2 = dict_get(attn, "rng_state");
    } elif variant == "L1" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);

    h m = dict_new();
    dict_set(m, "variant", variant);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(variant, attn, x_id) {
    if variant == "L0" { return prom_attention_forward(attn, x_id); }
    return prom_attention_substrate_k_forward(attn, x_id);
}

fn attn_params(variant, attn) {
    if variant == "L0" { return prom_attention_params(attn); }
    return prom_attention_substrate_k_params(attn);
}

fn forward_window(model, token_ids, pe_table) {
    h variant = dict_get(model, "variant");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);

    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i += 1;
    }
    h pe_const = tape_const(pe_rows);
    x = tape_add(x, pe_const);

    h attn_out = attn_forward(variant, dict_get(model, "attn"), x);
    h x_post_attn = tape_add(x, attn_out);
    h normed1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post_attn);
    h up = prom_linear_forward(dict_get(model, "ff_up"), normed1);
    h activated = prom_relu(up);
    h down = prom_linear_forward(dict_get(model, "ff_down"), activated);
    h x_post_ff = tape_add(x_post_attn, down);
    h normed2 = prom_layernorm_forward(dict_get(model, "ln2"), x_post_ff);
    return prom_linear_forward(dict_get(model, "head"), normed2);
}

fn collect_all_params(model) {
    h variant = dict_get(model, "variant");
    h attn_p = attn_params(variant, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train_arm(variant, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed) {
    tape_reset();
    h model = build_model(variant, vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all_params(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;

    h tail_losses = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 10 { arr_push(tail_losses, tape_value(loss)); }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) { sum += arr_get(tail_losses, i); i += 1; }
    h result = dict_new();
    dict_set(result, "loss", sum / arr_len(tail_losses));
    dict_set(result, "n_params", arr_len(params));
    return result;
}

fn main() {
    print("=== OMC L0-vs-L1 cross-runtime validation ===");
    # ~200-char English passage with real positional structure.
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver";
    print(concat_many("corpus: ", to_string(str_len(text)), " chars"));

    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 8;
    h d_model = 16;
    h ff_dim = 32;
    h lr = 0.01;
    h steps = 300;
    h seeds = [42, 7, 123, 2026, 1, 99];

    print(concat_many("vocab: ", to_string(vocab_size),
        "  seq_len: ", to_string(seq_len),
        "  d_model: ", to_string(d_model),
        "  ff: ", to_string(ff_dim)));
    print(concat_many("steps: ", to_string(steps), "  lr: ", to_string(lr)));
    print("");

    h l0_losses = [];
    h l1_losses = [];
    h l0_params = 0;
    h l1_params = 0;
    h s = 0;
    while s < arr_len(seeds) {
        h seed = arr_get(seeds, s);
        h r0 = train_arm("L0", vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        h r1 = train_arm("L1", vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        arr_push(l0_losses, dict_get(r0, "loss"));
        arr_push(l1_losses, dict_get(r1, "loss"));
        l0_params = dict_get(r0, "n_params");
        l1_params = dict_get(r1, "n_params");
        h delta = dict_get(r1, "loss") - dict_get(r0, "loss");
        h tag = "L0 better";
        if dict_get(r1, "loss") < dict_get(r0, "loss") { tag = "L1 better"; }
        print(concat_many("seed ", to_string(seed),
            "  L0=", to_string(dict_get(r0, "loss")),
            "  L1=", to_string(dict_get(r1, "loss")),
            "  delta=", to_string(delta), "  ", tag));
        s += 1;
    }
    print("");

    h l0_sum = 0.0;
    h l1_sum = 0.0;
    h wins = 0;
    h i = 0;
    while i < arr_len(seeds) {
        l0_sum += arr_get(l0_losses, i);
        l1_sum += arr_get(l1_losses, i);
        if arr_get(l1_losses, i) < arr_get(l0_losses, i) { wins += 1; }
        i += 1;
    }
    h l0_mean = l0_sum / arr_len(seeds);
    h l1_mean = l1_sum / arr_len(seeds);
    h rel = (l1_mean - l0_mean) / l0_mean * 100.0;

    print("=== Cross-runtime verdict ===");
    print(concat_many("L0 params: ", to_string(l0_params), "  L1 params: ", to_string(l1_params)));
    print(concat_many("L0 mean: ", to_string(l0_mean)));
    print(concat_many("L1 mean: ", to_string(l1_mean)));
    print(concat_many("L1 vs L0: ", to_string(rel), "%   wins: ", to_string(wins), "/", to_string(arr_len(seeds))));
    print("");
    if wins >= 2 {
        print("[CROSS-RUNTIME WIN] OMC tape produces the same L1-beats-L0 result");
        print("                    as PyTorch. The substrate-K finding holds across:");
        print("                      - OMC tape autograd");
        print("                      - PyTorch torch.autograd");
        print("                    Same architecture, same direction. Real result.");
    } else {
        print("[CROSS-RUNTIME MISMATCH] OMC didn't replicate L1's advantage.");
        print("                         Investigate OMC-specific behavior:");
        print("                           - tape arithmetic precision");
        print("                           - AdamW state representation");
        print("                           - prom_attention_substrate_k_forward correctness");
    }
}

main();

# 4-way attention A/B in Prometheus.
#
# Tests the substrate-as-attention-primitive hypothesis at four levels:
#
#   L0  standard         Q, K, V all learned matrices (with tape_transpose fix)
#   L1  substrate-K      K replaced by CRT-PE; Q, V learned
#   L2  substrate-K+Q    K and Q both CRT-PE; only V learned
#   L3  fully substrate  Q, K, V all substrate; ZERO learnable attention params
#
# Same training setup for all four:
#   - 73-char English passage
#   - 8-token windows
#   - vocab=27, d_model=16, ff=32
#   - AdamW lr=0.02, 3 seeds, 250 steps each
#
# Stop condition (multi-fact):
#   - L0 must train (loss must decrease) → proves the K-fix works
#   - Best variant is logged
#   - L3 within 20% of L0 → "substrate can replace attention at small scale"

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(variant, vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if variant == "L0" {
        attn = prom_attention_new(d_model, seq_len, s2);
        dict_set(attn, "alpha", 0.0);
        s2 = dict_get(attn, "rng_state");
    } elif variant == "L1" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    } elif variant == "L2" {
        attn = prom_attention_substrate_kq_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    } elif variant == "L3" {
        attn = prom_attention_substrate_full_new(d_model, seq_len);
        # s2 unchanged — no learnable params.
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);

    h m = dict_new();
    dict_set(m, "variant", variant);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(variant, attn, x_id) {
    if variant == "L0" { return prom_attention_forward(attn, x_id); }
    if variant == "L1" { return prom_attention_substrate_k_forward(attn, x_id); }
    if variant == "L2" { return prom_attention_substrate_kq_forward(attn, x_id); }
    if variant == "L3" { return prom_attention_substrate_full_forward(attn, x_id); }
    return x_id;
}

fn attn_params(variant, attn) {
    if variant == "L0" { return prom_attention_params(attn); }
    if variant == "L1" { return prom_attention_substrate_k_params(attn); }
    if variant == "L2" { return prom_attention_substrate_kq_params(attn); }
    if variant == "L3" { return prom_attention_substrate_full_params(attn); }
    return [];
}

fn forward_window(model, token_ids, pe_table) {
    h variant = dict_get(model, "variant");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);

    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i += 1;
    }
    h pe_const = tape_const(pe_rows);
    x = tape_add(x, pe_const);

    h attn_out = attn_forward(variant, dict_get(model, "attn"), x);
    h x_post_attn = tape_add(x, attn_out);
    h normed1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post_attn);
    h up = prom_linear_forward(dict_get(model, "ff_up"), normed1);
    h activated = prom_relu(up);
    h down = prom_linear_forward(dict_get(model, "ff_down"), activated);
    h x_post_ff = tape_add(x_post_attn, down);
    h normed2 = prom_layernorm_forward(dict_get(model, "ln2"), x_post_ff);
    return prom_linear_forward(dict_get(model, "head"), normed2);
}

fn collect_all_params(model) {
    h variant = dict_get(model, "variant");
    h attn_p = attn_params(variant, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train_arm(variant, vocab_size, ids, seq_len, d_model, ff_dim, n_windows, lr, steps, seed) {
    tape_reset();
    h model = build_model(variant, vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all_params(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);

    h tail_losses = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 10 { arr_push(tail_losses, tape_value(loss)); }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) { sum += arr_get(tail_losses, i); i += 1; }
    h mean_tail = sum / arr_len(tail_losses);
    h result = dict_new();
    dict_set(result, "loss", mean_tail);
    dict_set(result, "n_params", arr_len(params));
    return result;
}

fn main() {
    print("=== Prometheus attention 4-way A/B ===");
    h text = "the quick brown fox jumps over the lazy dog and the dog sleeps in the sun";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 8;
    h d_model = 16;
    h ff_dim = 32;
    h n_windows = arr_len(ids) - seq_len - 1;
    h lr = 0.02;
    h steps = 250;
    h seeds = [42, 7, 123];
    h variants = ["L0", "L1", "L2", "L3"];

    print(concat_many("setup: corpus=", to_string(str_len(text)),
        "  vocab=", to_string(vocab_size),
        "  seq=", to_string(seq_len),
        "  d=", to_string(d_model),
        "  ff=", to_string(ff_dim)));
    print(concat_many("  steps=", to_string(steps), "  lr=", to_string(lr),
        "  seeds=", to_string(seeds)));
    print("");

    # Collect results: results[variant] = [loss_per_seed, n_params]
    h results = dict_new();
    h vi = 0;
    while vi < arr_len(variants) {
        h v = arr_get(variants, vi);
        h losses = [];
        h n_params = 0;
        h si = 0;
        while si < arr_len(seeds) {
            h seed = arr_get(seeds, si);
            h r = train_arm(v, vocab_size, ids, seq_len, d_model, ff_dim,
                            n_windows, lr, steps, seed);
            arr_push(losses, dict_get(r, "loss"));
            n_params = dict_get(r, "n_params");
            si += 1;
        }
        h entry = dict_new();
        dict_set(entry, "losses", losses);
        dict_set(entry, "n_params", n_params);
        dict_set(results, v, entry);
        h sum = 0.0;
        h i = 0;
        while i < arr_len(losses) { sum += arr_get(losses, i); i += 1; }
        h mean = sum / arr_len(losses);
        print(concat_many("[", v, "] params=", to_string(n_params),
            "  mean loss=", to_string(mean),
            "  per-seed=", to_string(losses)));
        vi += 1;
    }

    print("");
    print("=== Summary ===");
    h baseline = dict_get(dict_get(results, "L0"), "losses");
    h base_sum = 0.0;
    h i = 0;
    while i < arr_len(baseline) { base_sum += arr_get(baseline, i); i += 1; }
    h base_mean = base_sum / arr_len(baseline);

    vi = 0;
    while vi < arr_len(variants) {
        h v = arr_get(variants, vi);
        h e = dict_get(results, v);
        h ls = dict_get(e, "losses");
        h s = 0.0;
        h wins = 0;
        h j = 0;
        while j < arr_len(ls) {
            s += arr_get(ls, j);
            if arr_get(ls, j) < arr_get(baseline, j) { wins += 1; }
            j += 1;
        }
        h mean = s / arr_len(ls);
        h rel = (mean - base_mean) / base_mean * 100.0;
        print(concat_many("  ", v, ": params=", to_string(dict_get(e, "n_params")),
            "  mean=", to_string(mean),
            "  vs L0: ", to_string(rel), "%",
            "  wins=", to_string(wins), "/", to_string(arr_len(ls))));
        vi += 1;
    }

    print("");
    print("Interpretation (with K-fix verified by test_attention_backward_flows_to_QKV):");
    print("  L0 = standard transformer attention (proper K gradient)");
    print("  L1 = substrate-K only — Q + V learned, K is CRT-PE");
    print("  L2 = substrate-K+Q — only V learned");
    print("  L3 = parameter-free attention — substrate handles QKV entirely");
    print("");
    print("If L3 is within 20% of L0: attention is over-parameterized at this scale.");
    print("If L1 wins: substrate addressing beats learned keys.");
    print("If L0 wins by a lot: learned QKV remains essential at small scale.");
}

main();

# Multi-token transformer with geodesic attention A/B.
#
# The key experiment: does the geodesic attention bias that won 3/3
# seeds in today's PyTorch experiment also help when training a
# Prometheus model from scratch on real text?
#
# Architecture (8-token sliding window):
#   tokens[8]
#     ↓ Embedding → [8, d_model]
#     ↓ + CRT-PE
#   x
#     ↓ Attention (with OR without geodesic bias on positions)
#     ↓ + residual
#     ↓ LayerNorm
#     ↓ FFN
#     ↓ + residual
#     ↓ LayerNorm
#     ↓ head → [8, vocab]
#   logits, target the next token at every position.
#
# A: alpha=0  → vanilla softmax attention (geodesic OFF)
# B: alpha=0.5 → geodesic-biased attention (geodesic ON)
#
# Stop condition: report final tail-mean loss for both arms.
# If B < A, the geodesic win replicates in Prometheus too.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(vocab_size, d_model, ff_dim, seq_len, alpha, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = prom_attention_new(d_model, seq_len, s1 + 11);
    dict_set(attn, "alpha", alpha);     # geodesic strength
    h s2 = dict_get(attn, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);

    h m = dict_new();
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    dict_set(m, "alpha", alpha);
    return m;
}

# Forward over an 8-token window. Returns [8, vocab] logits.
fn forward_window(model, token_ids, pe_table) {
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);

    # Add CRT-PE rows for these positions (0..N).
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i += 1;
    }
    h pe_const = tape_const(pe_rows);
    x = tape_add(x, pe_const);

    # Attention + residual.
    h attn_out = prom_attention_forward(dict_get(model, "attn"), x);
    h x_post_attn = tape_add(x, attn_out);

    # LayerNorm.
    h normed1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post_attn);

    # FFN.
    h up = prom_linear_forward(dict_get(model, "ff_up"), normed1);
    h activated = prom_relu(up);
    h down = prom_linear_forward(dict_get(model, "ff_down"), activated);
    h x_post_ff = tape_add(x_post_attn, down);

    # LayerNorm + head.
    h normed2 = prom_layernorm_forward(dict_get(model, "ln2"), x_post_ff);
    return prom_linear_forward(dict_get(model, "head"), normed2);
}

fn collect_all_params(model) {
    h layers = [
        dict_get(model, "emb"),
        dict_get(model, "attn"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ];
    return prom_collect_params_v2(layers);
}

fn train_arm(alpha, text, vocab, vocab_size, ids, seq_len, d_model,
             ff_dim, n_windows, lr, steps, seed) {
    tape_reset();
    h model = build_model(vocab_size, d_model, ff_dim, seq_len, alpha, seed);
    h params = collect_all_params(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);

    h tail_losses = [];
    h step = 0;
    while step < steps {
        # Pick a random-but-deterministic window start.
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 10 { arr_push(tail_losses, tape_value(loss)); }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) { sum += arr_get(tail_losses, i); i += 1; }
    return sum / arr_len(tail_losses);
}

fn main() {
    print("=== Prometheus multi-token attention: geodesic A/B ===");
    h text = "the quick brown fox jumps over the lazy dog and the dog sleeps in the sun";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 8;
    h d_model = 16;
    h ff_dim = 32;
    h n_windows = arr_len(ids) - seq_len - 1;
    h lr = 0.02;
    h steps = 250;
    h seeds = [42, 7, 123];

    print(concat_many("corpus length: ", to_string(str_len(text))));
    print(concat_many("vocab: ", to_string(vocab_size)));
    print(concat_many("seq_len: ", to_string(seq_len), "  windows: ", to_string(n_windows)));
    print(concat_many("d_model: ", to_string(d_model), "  ff: ", to_string(ff_dim)));
    print(concat_many("steps: ", to_string(steps), "  lr: ", to_string(lr), "  seeds: ", to_string(seeds)));
    print("");

    h a_results = [];
    h b_results = [];
    h s = 0;
    while s < arr_len(seeds) {
        h seed = arr_get(seeds, s);
        h loss_a = train_arm(0.0, text, vocab, vocab_size, ids, seq_len,
                             d_model, ff_dim, n_windows, lr, steps, seed);
        h loss_b = train_arm(0.5, text, vocab, vocab_size, ids, seq_len,
                             d_model, ff_dim, n_windows, lr, steps, seed);
        arr_push(a_results, loss_a);
        arr_push(b_results, loss_b);
        h delta = loss_b - loss_a;
        h tag = "(geodesic worse)";
        if loss_b < loss_a { tag = "(geodesic better)"; }
        print(concat_many("seed ", to_string(seed),
            "  vanilla=", to_string(loss_a),
            "  geodesic=", to_string(loss_b),
            "  delta=", to_string(delta), "  ", tag));
        s += 1;
    }

    h a_sum = 0.0;
    h b_sum = 0.0;
    h wins = 0;
    h i = 0;
    while i < arr_len(seeds) {
        a_sum += arr_get(a_results, i);
        b_sum += arr_get(b_results, i);
        if arr_get(b_results, i) < arr_get(a_results, i) { wins += 1; }
        i += 1;
    }
    h a_mean = a_sum / arr_len(seeds);
    h b_mean = b_sum / arr_len(seeds);
    h rel = (b_mean - a_mean) / a_mean * 100.0;

    print("");
    print("=== Multi-seed verdict ===");
    print(concat_many("  vanilla    mean: ", to_string(a_mean)));
    print(concat_many("  geodesic   mean: ", to_string(b_mean)));
    print(concat_many("  geodesic vs vanilla: ", to_string(rel), "%"));
    print(concat_many("  geodesic wins: ", to_string(wins), "/", to_string(arr_len(seeds))));
    print("");
    if wins >= 2 {
        print("[WIN] Geodesic attention helps Prometheus on majority of seeds.");
        print("      Cross-platform substrate-positional-bias validation.");
        print("      🥂");
    } elif wins == 0 {
        print("[FAIL-FORWARD] Geodesic lost 0/3 in Prometheus.");
        print("               Honest negative — the PyTorch -0.4% win at distractor=0.20");
        print("               didn't replicate at this scale (single-block model, no");
        print("               distractor mix, 250 steps). Suggests either: PyTorch result");
        print("               was scale-specific, OR our Prometheus model needs the");
        print("               same training setup (much longer steps, mix of clean+noise).");
    } else {
        print("[INCONCLUSIVE] 1/3 — noise. Need more seeds or larger model.");
    }
}

main();

# Substrate-cached inference — content-addressed activation memoization.
#
# Demonstrate that identical input+model pairs hit a cache instead of
# recomputing. Hash the (input, model) combination via fnv1a; the cache
# is just a dict keyed by that hash. Persistent caches route through
# omc-kernel (also keyed by canonical hash).
#
# This is most useful for INFERENCE workloads where identical queries
# recur — RAG retrieval, agentic loops, repeated tool-call refinements.
# Training cache misses on every step because params change.
#
# Stop condition: cache HIT on a repeated query returns identical
# output as the first uncached call; cache miss on a novel query
# computes fresh.

import "examples/lib/prometheus.omc";

fn make_corpus() {
    h chars = ["a", "b", "c"];
    h corpus = dict_new();
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "chars", chars);
    return corpus;
}

fn build_model(vocab, hidden, rng_state) {
    h L1 = prom_linear_new(vocab, hidden, rng_state);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    h h_pre = prom_linear_forward(L1, x_id);
    h h_post = prom_relu(h_pre);
    h logits = prom_linear_forward(L2, h_post);
    return logits;
}

fn predict_idx(model, char_idx, vocab) {
    h x = prom_one_hot(char_idx, vocab);
    h pred = forward(model, x);
    h logits = tape_value(pred);
    return prom_argmax_row(logits);
}

# Cached inference: check the cache first; on miss, compute + store.
# Returns {value, hit}.
fn infer_cached(cache, model, model_hash, char_idx, vocab) {
    h key = prom_cache_key(to_string(char_idx), model_hash);
    h hit = prom_cache_get(cache, key);
    h out = dict_new();
    if hit != null {
        dict_set(out, "value", hit);
        dict_set(out, "hit", true);
        dict_set(out, "key", key);
        return out;
    }
    h v = predict_idx(model, char_idx, vocab);
    prom_cache_put(cache, key, v);
    dict_set(out, "value", v);
    dict_set(out, "hit", false);
    dict_set(out, "key", key);
    return out;
}

fn main() {
    print("=== Prometheus substrate-cached inference ===");
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h chars = dict_get(corpus, "chars");

    tape_reset();
    h model = build_model(vocab, 8, 42);

    h bundle = prom_serialize_model(model, ["L1", "L2"]);
    h model_hash = prom_model_hash(bundle);
    print(concat_many("model canonical_hash: ", to_string(model_hash)));
    print("");

    h cache = prom_cache_new();

    # Phase A: first pass through all three chars — every call should miss.
    print("--- Phase A: cold cache, every query computes ---");
    h c = 0;
    while c < vocab {
        h r = infer_cached(cache, model, model_hash, c, vocab);
        print(concat_many("  ", arr_get(chars, c), " → ", arr_get(chars, dict_get(r, "value")),
                          "   hit=", to_string(dict_get(r, "hit"))));
        c += 1;
    }
    print("");

    # Phase B: same queries again — every call should hit.
    print("--- Phase B: warm cache, every query reuses ---");
    h hits_b = 0;
    c = 0;
    while c < vocab {
        h r = infer_cached(cache, model, model_hash, c, vocab);
        print(concat_many("  ", arr_get(chars, c), " → ", arr_get(chars, dict_get(r, "value")),
                          "   hit=", to_string(dict_get(r, "hit"))));
        if dict_get(r, "hit") { hits_b += 1; }
        c += 1;
    }
    print("");

    # Phase C: rebuild the SAME model from the same bundle in a fresh
    # tape; verify cache keyed by model_hash still hits (model identity
    # is the canonical hash, not the in-memory tape var IDs).
    print("--- Phase C: model rebuilt from bundle — cache survives ---");
    tape_reset();
    h model_b = prom_load_model(bundle);
    h hits_c = 0;
    c = 0;
    while c < vocab {
        h r = infer_cached(cache, model_b, model_hash, c, vocab);
        print(concat_many("  ", arr_get(chars, c), " → ", arr_get(chars, dict_get(r, "value")),
                          "   hit=", to_string(dict_get(r, "hit"))));
        if dict_get(r, "hit") { hits_c += 1; }
        c += 1;
    }
    print("");

    print(concat_many("Phase B hits: ", to_string(hits_b), "/3"));
    print(concat_many("Phase C hits: ", to_string(hits_c), "/3"));

    print("");
    if hits_b == 3 && hits_c == 3 {
        print("[OK] Substrate-cached inference works.");
        print("     Cache survives across tape_reset + model reload because");
        print("     the key is the model's canonical hash, not its in-memory ID.");
        print("     🥂 Two for two on the substrate-moat features.");
    } else {
        print("[FAIL] Cache did not behave as expected.");
        if hits_b < 3 { print(concat_many("       Phase B only got ", to_string(hits_b), "/3")); }
        if hits_c < 3 { print(concat_many("       Phase C only got ", to_string(hits_c), "/3")); }
    }
}

main();

# Prometheus checkpoint demo — content-addressed model weights.
#
# Demonstrates the substrate-moat property: a trained model's weights
# get a canonical hash that is invariant under in-memory representation.
# Two training runs that converge to the same weights → same hash.
# Two processes loading the same .omcs bundle → same hash → identical
# inference outputs.
#
# Flow:
#   1. Train tiny LM on "abc..." bigram (same as prometheus_tinylm)
#   2. Serialize trained weights via prom_serialize_model
#   3. Compute canonical hash of the bundle
#   4. Stringify to JSON; write to disk; also store in the kernel
#   5. SIMULATE A FRESH PROCESS: tape_reset(), discard model dict
#   6. Read JSON from disk, json_parse, prom_load_model
#   7. Verify predictions are IDENTICAL to step 1's trained model
#
# Stop condition: post-load predictions match pre-save predictions
# byte-for-byte; canonical hash before == canonical hash after.

import "examples/lib/prometheus.omc";

# ---------------------------------------------------------------------------
# Reuse the same model architecture + training loop as
# examples/prometheus_tinylm.omc
# ---------------------------------------------------------------------------

fn make_corpus() {
    h chars = ["a", "b", "c"];
    h text = "abcabcabcabcabcabcabcabcabc";
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        h idx = 0;
        if ch == "a" { idx = 0; }
        elif ch == "b" { idx = 1; }
        elif ch == "c" { idx = 2; }
        arr_push(ids, idx);
        i += 1;
    }
    h corpus = dict_new();
    dict_set(corpus, "chars", chars);
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "ids", ids);
    return corpus;
}

fn build_model(vocab, hidden, rng_state) {
    h L1 = prom_linear_new(vocab, hidden, rng_state);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    h h_pre = prom_linear_forward(L1, x_id);
    h h_post = prom_relu(h_pre);
    h logits = prom_linear_forward(L2, h_post);
    return logits;
}

fn predict_all(model, vocab, chars) {
    h preds = [];
    h c = 0;
    while c < vocab {
        h x = prom_one_hot(c, vocab);
        h pred_id = forward(model, x);
        h logits = tape_value(pred_id);
        h idx = prom_argmax_row(logits);
        arr_push(preds, arr_get(chars, idx));
        c += 1;
    }
    return preds;
}

fn train_model(model, corpus, steps, lr) {
    h ids = dict_get(corpus, "ids");
    h vocab = dict_get(corpus, "vocab");
    h n_pairs = arr_len(ids) - 1;
    h params = prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);
    h step = 0;
    while step < steps {
        h k = step % n_pairs;
        h x = prom_one_hot(arr_get(ids, k), vocab);
        h target = prom_one_hot(arr_get(ids, k + 1), vocab);
        h pred = forward(model, x);
        h loss = prom_mse_loss(pred, target);
        tape_backward(loss);
        prom_sgd_step(params, lr);
        step += 1;
    }
}

# ---------------------------------------------------------------------------
# Main: train → save → wipe → load → verify
# ---------------------------------------------------------------------------

fn main() {
    print("=== Prometheus checkpoint round-trip ===");
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h chars = dict_get(corpus, "chars");

    # ---- Phase 1: train ----
    print("\n[phase 1] training fresh model ...");
    tape_reset();
    h model_a = build_model(vocab, 8, 42);
    train_model(model_a, corpus, 200, 0.05);
    h preds_a = predict_all(model_a, vocab, chars);
    print(concat_many("  predictions: ", to_string(preds_a)));

    # ---- Phase 2: serialize + hash ----
    print("\n[phase 2] serializing + hashing ...");
    h bundle_a = prom_serialize_model(model_a, ["L1", "L2"]);
    h hash_a = prom_model_hash(bundle_a);
    print(concat_many("  canonical_hash = ", to_string(hash_a)));
    h json_a = json_stringify(bundle_a);
    print(concat_many("  serialized bytes = ", to_string(str_len(json_a))));

    # ---- Phase 3: write to disk ----
    h ckpt_path = "/tmp/prometheus_tinylm.json";
    write_file(ckpt_path, json_a);
    print(concat_many("  wrote ", ckpt_path));

    # ---- Phase 4: SIMULATE FRESH PROCESS ----
    # Reset the tape (drops every node from phase 1) and discard the
    # model reference. From the language's perspective we're now in
    # a fresh state — model_a is gone, only the JSON on disk remains.
    print("\n[phase 4] simulating fresh process — tape_reset() ...");
    tape_reset();
    # model_a's tape vars are now invalid. Confirm we can't use them:
    h confirm_wiped = false;
    try {
        h _ = tape_value(dict_get(dict_get(model_a, "L1"), "W"));
    } catch e {
        confirm_wiped = true;
    }
    print(concat_many("  pre-load tape access raises error: ", to_string(confirm_wiped)));

    # ---- Phase 5: load from disk ----
    print("\n[phase 5] reading + loading ...");
    h json_b = read_file(ckpt_path);
    h bundle_b = json_parse(json_b);
    h model_b = prom_load_model(bundle_b);
    h preds_b = predict_all(model_b, vocab, chars);
    print(concat_many("  predictions: ", to_string(preds_b)));

    # ---- Phase 6: verify hash + predictions match ----
    print("\n[phase 6] verifying ...");
    h hash_b = prom_model_hash(bundle_b);
    print(concat_many("  hash before save: ", to_string(hash_a)));
    print(concat_many("  hash after load:  ", to_string(hash_b)));
    h hash_match = hash_a == hash_b;
    print(concat_many("  hash match: ", to_string(hash_match)));

    h preds_match = true;
    h i = 0;
    while i < arr_len(preds_a) {
        if arr_get(preds_a, i) != arr_get(preds_b, i) {
            preds_match = false;
        }
        i += 1;
    }
    print(concat_many("  predictions match: ", to_string(preds_match)));

    # ---- Verdict ----
    print("");
    if hash_match && preds_match {
        print("[OK] Content-addressed checkpoint round-trip verified.");
        print("     Same canonical hash + bit-identical predictions");
        print("     across a simulated process boundary.");
    } else {
        print("[FAIL] Round-trip broken.");
        if !hash_match { print("       Hash mismatch."); }
        if !preds_match { print("       Predictions differ."); }
    }
}

main();

# Prometheus text generation — autoregressive greedy decoding.
#
# Train the tinyLM on the abc cycle, then GENERATE a string of length
# N starting from a seed character. The trained model should produce
# the expected cyclic continuation "abcabcabc..." because that's the
# only bigram pattern in the training data.
#
# Stop condition: generated output of length 20 must contain the
# expected cyclic pattern.

import "examples/lib/prometheus.omc";

fn make_corpus() {
    h chars = ["a", "b", "c"];
    h text = "abcabcabcabcabcabcabcabcabc";
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        h idx = 0;
        if ch == "a" { idx = 0; }
        elif ch == "b" { idx = 1; }
        elif ch == "c" { idx = 2; }
        arr_push(ids, idx);
        i += 1;
    }
    h corpus = dict_new();
    dict_set(corpus, "chars", chars);
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "ids", ids);
    return corpus;
}

fn build_model(vocab, hidden, seed) {
    h L1 = prom_linear_new(vocab, hidden, seed);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    return prom_linear_forward(L2, prom_relu(prom_linear_forward(L1, x_id)));
}

fn main() {
    print("=== Prometheus text generation ===");
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h chars = dict_get(corpus, "chars");
    h ids = dict_get(corpus, "ids");

    # Train.
    tape_reset();
    h model = build_model(vocab, 8, 42);
    h params = prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);
    h n_pairs = arr_len(ids) - 1;
    h step = 0;
    while step < 200 {
        h k = step % n_pairs;
        h x = prom_one_hot(arr_get(ids, k), vocab);
        h target = prom_one_hot(arr_get(ids, k + 1), vocab);
        h pred = forward(model, x);
        h loss = prom_mse_loss(pred, target);
        tape_backward(loss);
        prom_sgd_step(params, 0.05);
        step += 1;
    }
    print("[trained]");

    # Generate from each seed.
    h seed = 0;
    h all_correct = true;
    while seed < vocab {
        h generated = prom_generate_greedy(forward, model, seed, 19, vocab);
        h text = prom_decode_indices(generated, chars);
        # Expected: "abcabcabcabcabcabcab" starting at seed.
        # Build expected for this seed.
        h expected = "";
        h k = 0;
        while k < 20 {
            h idx = (seed + k) % 3;
            expected = concat_many(expected, arr_get(chars, idx));
            k += 1;
        }
        h ok = text == expected;
        if !ok { all_correct = false; }
        h tag = "x";
        if ok { tag = "ok"; }
        print(concat_many("  seed=", arr_get(chars, seed),
                          "  generated=\"", text, "\"  expected=\"", expected, "\" ", tag));
        seed += 1;
    }

    print("");
    if all_correct {
        print("[OK] Prometheus generates the trained cyclic pattern from every seed.");
        print("     The model didn't just learn one-step prediction — autoregressive");
        print("     decoding produces coherent multi-token output.");
    } else {
        print("[PARTIAL] Some seeds produced wrong output. Either training did not");
        print("          converge fully or the decoding has a bug.");
    }
}

main();

# Prometheus geodesic bias — verify the fused primitive matches the
# PyTorch impl that won 3/3 seeds today (train_geodesic_attention.py).
#
# Stop condition: prom_geodesic_bias_matrix(16) has the same shape +
# structure as the PyTorch geodesic_distance_table(16) (diagonal 0,
# symmetric, mean-off-diag normalized to ~1.0).

import "examples/lib/prometheus.omc";

fn main() {
    print("=== Prometheus geodesic bias (fused primitive) ===");
    h seq_len = 16;
    h bias = prom_geodesic_bias_matrix(seq_len);

    print(concat_many("shape: ", to_string(seq_len), " x ", to_string(seq_len)));
    print("");
    print("diagonal (should all be 0):");
    h diag = [];
    h i = 0;
    while i < 5 {
        arr_push(diag, arr_get(arr_get(bias, i), i));
        i += 1;
    }
    print(concat_many("  ", to_string(diag)));

    print("");
    print("row 0 (first 8):");
    h r0 = arr_get(bias, 0);
    h trim0 = [];
    i = 0;
    while i < 8 { arr_push(trim0, arr_get(r0, i)); i += 1; }
    print(concat_many("  ", to_string(trim0)));

    print("");
    print("row 5 (first 8 — should be symmetric around position 5):");
    h r5 = arr_get(bias, 5);
    h trim5 = [];
    i = 0;
    while i < 8 { arr_push(trim5, arr_get(r5, i)); i += 1; }
    print(concat_many("  ", to_string(trim5)));

    # Mean off-diagonal should be ~1.0 (normalization target).
    h sum = 0.0;
    h count = 0;
    i = 0;
    while i < seq_len {
        h j = 0;
        while j < seq_len {
            if i != j {
                sum += arr_get(arr_get(bias, i), j);
                count += 1;
            }
            j += 1;
        }
        i += 1;
    }
    h mean = sum / count;
    print("");
    print(concat_many("mean off-diagonal: ", to_string(mean), " (target ~1.0)"));

    # Symmetry check: bias[i,j] == bias[j,i]
    h sym_ok = true;
    i = 0;
    while i < seq_len {
        h j = 0;
        while j < seq_len {
            h a = arr_get(arr_get(bias, i), j);
            h b = arr_get(arr_get(bias, j), i);
            h diff = a - b;
            if diff < 0.0 { diff = 0.0 - diff; }
            if diff > 0.00001 { sym_ok = false; }
            j += 1;
        }
        i += 1;
    }
    print(concat_many("symmetric: ", to_string(sym_ok)));

    # Diagonal-zero check.
    h diag_ok = true;
    i = 0;
    while i < seq_len {
        h d = arr_get(arr_get(bias, i), i);
        if d != 0.0 { diag_ok = false; }
        i += 1;
    }
    print(concat_many("diagonal all zero: ", to_string(diag_ok)));

    print("");
    if sym_ok && diag_ok && mean > 0.95 && mean < 1.05 {
        print("[OK] Geodesic bias primitive matches PyTorch impl structure.");
        print("     Ready for use as one-call positional bias in any Prometheus");
        print("     model with attention. Today's 3/3-seed win is now native OMC.");
    } else {
        print("[FAIL] Structure check did not pass.");
    }
}

main();

# v0.8.11 reformulations of the v0.8.10 substrate-aware backward
# falsification. Same hypothesis (substrate as gradient-flow
# regularizer), three different applications:
#
#   R1 decay-alpha: alpha=0.5 → 0.0 linearly over training (warm start)
#   R2 FF-only:     apply substrate gm to FF up/down weights, not Q/V
#   R4 scale=1024:  gentler bias (finer attractor grid → less coarse pull)
#
# Plus baseline + v0.8.10 reference. 3 seeds, 250 steps, d_model=32.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) { dict_set(seen, ch, arr_len(chars)); arr_push(chars, ch); }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

# attn forward with substrate grad mod on Q and V
fn attn_forward_gm_qv(layer, x_id, gm_scale, gm_alpha) {
    h Q_w = dict_get(layer, "Q");
    h V_w = dict_get(layer, "V");
    h K_const = dict_get(layer, "K_const");
    h smod_alpha = dict_get(layer, "smod_alpha");
    h v_scale = dict_get(layer, "v_resample_scale");
    if v_scale == null { v_scale = 0.0; }
    h Q_mod = tape_substrate_grad_mod(Q_w, gm_scale, gm_alpha);
    h V_mod = tape_substrate_grad_mod(V_w, gm_scale, gm_alpha);
    h q = tape_matmul(x_id, Q_mod);
    h v_raw = tape_matmul(x_id, V_mod);
    h v = prom_substrate_resample(v_raw, v_scale);
    h k = tape_const(K_const);
    h kt = tape_transpose(k);
    h scores = tape_matmul(q, kt);
    h attn = prom_substrate_softmax(scores, smod_alpha);
    return tape_matmul(attn, v);
}

# linear forward with substrate grad mod on W
fn linear_forward_gm(layer, x_id, gm_scale, gm_alpha) {
    h W = dict_get(layer, "W");
    h b = dict_get(layer, "b");
    h W_mod = tape_substrate_grad_mod(W, gm_scale, gm_alpha);
    h xW = tape_matmul(x_id, W_mod);
    return tape_add(xW, b);
}

fn build_model(arm, vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = prom_attention_substrate_k_new(d_model, seq_len, s1 + 11);
    h s2 = dict_get(attn, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "arm", arm);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn forward_window(model, token_ids, pe_table, alpha_now, scale_now) {
    h arm = dict_get(model, "arm");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) { arr_push(pe_rows, arr_get(pe_table, i)); i += 1; }
    x = tape_add(x, tape_const(pe_rows));

    h attn_out = null;
    if arm == "baseline" {
        attn_out = prom_attention_substrate_k_forward(dict_get(model, "attn"), x);
    } elif arm == "v0810ref" {
        attn_out = attn_forward_gm_qv(dict_get(model, "attn"), x, 64.0, 0.5);
    } elif arm == "R1_decay" {
        attn_out = attn_forward_gm_qv(dict_get(model, "attn"), x, 64.0, alpha_now);
    } elif arm == "R2_ff_only" {
        attn_out = prom_attention_substrate_k_forward(dict_get(model, "attn"), x);
    } elif arm == "R4_scale1024" {
        attn_out = attn_forward_gm_qv(dict_get(model, "attn"), x, 1024.0, 0.5);
    }

    h x_post = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post);

    h up = null;
    h down = null;
    if arm == "R2_ff_only" {
        # Apply substrate gm to FF up/down weights only.
        up = linear_forward_gm(dict_get(model, "ff_up"), n1, 64.0, 0.5);
        down = linear_forward_gm(dict_get(model, "ff_down"), prom_relu(up), 64.0, 0.5);
    } else {
        up = prom_linear_forward(dict_get(model, "ff_up"), n1);
        down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    }
    h x_ff = tape_add(x_post, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h attn_p = prom_attention_substrate_k_params(dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train(arm, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed) {
    tape_reset();
    h model = build_model(arm, vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail = [];
    h step = 0;
    while step < steps {
        # alpha schedule for R1: linear decay 0.5 → 0.0
        h frac = step * 1.0 / steps;
        h alpha_now = 0.5 * (1.0 - frac);
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table, alpha_now, 64.0);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 30 { arr_push(tail, tape_value(loss)); }
        step += 1;
    }
    h s = 0.0; h i = 0;
    while i < arr_len(tail) { s += arr_get(tail, i); i += 1; }
    return s / arr_len(tail);
}

fn mean_arr(xs) {
    h s = 0.0; h i = 0;
    while i < arr_len(xs) { s += arr_get(xs, i); i += 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== v0.8.11 substrate-grad-mod reformulations ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h lr = 0.005;
    h steps = 250;
    h seeds = [42, 7, 123];

    print(concat_many("d_model=", to_string(d_model),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("");

    h arms = ["baseline", "v0810ref", "R1_decay", "R2_ff_only", "R4_scale1024"];
    h labels = dict_new();
    dict_set(labels, "baseline",     "baseline (no gm)        ");
    dict_set(labels, "v0810ref",     "v0810 ref (gm Q/V α=0.5) ");
    dict_set(labels, "R1_decay",     "R1 decay α 0.5→0        ");
    dict_set(labels, "R2_ff_only",   "R2 FF only              ");
    dict_set(labels, "R4_scale1024", "R4 scale=1024 (finer)   ");

    h results = dict_new();
    h ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h losses = [];
        h si = 0;
        while si < arr_len(seeds) {
            h seed = arr_get(seeds, si);
            h L = train(arm, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
            arr_push(losses, L);
            si += 1;
        }
        dict_set(results, arm, losses);
        h mu = mean_arr(losses);
        print(concat_many(dict_get(labels, arm), " mean=", to_string(mu)));
        ai += 1;
    }

    print("");
    print("=== headline ===");
    h base_mu = mean_arr(dict_get(results, "baseline"));
    ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h mu = mean_arr(dict_get(results, arm));
        h delta = mu - base_mu;
        h pct = (delta / base_mu) * 100.0;
        h wins = 0;
        h si = 0;
        while si < arr_len(seeds) {
            if arr_get(dict_get(results, arm), si) < arr_get(dict_get(results, "baseline"), si) {
                wins += 1;
            }
            si += 1;
        }
        print(concat_many(dict_get(labels, arm),
            " mean=", to_string(mu),
            "  Δ=", to_string(delta),
            "  (", to_string(pct), "%)",
            "  wins ", to_string(wins), "/", to_string(arr_len(seeds))));
        ai += 1;
    }
}

main();

# Harmonic SGD A/B — substrate-modulated gradient steps vs vanilla SGD.
#
# Hypothesis: gradients whose magnitude lands near a Fibonacci attractor
# represent substrate-coherent direction; amplifying their step (and
# damping off-attractor ones) speeds convergence and/or improves final
# loss. The architectural rule from today (substrate metric on
# integer-aggregated quantities) is honored: we hash + quantize the
# gradient magnitude to an integer before applying attractor_distance,
# we don't apply substrate to raw float activations.
#
# Setup: train the same tiny LM (bigram next-char prediction on
# "abcabc...") 3 times with different RNG seeds. Each seed runs
# both vanilla SGD and harmonic SGD; compare final loss.
#
# Stop condition: either harmonic wins on majority of seeds (≥2/3 lower
# final loss → log + celebrate), OR it loses cleanly (≥2/3 higher loss
# → fail-forward writeup explaining what we learned).

import "examples/lib/prometheus.omc";

fn make_corpus() {
    h chars = ["a", "b", "c"];
    h text = "abcabcabcabcabcabcabcabcabc";
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        h idx = 0;
        if ch == "a" { idx = 0; }
        elif ch == "b" { idx = 1; }
        elif ch == "c" { idx = 2; }
        arr_push(ids, idx);
        i += 1;
    }
    h corpus = dict_new();
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "ids", ids);
    return corpus;
}

fn build_model(vocab, hidden, rng_state) {
    h L1 = prom_linear_new(vocab, hidden, rng_state);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    h h_pre = prom_linear_forward(L1, x_id);
    h h_post = prom_relu(h_pre);
    h logits = prom_linear_forward(L2, h_post);
    return logits;
}

# Returns final-loss-average over last 20 steps (smoother signal than
# the noisy single-step final value).
fn train_run(seed, optimizer_kind, alpha) {
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h ids = dict_get(corpus, "ids");
    h n_pairs = arr_len(ids) - 1;

    tape_reset();
    h model = build_model(vocab, 8, seed);
    h params = prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);

    h lr = 0.05;
    h steps = 200;
    h tail_losses = [];
    h step = 0;
    while step < steps {
        h k = step % n_pairs;
        h x = prom_one_hot(arr_get(ids, k), vocab);
        h target = prom_one_hot(arr_get(ids, k + 1), vocab);
        h pred = forward(model, x);
        h loss = prom_mse_loss(pred, target);
        tape_backward(loss);
        if optimizer_kind == "harmonic" {
            prom_harmonic_sgd_step(params, lr, alpha);
        } else {
            prom_sgd_step(params, lr);
        }
        if step >= steps - 20 {
            arr_push(tail_losses, tape_value(loss));
        }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) {
        sum += arr_get(tail_losses, i);
        i += 1;
    }
    return sum / arr_len(tail_losses);
}

fn main() {
    print("=== Harmonic SGD vs Vanilla SGD ===");
    print("3 seeds × 2 optimizers, tinyLM bigram task, 200 steps each");
    print("");

    h seeds = [42, 7, 123];
    h alpha = 0.3;   # harmonic strength: ±30% lr modulation per param

    print(concat_many("harmonic alpha: ", to_string(alpha)));
    print("");

    h vanilla_results = [];
    h harmonic_results = [];
    h s = 0;
    while s < arr_len(seeds) {
        h seed = arr_get(seeds, s);
        h v = train_run(seed, "vanilla", 0.0);
        h hv = train_run(seed, "harmonic", alpha);
        arr_push(vanilla_results, v);
        arr_push(harmonic_results, hv);
        h delta = hv - v;
        h marker = "(harmonic worse)";
        if hv < v { marker = "(harmonic better)"; }
        print(concat_many("seed ", to_string(seed),
            "  vanilla=", to_string(v),
            "  harmonic=", to_string(hv),
            "  delta=", to_string(delta), "  ", marker));
        s += 1;
    }
    print("");

    # Tally.
    h v_mean = 0.0;
    h h_mean = 0.0;
    h wins = 0;
    h i = 0;
    while i < arr_len(seeds) {
        v_mean += arr_get(vanilla_results, i);
        h_mean += arr_get(harmonic_results, i);
        if arr_get(harmonic_results, i) < arr_get(vanilla_results, i) {
            wins += 1;
        }
        i += 1;
    }
    v_mean /= arr_len(seeds);
    h_mean /= arr_len(seeds);
    print(concat_many("vanilla   mean: ", to_string(v_mean)));
    print(concat_many("harmonic  mean: ", to_string(h_mean)));
    h rel = (h_mean - v_mean) / v_mean * 100.0;
    print(concat_many("harmonic vs vanilla: ", to_string(rel), "%"));
    print(concat_many("harmonic wins: ", to_string(wins), "/", to_string(arr_len(seeds))));

    print("");
    if wins >= 2 {
        print("[WIN] Harmonic SGD beats vanilla on majority of seeds.");
        print("      Substrate-modulated gradients earn their keep on this task.");
        print("      🥂 Champagne uncorked.");
    } elif wins == 0 {
        print("[FAIL-FORWARD] Harmonic loses 0/3.");
        print("               What we learned: substrate modulation of per-param");
        print("               lr based on grad-magnitude→attractor distance does");
        print("               not help on the tinyLM bigram task. Possible reasons:");
        print("                 - signal-to-noise too low at this model scale");
        print("                 - grad magnitudes don't naturally land near attractors");
        print("                 - alpha may need different sign or magnitude");
        print("               Next attempt: alpha sweep, or per-layer modulation.");
    } else {
        print("[INCONCLUSIVE] 1/3 wins — within noise.");
        print("               Need more seeds or larger model to call.");
    }
}

main();

# MH + Q6 compound test (#3 — validates v0.8.8 finding in multi-head setting).
#
# v0.8.5 saw MH at d_model=32 win -0.25% vs SH (single-head). v0.8.8 saw
# Q6 push attention 8.31x toward substrate positions after training. If
# Q6 sculpts attention per-head, the MH+Q6 combo should beat plain MH by
# more than the SH+Q6 combo beat plain SH.
#
# Four arms at d_model=64, n_heads=4, 3 seeds, 400 steps:
#   A. MH off  (substrate-K + S-MOD + V, Q6 off)
#   B. MH+Q6 fused (same + Q6 fused)
#   C. SH off  (single-head, Q6 off) — reference
#   D. SH+Q6 fused — reference

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) { dict_set(seen, ch, arr_len(chars)); arr_push(chars, ch); }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if arm == "SH" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    } elif arm == "SHQ6" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        dict_set(attn, "q6_mode", "fused");
        s2 = dict_get(attn, "rng_state");
    } elif arm == "MH" {
        attn = prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, s2);
        s2 = dict_get(attn, "rng_state");
    } else {  # MHQ6
        attn = prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, s2);
        dict_set(attn, "q6_mode", "fused");
        s2 = dict_get(attn, "rng_state");
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "arm", arm);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(arm, attn, x_id) {
    if arm == "MH" { return prom_attention_substrate_k_mh_forward(attn, x_id); }
    if arm == "MHQ6" { return prom_attention_substrate_k_mh_forward(attn, x_id); }
    return prom_attention_substrate_k_forward(attn, x_id);
}

fn attn_params(arm, attn) {
    if arm == "MH" { return prom_attention_substrate_k_mh_params(attn); }
    if arm == "MHQ6" { return prom_attention_substrate_k_mh_params(attn); }
    return prom_attention_substrate_k_params(attn);
}

fn forward_window(model, token_ids, pe_table) {
    h arm = dict_get(model, "arm");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) { arr_push(pe_rows, arr_get(pe_table, i)); i += 1; }
    x = tape_add(x, tape_const(pe_rows));
    h attn_out = attn_forward(arm, dict_get(model, "attn"), x);
    h x_post = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post);
    h up = prom_linear_forward(dict_get(model, "ff_up"), n1);
    h down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    h x_ff = tape_add(x_post, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h arm = dict_get(model, "arm");
    h attn_p = attn_params(arm, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train(arm, vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed) {
    tape_reset();
    h model = build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 30 { arr_push(tail, tape_value(loss)); }
        step += 1;
    }
    h s = 0.0; h i = 0;
    while i < arr_len(tail) { s += arr_get(tail, i); i += 1; }
    return s / arr_len(tail);
}

fn mean_arr(xs) {
    h s = 0.0; h i = 0;
    while i < arr_len(xs) { s += arr_get(xs, i); i += 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== MH+Q6 compound test (#3) ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver beneath the stars";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h n_heads = 4;
    h lr = 0.005;
    h steps = 250;
    h seeds = [42, 7, 123];

    print(concat_many("d_model=", to_string(d_model),
        "  n_heads=", to_string(n_heads),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("");

    h arms = ["SH", "SHQ6", "MH", "MHQ6"];
    h labels = dict_new();
    dict_set(labels, "SH",   "SH         ");
    dict_set(labels, "SHQ6", "SH + Q6    ");
    dict_set(labels, "MH",   "MH (4h)    ");
    dict_set(labels, "MHQ6", "MH (4h) + Q6");

    h results = dict_new();
    h ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h losses = [];
        h si = 0;
        while si < arr_len(seeds) {
            h seed = arr_get(seeds, si);
            h L = train(arm, vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed);
            arr_push(losses, L);
            si += 1;
        }
        dict_set(results, arm, losses);
        h mu = mean_arr(losses);
        print(concat_many(dict_get(labels, arm), "  mean=", to_string(mu)));
        ai += 1;
    }

    print("");
    print("=== compound analysis ===");
    h sh_mu = mean_arr(dict_get(results, "SH"));
    h shq6_mu = mean_arr(dict_get(results, "SHQ6"));
    h mh_mu = mean_arr(dict_get(results, "MH"));
    h mhq6_mu = mean_arr(dict_get(results, "MHQ6"));
    print(concat_many("SH→SHQ6  Δ=", to_string(shq6_mu - sh_mu),
        " (", to_string((shq6_mu - sh_mu) / sh_mu * 100.0), "%)"));
    print(concat_many("MH→MHQ6  Δ=", to_string(mhq6_mu - mh_mu),
        " (", to_string((mhq6_mu - mh_mu) / mh_mu * 100.0), "%)"));
    print(concat_many("SH→MH    Δ=", to_string(mh_mu - sh_mu),
        " (", to_string((mh_mu - sh_mu) / sh_mu * 100.0), "%)"));
    print(concat_many("SH→MHQ6  Δ=", to_string(mhq6_mu - sh_mu),
        " (", to_string((mhq6_mu - sh_mu) / sh_mu * 100.0), "%) ← compound"));
}

main();

