    print(concat_many("base (L1+SMOD+V)  mean=", to_string(B_mean)));
    print(concat_many("+ Q6 fused         mean=", to_string(C_mean),
        "  Δ=", to_string(delta), "  (", to_string(pct), "%)",
        "  wins ", to_string(wins), "/", to_string(arr_len(seeds))));
}

