            arr_push(losses, L);
            print(concat_many("  ", dict_get(labels, arm),
                " seed=", to_string(seed), "  loss=", to_string(L)));
            si += 1;
        }
        dict_set(results, arm, losses);
        ai += 1;
    }

    print("");
    print("=== headline (tail loss mean over last 50 steps) ===");
    h L0_mean = mean_arr(dict_get(results, "L0"));
    ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h mu = mean_arr(dict_get(results, arm));
        h delta = mu - L0_mean;
        h pct = (delta / L0_mean) * 100.0;
        h wins = 0;
        h si = 0;
        while si < arr_len(seeds) {
            if arr_get(dict_get(results, arm), si) < arr_get(dict_get(results, "L0"), si) {
                wins += 1;
            }
            si += 1;
        }
        print(concat_many(dict_get(labels, arm),
            "  mean=", to_string(mu),
            "  Δ=", to_string(delta),
            "  (", to_string(pct), "%)",
            "  wins ", to_string(wins), "/", to_string(arr_len(seeds))));
        ai += 1;
    }
}

main();

# Substrate-quantized matmul weights 6-seed verification (#280).
#
# v0.8.7 first-look (1 seed, 5 steps) saw scale=4096 substrate-quant give
# loss 6.149 vs baseline 6.959 — suspiciously low. Re-test across 6 seeds
# × 300 steps to determine: real "substrate alignment regularizes" or
# seed noise?
#
# The substrate-quant happens INSIDE every GPU matmul call (boundary in
# install_gpu_matmul_accelerator): each cell is snapped to nearest
# Fibonacci attractor before f32 conversion. So the quantization persists
# through every forward and backward step.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) { dict_set(seen, ch, arr_len(chars)); arr_push(chars, ch); }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = prom_attention_substrate_k_new(d_model, seq_len, s1 + 11);
    h s2 = dict_get(attn, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn forward_window(model, token_ids, pe_table) {
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) { arr_push(pe_rows, arr_get(pe_table, i)); i += 1; }
    x = tape_add(x, tape_const(pe_rows));
    h attn_out = prom_attention_substrate_k_forward(dict_get(model, "attn"), x);
    h x_post = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post);
    h up = prom_linear_forward(dict_get(model, "ff_up"), n1);
    h down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    h x_ff = tape_add(x_post, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h attn_p = prom_attention_substrate_k_params(dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train(vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed) {
    tape_reset();
    h model = build_model(vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 30 { arr_push(tail, tape_value(loss)); }
        step += 1;
    }
    h s = 0.0;
    h i = 0;
    while i < arr_len(tail) { s += arr_get(tail, i); i += 1; }
    return s / arr_len(tail);
}

fn mean_arr(xs) {
    h s = 0.0; h i = 0;
    while i < arr_len(xs) { s += arr_get(xs, i); i += 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== substrate-quant 6-seed verification ===");
    # Use d_model=128 so matmuls cross the 1M GPU threshold and the
    # substrate-quant accelerator-boundary clamp actually fires.
    h text = "four score and seven years ago our fathers brought forth on this continent a new nation conceived in liberty and dedicated to the proposition that all men are created equal now we are engaged in a great civil war testing whether that nation or any nation so conceived and so dedicated can long endure";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h lr = 0.005;
    h steps = 300;
    h seeds = [42, 7, 123, 2026, 99, 1];

    print(concat_many("d_model=", to_string(d_model),
        "  ff=", to_string(ff_dim),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("Run with OMC_GPU_BACKEND=wgpu (and OMC_GPU_SUBSTRATE_QUANT=1 in one arm).");
    print("");

    h losses = [];
    h si = 0;
    while si < arr_len(seeds) {
        h seed = arr_get(seeds, si);
        h L = train(vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        arr_push(losses, L);
        print(concat_many("  seed=", to_string(seed), "  loss=", to_string(L)));
        si += 1;
    }
    h mu = mean_arr(losses);
    print(concat_many("mean=", to_string(mu)));
}

main();

# Cross-runtime validation of the cumulative substrate-attention stack
# in pure-OMC Prometheus. PyTorch already showed the stack winning at
# L1-MH on TinyShakespeare; v0.8.4 made it practical to run the same
# question in OMC at single-head, modest scale, multiple seeds.
#
# Four arms, all single-head transformer, same corpus / size / steps:
#   A. L0          standard QKV attention
#   B. L1+SMOD+V   substrate-K + S-MOD α=1.0 + substrate-V resample
#   C. + Q6 fused  adds tape_phi_log-based Q6 modulation (v0.8.1)
#   D. + Q6 composed  same math via tape_abs+tape_log (v0.8.1 reference)
#
# Reports per-seed losses + mean per arm. Hypothesis is the PyTorch
# directional ranking (A > B > C ≈ D) carries over to the OMC runtime.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

# Arms B, C, D all use substrate_k attention; differ only in field toggles.
fn build_model(arm, vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if arm == "L0" {
        attn = prom_attention_new(d_model, seq_len, s2);
        dict_set(attn, "alpha", 0.0);
        s2 = dict_get(attn, "rng_state");
    } else {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        # B keeps defaults (smod=1, v_resample=10, q6=off)
        if arm == "Bq6_fused" {
            dict_set(attn, "q6_mode", "fused");
        } elif arm == "Bq6_composed" {
            dict_set(attn, "q6_mode", "composed");
        }
        s2 = dict_get(attn, "rng_state");
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "arm", arm);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(arm, attn, x_id) {
    if arm == "L0" { return prom_attention_forward(attn, x_id); }
    return prom_attention_substrate_k_forward(attn, x_id);
}

fn attn_params(arm, attn) {
    if arm == "L0" { return prom_attention_params(attn); }
    return prom_attention_substrate_k_params(attn);
}

fn forward_window(model, token_ids, pe_table) {
    h arm = dict_get(model, "arm");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i += 1;
    }
    x = tape_add(x, tape_const(pe_rows));
    h attn_out = attn_forward(arm, dict_get(model, "attn"), x);
    h x_post_attn = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post_attn);
    h up = prom_linear_forward(dict_get(model, "ff_up"), n1);
    h down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    h x_post_ff = tape_add(x_post_attn, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_post_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h arm = dict_get(model, "arm");
    h attn_p = attn_params(arm, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i += 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i += 1; }
    return out;
}

fn train_arm(arm, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed) {
    tape_reset();
    h model = build_model(arm, vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail_losses = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k += 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 20 { arr_push(tail_losses, tape_value(loss)); }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) { sum += arr_get(tail_losses, i); i += 1; }
    return sum / arr_len(tail_losses);
}

fn mean_arr(xs) {
    h s = 0.0;
    h i = 0;
    while i < arr_len(xs) { s += arr_get(xs, i); i += 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== OMC substrate-attention cumulative stack cross-validation ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver beneath the stars while waves crash against rocky shores carrying secrets older than time itself across the deep blue ocean toward the horizon where dreams meet reality";
    print(concat_many("corpus: ", to_string(str_len(text)), " chars"));

    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 8;
    h d_model = 16;
    h ff_dim = 32;
    h lr = 0.01;
    h steps = 400;
    h seeds = [42, 7, 123, 2026, 99, 1];
    print(concat_many("vocab: ", to_string(vocab_size),
        "  seq_len: ", to_string(seq_len),
        "  d_model: ", to_string(d_model),
        "  steps: ", to_string(steps),
        "  seeds: ", to_string(arr_len(seeds))));
    print("");

    h arms = ["L0", "B", "Bq6_fused", "Bq6_composed"];
    h labels = dict_new();
    dict_set(labels, "L0",           "L0 standard QKV          ");
    dict_set(labels, "B",            "B  L1+SMOD+V             ");
    dict_set(labels, "Bq6_fused",    "C  + Q6 fused tape_phi_log");
    dict_set(labels, "Bq6_composed", "D  + Q6 composed          ");

    h results = dict_new();
    h ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h losses = [];
        h si = 0;
        while si < arr_len(seeds) {
            h seed = arr_get(seeds, si);
            h L = train_arm(arm, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
            arr_push(losses, L);
            si += 1;
        }
        dict_set(results, arm, losses);
        h mu = mean_arr(losses);
        print(concat_many(dict_get(labels, arm), "  mean=", to_string(mu)));
        ai += 1;
    }

    print("");
    print("=== headline (mean tail loss, lower is better) ===");
    h L0_mean = mean_arr(dict_get(results, "L0"));
    ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h mu = mean_arr(dict_get(results, arm));
        h delta = mu - L0_mean;
        h pct = (delta / L0_mean) * 100.0;
        # wins vs L0 per seed
        h wins = 0;
        h L0_seeds = dict_get(results, "L0");
        h arm_seeds = dict_get(results, arm);
        h si = 0;
        while si < arr_len(seeds) {
            if arr_get(arm_seeds, si) < arr_get(L0_seeds, si) { wins += 1; }
            si += 1;
        }
        print(concat_many(dict_get(labels, arm), "  ",
            to_string(mu),
            "   Δ=", to_string(delta),
            "  (", to_string(pct), "%)",
            "  wins ", to_string(wins), "/", to_string(arr_len(seeds))));
        ai += 1;
    }
}

main();

# Prometheus tiny LM — substrate-native bigram next-char prediction.
#
# A 2-layer MLP trained via OMC's reverse-mode autograd (no PyTorch).
# Predicts P(next_char | current_char) on a tiny ABA-pattern corpus.
# Loss must decrease over training steps; final predictions must
# show the model learned the bigram structure.
#
# This is the MVP that proves the Prometheus thesis: you can train a
# neural language model in pure OMC, using only substrate-native
# autograd and ML kernels.
#
# Architecture:
#   input  = one-hot of current char  [1, vocab]
#   hidden = relu(input @ W1 + b1)    [1, hidden]
#   output = hidden @ W2 + b2         [1, vocab]   (logits, MSE-trained
#                                                   against one-hot target)
#
# Training:
#   - SGD with substrate-native tape_update
#   - MSE loss against one-hot next-char target
#   - 200 steps over a synthetic bigram corpus
#
# Stop condition (substrate-clear): loss must strictly decrease
#   between step 0 and step 200, and final prediction on at least
#   one bigram must be correct (argmax matches target).

import "examples/lib/prometheus.omc";

# ---------------------------------------------------------------------------
# Corpus + tokenization
# ---------------------------------------------------------------------------

# Tiny alphabet, deterministic bigram pattern: a→b, b→c, c→a (cycle).
# Train data is "abcabcabcabc...". A successful model will learn this
# exact mapping (vocab = 3, perfect predictability).
fn make_corpus() {
    h chars = ["a", "b", "c"];        # vocab = 3
    h text = "abcabcabcabcabcabcabcabcabc";
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        # Index of ch in chars
        h idx = 0;
        if ch == "a" { idx = 0; }
        elif ch == "b" { idx = 1; }
        elif ch == "c" { idx = 2; }
        arr_push(ids, idx);
        i += 1;
    }
    h corpus = dict_new();
    dict_set(corpus, "chars", chars);
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "ids", ids);
    return corpus;
}

# ---------------------------------------------------------------------------
# Build model
# ---------------------------------------------------------------------------

fn build_model(vocab, hidden, rng_state) {
    h L1 = prom_linear_new(vocab, hidden, rng_state);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    h h_pre = prom_linear_forward(L1, x_id);
    h h_post = prom_relu(h_pre);
    h logits = prom_linear_forward(L2, h_post);
    return logits;
}

fn model_params(model) {
    return prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);
}

# ---------------------------------------------------------------------------
# Training loop
# ---------------------------------------------------------------------------

fn main() {
    print("=== Prometheus tiny LM ===");
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h ids = dict_get(corpus, "ids");
    h n_pairs = arr_len(ids) - 1;
    print(concat_many("corpus pairs (current→next): ", to_string(n_pairs)));
    print(concat_many("vocab: ", to_string(vocab)));

    tape_reset();
    h model = build_model(vocab, 8, 42);
    h params = model_params(model);
    print(concat_many("trainable param tensors: ", to_string(arr_len(params))));

    h lr = 0.05;
    h steps = 200;
    h loss_history = [];
    h step = 0;
    while step < steps {
        # Online SGD: cycle through pairs deterministically.
        h k = step % n_pairs;
        h cur = arr_get(ids, k);
        h nxt = arr_get(ids, k + 1);
        h x = prom_one_hot(cur, vocab);
        h target = prom_one_hot(nxt, vocab);
        h pred = forward(model, x);
        h loss = prom_mse_loss(pred, target);
        tape_backward(loss);
        prom_sgd_step(params, lr);
        h lv = tape_value(loss);
        arr_push(loss_history, lv);
        if step % 20 == 0 || step == steps - 1 {
            print(concat_many("step ", to_string(step), "  loss=", to_string(lv)));
        }
        step += 1;
    }
    print("");

    # ---- Stop-condition checks ----

    h first = arr_get(loss_history, 0);
    h last = arr_get(loss_history, arr_len(loss_history) - 1);
    print(concat_many("first loss: ", to_string(first)));
    print(concat_many("final loss: ", to_string(last)));
    h ratio = first / last;
    print(concat_many("loss reduction ratio: ", to_string(ratio), "x"));

    # Quality check: predict argmax for each bigram, count correct.
    print("");
    print("=== Inference: bigram predictions ===");
    h chars = dict_get(corpus, "chars");
    h correct = 0;
    h total = 0;
    h c = 0;
    while c < vocab {
        h x = prom_one_hot(c, vocab);
        h pred = forward(model, x);
        h logits = tape_value(pred);
        h pred_idx = prom_argmax_row(logits);
        # Expected next: (c+1) % vocab for the abcabc cycle
        h expected = (c + 1) % vocab;
        h ok = pred_idx == expected;
        if ok { correct += 1; }
        total += 1;
        h marker = "✗";
        if ok { marker = "✓"; }
        print(concat_many("  ", arr_get(chars, c), " → ", arr_get(chars, pred_idx),
                          "  (expected ", arr_get(chars, expected), ") ", marker));
        c += 1;
    }
    print("");
    print(concat_many("argmax accuracy: ", to_string(correct), "/", to_string(total)));

    # Final verdict.
    print("");
    if last < first && correct >= 1 {
        print("[OK] Prometheus end-to-end training works.");
        print("     Loss decreased AND argmax predicted at least one bigram.");
    } else {
        print("[FAIL] Did not meet stop condition.");
        if last >= first { print("       Loss did not decrease."); }
        if correct == 0 { print("       Zero correct predictions."); }
    }
}

main();

# Prometheus on real English text — cross-entropy LM, not bigram toy.
#
# Train a tiny char-LM on a real English sentence using Prometheus'
# new cross-entropy loss (built on the freshly-added tape_softmax +
# tape_log Rust builtins). Measure: cross-entropy goes down, generated
# text is more letter-statistic plausible than random.
#
# Why not full TinyShakespeare (1.1 MB)?
#   Pure-OMC training is ~1000x slower than PyTorch on CPU because we
#   don't have BLAS for matmul, only the basic OMC interpreter. A 1MB
#   corpus would take hours. A 200-char corpus converges in seconds and
#   proves the same thesis: Prometheus trains on real text, not toys.
#
# When GPU codegen lands, the same code scales to the full corpus.
#
# Stop condition: cross-entropy decreases by >2x over training AND
# generated text shows a non-uniform distribution over the vocab
# (model learned SOMETHING about the corpus, not just memorized noise).

import "examples/lib/prometheus.omc";

# ---------------------------------------------------------------------------
# Tokenize a small real-English corpus into char-ids.
# ---------------------------------------------------------------------------

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h out = dict_new();
    dict_set(out, "chars", chars);
    dict_set(out, "lookup", seen);
    return out;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

fn build_model(vocab_size, hidden, seed) {
    h L1 = prom_linear_new(vocab_size, hidden, seed);
    h L2 = prom_linear_new(hidden, vocab_size, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    return prom_linear_forward(L2, prom_relu(prom_linear_forward(L1, x_id)));
}

fn main() {
    print("=== Prometheus on real English ===");

    # A short real-English passage. ~135 chars, vocab ~26.
    h text = "the quick brown fox jumps over the lazy dog and the dog sleeps in the sun while the fox finds another quiet place to rest";
    print(concat_many("corpus: \"", text, "\""));
    print(concat_many("corpus length: ", to_string(str_len(text)), " chars"));

    h vocab = build_vocab(text);
    h chars = dict_get(vocab, "chars");
    h vocab_size = arr_len(chars);
    print(concat_many("vocab size: ", to_string(vocab_size)));
    print(concat_many("alphabet: ", to_string(chars)));

    h ids = encode(text, vocab);
    h n_pairs = arr_len(ids) - 1;
    print(concat_many("training pairs: ", to_string(n_pairs)));
    print("");

    # Train.
    tape_reset();
    h model = build_model(vocab_size, 16, 42);
    h params = prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);
    print(concat_many("trainable params: ", to_string(arr_len(params))));

    h lr = 0.1;
    h epochs = 12;    # passes over the corpus
    h total_steps = epochs * n_pairs;
    print(concat_many("training: ", to_string(total_steps), " steps (", to_string(epochs), " epochs)"));
    print("");

    h step = 0;
    h first_loss = 0.0;
    h last_losses = [];
    while step < total_steps {
        h k = step % n_pairs;
        h x = prom_one_hot(arr_get(ids, k), vocab_size);
        h target_idx = arr_get(ids, k + 1);
        h logits = forward(model, x);
        h loss = prom_cross_entropy_loss(logits, target_idx, vocab_size);
        tape_backward(loss);
        prom_sgd_step(params, lr);
        h lv = tape_value(loss);
        if step == 0 { first_loss = lv; }
        if step >= total_steps - n_pairs { arr_push(last_losses, lv); }
        if step % n_pairs == 0 {
            print(concat_many("  epoch ", to_string(step / n_pairs), "  loss=", to_string(lv)));
        }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(last_losses) { sum += arr_get(last_losses, i); i += 1; }
    h last_mean = sum / arr_len(last_losses);
    print("");
    print(concat_many("first loss: ", to_string(first_loss)));
    print(concat_many("last-epoch mean loss: ", to_string(last_mean)));
    h ratio = first_loss / last_mean;
    print(concat_many("reduction: ", to_string(ratio), "x"));

    # Generate.
    print("");
    print("--- Generated text from seed 't' ---");
    h seed_idx = dict_get(dict_get(vocab, "lookup"), "t");
    h gen = prom_generate_greedy(forward, model, seed_idx, 60, vocab_size);
    print(concat_many("  \"", prom_decode_indices(gen, chars), "\""));

    print("");
    if ratio > 2.0 {
        print("[OK] Prometheus trained on real English text via cross-entropy.");
        print(concat_many("     Loss reduced ", to_string(ratio), "x. Generated output above."));
        print("     tape_softmax + tape_log + prom_cross_entropy_loss all working.");
        print("     🥂 4-for-4 on the goal items.");
    } else {
        print("[PARTIAL] Loss reduction <2x — model under-trained or under-parameterized.");
        print("          More epochs or larger hidden layer would help.");
    }
}

main();

# Prometheus transformer-class model — train end-to-end in pure OMC.
#
# Architecture (single-step attention, no causal mask, sequence dim collapsed
# to 1 for this scale — full multi-token sequences are a next step that
# needs gather/scatter primitives we haven't built yet):
#
#   token_idx
#     ↓ Embedding(vocab → d_model)
#     ↓ + CRT-PE[pos]                  (additive CRT-Fibonacci PE)
#   x ∈ [1, d_model]
#     ↓ LayerNorm
#     ↓ FFN: Linear(d_model → ff) → ReLU → Linear(ff → d_model)
#     ↓ residual
#     ↓ LayerNorm
#     ↓ output_head: Linear(d_model → vocab)
#   logits ∈ [1, vocab]
#
# This is the tiniest possible transformer-style block: pre-norm,
# residual, FFN — substrate-native, trained via AdamW + cross-entropy.
# The "single-token attention" caveat means our attention layer
# operates on a 1-token sequence here; the geodesic bias logic is
# already in the layer and would activate when we extend to multi-token
# input. That extension needs proper tape-level gather/scatter, which
# is a separate Rust addition.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i += 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i += 1;
    }
    return ids;
}

# Add a CRT-PE row (matrix slice) to a single-row tape value.
fn add_pe(x_id, pe_row) {
    h pe = tape_const([pe_row]);
    return tape_add(x_id, pe);
}

fn build_transformer(vocab_size, d_model, ff_dim, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s1);
    h ff_up = prom_linear_new(d_model, ff_dim, s1 + 17);
    h s2 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s2);
    h s3 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s3);
    h head = prom_linear_new(d_model, vocab_size, s3 + 23);

    h m = dict_new();
    dict_set(m, "emb", emb);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn forward(model, token_idx, pe_row) {
    # Embed + position
    h x = prom_embedding_forward(dict_get(model, "emb"), token_idx);
    x = add_pe(x, pe_row);

    # Pre-norm + FFN + residual
    h normed = prom_layernorm_forward(dict_get(model, "ln1"), x);
    h up = prom_linear_forward(dict_get(model, "ff_up"), normed);
    h activated = prom_relu(up);
    h down = prom_linear_forward(dict_get(model, "ff_down"), activated);
    h residual = tape_add(x, down);

    # Final norm + head
    h normed2 = prom_layernorm_forward(dict_get(model, "ln2"), residual);
    return prom_linear_forward(dict_get(model, "head"), normed2);
}

fn collect_all_params(model) {
    h layers = [
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ];
    return prom_collect_params_v2(layers);
}

fn main() {
    print("=== Prometheus transformer-class model ===");
    h text = "the quick brown fox jumps over the lazy dog and the dog sleeps in the sun";
    print(concat_many("corpus: ", text));
    print(concat_many("length: ", to_string(str_len(text))));

    h vocab = build_vocab(text);
    h chars = dict_get(vocab, "chars");
    h vocab_size = arr_len(chars);
    h ids = encode(text, vocab);
    h n_pairs = arr_len(ids) - 1;
    print(concat_many("vocab=", to_string(vocab_size), "  pairs=", to_string(n_pairs)));

    h d_model = 16;
    h ff_dim = 32;
    h seq_len = arr_len(ids);
    print(concat_many("d_model=", to_string(d_model), "  ff=", to_string(ff_dim)));

    # Precompute CRT-PE table for all positions.
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    print(concat_many("CRT-PE table: ", to_string(seq_len), " x ", to_string(d_model)));

    tape_reset();
    h model = build_transformer(vocab_size, d_model, ff_dim, 42);
    h params = collect_all_params(model);
    print(concat_many("trainable param tensors: ", to_string(arr_len(params))));

    h opt = prom_adamw_new(params, 0.02, 0.9, 0.999, 1e-8, 0.0);

    h epochs = 6;
    h total_steps = epochs * n_pairs;
    print(concat_many("training: ", to_string(total_steps), " steps (",
                      to_string(epochs), " epochs), AdamW"));
    print("");

    h step = 0;
    h first_loss = 0.0;
    h last_losses = [];
    while step < total_steps {
        h k = step % n_pairs;
        h pe_row = arr_get(pe_table, k);
        h logits = forward(model, arr_get(ids, k), pe_row);
        h loss = prom_cross_entropy_loss(logits, arr_get(ids, k + 1), vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        h lv = tape_value(loss);
        if step == 0 { first_loss = lv; }
        if step >= total_steps - n_pairs { arr_push(last_losses, lv); }
        if step % n_pairs == 0 {
            print(concat_many("  epoch ", to_string(step / n_pairs), "  loss=", to_string(lv)));
        }
        step += 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(last_losses) { sum += arr_get(last_losses, i); i += 1; }
    h last_mean = sum / arr_len(last_losses);
    print("");
    print(concat_many("first loss: ", to_string(first_loss)));
    print(concat_many("last-epoch mean: ", to_string(last_mean)));
    h ratio = first_loss / last_mean;
    print(concat_many("reduction: ", to_string(ratio), "x"));

    # Generate text from seed 't'.
    print("");
    print("--- Generated text from seed 't' ---");
    h seed_idx = dict_get(dict_get(vocab, "lookup"), "t");
    h gen = [seed_idx];
    h cur = seed_idx;
    h gen_pos = 0;
    while gen_pos < 50 {
        h pe_row = arr_get(pe_table, gen_pos - (gen_pos / seq_len) * seq_len);
        h logits = forward(model, cur, pe_row);
        h pv = tape_value(logits);
        h next_idx = prom_argmax_row(pv);
        arr_push(gen, next_idx);
        cur = next_idx;
        gen_pos += 1;
    }
    print(concat_many("  \"", prom_decode_indices(gen, chars), "\""));

    print("");
    if ratio > 2.0 {
        print(concat_many("[OK] Transformer block trained end-to-end in pure OMC."));
        print(concat_many("     Loss reduction ", to_string(ratio), "x via AdamW + cross-entropy."));
        print("     Components: Embedding + CRT-PE + LayerNorm + FFN + residual + head.");
        print("     🥂 Prometheus ships a transformer.");
    } else {
        print("[PARTIAL] Loss reduction <2x. More epochs / d_model / lr tuning needed.");
    }
}

main();

# =============================================================================
# OmniWeight Quantization Demo (Phase S)
# =============================================================================
# Mirrors the Phase 18 pattern from omnicode_experiment in miniature.
#
# The thesis: a vector of values is "harmonically compressible" if most of
# its elements live near Fibonacci attractors. We measure that with mean
# OmniWeight = average of φ^(-|e|) where e is the normalized distance to
# the nearest attractor. Higher = more compressible.
#
# Compression is just: replace each element with its nearest attractor
# when the OmniWeight crosses a threshold. The output has a smaller
# effective vocabulary (a handful of Fibonacci numbers instead of
# arbitrary integers) while preserving the φ-geodesic structure of the
# original data.
#
# This is the same principle Phase 18 of omnicode_experiment uses to
# quantize a 35B-parameter Qwen model — at scale, with weights in the
# millions. The math is identical to what runs here.
# =============================================================================

print("== OmniWeight Quantization Demo ==");
print("");

# ---------------------------------------------------------------------------
# Dataset A: a "harmonic" dataset — values clustered near attractors.
# Should compress with very little loss.
# ---------------------------------------------------------------------------
print("--- Dataset A: harmonic (values near Fibonacci attractors) ---");
h harmonic = [85, 90, 142, 150, 230, 240, 375, 380, 605, 615];
print(concat_many("  size = ", arr_len(harmonic)));
print(concat_many("  mean OmniWeight = ", mean_omni_weight(harmonic)));
print(concat_many("  quantizable @ 0.5 = ", quantization_ratio(harmonic, 0.5)));
print(concat_many("  quantizable @ 0.9 = ", quantization_ratio(harmonic, 0.9)));
print("  quantized @ 0.5 (each value's nearest Fibonacci):");
h q_a = quantize(harmonic, 0.5);
print(q_a);
print("");

# ---------------------------------------------------------------------------
# Dataset B: a "noisy" dataset — values far from any attractor.
# Should resist compression.
# ---------------------------------------------------------------------------
print("--- Dataset B: noisy (values off the geodesic) ---");
h noisy = [50, 75, 110, 175, 280, 400, 500, 700];
print(concat_many("  size = ", arr_len(noisy)));
print(concat_many("  mean OmniWeight = ", mean_omni_weight(noisy)));
