#      and demonstrates that all three classes co-exist in the loop.

fn run_h2(label, source, max_iter) {
    print(concat_many("==== ", label, " ===="));
    print("--- BROKEN SOURCE ---");
    print(source);
    print("");
    print("--- Lex + parse ---");
    h toks = tokenize_b(source);
    h ast = p_program(toks);
    print(concat_many("  tokens=", arr_len(toks),
                      "  stmts=", arr_len(ast)));
    print("");
    print(concat_many("--- heal_until_fixpoint (max_iter=", max_iter, ") ---"));
    h r = heal_until_fixpoint(ast, max_iter);
    h final_ast = arr_get(r, 0);
    h trajectory = arr_get(r, 1);
    h outcome = arr_get(r, 2);
    h iters = arr_get(r, 3);
    h ti = 0;
    while ti < arr_len(trajectory) {
        print(arr_get(trajectory, ti));
        ti += 1;
    }
    print(concat_many("  outcome: ", outcome,
                      " (after ", iters, " iterations)"));
    print("");
    print("--- HEALED SOURCE ---");
    h healed_source = emit_source(final_ast);
    print(healed_source);
    print("--- execute healed via the OMC bytecode VM ---");
    h prog = encode_program(final_ast);
    print(concat_many("  bytecode ops: ", arr_len(prog)));
    print("  output:");
    execute(prog);
    print("");
    return outcome;
}

