print("# Phase H.5: array-bounds healing via fold_escape on the index");
print("# `safe arr_get(a, idx)` and `safe arr_set(a, idx, v)` make");
print("# out-of-bounds reads/writes total — finite, attractor-landing.");
print("############################################################");
