# -------- Demo 1: H.4 regression — runtime divide-by-zero still healed -----
# Sanity check: H.4 still works exactly as it did. compute(144, 0) returns
# 144 instead of crashing. No change vs H.4.

h H4_REGRESSION = "fn compute(count, mod) {
    return safe count / mod;
}
print(compute(144, 3));
print(compute(144, 0));";

h outcome_1 = run_h3("Demo 1 (regression): safe-divide still works",
                     H4_REGRESSION, 5);

# -------- Demo 2: bare arr_get out of bounds — would crash -----------------
# Without `safe`, an out-of-bounds index halts execution. Run with idx=1
# (in bounds) so the demo terminates cleanly, but the architectural point
# stands: the unguarded `arr_get(xs, idx)` has no compile-time signal that
# idx might be out of bounds when supplied by a caller.

h UNGUARDED_ARRAY = "fn lookup(xs, idx) {
    return arr_get(xs, idx);
}
h xs = [10, 20, 30];
print(lookup(xs, 1));";

h outcome_2 = run_h3("Demo 2 (no safe): unguarded arr_get",
                     UNGUARDED_ARRAY, 5);

# -------- Demo 3: safe arr_get with out-of-bounds indices ------------------
# Same lookup function, with `safe` wrapping the arr_get call. Now every
# call returns a finite value regardless of idx:
#   idx=1   → in-bounds, returns xs[1] = 20.
#   idx=999 → fold to 610, 610 % 3 = 1, returns xs[1] = 20.
#   idx=-5  → fold to -5, ((-5 % 3) + 3) % 3 = 1, returns xs[1] = 20.
#   idx=7   → fold to 8, 8 % 3 = 2, returns xs[2] = 30.
# The math is the bounds check. No `if 0 <= idx < len` boilerplate.

h GUARDED_ARRAY = "fn lookup(xs, idx) {
    return safe arr_get(xs, idx);
}
h xs = [10, 20, 30];
print(lookup(xs, 1));
print(lookup(xs, 999));
print(lookup(xs, 0 - 5));
print(lookup(xs, 7));";

