# ---- V.7c new: pass-by-value + arr_push + recursion, return-and-rebind ----
#
# OMC arrays pass by value at function boundaries, so the natural callee
# pattern is: take an accumulator in, mutate it locally, return it, let
# the caller rebind. This program threads `acc` through five recursive
# frames, each frame's ARR_PUSH_NAMED mutating ITS OWN local copy; the
# final returned array carries every push back up. The bytecode VM and
# the tree-walker produce identical output (length 5, elements 5,4,3,2,1).
#
# This is the test that proves V.7c's mutating ops compose correctly with
# the V.7 call-frame plumbing — without ARR_PUSH_NAMED, every recursive
# frame's mutation would be lost; without the call-frame scope save/restore,
# the namespace would be wrong. Both pieces have to land together.

compile_and_run("Test 7: recursion + arr_push + return-and-rebind",
    "fn trace_fact(n, acc) { if n == 0 { return acc; } arr_push(acc, n); return trace_fact(n - 1, acc); } h trace = trace_fact(5, arr_new(0, 0)); print(arr_len(trace)); h i = 0; while i < arr_len(trace) { print(arr_get(trace, i)); i += 1; }");

# A side-by-side variant that DROPS the return value to show the contrast:
# without rebinding, the caller's `trace` stays empty because the param
# was passed by value. Both interpreters agree.

compile_and_run("Test 8: contrast — same fn, return discarded (trace stays empty)",
    "fn trace_fact(n, acc) { if n == 0 { return acc; } arr_push(acc, n); return trace_fact(n - 1, acc); } h trace = arr_new(0, 0); trace_fact(5, trace); print(arr_len(trace));");

