    h i = 1;
    while i <= n {
        h row = \"\";
        h j = 0;
        while j < i {
            row = str_concat(row, \"*\");
            j += 1;
        }
        arr_push(out, row);
        i += 1;
    }
    return out;
}
h __result = build_pyramid(5);";

