class Vector {
    dx;
    dy;
    fn magnitude(self) {
        h dx = dict_get(self, "dx");
        h dy = dict_get(self, "dy");
        return sqrt(dx * dx + dy * dy);
    }
    fn add(self, other) {
        return Vector(
            dict_get(self, "dx") + dict_get(other, "dx"),
            dict_get(self, "dy") + dict_get(other, "dy")
