class Counter {
    value;
    fn increment(self) {
        dict_set(self, "value", dict_get(self, "value") + 1);
        return self;
    }
    fn decrement(self) {
        dict_set(self, "value", dict_get(self, "value") - 1);
        return self;
    }
    fn get(self) { return dict_get(self, "value"); }
}

fn test_counter_increment() {
