# ---- arr_eye (identity matrix) ----

fn test_eye_3() {
    h I = arr_eye(3);
    assert_eq(arr_len(I), 3, "I has 3 rows");
    h r0 = arr_get(I, 0);
    h r1 = arr_get(I, 1);
    assert_eq(arr_len(r0), 3, "row has 3 cols");
    assert_eq(arr_get(r0, 0), 1, "I[0][0]=1");
    assert_eq(arr_get(r0, 1), 0, "I[0][1]=0");
    assert_eq(arr_get(r1, 1), 1, "I[1][1]=1");
