fn test_substrate_resample_modulates_off_attractor_components() {
    tape_reset();
    # Use a 2x2 input — tape_value auto-unwraps a single-row matrix to
    # a 1D array which the matrix builder doesn't handle; 2x2 matches
    # real-world attention shapes [T, D] with T >= 2 anyway.
    # Cells inspected:
    # (0,0) = 0.7  * 10 = 7  → distance(7)=1  → mod = 1/(1 + 1/10) ≈ 0.909
    # (0,1) = 0.2  * 10 = 2  → distance(2)=0  → mod = 1            (identity)
    h v = tape_var([[0.7, 0.2], [0.0, 0.0]]);
    h out = prom_substrate_resample(v, 10.0);
    h vout = tape_value(out);
    h row0 = arr_get(vout, 0);
    h expected_off = 0.7 * (1.0 / (1.0 + 1.0 / 10.0));
    h expected_on  = 0.2;
    assert_true(approx_eq(arr_get(row0, 0), expected_off, 1e-9),
                "off-attractor scalar gets modulated as predicted");
    assert_true(approx_eq(arr_get(row0, 1), expected_on, 1e-9),
                "on-attractor scalar passes through identity");
}

