    h loss = tape_sum(out);
    tape_backward(loss);
    h vg = tape_grad(v);
    # Backward must produce non-zero gradients on every cell — modulation
    # rides as a const so dv = modulation * dy where dy=1 for sum loss.
    h i = 0;
    while i < 2 {
        h row = arr_get(vg, i);
        h j = 0;
        while j < 2 {
            assert_true(arr_get(row, j) > 0.0,
                "v gradient cell [" + to_string(i) + "][" + to_string(j) + "] non-zero");
            j += 1;
        }
        i += 1;
    }
}

fn test_substrate_softmax_alpha_positive_still_sums_to_one() {
    tape_reset();
    h scores = tape_const([[1.0, 2.0, 3.0], [-1.0, 0.5, 2.5]]);
    h smod = prom_substrate_softmax(scores, 0.5);
