fn extract_fns_from_file(path) {
    h src = read_file(path);
    h fns = [];
    h i = 0;
    h n = str_len(src);
    while i < n {
        # Look for "fn " at line start or after whitespace.
        if str_slice(src, i, i + 3) == "fn " && (i == 0 || str_slice(src, i - 1, i) == "\n" || str_slice(src, i - 1, i) == " ") {
            # Find the opening brace.
            h j = i;
            while j < n && str_slice(src, j, j + 1) != "{" { j += 1; }
            if j >= n { i += 1; }
            else {
                # Track brace depth.
                h depth = 0;
                h k = j;
                while k < n {
                    h c = str_slice(src, k, k + 1);
                    if c == "{" { depth += 1; }
                    elif c == "}" {
                        depth -= 1;
                        if depth == 0 { k += 1; break; }
                    }
                    k += 1;
                }
                if depth == 0 {
                    arr_push(fns, str_slice(src, i, k));
                    i = k;
                } else {
                    i += 1;
                }
            }
        } else {
            i += 1;
        }
    }
    return fns;
}

fn fn_name_of(src) {
    # Pull NAME from "fn NAME(...)". skip "fn " (3 chars).
    h after = str_slice(src, 3, str_len(src));
    h i = 0;
    while i < str_len(after) {
        h c = str_slice(after, i, i + 1);
        if c == "(" || c == " " { break; }
        i += 1;
    }
    return str_slice(after, 0, i);
}

fn signature_first_line(src) {
    # Return the "fn NAME(...)" signature only.
    h i = 0;
    while i < str_len(src) && str_slice(src, i, i + 1) != "{" { i += 1; }
    return str_trim(str_slice(src, 0, i));
}

fn build_lib_manifest() {
    h libs = [
        "examples/lib/np.omc",
        "examples/lib/pd.omc",
        "examples/lib/sklearn.omc",
        "examples/lib/torch.omc",
        "examples/lib/requests.omc",
        "examples/lib/sqlite.omc",
        "examples/lib/substrate.omc",
        "examples/lib/harmonic_anomaly.omc",
        "examples/lib/harmonic_clustering.omc",
        "examples/lib/harmonic_recommend.omc",
        "examples/lib/test.omc",
    ];
    h manifest = [];
    h i = 0;
    while i < arr_len(libs) {
        h path = arr_get(libs, i);
        h fns = extract_fns_from_file(path);
        h j = 0;
        while j < arr_len(fns) {
            h fn_src = arr_get(fns, j);
            h entry = dict_new();
            dict_set(entry, "lib", path);
            dict_set(entry, "name", fn_name_of(fn_src));
            try {
                h hash_dict = omc_canonical_hash(fn_src);
                dict_set(entry, "canonical_hash", dict_get(hash_dict, "raw"));
                dict_set(entry, "attractor", dict_get(hash_dict, "attractor"));
            } catch e {
                # Some fns use library-specific syntax that doesn't parse
                # in isolation (e.g. closures referencing the module's
                # imports). Skip the hash for these; the name + sig still
                # serve as a discovery hint.
                dict_set(entry, "canonical_hash", 0);
                dict_set(entry, "attractor", 0);
            }
            dict_set(entry, "signature", signature_first_line(fn_src));
            arr_push(manifest, entry);
            j += 1;
        }
        i += 1;
    }
    return manifest;
}

fn main() {
    h pack = omc_bootstrap_pack();
    h manifest = build_lib_manifest();
    h bundle = dict_new();
    dict_set(bundle, "kind", "omc_onboarding_token_v1");
    dict_set(bundle, "version", "2026.05.16");
    dict_set(bundle, "bootstrap_pack", pack);
    dict_set(bundle, "lib_manifest", manifest);
    dict_set(bundle, "fn_count", arr_len(manifest));
    dict_set(bundle, "bootstrap_bytes", str_len(pack));

    # Substrate-sign the entire bundle so receivers can verify integrity.
    h bundle_json = json_stringify(bundle);
    h envelope = omc_msg_sign(bundle_json, 0, 7);  # sender=0, kind=7 (onboarding)
    h envelope_json = omc_msg_serialize(envelope);

    # Emit one JSON line: the substrate-signed envelope. The receiver
    # verifies with omc_msg_verify and then json_parse the content.
    print(envelope_json);
}

main();

# =============================================================================
# Experiment 0 — OmniWeight vs softmax scoring on a copy task.
#
# Setup:
#   - 8-token "context" sampled from a Fibonacci-attractor vocab.
#   - 1 separator token (0) — present but not scored.
#   - 1 "query" token that equals one of the context tokens verbatim.
#   - Both scoring rules must point at the matching context position.
#
# We are NOT training anything. We're isolating the SCORING FUNCTION:
#   - OmniWeight (harmonic): w(q, k) = φ^(-|q - k| / max(|k|, 1))
#   - Softmax-style:         w(q, k) = exp(-|q - k|), normalized
# Both pick the argmax position; we measure exact-match accuracy.
#
# Run:
#   ./target/release/omnimcode-standalone experiments/hybrid_llm/experiment_0_copy_task.omc
#   OMC_VM=1 ./target/release/omnimcode-standalone experiments/hybrid_llm/experiment_0_copy_task.omc
# =============================================================================

h PHI = 1.6180339887498948;

# Vocabulary: 12 Fibonacci attractors. Index 0 is the separator (never queried).
h VOCAB_SIZE = 12;
fn vocab_at(i) -> int {
    if i == 0 { return 1; }
    if i == 1 { return 2; }
    if i == 2 { return 3; }
    if i == 3 { return 5; }
    if i == 4 { return 8; }
    if i == 5 { return 13; }
    if i == 6 { return 21; }
    if i == 7 { return 34; }
    if i == 8 { return 55; }
    if i == 9 { return 89; }
    if i == 10 { return 144; }
    if i == 11 { return 233; }
    return 1;
}

# ---------------------------------------------------------------------------
# Scoring functions
# ---------------------------------------------------------------------------

# OmniWeight: harmonic geodesic distance, no normalization.
fn omni_weight(q, k) -> float {
    h diff = to_float(q - k);
    if diff < 0.0 { diff = 0.0 - diff; }
    h denom = to_float(k);
    if denom < 0.0 { denom = 0.0 - denom; }
    if denom < 1.0 { denom = 1.0; }
    h e = diff / denom;
    return pow(PHI, 0.0 - e);
}

# Softmax-style score: exp(-|q - k|). Returned unnormalized; argmax is
# scale-invariant so the softmax denominator doesn't affect the
# selection. (We'd need it for KL divergence or sampling, not here.)
fn softmax_score(q, k) -> float {
    h diff = to_float(q - k);
    if diff < 0.0 { diff = 0.0 - diff; }
    return exp(0.0 - diff);
}

# ---------------------------------------------------------------------------
# Argmax over a length-N context using a chosen scoring function.
# `which_score` = 0 → OmniWeight, 1 → softmax.
# Returns the INDEX of the highest-scoring position.
# ---------------------------------------------------------------------------
fn argmax_score(context, n, query, which_score) -> int {
    h best_idx = 0;
    h k0 = arr_get(context, 0);
    h best_score = 0.0;
    if which_score == 0 {
        best_score = omni_weight(query, k0);
    } else {
        best_score = softmax_score(query, k0);
    }

    h i = 1;
    while i < n {
        h k = arr_get(context, i);
        h s = 0.0;
        if which_score == 0 {
            s = omni_weight(query, k);
        } else {
            s = softmax_score(query, k);
        }
        if s > best_score {
            best_score = s;
            best_idx = i;
        }
        i = i + 1;
    }
    return best_idx;
}

# ---------------------------------------------------------------------------
# Build one trial: random 8-token context, query equals context[target_idx].
# Returns the predicted index from each scorer.
# We pre-seed with random_seed() so the trials are reproducible.
# ---------------------------------------------------------------------------
fn run_trial(target_idx, ctx_len) -> array {
    h context = arr_new(ctx_len, 0);
    h i = 0;
    while i < ctx_len {
        # random_int is inclusive on both ends in OMC, so clamp upper.
        h v = random_int(0, VOCAB_SIZE - 1);
        arr_set(context, i, vocab_at(v));
        i = i + 1;
    }
    h query = arr_get(context, target_idx);

    h omni_pick = argmax_score(context, ctx_len, query, 0);
    h soft_pick = argmax_score(context, ctx_len, query, 1);

    # Pack result as [target, omni_pick, soft_pick] for downstream tallying.
    h out = arr_new(3, 0);
    arr_set(out, 0, target_idx);
    arr_set(out, 1, omni_pick);
    arr_set(out, 2, soft_pick);
    return out;
}

# ---------------------------------------------------------------------------
# Main loop.
# ---------------------------------------------------------------------------
random_seed(42);

h N_TRIALS = 100;
h CTX_LEN = 8;

print("== Experiment 0: OmniWeight vs softmax-style argmax (copy task) ==");
print(concat_many("trials=", N_TRIALS, "  ctx_len=", CTX_LEN, "  vocab_size=", VOCAB_SIZE));
print("");

h omni_correct = 0;
h soft_correct = 0;
h disagreements = 0;
h trial = 0;
while trial < N_TRIALS {
    # Pick a target position uniformly in [0, CTX_LEN). random_int is
    # inclusive on both ends, so the upper bound is CTX_LEN - 1.
    h target = random_int(0, CTX_LEN - 1);
    h trial_out = run_trial(target, CTX_LEN);
    h tgt = arr_get(trial_out, 0);
    h omni = arr_get(trial_out, 1);
    h soft = arr_get(trial_out, 2);

    # A "correct" pick = the picked position carries the same VALUE as the
    # target position. Multiple positions can share a value, so any
    # collision is a fair hit.
    # NOTE: when several positions hold the same Fibonacci value, all of
    # them are valid argmaxes. We don't penalize ambiguous trials here —
    # both scorers will tie-break to the first occurrence.
    if omni == tgt { omni_correct = omni_correct + 1; }
    if soft == tgt { soft_correct = soft_correct + 1; }
    if omni != soft { disagreements = disagreements + 1; }
    trial = trial + 1;
}

print(concat_many("OmniWeight argmax correct:  ", omni_correct, " / ", N_TRIALS));
print(concat_many("Softmax-style argmax correct: ", soft_correct, " / ", N_TRIALS));
print(concat_many("Disagreements between scorers: ", disagreements, " / ", N_TRIALS));
print("");

# When q == k exactly, both score functions return their maximum:
# OmniWeight → φ^0 = 1; softmax → e^0 = 1. Both should pick correctly
# whenever the query exactly matches AT LEAST ONE context value. The
# interesting case is the tie-break — both implementations pick the
# first occurrence, so they should AGREE on every trial.
#
# If disagreements > 0, we've found a case where φ-geodesic distance
# and exponential distance rank differently. That's the seed for
# experiment 1 (perturbed-query task) — handle it there.

print("== Sanity check ==");
print("Both scorers monotonically decrease in |q - k|, so on EXACT-MATCH");
print("queries they should always agree. Non-zero disagreement is a bug");
print("OR an environment ambiguity (multiple positions sharing the query");
print("value, tie-broken differently).");
print("");
print("Next: experiment_1_perturbed.omc — query is off-attractor.");
print("There, OmniWeight's denominator (max(|k|, 1)) normalises the");
print("error differently from softmax's raw |q - k|, so they diverge");
print("in measurable ways.");
print("== End ==");

# =============================================================================
# Experiment 10 — Harmonic CRT-style positional encoding (Path E2).
#
# Background: experiment 3 found that 4-channel harmonic PE
# (phi.fold(pos * prime + 1)) saturates at 22 unique vectors by L=64
# while sinusoidal PE stays distinct to L=64 then saturates at 64.
# This experiment tries a different harmonic strategy: pure-CRT-style
# modular encoding with Fibonacci-attractor moduli.
#
# Chinese Remainder Theorem: for pairwise-coprime moduli (m1, ..., mk),
# the residue tuple (pos mod m1, ..., pos mod mk) uniquely identifies
# pos in [0, m1*m2*...*mk).
#
# Pairwise-coprime Fibonacci attractors near our target range:
#   F_5 = 5
#   F_6 = 8  (gcd(5,8) = 1)
#   F_7 = 13 (gcd(5,13)=1, gcd(8,13)=1)
#   F_8 = 21 (gcd(5,21)=1, gcd(8,21)=1, gcd(13,21)=1)
# Product = 10920 — encoding capacity well past L=200.
#
# Channel design:
#   harmonic_crt_pe(pos) = [
#       pos mod 5,
#       pos mod 8,
#       pos mod 13,
#       pos mod 21,
#   ]
#
# This is unambiguously substrate-aligned: the choice of moduli IS
# the harmonic claim. Whether THESE specific values give
# better-than-sinusoidal distinctness is what we measure.
#
# Comparison: same sinusoidal_pe as experiment 3 (4 channels at 2
# periods) so the head-to-head is direct.
#
# Sweep: L = 8, 16, 32, 48, 64, 100, 200.
# Metric: distinct-vector count + lookup recovery rate (squared L2).
#
# Hypothesis: CRT with Fibonacci moduli should stay distinct to
# L = product of moduli = 10920, well past sinusoidal's 64-period
# wrap. If true, this is the first per-component harmonic primitive
# that beats its transformer baseline on a real task — the missing
# piece for transformerless LLM positional encoding.
# =============================================================================

h D = 4;

# ---------------------------------------------------------------------------
# CRT-style harmonic encoding: residues mod Fibonacci attractors.
# ---------------------------------------------------------------------------
fn harmonic_crt_pe(pos) -> array {
    h v = arr_new(D, 0);
    arr_set(v, 0, pos % 5);
    arr_set(v, 1, pos % 8);
    arr_set(v, 2, pos % 13);
    arr_set(v, 3, pos % 21);
    return v;
}

# ---------------------------------------------------------------------------
# Same multi-channel sinusoidal as experiment 3 — paper's geometric
# frequency layout, two periods (8 and 64), four channels total.
# ---------------------------------------------------------------------------
fn sin_channel(pos, period) -> int {
    h two_pi = 2.0 * pi();
    h theta = to_float(pos) * two_pi / to_float(period);
    return to_int(1000.0 * sin(theta));
}

fn cos_channel(pos, period) -> int {
    h two_pi = 2.0 * pi();
    h theta = to_float(pos) * two_pi / to_float(period);
    return to_int(1000.0 * cos(theta));
}

fn sinusoidal_pe(pos) -> array {
    h v = arr_new(D, 0);
    arr_set(v, 0, sin_channel(pos, 8));
    arr_set(v, 1, cos_channel(pos, 8));
    arr_set(v, 2, sin_channel(pos, 64));
    arr_set(v, 3, cos_channel(pos, 64));
    return v;
}

# ---------------------------------------------------------------------------
# Squared L2 distance and exact equality on D-vectors.
# ---------------------------------------------------------------------------
fn l2sq(a, b) -> int {
    h s = 0;
    h i = 0;
    while i < D {
        h d = arr_get(a, i) - arr_get(b, i);
        s = s + (d * d);
        i = i + 1;
    }
    return s;
}

fn vec_eq(a, b) -> int {
    h i = 0;
    while i < D {
        if arr_get(a, i) != arr_get(b, i) { return 0; }
        i = i + 1;
    }
    return 1;
}

# ---------------------------------------------------------------------------
# Count unique vectors among L positions. O(L^2) — fine for L<=200.
# which: 0 = harmonic-CRT, 1 = sinusoidal.
# ---------------------------------------------------------------------------
fn count_unique(L, which) -> int {
    h unique = 0;
    h i = 0;
    while i < L {
        h vi = arr_new(D, 0);
        if which == 0 { vi = harmonic_crt_pe(i); }
        if which == 1 { vi = sinusoidal_pe(i); }
        h is_first = 1;
        h j = 0;
        while j < i {
            h vj = arr_new(D, 0);
            if which == 0 { vj = harmonic_crt_pe(j); }
            if which == 1 { vj = sinusoidal_pe(j); }
            if vec_eq(vi, vj) == 1 {
                is_first = 0;
                j = i;
            }
            j = j + 1;
        }
        if is_first == 1 { unique = unique + 1; }
        i = i + 1;
    }
    return unique;
}

# ---------------------------------------------------------------------------
# Lookup recovery: build vectors for positions 0..L, then for each
# position generate a query (perfect, no perturbation), find the
# argmin-L2 stored position, count exact-match recoveries.
# ---------------------------------------------------------------------------
fn lookup_recovery(L, which) -> int {
    h hits = 0;
    h q = 0;
    while q < L {
        h vq = arr_new(D, 0);
        if which == 0 { vq = harmonic_crt_pe(q); }
        if which == 1 { vq = sinusoidal_pe(q); }
        h best_dist = 0 - 1;   # sentinel "infinity"
        h best_pos = 0 - 1;
        h k = 0;
        while k < L {
            h vk = arr_new(D, 0);
            if which == 0 { vk = harmonic_crt_pe(k); }
            if which == 1 { vk = sinusoidal_pe(k); }
            h d = l2sq(vq, vk);
            if best_dist < 0 {
                best_dist = d;
                best_pos = k;
            }
            if d < best_dist {
                best_dist = d;
                best_pos = k;
            }
            k = k + 1;
        }
        if best_pos == q { hits = hits + 1; }
        q = q + 1;
    }
    return hits;
}

