# =============================================================================
# Experiment 2 — Positional encoding under length extrapolation.
#
# Question: when a position-encoding scheme is "designed" for sequences
# of length N, how does it behave at length 2N? This is the classic
# length-extrapolation problem in transformers — sinusoidal PE
# extrapolates poorly because higher positions fall outside the
# frequency basis the model has effectively seen.
#
# We compare two single-channel encodings:
#
#   harmonic_pe(pos) = phi.fold(pos * 7 + 1)
#       Maps a position to its nearest Fibonacci attractor.
#       The attractor set is FINITE (~14 attractors in the int range
#       we use), so positions WILL collide once the sequence is long
#       enough. The question is whether the collisions are "structured"
#       (positions K apart collide predictably) or "chaotic".
#
#   sin_pe(pos) = to_int(1000.0 * sin(pos * 2*pi / 17.0)) + 1000
#       Single-channel sinusoidal with prime period 17 and quantised
#       to integer for fair comparison. The period bounds the
#       number of distinct values to ~17 (modulo quantisation).
#       Extrapolation past pos=17 produces straight-up wraparound.
#
# Both encodings produce a single integer per position. Distinctness
# at sequence length L is measured by:
#
#   1. unique values  — how many of L positions map to different codes
#   2. max collisions — the largest group of positions sharing one code
#   3. first collision — the smallest pos at which a code repeats from
#                        an earlier position
#
# A real positional encoding needs `unique values == L`. The point at
# which `first collision < L` is the point at which the scheme breaks
# for "addressable" memory.
#
# Run:
#   ./target/release/omnimcode-standalone experiments/hybrid_llm/experiment_2_positional_encoding.omc
# =============================================================================

# ---------------------------------------------------------------------------
# Encodings
# ---------------------------------------------------------------------------

fn harmonic_pe(pos) -> int {
    return phi.fold(pos * 7 + 1);
}

fn sin_pe(pos) -> int {
    h two_pi = 2.0 * pi();
    h period = 17.0;
    h theta = to_float(pos) * two_pi / period;
    return to_int(1000.0 * sin(theta)) + 1000;
}

# ---------------------------------------------------------------------------
# Distinctness over positions [0, L).
#
# We compute the PE for each position, then naive O(L^2) scan to count:
#   - distinct codes
#   - max group size
#   - first collision position (or L if none)
#
# Returns [unique_codes, max_group, first_collision].
# ---------------------------------------------------------------------------
fn analyse_pe(L, which) -> array {
    h codes = arr_new(L, 0);
    h i = 0;
    while i < L {
        h c = 0;
        if which == 0 { c = harmonic_pe(i); }
        if which == 1 { c = sin_pe(i); }
        arr_set(codes, i, c);
        i = i + 1;
    }

    # Count unique codes via O(L^2) — fine for L <= 64.
    h unique = 0;
    h max_group = 0;
    h first_collision = L;
    h ii = 0;
    while ii < L {
        h is_unique = 1;
        h group = 1;
        h jj = 0;
        while jj < L {
            if jj != ii {
                if arr_get(codes, jj) == arr_get(codes, ii) {
                    group = group + 1;
                    if jj < ii {
                        # ii is a collision against an earlier position.
                        is_unique = 0;
                        if ii < first_collision { first_collision = ii; }
                    }
                }
            }
            jj = jj + 1;
        }
        if is_unique == 1 { unique = unique + 1; }
        if group > max_group { max_group = group; }
        ii = ii + 1;
    }

    h out = arr_new(3, 0);
    arr_set(out, 0, unique);
    arr_set(out, 1, max_group);
    arr_set(out, 2, first_collision);
    return out;
}

# ---------------------------------------------------------------------------
# Sweep sequence length and tabulate distinctness.
# ---------------------------------------------------------------------------
print("== Experiment 2: positional-encoding distinctness vs sequence length ==");
print("");
print("L     | harmonic (unique / max_group / first_collision) | sinusoidal (unique / max_group / first_collision)");
print("------+--------------------------------------------------+----------------------------------------------------");

h lengths = [8, 14, 17, 22, 32, 48, 64];
h n_lens = arr_len(lengths);
h li = 0;
while li < n_lens {
    h L = arr_get(lengths, li);
    h h_stats = analyse_pe(L, 0);
    h s_stats = analyse_pe(L, 1);
    print(concat_many(
        "  ", L,
        "  |       ", arr_get(h_stats, 0), " / ", arr_get(h_stats, 1), " / ", arr_get(h_stats, 2),
        "                       |     ", arr_get(s_stats, 0), " / ", arr_get(s_stats, 1), " / ", arr_get(s_stats, 2)
    ));
    li = li + 1;
}
print("");

# ---------------------------------------------------------------------------
# Practical task: positional lookup.
#   Given a sequence of 8 tokens and a query position k, retrieve token[k].
#   "Retrieval" works by combining each token with its PE, then matching
#   against (sentinel_token, pe(k)). Whichever stored pair matches the
#   target PE wins. If two positions share a PE, the wrong token can win.
#
#   We run this at L=8 (where both PEs should be distinct) and L=24
#   (well past sin's period and within harmonic's small attractor set).
# ---------------------------------------------------------------------------

fn vocab_token(i) -> int {
    # Small fixed vocab for the lookup task — Fibonacci attractors again.
    if i == 0 { return 1; }
    if i == 1 { return 2; }
    if i == 2 { return 3; }
    if i == 3 { return 5; }
    if i == 4 { return 8; }
    if i == 5 { return 13; }
    if i == 6 { return 21; }
    if i == 7 { return 34; }
    if i == 8 { return 55; }
    if i == 9 { return 89; }
    if i == 10 { return 144; }
    if i == 11 { return 233; }
    return 1;
}

# A "lookup" head: for each stored (token, pe(stored_pos)), pick the one
# whose pe(stored_pos) is closest to pe(query). Ties broken by first.
fn lookup(tokens, n, query_pos, which_pe) -> int {
    h target_code = 0;
    if which_pe == 0 { target_code = harmonic_pe(query_pos); }
    if which_pe == 1 { target_code = sin_pe(query_pos); }

    h best_idx = 0;
    h best_diff = 999999;
    h i = 0;
    while i < n {
        h stored_code = 0;
        if which_pe == 0 { stored_code = harmonic_pe(i); }
        if which_pe == 1 { stored_code = sin_pe(i); }
        h d = stored_code - target_code;
        if d < 0 { d = 0 - d; }
        if d < best_diff {
            best_diff = d;
            best_idx = i;
        }
        i = i + 1;
    }
    return arr_get(tokens, best_idx);
}

fn run_lookup_suite(L) {
    print(concat_many("-- Lookup task at L=", L, " (token = vocab[i]) --"));
    h tokens = arr_new(L, 0);
    h i = 0;
    while i < L {
        arr_set(tokens, i, vocab_token(i));   # deterministic: token[i] = vocab[i]
        i = i + 1;
    }

    h h_correct = 0;
    h s_correct = 0;
    h k = 0;
    while k < L {
        h truth = arr_get(tokens, k);
        h h_got = lookup(tokens, L, k, 0);
        h s_got = lookup(tokens, L, k, 1);
        if h_got == truth { h_correct = h_correct + 1; }
        if s_got == truth { s_correct = s_correct + 1; }
        k = k + 1;
    }
    print(concat_many("  harmonic_pe:   ", h_correct, " / ", L, " positions retrieved correctly"));
    print(concat_many("  sin_pe:        ", s_correct, " / ", L, " positions retrieved correctly"));
    print("");
}

run_lookup_suite(8);
run_lookup_suite(14);
run_lookup_suite(24);
run_lookup_suite(48);

print("== Interpretation ==");
print("");
print("Distinctness table:");
print("  - harmonic_pe collides EARLY. phi.fold has ~14 attractors in this");
print("    range, so once we ask for >14 positions, codes must repeat.");
print("    first_collision tells us at what L this kicks in.");
print("  - sin_pe with period 17 should be roughly distinct up to L=17");
print("    then wrap. Quantisation can cause earlier collisions if two");
print("    sin values land in the same int bucket.");
print("");
print("Lookup table:");
print("  - At L=8, both PEs should retrieve perfectly (one code per position).");
print("  - At L=14, harmonic is at the edge of its attractor budget.");
print("  - At L=24, sin starts wrapping (24 > 17) — positions k and k+17");
print("    collide and the wrong token wins.");
print("  - At L=48, both should be heavily degraded but in different ways:");
print("    sin wraps cleanly, harmonic collapses to a few attractor buckets.");
print("");
print("If harmonic_pe collides badly at modest L, the harmonic positional");
print("scheme is NOT a drop-in for sinusoidal — you'd need a multi-channel");
print("variant (several phi.fold(pos*k_i)) to get a unique per-position");
print("vector. That extension is experiment 3.");
print("== End ==");

# =============================================================================
# Experiment 3 — Multi-channel positional encoding under length extrapolation.
#
# Experiment 2 used single-integer codes and a closest-int lookup metric,
# which favours monotonic-saturating encodings (harmonic) over periodic
# ones (sinusoidal). That's not how real transformers use PE — they
# concatenate multiple channels and compute similarity over the full
# vector.
#
# This experiment makes the comparison apples-to-apples:
#
#   harmonic_pe(pos) = [
#       phi.fold(pos * 7  + 1),
#       phi.fold(pos * 11 + 1),
#       phi.fold(pos * 13 + 1),
#       phi.fold(pos * 17 + 1),
#   ]
#       Four channels with prime multipliers. Each channel saturates
#       at the largest Fibonacci attractor in range, but at DIFFERENT
#       positions, so the joint vector stays distinguishable past the
#       single-channel saturation point.
#
#   sinusoidal_pe(pos) = [
#       to_int(1000 * sin(2π·pos / 8)),
#       to_int(1000 * cos(2π·pos / 8)),
#       to_int(1000 * sin(2π·pos / 64)),
#       to_int(1000 * cos(2π·pos / 64)),
#   ]
#       Four channels, two geometric periods (8 and 64) — the
#       transformer paper's geometric-frequency layout, scaled to a
#       small d_model.
#
# Lookup uses squared L2 distance over the 4-vector. We sweep L from
# 8 to 200 and measure:
#   - distinctness (number of unique 4-vectors)
#   - lookup recovery rate (queries that retrieve the correct token)
#
# The hypothesis from experiment 2 is that multi-channel sinusoidal
# RECOVERS the win because L2 over the long-period channel keeps
# positions distinguishable past the short period's wrap. If that
# holds, the harmonic substrate doesn't actually beat sinusoidal at
# this task — experiment 2's harmonic win was a metric artefact.
#
# Run:
#   ./target/release/omnimcode-standalone experiments/hybrid_llm/experiment_3_multichannel_pe.omc
# =============================================================================

h D = 4;       # vector dimension (number of channels)

# ---------------------------------------------------------------------------
# Multi-channel encodings. Each returns an array of length D.
# ---------------------------------------------------------------------------

fn harmonic_pe(pos) -> array {
    h v = arr_new(D, 0);
    arr_set(v, 0, phi.fold(pos * 7  + 1));
    arr_set(v, 1, phi.fold(pos * 11 + 1));
    arr_set(v, 2, phi.fold(pos * 13 + 1));
    arr_set(v, 3, phi.fold(pos * 17 + 1));
    return v;
}

fn sin_channel(pos, period) -> int {
    h two_pi = 2.0 * pi();
    h theta = to_float(pos) * two_pi / to_float(period);
    return to_int(1000.0 * sin(theta));
}

fn cos_channel(pos, period) -> int {
    h two_pi = 2.0 * pi();
    h theta = to_float(pos) * two_pi / to_float(period);
    return to_int(1000.0 * cos(theta));
}

fn sinusoidal_pe(pos) -> array {
    h v = arr_new(D, 0);
    arr_set(v, 0, sin_channel(pos, 8));
    arr_set(v, 1, cos_channel(pos, 8));
    arr_set(v, 2, sin_channel(pos, 64));
    arr_set(v, 3, cos_channel(pos, 64));
    return v;
}

# ---------------------------------------------------------------------------
# Squared L2 distance between two D-vectors. Squared = monotonic in
# distance, so it's good enough for argmin.
# ---------------------------------------------------------------------------
fn l2sq(a, b) -> int {
    h s = 0;
    h i = 0;
    while i < D {
        h d = arr_get(a, i) - arr_get(b, i);
        s = s + (d * d);
        i = i + 1;
    }
    return s;
}

# Test whether two D-vectors are exactly equal.
fn vec_eq(a, b) -> int {
    h i = 0;
    while i < D {
        if arr_get(a, i) != arr_get(b, i) { return 0; }
        i = i + 1;
    }
    return 1;
}

# ---------------------------------------------------------------------------
# Count unique vectors among the L stored vectors (O(L^2 D)).
# `which` 0 = harmonic, 1 = sinusoidal.
# ---------------------------------------------------------------------------
fn count_unique(L, which) -> int {
    h unique = 0;
    h i = 0;
    while i < L {
        h vi = arr_new(D, 0);
        if which == 0 { vi = harmonic_pe(i); }
        if which == 1 { vi = sinusoidal_pe(i); }
        h is_first = 1;
        h j = 0;
        while j < i {
            h vj = arr_new(D, 0);
            if which == 0 { vj = harmonic_pe(j); }
            if which == 1 { vj = sinusoidal_pe(j); }
            if vec_eq(vi, vj) == 1 { is_first = 0; }
            j = j + 1;
        }
        if is_first == 1 { unique = unique + 1; }
        i = i + 1;
    }
    return unique;
}

# ---------------------------------------------------------------------------
# Vocabulary for the lookup task.
# ---------------------------------------------------------------------------
fn vocab_token(i) -> int {
    h base = i % 12;
    if base == 0 { return 1; }
    if base == 1 { return 2; }
    if base == 2 { return 3; }
    if base == 3 { return 5; }
    if base == 4 { return 8; }
    if base == 5 { return 13; }
    if base == 6 { return 21; }
    if base == 7 { return 34; }
    if base == 8 { return 55; }
    if base == 9 { return 89; }
    if base == 10 { return 144; }
    if base == 11 { return 233; }
    return 1;
}

# ---------------------------------------------------------------------------
# Lookup head: for each stored position 0..L-1, compute its PE vector,
# compare to the query PE vector by squared L2, return the token at
# argmin position. Ties broken by first occurrence.
# ---------------------------------------------------------------------------
fn lookup(tokens, L, query_pos, which) -> int {
    h q = arr_new(D, 0);
    if which == 0 { q = harmonic_pe(query_pos); }
    if which == 1 { q = sinusoidal_pe(query_pos); }

    h best_idx = 0;
    h best_d = -1;
    h i = 0;
    while i < L {
        h vi = arr_new(D, 0);
        if which == 0 { vi = harmonic_pe(i); }
        if which == 1 { vi = sinusoidal_pe(i); }
        h d = l2sq(vi, q);
        if best_d < 0 {
            best_d = d;
            best_idx = i;
        } else {
            if d < best_d {
                best_d = d;
                best_idx = i;
            }
        }
        i = i + 1;
    }
    return arr_get(tokens, best_idx);
}

# Run the full L-position lookup suite and return [harmonic_correct,
# sinusoidal_correct] as a small array.
fn run_lookup_suite(L) -> array {
    h tokens = arr_new(L, 0);
    h i = 0;
    while i < L {
        arr_set(tokens, i, vocab_token(i));
        i = i + 1;
    }
    h h_correct = 0;
    h s_correct = 0;
    h k = 0;
    while k < L {
        h truth = arr_get(tokens, k);
        if lookup(tokens, L, k, 0) == truth { h_correct = h_correct + 1; }
        if lookup(tokens, L, k, 1) == truth { s_correct = s_correct + 1; }
        k = k + 1;
    }
    h out = arr_new(2, 0);
    arr_set(out, 0, h_correct);
    arr_set(out, 1, s_correct);
    return out;
}

# ---------------------------------------------------------------------------
# Run the sweep.
# ---------------------------------------------------------------------------
print("== Experiment 3: 4-channel positional encoding under length extrapolation ==");
print(concat_many("D = ", D, "; harmonic primes = [7, 11, 13, 17]; sinusoidal periods = [8, 64]"));
print("");
print("L     | harmonic (unique / lookup correct) | sinusoidal (unique / lookup correct)");
print("------+------------------------------------+--------------------------------------");

h lengths = [8, 16, 32, 48, 64, 96, 128, 200];
h nL = arr_len(lengths);
h li = 0;
while li < nL {
    h L = arr_get(lengths, li);
    h h_unique = count_unique(L, 0);
    h s_unique = count_unique(L, 1);
    h lookup_out = run_lookup_suite(L);
    h h_corr = arr_get(lookup_out, 0);
    h s_corr = arr_get(lookup_out, 1);
    print(concat_many(
        "  ", L,
        "   |         ", h_unique, " / ", h_corr, " / ", L,
        "          |          ", s_unique, " / ", s_corr, " / ", L
    ));
    li = li + 1;
}
print("");

# ---------------------------------------------------------------------------
# Crossover analysis: at what L does each encoding's UNIQUE count
# stop growing? (i.e., when has the encoding "saturated"?)
# ---------------------------------------------------------------------------
print("== Saturation summary ==");

# Find the smallest L at which unique(L) < L for each scheme.
fn first_saturation(which) -> int {
    h L = 1;
    while L <= 256 {
        if count_unique(L, which) < L { return L; }
        L = L + 1;
    }
    return -1;
}

h h_sat = first_saturation(0);
h s_sat = first_saturation(1);
print(concat_many("harmonic_pe   first L with unique < L: ", h_sat));
print(concat_many("sinusoidal_pe first L with unique < L: ", s_sat));
print("");

# ---------------------------------------------------------------------------
# Interpretation.
# ---------------------------------------------------------------------------
print("== Interpretation ==");
print("");
print("If harmonic_pe saturates LATER than experiment 2's single-channel did");
print("(it should — the 4 prime-multiplier channels saturate independently),");
print("the multi-channel approach genuinely buys length-extrapolation room.");
print("");
print("If sinusoidal_pe stays distinct longer than its short period (8) would");
print("suggest, that's the long-period channel (64) doing its job. This is the");
print("classic transformer-PE story: geometric frequencies layered to span a");
print("wide range of positions with a small vector.");
print("");
print("If the lookup-correct numbers track unique counts on both sides, the");
print("L2-vector metric is doing what it should — distinguishability translates");
print("to retrieval. If lookup correct < unique, there's tie-breaking ambiguity");
print("(two distinct vectors equidistant from the query).");
print("");
print("The key crossover from experiment 2 to verify: at L=48, single-channel");
print("harmonic beat single-channel sinusoidal (38 vs 26). Does the 4-channel");
print("comparison restore sinusoidal's lead (the metric-artefact hypothesis),");
print("or does harmonic STILL win (a genuine structural property)?");
print("== End ==");

# =============================================================================
# Experiment 4 — Harmonic OOD gate vs L2-nearest-neighbour baseline.
#
# The pivot from experiments 0-3: stop trying to substitute transformer
# components with harmonic ones. The harmonic substrate's documented
# strength is multi-dim STRUCTURAL ANOMALY DETECTION (per the README's
# credential-stuffing benchmark: 10/10 vs IsolationForest's 7/10).
#
# An OOD gate is an instance of exactly that task: given a feature
# vector, decide whether it came from the in-distribution corpus or
# from somewhere else. Useful as an auxiliary signal on top of a
# transformer — flag inputs the main model shouldn't be confident
# about.
#
# Setup:
#   D = 4 feature dims.
#   Reference set: 300 in-distribution vectors. Each dim sampled
#     from a non-uniform discrete distribution biased toward small
#     Fibonacci attractors: 60% small {1,2,3,5,8}, 30% medium
#     {13,21,34}, 10% large {55,89}. Mimics the kind of skewed
#     distribution real LM activations have.
#   In-dist test set:  150 fresh draws from the same distribution.
#   OOD test set:      150 vectors with each dim uniform on [1, 90].
#
# Two gates:
#
#   harmonic_gate(vec):
#       per-dim score = -log(freq[phi.fold(vec[d])] / n_ref)
#       gate_score    = sum over dims (subspace anomaly, same as
#                       examples/lib/harmonic_anomaly.omc)
#       Higher = more OOD.
#
#   l2_baseline_gate(vec):
#       gate_score    = min over reference points of L2(vec, ref)
#       Higher = more OOD.
#
# Metrics:
#   - AUROC (rank-based: for each pair of in-dist test, OOD test,
#     count how often score(OOD) > score(in-dist)).
#   - TPR @ FPR = 10% and TPR @ FPR = 1% (the regimes where an
#     OOD gate is operationally useful — you can only afford to
#     refuse a small fraction of in-dist queries).
#
# Run:
#   ./target/release/omnimcode-standalone experiments/hybrid_llm/experiment_4_ood_gate.omc
# =============================================================================

h D = 4;

# ---------------------------------------------------------------------------
# Data generation.
#
# In-dist: each dim drawn from a 3-tier non-uniform distribution over
# Fibonacci attractors. Mimics "activations cluster around a few
# learned modes with rare large excursions".
#
# OOD: each dim uniform random on [1, 90]. Same magnitude range as
# in-dist but no harmonic structure.
# ---------------------------------------------------------------------------

fn sample_in_dist_value() -> int {
    h tier = random_int(0, 99);
    if tier < 60 {
        # small attractors
        h pick = random_int(0, 4);
        if pick == 0 { return 1; }
        if pick == 1 { return 2; }
        if pick == 2 { return 3; }
        if pick == 3 { return 5; }
        return 8;
    }
    if tier < 90 {
        # medium attractors
        h pick = random_int(0, 2);
        if pick == 0 { return 13; }
        if pick == 1 { return 21; }
        return 34;
    }
    # large attractors
    h pick = random_int(0, 1);
    if pick == 0 { return 55; }
    return 89;
}

fn sample_in_dist_vec() -> array {
    h v = arr_new(D, 0);
    h d = 0;
    while d < D {
        arr_set(v, d, sample_in_dist_value());
        d = d + 1;
    }
    return v;
}

fn sample_ood_vec() -> array {
    h v = arr_new(D, 0);
    h d = 0;
    while d < D {
        arr_set(v, d, random_int(1, 90));
        d = d + 1;
    }
    return v;
}

# ---------------------------------------------------------------------------
# Build reference and test sets.
# ---------------------------------------------------------------------------

random_seed(7);

h N_REF = 300;
h N_IN_TEST = 150;
h N_OOD_TEST = 150;

fn build_set(n, gen_kind) -> array {
    h xs = arr_new(n, 0);
    h i = 0;
    while i < n {
        h v = arr_new(D, 0);
        if gen_kind == 0 { v = sample_in_dist_vec(); }
        if gen_kind == 1 { v = sample_ood_vec(); }
        arr_set(xs, i, v);
        i = i + 1;
    }
    return xs;
}

h ref_set      = build_set(N_REF,      0);
h in_dist_test = build_set(N_IN_TEST,  0);
h ood_test     = build_set(N_OOD_TEST, 1);

# ---------------------------------------------------------------------------
# HARMONIC GATE
#
# Per-dim frequency table over phi.fold(value) bucket.
# Score(vec) = sum_d (-log(freq[fold(vec[d])] / N_REF)).
# Higher score = rarer bucket pattern = more OOD.
# ---------------------------------------------------------------------------

fn fit_freqs(corpus) -> array {
    # Returns an array of D dicts, one per dim. Each dict maps
    # bucket_value_as_string → count.
    h freqs = arr_new(D, 0);
    h d = 0;
    while d < D {
        arr_set(freqs, d, dict_new());
        d = d + 1;
    }

    h n = arr_len(corpus);
    h i = 0;
    while i < n {
        h vec = arr_get(corpus, i);
        h di = 0;
        while di < D {
            h b = phi.fold(arr_get(vec, di));
            h key = concat_many("", b);
            h fd = arr_get(freqs, di);
            h prior = dict_get(fd, key, 0);
            dict_set(fd, key, prior + 1);
            di = di + 1;
        }
        i = i + 1;
    }
    return freqs;
}

fn harmonic_score(vec, freqs, n_ref) -> float {
    h total = 0.0;
    h d = 0;
    while d < D {
        h b = phi.fold(arr_get(vec, d));
        h key = concat_many("", b);
        h fd = arr_get(freqs, d);
        h count = dict_get(fd, key, 0);
        # Add-one smoothing: never let count = 0 produce -log(0).
        h p = to_float(count + 1) / to_float(n_ref + 1);
        total = total + (0.0 - log(p));
        d = d + 1;
    }
    return total;
}

# ---------------------------------------------------------------------------
# L2 BASELINE GATE
#
# Score(vec) = min over reference points of squared L2 distance.
# Squared = monotonic, fine for ranking.
# ---------------------------------------------------------------------------

fn l2_score(vec, ref_corpus) -> float {
    h n = arr_len(ref_corpus);
    h best = -1.0;
    h i = 0;
    while i < n {
        h ref = arr_get(ref_corpus, i);
        h s = 0.0;
        h d = 0;
        while d < D {
            h diff = to_float(arr_get(vec, d) - arr_get(ref, d));
            s = s + (diff * diff);
            d = d + 1;
        }
        if best < 0.0 { best = s; }
        if s < best { best = s; }
        i = i + 1;
    }
    return best;
}

# ---------------------------------------------------------------------------
# Score everything.
# ---------------------------------------------------------------------------

h freqs = fit_freqs(ref_set);

fn score_all_harmonic(xs, freqs, n_ref) -> array {
    h n = arr_len(xs);
    h out = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(out, i, harmonic_score(arr_get(xs, i), freqs, n_ref));
        i = i + 1;
    }
    return out;
}

fn score_all_l2(xs, ref_corpus) -> array {
    h n = arr_len(xs);
    h out = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(out, i, l2_score(arr_get(xs, i), ref_corpus));
        i = i + 1;
    }
    return out;
}

print("== Experiment 4: harmonic OOD gate vs L2-NN baseline ==");
print(concat_many("D=", D, " N_REF=", N_REF, " N_IN_TEST=", N_IN_TEST, " N_OOD_TEST=", N_OOD_TEST));
print("");
print("Scoring (this is O(N_TEST * N_REF) for L2 — be patient)...");

h h_in   = score_all_harmonic(in_dist_test, freqs, N_REF);
h h_ood  = score_all_harmonic(ood_test,     freqs, N_REF);
h l2_in  = score_all_l2(in_dist_test, ref_set);
h l2_ood = score_all_l2(ood_test,     ref_set);

# ---------------------------------------------------------------------------
# AUROC via rank-based formula.
# AUROC = P(score_ood > score_in), estimated by counting ordered pairs.
# Ties contribute 0.5.
# ---------------------------------------------------------------------------

fn auroc(in_scores, ood_scores) -> float {
    h n_in = arr_len(in_scores);
    h n_ood = arr_len(ood_scores);
    h correct = 0;
    h ties = 0;
    h i = 0;
    while i < n_in {
        h sin = arr_get(in_scores, i);
        h j = 0;
        while j < n_ood {
            h sood = arr_get(ood_scores, j);
            if sood > sin { correct = correct + 1; }
            if sood == sin { ties = ties + 1; }
            j = j + 1;
        }
        i = i + 1;
    }
    h total = n_in * n_ood;
    h num = to_float(correct) + (0.5 * to_float(ties));
    return num / to_float(total);
}

h harmonic_auroc = auroc(h_in, h_ood);
h l2_auroc       = auroc(l2_in, l2_ood);

print("");
print(concat_many("AUROC harmonic gate: ", harmonic_auroc));
print(concat_many("AUROC L2 baseline:   ", l2_auroc));
print("");

# ---------------------------------------------------------------------------
# TPR @ fixed FPR.
#
# Method: pick the threshold such that EXACTLY `target_fpr * N_IN_TEST`
# in-dist scores exceed it. Then count what fraction of OOD scores
# exceed the same threshold = TPR.
#
# We sort the in-dist scores via a simple selection-sort (O(n^2), fine
# for N=150) to find the cutoff.
# ---------------------------------------------------------------------------

fn sort_floats_ascending(xs) -> array {
    h n = arr_len(xs);
    h out = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(out, i, arr_get(xs, i));
        i = i + 1;
    }
    # Insertion sort — quadratic but tiny n.
    h k = 1;
    while k < n {
        h cur = arr_get(out, k);
        h j = k - 1;
        h placed = 0;
        while j >= 0 {
            if placed == 0 {
                if arr_get(out, j) > cur {
                    arr_set(out, j + 1, arr_get(out, j));
                    j = j - 1;
                } else {
                    arr_set(out, j + 1, cur);
                    placed = 1;
                    j = -1;
                }
            }
        }
        if placed == 0 { arr_set(out, 0, cur); }
        k = k + 1;
    }
    return out;
}

fn mean_of(xs) -> float {
    h n = arr_len(xs);
    h s = 0.0;
    h i = 0;
    while i < n {
        s = s + arr_get(xs, i);
        i = i + 1;
    }
    return s / to_float(n);
}

fn tpr_at_fpr(in_scores, ood_scores, target_fpr) -> float {
    h n_in = arr_len(in_scores);
    h n_ood = arr_len(ood_scores);
    h sorted_in = sort_floats_ascending(in_scores);

    # We want threshold such that approx target_fpr fraction of in-dist
    # exceeds it. Equivalently, threshold = (1 - target_fpr)-quantile.
    h k = to_int(to_float(n_in) * (1.0 - target_fpr));
    if k < 0 { k = 0; }
    if k >= n_in { k = n_in - 1; }
    h threshold = arr_get(sorted_in, k);

    h tp = 0;
    h j = 0;
    while j < n_ood {
        if arr_get(ood_scores, j) > threshold { tp = tp + 1; }
        j = j + 1;
    }
    return to_float(tp) / to_float(n_ood);
}

print("Operating points (TPR at fixed FPR):");
print(concat_many("  harmonic gate, TPR @ FPR=10%: ", tpr_at_fpr(h_in,  h_ood,  0.10)));
print(concat_many("  L2 baseline,   TPR @ FPR=10%: ", tpr_at_fpr(l2_in, l2_ood, 0.10)));
print(concat_many("  harmonic gate, TPR @ FPR=5%:  ", tpr_at_fpr(h_in,  h_ood,  0.05)));
print(concat_many("  L2 baseline,   TPR @ FPR=5%:  ", tpr_at_fpr(l2_in, l2_ood, 0.05)));
print(concat_many("  harmonic gate, TPR @ FPR=1%:  ", tpr_at_fpr(h_in,  h_ood,  0.01)));
print(concat_many("  L2 baseline,   TPR @ FPR=1%:  ", tpr_at_fpr(l2_in, l2_ood, 0.01)));
print("");

# ===========================================================================
# Scenario B: magnitude-matched structural OOD.
#
# Scenario A above gave L2 a trivial advantage: OOD values are uniform on
# [1, 90] while in-dist is heavily biased toward small attractors. L2
# separates by mean magnitude; the harmonic gate can't because phi.fold
# discards magnitude info above the attractor ceiling.
#
# Real LM activations are layer-normalised — the magnitude signal that
# L2 leans on here doesn't exist there. To simulate that, scenario B
# matches the marginal distribution per dim but DIFFERENT per-dim
# weights:
#
#   In-dist:  60% small / 30% medium / 10% large (same as scenario A)
#   Hard OOD: 10% small / 30% medium / 60% large  (INVERTED weights)
#
# Both draw from the same attractor set. Mean magnitudes differ less.
# A per-dim rarity gate that's seen the in-dist frequency table should
# light up on OOD because each dim's value distribution looks shifted;
# L2 has a softer separation because the value sets overlap.
# ===========================================================================

fn sample_hard_ood_value() -> int {
    h tier = random_int(0, 99);
    if tier < 10 {
        # small attractors — rare now
        h pick = random_int(0, 4);
        if pick == 0 { return 1; }
        if pick == 1 { return 2; }
        if pick == 2 { return 3; }
        if pick == 3 { return 5; }
        return 8;
    }
    if tier < 40 {
        # medium attractors — same weight
        h pick = random_int(0, 2);
        if pick == 0 { return 13; }
        if pick == 1 { return 21; }
        return 34;
    }
    # large attractors — common now
    h pick = random_int(0, 1);
    if pick == 0 { return 55; }
    return 89;
}

fn sample_hard_ood_vec() -> array {
    h v = arr_new(D, 0);
    h d = 0;
    while d < D {
        arr_set(v, d, sample_hard_ood_value());
        d = d + 1;
    }
    return v;
}

h hard_ood_test = arr_new(N_OOD_TEST, 0);
h hi = 0;
while hi < N_OOD_TEST {
    arr_set(hard_ood_test, hi, sample_hard_ood_vec());
    hi = hi + 1;
}

h h_hard  = score_all_harmonic(hard_ood_test, freqs, N_REF);
h l2_hard = score_all_l2(hard_ood_test, ref_set);

h harmonic_auroc_B = auroc(h_in,  h_hard);
h l2_auroc_B       = auroc(l2_in, l2_hard);

print("== Scenario B: magnitude-matched structural OOD (inverted attractor weights) ==");
print(concat_many("AUROC harmonic gate: ", harmonic_auroc_B));
print(concat_many("AUROC L2 baseline:   ", l2_auroc_B));
print("");
print("Operating points (TPR at fixed FPR):");
print(concat_many("  harmonic gate, TPR @ FPR=10%: ", tpr_at_fpr(h_in,  h_hard,  0.10)));
print(concat_many("  L2 baseline,   TPR @ FPR=10%: ", tpr_at_fpr(l2_in, l2_hard, 0.10)));
print(concat_many("  harmonic gate, TPR @ FPR=5%:  ", tpr_at_fpr(h_in,  h_hard,  0.05)));
print(concat_many("  L2 baseline,   TPR @ FPR=5%:  ", tpr_at_fpr(l2_in, l2_hard, 0.05)));
print(concat_many("  harmonic gate, TPR @ FPR=1%:  ", tpr_at_fpr(h_in,  h_hard,  0.01)));
print(concat_many("  L2 baseline,   TPR @ FPR=1%:  ", tpr_at_fpr(l2_in, l2_hard, 0.01)));
print("");
print(concat_many("Mean harmonic score, hard OOD:  ", mean_of(h_hard)));
print(concat_many("Mean L2 score, hard OOD:        ", mean_of(l2_hard)));
print("");

# ---------------------------------------------------------------------------
# Score distribution summaries (so we can sanity-check the AUROC).
