fn run_chain_traced_with_phi_fib(initial_state, keys, alive_mask) -> int {
    h packed = alive_keys_and_ops(alive_mask);
    h alive_keys = arr_get(packed, 0);
    h alive_ops  = arr_get(packed, 1);

    h state = initial_state;
    h n = arr_len(keys);
    h i = 0;
    while i < n {
        h target = arr_get(keys, i);
        h idx = phi_pi_fib_nearest(alive_keys, target);
        if idx >= 0 {
            h actual_key = arr_get(alive_keys, idx);
            h op = arr_get(alive_ops, idx);
            h prev = state;
            state = apply_op(op, state);
