        if which == 1 { r = phi_pi_fib_search_v2(arr, target); }
        if which == 2 { r = phi_pi_bin_search(arr, target); }
        k = k + 1;
    }
    h s = phi_pi_fib_stats();
    return to_float(arr_get(s, 1)) / to_float(arr_get(s, 0));
}

