fn build_big_table(n) -> array {
    h arr = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(arr, i, (i + 1) * (i + 1));
        i = i + 1;
    }
    return arr;
}

h BIG = build_big_table(200);

random_seed(42);
h compares_lin_big = 0;
h compares_bin_big = 0;
h compares_fib_big = 0;
h q = 0;
while q < 200 {
    h x = random_int(0, 40000);

    # Linear scan over BIG
    h li = 0;
    while li < 200 {
        compares_lin_big = compares_lin_big + 1;
        li = li + 1;
    }

    # Binary search
    phi_pi_fib_reset();
    h _bi = phi_pi_bin_search(BIG, x);
    h sb = phi_pi_fib_stats();
    compares_bin_big = compares_bin_big + arr_get(sb, 1);

    # Phi-pi-fib search
