# ---- 2. Multi-dim harmonic detector (subspace anomaly version) ----------
# Naive tuple-frequency loses on structural attacks: 50 identical
# credential-stuffing tuples have count=50, look "common". The right
# approach is SUBSPACE anomaly detection — score by how many DIMS the
# event sits in the tail of, weighted by rarity per dim.
#
# Method:
#   1. For each dim, build a frequency histogram over its attractor buckets.
#   2. For each event, compute per-dim "rarity" = -log(p_bucket).
#      Common buckets → 0; rare buckets → high.
#   3. Total score = SUM of per-dim rarities. The credential-stuffing
#      pattern (rare-ish on 4 dims simultaneously) scores higher than
#      noise events (very rare on 1 dim, common on rest).

fn lat_bucket(v) {
    if v <= 0 { return 0; }
    # Substrate-routed log bucketing. Was py_call(math, "log10", v)
    # before the substrate-fill-in; routing through the φ-π-fibonacci
    # substrate aligns the bucket cuts with OMC's attractor lattice.
    h logv = log_phi_pi_fibonacci(to_float(v));
    return fold(to_int(logv * 50));
}
fn status_bucket(s) { return s; }
fn endpoint_bucket(e) { return e; }
fn hour_bucket(hr) { return fold(hr); }

# Build per-dim frequency tables. Inline the bucket fn so we don't go
# through py_callback (which can interact oddly with this re-entrancy
# pattern — saw harmonic flatten to picking idx=0..9 when callbacks
# were used).
h lat_freq = {};
h k_lf = 0;
while k_lf < n_total {
    h bkt = lat_bucket(arr_get(all_lat, k_lf));
    h key = concat_many("", bkt);
    dict_set(lat_freq, key, dict_get(lat_freq, key, 0) + 1);
    k_lf += 1;
}
h status_freq = {};
h k_sf = 0;
while k_sf < n_total {
    h key = concat_many("", arr_get(all_status, k_sf));
    dict_set(status_freq, key, dict_get(status_freq, key, 0) + 1);
    k_sf += 1;
}
h endpoint_freq = {};
h k_ef = 0;
while k_ef < n_total {
    h key = concat_many("", arr_get(all_endpoints, k_ef));
    dict_set(endpoint_freq, key, dict_get(endpoint_freq, key, 0) + 1);
    k_ef += 1;
}
h hour_freq = {};
h k_hf = 0;
while k_hf < n_total {
    h key = concat_many("", hour_bucket(arr_get(all_hours, k_hf)));
    dict_set(hour_freq, key, dict_get(hour_freq, key, 0) + 1);
    k_hf += 1;
}

println(concat_many("dim diversity: lat=", dict_len(lat_freq),
    " status=", dict_len(status_freq),
    " endpoint=", dict_len(endpoint_freq),
    " hour=", dict_len(hour_freq), " buckets"));

# -log(p) for one dim: high when bucket count is low.
# Force float division — `int / int` in OMC truncates to int, which
# zeroed every probability and made every score saturate at the same
# fallback value. to_float on the numerator promotes the whole
# expression to float arithmetic.
fn neg_log_p(freq_dict, bucket, total) {
    h count = dict_get(freq_dict, concat_many("", bucket), 1);
    h p = to_float(count) / total;
    if p <= 0 { p = 1.0 / to_float(total); }
    # Substrate-routed rarity: log_phi_pi_fibonacci(1/p) is a monotonic
    # transform of -ln(p), in φ-π-fibonacci units. Ranking preserved.
    return log_phi_pi_fibonacci(1.0 / p);
}

fn harmonic_md_score(idx) {
    h tot = n_total;
    h r1 = neg_log_p(lat_freq,      lat_bucket(arr_get(all_lat, idx)),         tot);
    h r2 = neg_log_p(status_freq,   status_bucket(arr_get(all_status, idx)),   tot);
    h r3 = neg_log_p(endpoint_freq, endpoint_bucket(arr_get(all_endpoints, idx)), tot);
    h r4 = neg_log_p(hour_freq,     hour_bucket(arr_get(all_hours, idx)),       tot);
    return r1 + r2 + r3 + r4;
}

h h_scores = [];
h hi = 0;
while hi < n_total {
    arr_push(h_scores, harmonic_md_score(hi));
    hi += 1;
}

