fn cosine_sim(a, b) {
    h dot = 0.0
    h i = 0
    while i < arr_len(a) {
        dot += a[i] * b[i]
        i += 1
    }
    return dot
}

fn closest_doc(query, docs, texts) {
    h qv = substrate_embed(query, 16)
    h best_score = -2.0
    h best_idx = 0
    h i = 0
    while i < arr_len(docs) {
        h score = cosine_sim(qv, docs[i])
        if score > best_score {
            best_score = score
            best_idx = i
        }
        i += 1
    }
    return texts[best_idx]
}

