# Substrate-native agent — composes fibtier + kernel + protocol + (optional) Prometheus.
#
# An agent is:
#   - identity (sender_id derived from name)
#   - memory (persistent fibtier; ~/.omc/fibtier/<name>/)
#   - knowledge (a dict of fact → response, for the demo's generator)
#   - role (string, used in introductions)
#
# Agents talk over OMC-PROTOCOL: every message is substrate-signed
# (omc_msg_sign), serialized via omc_msg_serialize. Recipients verify
# via omc_msg_verify with no shared key. The wire format and identity
# guarantees come for free from primitives shipped earlier.
#
# Replace knowledge_dispatch with a Prometheus-trained generator
# when you want the agent's responses to come from a substrate-native
# LM. For now, the demo uses a dictionary-driven responder so the
# conversation is intelligible.

import "examples/lib/fibtier_persistent.omc";

# ---------------------------------------------------------------------------
# Identity: substrate-derived sender_id from the agent name.
# ---------------------------------------------------------------------------

fn _agent_sender_id(name) {
    h hval = fnv1a_hash(name);
    # Truncate to 31 bits (positive int32) to match omc_msg_sign expectation.
    h pos = hval - (hval / 2147483648) * 2147483648;
    if pos < 0 { pos = 0 - pos; }
    return pos;
}

# ---------------------------------------------------------------------------
# Agent construction
# ---------------------------------------------------------------------------

fn agent_new(name, role, knowledge_dict, max_tiers) {
    fibtier_persistent_new(name, max_tiers);
    h mem = fibtier_persistent_load(name);
    h agent = dict_new();
    dict_set(agent, "name", name);
    dict_set(agent, "role", role);
    dict_set(agent, "sender_id", _agent_sender_id(name));
    dict_set(agent, "memory", mem);
    dict_set(agent, "knowledge", knowledge_dict);
    return agent;
}

# Reload an existing agent (preserves memory).
fn agent_load(name, role, knowledge_dict) {
    h mem = fibtier_persistent_load(name);
    h agent = dict_new();
    dict_set(agent, "name", name);
    dict_set(agent, "role", role);
    dict_set(agent, "sender_id", _agent_sender_id(name));
    dict_set(agent, "memory", mem);
    dict_set(agent, "knowledge", knowledge_dict);
    return agent;
}

# ---------------------------------------------------------------------------
# Response generator (knowledge-based for the demo)
#
# Looks up the input text against the agent's knowledge dict. If
# nothing matches, returns a substrate-aware "I don't know"-style
# response. Production agents would replace this with a Prometheus
# forward pass over the input + retrieved context from memory.
# ---------------------------------------------------------------------------

fn _agent_respond(agent, input_text) {
    h kn = dict_get(agent, "knowledge");
    # Linear scan; keys are short substrings to match against input.
    h keys = dict_keys(kn);
    h i = 0;
    while i < arr_len(keys) {
        h key = arr_get(keys, i);
        if re_match(key, input_text) == 1 {
            return dict_get(kn, key);
        }
        i += 1;
    }
    # Fallback: query memory for closest related entry.
    h hits = fibtier_query(dict_get(agent, "memory"), input_text, 1);
    if arr_len(hits) > 0 {
        h hit = arr_get(hits, 0);
        h entry = dict_get(hit, "entry");
        return concat_many("That reminds me of: ", dict_get(entry, "content"));
    }
    return concat_many("I haven't encountered \"", input_text, "\" yet.");
}

# ---------------------------------------------------------------------------
# Inter-agent messaging via OMC-PROTOCOL
# ---------------------------------------------------------------------------

# Send a substrate-signed message. Returns the wire-serialized form
# that the recipient deserializes via omc_msg_deserialize.
fn agent_send(agent, content) {
    h KIND_REQUEST = 1;
    h msg = omc_msg_sign(content, dict_get(agent, "sender_id"), KIND_REQUEST);
    return omc_msg_serialize(msg);
}

# Receive a wire message: deserialize, verify signature, push verified
# content into the agent's memory, generate a response, sign + return
# the response wire. This is the full inbound→outbound loop.
fn agent_receive(agent, wire) {
    h msg = omc_msg_deserialize(wire);
    h check = omc_msg_verify(msg);
    if dict_get(check, "valid") != 1 {
        return omc_msg_serialize(
            omc_msg_sign("[INVALID SIGNATURE]", dict_get(agent, "sender_id"), 8)
        );
    }
    h content = dict_get(check, "content");
    h reply_content = _agent_respond(agent, content);
    # Push the Q+A pair into memory.
    h qa = concat_many("Q: ", content, " | A: ", reply_content);
    fibtier_persistent_push(dict_get(agent, "memory"), qa);
    # Sign + serialize the reply.
    h reply_msg = omc_msg_sign(reply_content, dict_get(agent, "sender_id"), 2);
    return omc_msg_serialize(reply_msg);
}

# ---------------------------------------------------------------------------
# Stats
# ---------------------------------------------------------------------------

fn agent_stats(agent) {
    h mem_stats = fibtier_stats(dict_get(agent, "memory"));
    h s = dict_new();
    dict_set(s, "name", dict_get(agent, "name"));
    dict_set(s, "role", dict_get(agent, "role"));
    dict_set(s, "sender_id", dict_get(agent, "sender_id"));
    dict_set(s, "memory_pushes", dict_get(mem_stats, "total_pushes"));
    dict_set(s, "memory_folds", dict_get(mem_stats, "total_folds"));
    dict_set(s, "memory_entries", dict_get(mem_stats, "total_entries"));
    dict_set(s, "memory_occupancy", dict_get(mem_stats, "occupancy"));
    return s;
}

# archaeology.omc — Universal Codebase Archaeologist library
#
# Scans any source directory and surfaces:
#   • Attractor modules  — highest phi-pi-fib density × import gravity
#   • Semantic duplicate clusters  — grouped, not raw pairs
#   • Per-language function surface area
#
# Universality: omc_attractor_density works on ANY text (Python, Rust, JS, …)
# because it tokenizes raw bytes — no OMC parsing required.
# omc_code_similarity and omc_code_valid are used only for .omc files.
#
# Public API:
#   archaeology_scan(base, opts) -> results
#   archaeology_narrate(results, model) -> string (Claude explanation)
#
# opts keys (all optional):
#   "extensions"  -> [".omc"]               which extensions to scan
#   "top_n"       -> 8                       attractor count
#   "threshold"   -> 0.78                    duplicate similarity cutoff
#                    (raise to 0.90+ for Python/Rust — boilerplate inflates similarity)
#   "check_limit" -> 40                      max modules for pairwise dup check
#   "ref_weight"  -> 5.0                     multiplier: import references
#   "fn_weight"   -> 0.5                     multiplier: function count

# ── Helpers ────────────────────────────────────────────────────────────────────

fn _opt(opts, key, default) {
    if dict_has(opts, key) { return dict_get(opts, key) }
    return default
}

fn _short_path(p) {
    h idx = str_rfind(p, "/")
    if idx < 0 { return p }
    h dir_end = str_rfind(str_slice(p, 0, idx), "/")
    if dir_end < 0 { return str_slice(p, idx + 1, str_len(p)) }
    return str_slice(p, dir_end + 1, str_len(p))
}

# ── Language detection ─────────────────────────────────────────────────────────

fn detect_language(path) {
    if str_ends_with(path, ".omc")  { return "omc" }
    if str_ends_with(path, ".py")   { return "python" }
    if str_ends_with(path, ".rs")   { return "rust" }
    if str_ends_with(path, ".ts")   { return "typescript" }
    if str_ends_with(path, ".js")   { return "javascript" }
    if str_ends_with(path, ".go")   { return "go" }
    if str_ends_with(path, ".c")    { return "c" }
    if str_ends_with(path, ".cpp")  { return "cpp" }
    if str_ends_with(path, ".java") { return "java" }
    if str_ends_with(path, ".rb")   { return "ruby" }
    return "other"
}

# ── File discovery ─────────────────────────────────────────────────────────────

fn _find_files(base, extensions) {
    h all = []
    h ei = 0
    while ei < arr_len(extensions) {
        h ext = extensions[ei]
        h found = omc_spawn("find", [base, "-name", "*" + ext,
                                      "-not", "-path", "*node_modules*",
                                      "-not", "-path", "*/.git/*",
                                      "-not", "-path", "*/target/*"])
        if found["ok"] {
            h raw = str_trim(found["stdout"])
            if str_len(raw) > 0 {
                h paths = str_split(raw, "\n")
                h fi = 0
                while fi < arr_len(paths) {
                    h pth = str_trim(paths[fi])
                    if str_len(pth) > 0 {
                        arr_push(all, pth)
                    }
                    fi += 1
                }
            }
        }
        ei += 1
    }
    return all
}

# ── Function counting (language-aware) ────────────────────────────────────────

fn _fn_pattern_for_lang(lang) {
    if lang == "omc"        { return null }            # use native builtin
    if lang == "python"     { return "^def \\|^    def \\|^        def " }
    if lang == "rust"       { return " fn " }
    if lang == "typescript" { return "function \\|=> {\\|): " }
    if lang == "javascript" { return "function \\|=> {" }
    if lang == "go"         { return "^func " }
    if lang == "c"          { return "^[a-zA-Z].*(\\(.*\\).*{" }
    if lang == "cpp"        { return "^[a-zA-Z].*(\\(.*\\).*{\\|^[a-zA-Z].*::" }
    if lang == "java"       { return "(public\\|private\\|protected\\|static).*(\\(.*\\).*{" }
    if lang == "ruby"       { return "^def \\|^  def " }
    return "function\\|def \\|fn \\|func " # generic fallback
}

fn _count_fns(path, content, lang) {
    if lang == "omc" {
        if omc_code_valid(content) {
            return arr_len(omc_code_extract_fns(content))
        }
        return 0
    }
    h pat = _fn_pattern_for_lang(lang)
    if pat == null { return 0 }
    h grep_result = omc_spawn("grep", ["-c", pat, path])
    if !grep_result["ok"] { return 0 }
    h n = str_trim(grep_result["stdout"])
    if str_len(n) == 0 { return 0 }
    return str_to_int(n)
}

# ── Scoring ────────────────────────────────────────────────────────────────────
# omc_attractor_density(text) works on ANY language — no parsing required.
# It tokenizes raw bytes via the OMC tokenizer and returns the fraction of
# token IDs that land on Fibonacci attractors.

fn _score(content) {
    if str_len(content) == 0 { return 0.0 }
    return omc_attractor_density(content)
}

# ── Import/reference counting ─────────────────────────────────────────────────

fn _count_refs(target_path, all_contents) {
    h slash = str_rfind(target_path, "/")
    h basename = if slash >= 0 { str_slice(target_path, slash + 1, str_len(target_path)) } else { target_path }
    h count = 0
    h i = 0
    while i < arr_len(all_contents) {
        if str_contains(all_contents[i], basename) {
            count += 1
        }
        i += 1
    }
    # Subtract 1 for self-reference in the file's own content
    if count > 0 { count -= 1 }
    return count
}

# ── Top-k selection ────────────────────────────────────────────────────────────

fn _top_k(arr, score_key, k) {
    h result = []
    h used   = {}
    h r = 0
    while r < k and r < arr_len(arr) {
        h best_idx = -1
        h best_val = -1.0
        h i = 0
        while i < arr_len(arr) {
            if !dict_has(used, to_string(i)) {
                if arr[i][score_key] > best_val {
                    best_val = arr[i][score_key]
                    best_idx = i
                }
            }
            i += 1
        }
        if best_idx >= 0 {
            dict_set(used, to_string(best_idx), true)
            arr_push(result, arr[best_idx])
        }
        r += 1
    }
    return result
}

# ── Similarity (language-aware) ────────────────────────────────────────────────
# For OMC: structural canonical similarity.
# For everything else: raw text similarity via str_similarity.

fn _module_sim(content_a, lang_a, content_b, lang_b) {
    if lang_a == "omc" and lang_b == "omc" {
        if omc_code_valid(content_a) and omc_code_valid(content_b) {
            return omc_code_similarity(content_a, content_b)
        }
    }
    return str_similarity(content_a, content_b)
}

# ── Duplicate pair detection ───────────────────────────────────────────────────

fn _find_pairs(modules, threshold) {
    h pairs = []
    h i = 0
    while i < arr_len(modules) {
        h j = i + 1
        while j < arr_len(modules) {
            h a = modules[i]
            h b = modules[j]
            if a["hash"] != b["hash"] {
                h sim = _module_sim(a["content"], a["lang"], b["content"], b["lang"])
                if sim >= threshold {
                    arr_push(pairs, {
                        "a":     a["path"],
                        "b":     b["path"],
                        "a_fns": a["fn_count"],
                        "b_fns": b["fn_count"],
                        "sim":   sim
                    })
                }
            }
            j += 1
        }
        i += 1
    }
    return pairs
}

# ── Duplicate clustering (union-find style) ───────────────────────────────────
# Groups individual pairs into connected clusters so version chains like
# v7→v8→v9 appear as ONE group instead of N*(N-1)/2 pairs.

fn cluster_pairs(pairs) {
    h leaders = {}   # path -> leader path
    h groups  = {}   # leader path -> [paths] (Rc-shared, mutated in place)

    h pi = 0
    while pi < arr_len(pairs) {
        h pair  = pairs[pi]
        h a     = pair["a"]
        h b     = pair["b"]

        h la = if dict_has(leaders, a) { dict_get(leaders, a) } else { a }
        h lb = if dict_has(leaders, b) { dict_get(leaders, b) } else { b }

        if la == lb {
            pi += 1
            continue
        }

        # Ensure la has a group array
        if !dict_has(groups, la) {
            dict_set(groups, la, [la])
            dict_set(leaders, la, la)
        }
        h ga = dict_get(groups, la)   # shared reference — push mutates it

        # Collect lb's members (or just [b] if lb has no group yet)
        h lb_members = if dict_has(groups, lb) { dict_get(groups, lb) } else { [lb] }

        # Merge lb's members into la's group, update their leader pointers
        h mi = 0
        while mi < arr_len(lb_members) {
            h member = lb_members[mi]
            arr_push(ga, member)
            dict_set(leaders, member, la)
            mi += 1
        }
        # Invalidate lb's old group entry so collection skips it
        if dict_has(groups, lb) { dict_set(groups, lb, []) }

        pi += 1
    }

    # Collect all non-trivial (≥2 members) groups
    h result = []
    h leader_list = dict_keys(groups)
    h li = 0
    while li < arr_len(leader_list) {
        h grp = dict_get(groups, leader_list[li])
        if arr_len(grp) >= 2 { arr_push(result, grp) }
        li += 1
    }
    return result
}

# ── Claude narration ───────────────────────────────────────────────────────────

fn archaeology_narrate(results, model) {
    h top    = results["attractors"]
    h stats  = results["stats"]
    h listing = ""
    h i = 0
    while i < arr_len(top) {
        h m = top[i]
        h preview = str_slice(m["content"], 0, 150)
        listing = listing +
            to_string(i + 1) + ". " + _short_path(m["path"]) +
            "  [attractor=" + to_string(m["attractor_score"]) +
            "  density=" + to_string(m["density"]) +
            "  fns=" + to_string(m["fn_count"]) +
            "  refs=" + to_string(m["refs"]) + "]\n" +
            "   " + preview + "\n\n"
        i += 1
    }
    h lang_note = "language: " + stats["primary_lang"]
    h prompt =
        "You are doing codebase archaeology on a " + lang_note + " project.\n\n" +
        "Stats: " + to_string(stats["file_count"]) + " files, " +
        to_string(stats["total_fns"]) + " functions, " +
        to_string(stats["cluster_count"]) + " duplicate clusters.\n\n" +
        "Attractor score = phi-pi-fib token density × (1 + import references).\n" +
        "Higher density = more idiomatic use of recognized vocabulary.\n\n" +
        "Top attractor modules:\n\n" + listing +
        "In 4-5 sentences: What architectural shape do these attractors reveal? " +
        "Which is the foundational layer, which is orchestration? " +
        "What should a new contributor understand first? " +
        "Any concerns about the duplicate clusters?"
    return llm_call(prompt, model)
}

# ── Main scan entry point ──────────────────────────────────────────────────────

fn archaeology_scan(base, opts) {
    h extensions   = _opt(opts, "extensions",  [".omc"])
    h top_n        = _opt(opts, "top_n",       8)
    h threshold    = _opt(opts, "threshold",   0.78)
    h check_limit  = _opt(opts, "check_limit", 40)
    h ref_weight   = _opt(opts, "ref_weight",  5.0)
    h fn_weight    = _opt(opts, "fn_weight",   0.5)

    # ── 1. Discover files ──────────────────────────────────────────────────────
    h files = _find_files(base, extensions)

    # ── 2. Read all content (needed for ref counting) ─────────────────────────
    h all_contents = []
    h fi = 0
    while fi < arr_len(files) {
        h content = ""
        if file_exists(files[fi]) { content = read_file(files[fi]) }
        arr_push(all_contents, content)
        fi += 1
    }

    # ── 3. Score each module ──────────────────────────────────────────────────
    h modules  = []
    h total_fns = 0
    h lang_counts = {}

    fi = 0
    while fi < arr_len(files) {
        h path    = files[fi]
        h content = all_contents[fi]
        h lang    = detect_language(path)
        h density = _score(content)
        h fn_cnt  = _count_fns(path, content, lang)
        h refs    = _count_refs(path, all_contents)
        h chash   = omc_code_hash(content)
        h asc     = density * 40.0 + refs * ref_weight + fn_cnt * fn_weight

        total_fns += fn_cnt
        h lcount = if dict_has(lang_counts, lang) { dict_get(lang_counts, lang) } else { 0 }
        dict_set(lang_counts, lang, lcount + 1)

        arr_push(modules, {
            "path":           path,
            "content":        content,
            "lang":           lang,
            "density":        density,
            "fn_count":       fn_cnt,
            "refs":           refs,
            "hash":           chash,
            "attractor_score": asc
        })
        fi += 1
    }

    # ── 4. Find top attractors ─────────────────────────────────────────────────
    h attractors = _top_k(modules, "attractor_score", top_n)

    # ── 5. Detect semantic duplicates among top modules ────────────────────────
    h check_pool  = _top_k(modules, "attractor_score", check_limit)
    h non_empty   = []
    h ci = 0
    while ci < arr_len(check_pool) {
        if str_len(check_pool[ci]["content"]) > 20 { arr_push(non_empty, check_pool[ci]) }
        ci += 1
    }
    h pairs    = _find_pairs(non_empty, threshold)
    h clusters = cluster_pairs(pairs)

    # ── 6. Determine primary language ─────────────────────────────────────────
    h primary_lang = "unknown"
    h max_lang_count = 0
    h lang_keys = dict_keys(lang_counts)
    h lki = 0
    while lki < arr_len(lang_keys) {
        h lk = lang_keys[lki]
        if dict_get(lang_counts, lk) > max_lang_count {
            max_lang_count = dict_get(lang_counts, lk)
            primary_lang = lk
        }
        lki += 1
    }

    return {
        "attractors": attractors,
        "modules":    modules,
        "clusters":   clusters,
        "stats": {
            "file_count":    arr_len(files),
            "total_fns":     total_fns,
            "cluster_count": arr_len(clusters),
            "primary_lang":  primary_lang,
            "lang_counts":   lang_counts
        }
    }
}

# cache.omc — memoize, LRU cache, TTL cache, disk cache

# ── Simple memoize ──────────────────────────────────────────────────────────

# memoize(fn) → fn
# Returns a wrapper that caches results keyed by stringified args.
fn memoize(f) {
    h store = {}
    h memo_wrapper = fn(arg) {
        h key = to_string(arg)
        if dict_has(store, key) {
            return store[key]
        }
        h result = f(arg)
        store[key] = result
        return result
    }
    return memo_wrapper
}

# memoize2(fn) → fn
# Two-argument version.
fn memoize2(f) {
    h store = {}
    h memo2_wrapper = fn(a, b) {
        h key = str_concat(to_string(a), "|", to_string(b))
        if dict_has(store, key) {
            return store[key]
        }
        h result = f(a, b)
        store[key] = result
        return result
    }
    return memo2_wrapper
}

# ── LRU cache ───────────────────────────────────────────────────────────────

# lru_new(capacity) → lru_cache dict
fn lru_new(capacity) {
    return {
        capacity: capacity,
        store: {},
        order: [],
        hits: 0,
        misses: 0
    }
}

fn _lru_evict(lru) {
    if arr_len(lru["order"]) >= lru["capacity"] {
        h oldest = lru["order"][0]
        lru["order"] = arr_slice(lru["order"], 1, arr_len(lru["order"]))
        if dict_has(lru["store"], oldest) {
            dict_delete(lru["store"], oldest)
        }
    }
}

fn _lru_touch(lru, key) {
    h new_order = []
    h i = 0
    while i < arr_len(lru["order"]) {
        if lru["order"][i] != key {
            arr_push(new_order, lru["order"][i])
        }
        i += 1
    }
    arr_push(new_order, key)
    lru["order"] = new_order
}

# lru_get(lru, key) → value or null
fn lru_get(lru, key) {
    h k = to_string(key)
    if dict_has(lru["store"], k) {
        _lru_touch(lru, k)
        lru["hits"] = lru["hits"] + 1
        return lru["store"][k]
    }
    lru["misses"] = lru["misses"] + 1
    return null
}

# lru_put(lru, key, value)
fn lru_put(lru, key, value) {
    h k = to_string(key)
    if !dict_has(lru["store"], k) {
        _lru_evict(lru)
        arr_push(lru["order"], k)
    } else {
        _lru_touch(lru, k)
    }
    lru["store"][k] = value
}

# lru_stats(lru) → {hits, misses, size, capacity, hit_rate}
fn lru_stats(lru) {
    h total = lru["hits"] + lru["misses"]
    h rate = 0.0
    if total > 0 { rate = lru["hits"] / total }
    return {
        hits: lru["hits"],
        misses: lru["misses"],
        size: arr_len(lru["order"]),
        capacity: lru["capacity"],
        hit_rate: rate
    }
}

# lru_memoize(fn, capacity) → fn
# LRU-backed memoized wrapper.
fn lru_memoize(f, capacity) {
    h cache = lru_new(capacity)
    h lru_wrapper = fn(arg) {
        h key = to_string(arg)
        h cached = lru_get(cache, key)
        if cached != null { return cached }
        h result = f(arg)
        lru_put(cache, key, result)
        return result
    }
    return lru_wrapper
}

# ── TTL cache ───────────────────────────────────────────────────────────────

# ttl_new(ttl_seconds) → ttl_cache dict
fn ttl_new(ttl_seconds) {
    return {ttl: ttl_seconds, store: {}, expires: {}, hits: 0, misses: 0}
}

# ttl_get(cache, key) → value or null (returns null if expired)
fn ttl_get(cache, key) {
    h k = to_string(key)
    if !dict_has(cache["store"], k) {
        cache["misses"] = cache["misses"] + 1
        return null
    }
    h now = unix_time()
    if now > cache["expires"][k] {
        dict_delete(cache["store"], k)
        dict_delete(cache["expires"], k)
        cache["misses"] = cache["misses"] + 1
        return null
    }
    cache["hits"] = cache["hits"] + 1
    return cache["store"][k]
}

# ttl_put(cache, key, value)
fn ttl_put(cache, key, value) {
    h k = to_string(key)
    h now = unix_time()
    cache["store"][k] = value
    cache["expires"][k] = now + cache["ttl"]
}

# ttl_memoize(fn, ttl_seconds) → fn
fn ttl_memoize(f, ttl) {
    h cache = ttl_new(ttl)
    h ttl_wrapper = fn(arg) {
        h key = to_string(arg)
        h cached = ttl_get(cache, key)
        if cached != null { return cached }
        h result = f(arg)
        ttl_put(cache, key, result)
        return result
    }
    return ttl_wrapper
}

# ── Disk cache ──────────────────────────────────────────────────────────────

# disk_cache_get(dir, key) → string or null
fn disk_cache_get(dir, key) {
    h safe_key = str_replace(to_string(key), "/", "_")
    h path = str_concat(dir, "/", safe_key, ".cache")
    h content = file_read(path)
    return content
}

# disk_cache_put(dir, key, value)
fn disk_cache_put(dir, key, value) {
    h safe_key = str_replace(to_string(key), "/", "_")
    h path = str_concat(dir, "/", safe_key, ".cache")
    write_file(path, to_string(value))
}

# disk_memoize(fn, dir) → fn
# Persists results to disk; survives process restarts.
fn disk_memoize(f, dir) {
    h disk_wrapper = fn(arg) {
        h key = to_string(arg)
        h cached = disk_cache_get(dir, key)
        if cached != null { return cached }
        h result = f(arg)
        disk_cache_put(dir, key, result)
        return result
    }
    return disk_wrapper
}

# ── Batch cache ─────────────────────────────────────────────────────────────

# batch_cached(fn, keys_array, cache) → [values]
# For each key: return cached value or call fn(key) and cache it.
fn batch_cached(f, keys, cache) {
    h results = []
    h i = 0
    while i < arr_len(keys) {
        h k = keys[i]
        h cached = lru_get(cache, k)
        if cached != null {
            arr_push(results, cached)
        } else {
            h v = f(k)
            lru_put(cache, k, v)
            arr_push(results, v)
        }
        i += 1
    }
    return results
}

