# =============================================================================
# pandas bridge for OMC — written in OMC
# =============================================================================
# The "OMC can dissect any dataset" layer. Wraps pd.read_* so OMC code
# can ingest CSV / parquet / JSON / Excel / SQL with one call each.
#
# Design choice: we always return PANDAS HANDLES, not OMC dicts. The
# caller can pull rows / columns into OMC via to_dict / to_list when
# they actually need it. This keeps memory off OMC's heap until the
# user decides to materialise — matters for million-row datasets.
#
# Usage:
#   import "examples/lib/pd.omc" as pd;
#   h df = pd.read_csv("data/movies.csv");
#   h cols = pd.columns(df);                    # OMC array of strings
#   h rows = pd.head_dict(df, 5);               # OMC dict of arrays
# =============================================================================

h _PD_HANDLE = 0;

fn _pd() {
    if _PD_HANDLE == 0 {
        _PD_HANDLE = py_import("pandas");
    }
    return _PD_HANDLE;
}

# ---- Loaders --------------------------------------------------------------
# Each one returns a pandas handle. Composable with the rest of pd.*.

fn read_csv(path)      { return py_call(_pd(), "read_csv", [path]); }
fn read_json(path)     { return py_call(_pd(), "read_json", [path]); }
fn read_parquet(path)  { return py_call(_pd(), "read_parquet", [path]); }
fn read_excel(path)    { return py_call(_pd(), "read_excel", [path]); }
fn read_table(path)    { return py_call(_pd(), "read_table", [path]); }

# ---- DataFrame inspection -------------------------------------------------

fn shape(df)        { return py_get(df, "shape"); }
fn nrows(df)        { return arr_get(shape(df), 0); }
fn ncols(df)        { return arr_get(shape(df), 1); }

fn columns(df) {
    # py_get already auto-converts pandas.Index via .tolist(), so we
    # get an OMC array directly. No need for a second .tolist() call.
    return py_get(df, "columns");
}

# ---- Materialisation (handle → OMC) --------------------------------------

# All rows as a dict-of-arrays (one entry per column). Memory-heavy
# on big DataFrames; prefer head_dict when sampling.
fn to_dict(df) {
    return py_call(df, "to_dict", ["list"]);
}

fn head_dict(df, n) {
    h h_df = py_call(df, "head", [n]);
    return py_call(h_df, "to_dict", ["list"]);
}

# Pull a single column as an OMC array. py_call already auto-converts
# the returned pandas Series via .tolist() (Series exposes that
# attr), so we get an OMC array directly. No second call needed.
fn col(df, name) {
    return py_call(df, "get", [name]);
}

# ---- Filtering / selection -----------------------------------------------

fn head(df, n)      { return py_call(df, "head", [n]); }
fn tail(df, n)      { return py_call(df, "tail", [n]); }

fn select_cols(df, cols) {
    return py_call(df, "get", [cols]);   # df[cols] equivalent
}

# ---- Aggregation ----------------------------------------------------------

fn group_by(df, key) {
    return py_call(df, "groupby", [key]);
}

# Apply mean/sum/count to a groupby and pull as a dict-of-arrays.
fn agg_mean(grouped) {
    h means = py_call(grouped, "mean", []);
    h reset = py_call(means, "reset_index", []);
    return py_call(reset, "to_dict", ["list"]);
}

fn agg_count(grouped) {
    h counts = py_call(grouped, "count", []);
    h reset = py_call(counts, "reset_index", []);
    return py_call(reset, "to_dict", ["list"]);
}

# ---- Conversion -----------------------------------------------------------

fn describe(df) {
    h d = py_call(df, "describe", []);
    return py_call(d, "to_dict", ["list"]);
}

# ---- Cleaning -------------------------------------------------------------
# Fill missing values in `col` with `value`. Returns a NEW DataFrame
# (pandas immutable-on-assignment semantics).
#
# Implementation note: we can't pull the Series out and operate on it
# (py_to_omc auto-converts Series → OMC array via .tolist(), losing
# the handle). Instead we call df.fillna(value={col: value}) which
# operates on the whole DataFrame and returns a fresh one.
fn fillna_col(df, col, value) {
    return py_call_kw(df, "fillna", [],
        {"value": dict_merge({}, {col: value})});
}

# ---- One-hot / dummies ---------------------------------------------------
# Returns a new DataFrame with `col` replaced by N indicator columns.
# Uses pandas.get_dummies under the hood.
fn one_hot(df, col) {
    return py_call_kw(_pd(), "get_dummies", [df],
        {"columns": [col], "drop_first": false});
}

# ---- Apply an OMC callback to every row of a column ----------------------
# `omc_fn_name` is the name of an OMC fn taking a single value.
# Returns a new column (OMC array).
#
# Implementation: py_call_raw keeps the Series as a handle (vanilla
# py_call would auto-convert via .tolist()). Then apply via the
# py_callback. Final .tolist() materialises the result.
fn apply_omc(df, col, omc_fn_name) {
    h series = py_call_raw(df, "get", [col]);
    h cb = py_callback(omc_fn_name);
    h applied = py_call_raw(series, "apply", [cb]);
    return py_call(applied, "tolist", []);
}

# Prometheus — substrate-native ML composition layer.
#
# A pure-OMC framework built on the existing tape_* (reverse-mode autograd)
# and arr_* (ML kernels + linalg) primitives. NOT a PyTorch wrapper — every
# layer here is implemented in OMC and trains via the substrate's own
# autograd engine.
#
# Status: MVP. Provides Linear + activations + MSE loss + SGD step.
# Trained end-to-end in examples/prometheus_tinylm.omc.
#
# Strategic intent: be substrate-native for the things substrate uniquely
# provides (alpha-rename-invariant content hashing of model weights,
# harmonic-resonance modulated gradients, geodesic attention as a first-
# class layer), while harvesting Python's correctness oracles via py_*
# imports during development.
#
# Conventions:
#   - A "module" is a dict carrying parameter tape-var IDs.
#   - prom_*_new(...)         → constructs the module + registers params on the tape
#   - prom_*_forward(mod, x)  → runs the forward pass; returns a tape node id
#   - prom_collect_params(mod) → returns a flat list of every tape-var id in the module
#   - The user manages tape_reset() once before constructing the model;
#     param IDs persist across training steps as the forward graph rebuilds.

# ---------------------------------------------------------------------------
# Initialization helpers
# ---------------------------------------------------------------------------

# Uniform [-bound, bound) — deterministic if seed_state is threaded through.
# OMC doesn't ship a real RNG; we use a tiny LCG for reproducibility.
fn _prom_lcg_step(state) {
    return (state * 1103515245 + 12345) % 2147483648;
}

fn _prom_uniform(state, bound) {
    h s = _prom_lcg_step(state);
    h r = s / 2147483648.0;          # [0, 1)
    h v = (r * 2.0 - 1.0) * bound;   # [-bound, bound)
    h out = dict_new();
    dict_set(out, "state", s);
    dict_set(out, "value", v);
    return out;
}

# Build a random matrix [rows][cols] in OMC array form, register each cell
# as a tape_var, return both the matrix-of-ids and the updated rng state.
fn _prom_random_matrix(rows, cols, bound, state) {
    h matrix = [];
    h s = state;
    h i = 0;
    while i < rows {
        h row = [];
        h j = 0;
        while j < cols {
            h step = _prom_uniform(s, bound);
            s = dict_get(step, "state");
            arr_push(row, dict_get(step, "value"));
            j += 1;
        }
        arr_push(matrix, row);
        i += 1;
    }
    h node = tape_var(matrix);   # register the whole matrix as one variable
    h out = dict_new();
    dict_set(out, "node", node);
    dict_set(out, "state", s);
    return out;
}

# v0.8.8 substrate-init variant. After random init, snap each cell to
# the nearest Fibonacci attractor at the given scale. The hypothesis:
# substrate-aligned starting weights may give different (potentially
# better-regularized) training trajectories than uniform random init.
# Pairs with the substrate_snap_matrix Rust builtin.
#
# Usage:
#   h W = _prom_substrate_random_matrix(rows, cols, bound, state, 1024.0);
# scale=0 returns the same node unchanged (no snapping).
fn _prom_substrate_random_matrix(rows, cols, bound, state, init_scale) {
    h out = _prom_random_matrix(rows, cols, bound, state);
    if init_scale > 0.0 {
        h node = dict_get(out, "node");
        h v = tape_value(node);
        h snapped = substrate_snap_matrix(v, init_scale);
        tape_set_value(node, snapped);
    }
    return out;
}

# Same as above but produces a zero-initialized bias row vector.
fn _prom_zeros_row(cols) {
    h row = [];
    h j = 0;
    while j < cols {
        arr_push(row, 0.0);
        j += 1;
    }
    h matrix = [row];   # 1 x cols
    return tape_var(matrix);
}

# ---------------------------------------------------------------------------
# Linear layer: y = x @ W + b
# x: [batch, in_dim],  W: [in_dim, out_dim],  b: [1, out_dim]
# ---------------------------------------------------------------------------

fn prom_linear_new(in_dim, out_dim, rng_state) {
    # Xavier-ish bound: sqrt(6 / (in + out))
    h bound = 0.5;
    h Wr = _prom_random_matrix(in_dim, out_dim, bound, rng_state);
    h b = _prom_zeros_row(out_dim);
    h layer = dict_new();
    dict_set(layer, "kind", "linear");
    dict_set(layer, "in_dim", in_dim);
    dict_set(layer, "out_dim", out_dim);
    dict_set(layer, "W", dict_get(Wr, "node"));
    dict_set(layer, "b", b);
    dict_set(layer, "rng_state", dict_get(Wr, "state"));
    return layer;
}

fn prom_linear_forward(layer, x_id) {
    h W = dict_get(layer, "W");
    h b = dict_get(layer, "b");
    h xW = tape_matmul(x_id, W);
    return tape_add(xW, b);
}

fn prom_linear_params(layer) {
    h out = [];
    arr_push(out, dict_get(layer, "W"));
    arr_push(out, dict_get(layer, "b"));
    return out;
}

# ---------------------------------------------------------------------------
# Activations — substrate-native (route to tape ops).
# ---------------------------------------------------------------------------

fn prom_relu(x_id)    { return tape_relu(x_id); }
fn prom_sigmoid(x_id) { return tape_sigmoid(x_id); }

# ---------------------------------------------------------------------------
# Losses — MSE works with what the tape currently supports
# (no exp/log on the tape, so true softmax+CE isn't yet here; using
# sigmoid + MSE against one-hot target is a viable LM loss for tiny
# scale and demonstrates substrate-native training).
# ---------------------------------------------------------------------------

fn prom_mse_loss(pred_id, target_id) {
    h diff = tape_sub(pred_id, target_id);
    h sq = tape_mul(diff, diff);
    return tape_mean(sq);
}

# ---------------------------------------------------------------------------
# Optimizer — substrate-native SGD step.
# Calls tape_update on every parameter in the supplied flat list.
# ---------------------------------------------------------------------------

fn prom_sgd_step(params, lr) {
    h i = 0;
    while i < arr_len(params) {
        tape_update(arr_get(params, i), lr);
        i += 1;
    }
}

# Variant: substrate-modulated SGD step.
# Reads each param's gradient, scales by (1 + phi.res(grad_hash)) so
# gradients pointing toward Fibonacci attractors get a small boost.
# Experimental; the architectural rule derived today says substrate
# metric on float activations doesn't work as an attention modulator,
# but on GRADIENT MAGNITUDES (integer-keyed via hash of grad bytes)
# the rule may differ. Worth measuring once the baseline converges.
fn prom_harmonic_sgd_step(params, lr) {
    # TODO: read tape_grad(p), compute substrate scaling factor, then
    # call a (yet-to-add) tape_update_scaled(p, lr, scale). For now,
    # fall back to plain SGD.
    prom_sgd_step(params, lr);
}

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

# Build a [vocab] one-hot row vector as a tape_const.
fn prom_one_hot(idx, vocab) {
    h row = [];
    h i = 0;
    while i < vocab {
        if i == idx { arr_push(row, 1.0); }
        else { arr_push(row, 0.0); }
        i += 1;
    }
    return tape_const([row]);    # [1, vocab]
}

# Argmax over a logits vector. Handles either a flat 1D array (when
# tape_value collapses a 1xN matrix) or a true 2D [1, vocab] matrix.
fn prom_argmax_row(logits) {
    h row = logits;
    # If the first element is itself an array, this is 2D and we need row 0.
    if arr_len(logits) > 0 {
        h first = arr_get(logits, 0);
        if type_of(first) == "array" { row = first; }
    }
    h best = 0;
    h best_val = arr_get(row, 0);
    h i = 1;
    while i < arr_len(row) {
        h v = arr_get(row, i);
        if v > best_val { best_val = v; best = i; }
        i += 1;
    }
    return best;
}

# ---------------------------------------------------------------------------
# Convenience: collect parameters from a list of layers.
# ---------------------------------------------------------------------------

fn prom_collect_params(layers) {
    h out = [];
    h i = 0;
    while i < arr_len(layers) {
        h layer = arr_get(layers, i);
        h kind = dict_get(layer, "kind");
        h ps = [];
        if kind == "linear" { ps = prom_linear_params(layer); }
        elif kind == "attention" { ps = prom_attention_params(layer); }
        h j = 0;
        while j < arr_len(ps) {
            arr_push(out, arr_get(ps, j));
            j += 1;
        }
        i += 1;
    }
    return out;
}

# ---------------------------------------------------------------------------
# Checkpoint I/O — content-addressed model weights via canonical hash.
#
# Save: serialize every layer's (W, b) tape values to a JSON blob,
# canonicalize via key-sort (the standard "json" kind in omc-kernel),
# return the canonical hex hash. The blob can be written to disk,
# shipped over OMC-PROTOCOL, or stored in the kernel — the hash IS
# the identity.
#
# Load: take a JSON blob; reconstruct each layer's params as fresh
# tape vars holding the saved values; return a new model dict that
# threads through the same forward() function the original used.
#
# The substrate moat: two trained models with IDENTICAL weights but
# different in-memory representations (different tape IDs, different
# session order) collapse to the SAME canonical hash. Dedup, ship,
# verify integrity all become substrate-native operations.
# ---------------------------------------------------------------------------

fn _prom_serialize_linear(layer) {
    h W_id = dict_get(layer, "W");
    h b_id = dict_get(layer, "b");
    h W_vals = tape_value(W_id);
    h b_vals = tape_value(b_id);
    h entry = dict_new();
    dict_set(entry, "kind", "linear");
    dict_set(entry, "in_dim", dict_get(layer, "in_dim"));
    dict_set(entry, "out_dim", dict_get(layer, "out_dim"));
    dict_set(entry, "W", W_vals);
    dict_set(entry, "b", b_vals);
    return entry;
}

# Serialize an arbitrary model dict that names its layers via
# string keys to layer dicts. Returns a {layers: [{name, entry}],
# meta: {...}} struct ready for json_stringify.
fn prom_serialize_model(model, layer_names) {
    h out_layers = [];
    h i = 0;
    while i < arr_len(layer_names) {
        h name = arr_get(layer_names, i);
        h layer = dict_get(model, name);
        h entry = dict_new();
        dict_set(entry, "name", name);
        dict_set(entry, "data", _prom_serialize_linear(layer));
        arr_push(out_layers, entry);
        i += 1;
    }
    h bundle = dict_new();
    dict_set(bundle, "format", "prometheus_model_v1");
    dict_set(bundle, "layers", out_layers);
    return bundle;
}

# Compute the canonical hash that addresses a serialized model.
# Two models with the same weights (in canonical-JSON form) collapse
# to the same hash regardless of session or insertion order.
#
# Strategy: re-parse + re-serialize via OMC's deterministic json
# round-trip (sorts dict keys, normalizes float format), then fnv1a
# the canonical string. Two models with identical weights but
# different in-memory ordering land on the same hash.
fn prom_model_hash(bundle) {
    h j = json_stringify(bundle);
    h reparsed = json_parse(j);
    h canon = json_stringify(reparsed);
    return fnv1a_hash(canon);
}

# Reconstruct one Linear layer from a serialized entry. Creates
# fresh tape_var nodes — caller is responsible for calling
# tape_reset() first if they want a clean slate.
fn _prom_load_linear(entry) {
    h data = dict_get(entry, "data");
    h W_node = tape_var(dict_get(data, "W"));
    h b_node = tape_var(dict_get(data, "b"));
    h layer = dict_new();
    dict_set(layer, "kind", "linear");
    dict_set(layer, "in_dim", dict_get(data, "in_dim"));
    dict_set(layer, "out_dim", dict_get(data, "out_dim"));
    dict_set(layer, "W", W_node);
    dict_set(layer, "b", b_node);
    return layer;
}

# Reconstruct a model from a serialized bundle. Returns a dict keyed
# by layer name, suitable for the same forward() the caller used
# during training.
fn prom_load_model(bundle) {
    h layers = dict_get(bundle, "layers");
    h model = dict_new();
    h i = 0;
    while i < arr_len(layers) {
        h entry = arr_get(layers, i);
        h name = dict_get(entry, "name");
        dict_set(model, name, _prom_load_linear(entry));
        i += 1;
    }
    return model;
}

# ---------------------------------------------------------------------------
# Geodesic attention bias — fused primitive.
#
# Today's transformerless-LM win (3/3 seeds, -0.4% val loss vs crt_only)
# was: scores[i,j] -= alpha * geodesic(i, j) where geodesic is the
# CRT-Fibonacci-moduli distance between positions i and j. Promote
# that to a one-call API any Prometheus model can use.
#
# Architectural rule (derived today): the substrate metric is only
# valid on integer-valued quantities. Positions are integers; this is
# the basis substrate was built for. Continuous learned activations
# are not in the substrate's lattice — three previous gate
# formulations on activations all failed (0/3); this geodesic-on-
# positions formulation won 3/3.
# ---------------------------------------------------------------------------

# Same Fibonacci moduli used by CRT-PE.
fn _prom_geodesic_moduli() {
    return [5, 8, 13, 21, 34, 55, 89, 144];
}

# Circular distance on a ring of size m between residues a and b.
# Mirrors the PyTorch min(|a-b|, m - |a-b|) formulation that won
# 3/3 seeds in train_geodesic_attention.py today.
fn _prom_circular_dist(a, b, m) {
    h d = a - b;
    if d < 0 { d = 0 - d; }
    h alt = m - d;
    if alt < d { return alt; }
    return d;
}

# Compute geodesic distance between two integer positions in the
# CRT-Fibonacci lattice. The substrate metric, applied to its
# native basis (integer position pairs).
fn prom_geodesic_distance(i, j) {
    h moduli = _prom_geodesic_moduli();
    h k = 0;
    h total = 0.0;
    while k < arr_len(moduli) {
        h m = arr_get(moduli, k);
        h ri = i - (i / m) * m;
        h rj = j - (j / m) * m;
        h d_circ = _prom_circular_dist(ri, rj, m);
        # Force float division — OMC int/int truncates.
        total += (d_circ * 1.0) / (m * 1.0);
        k += 1;
    }
    return total;
}

# Build the [seq_len, seq_len] bias matrix. Used as additive bias on
# attention scores: scores[i,j] -= alpha * bias[i,j].
# Normalized so mean-off-diagonal is ~1.0, giving alpha interpretable
# units (matches the PyTorch impl's normalization).
fn prom_geodesic_bias_matrix(seq_len) {
    h table = [];
    h i = 0;
    h offdiag_sum = 0.0;
    h offdiag_count = 0;
    while i < seq_len {
        h row = [];
        h j = 0;
        while j < seq_len {
            h d = prom_geodesic_distance(i, j);
            arr_push(row, d);
            if i != j {
                offdiag_sum += d;
                offdiag_count += 1;
            }
            j += 1;
        }
        arr_push(table, row);
        i += 1;
    }
    h mean_off = 1.0;
    if offdiag_count > 0 {
        mean_off = offdiag_sum / offdiag_count;
    }
    # Normalize.
    h normed = [];
    i = 0;
    while i < seq_len {
        h row = arr_get(table, i);
        h nr = [];
        h j = 0;
        while j < seq_len {
            arr_push(nr, arr_get(row, j) / mean_off);
            j += 1;
        }
        arr_push(normed, nr);
        i += 1;
    }
    return normed;
}

# ---------------------------------------------------------------------------
# Harmonic SGD step — substrate-modulated per-parameter learning rate.
#
# Hypothesis: gradients whose magnitude lands near a Fibonacci attractor
# are "substrate-coherent" and should be amplified; off-attractor
# gradients are noise and should be dampened. The architectural rule
# from today (substrate metric only on integer quantities) means we
# operate on hashed-grad summary, not raw grad values.
#
# Per-param effective lr:
#   gnorm = sum(|grad|) cast to int  (a quantization step that puts the
#                                    magnitude into integer space)
#   attractor_dist = nearest_attractor_distance(gnorm)
#   resonance = 1.0 / (1.0 + log(1 + attractor_dist))
#   effective_lr = lr * (1.0 + alpha * (resonance - 0.5))
#
# alpha=0 → identical to vanilla SGD. alpha>0 → on-attractor gradients
# move further; off-attractor move less.
# ---------------------------------------------------------------------------

# Compute scalar magnitude of a gradient that may be scalar or matrix.
fn _prom_grad_magnitude(g) {
    if type_of(g) == "array" {
        h total = 0.0;
        h i = 0;
        while i < arr_len(g) {
            h v = arr_get(g, i);
            if type_of(v) == "array" {
                h j = 0;
                while j < arr_len(v) {
                    h e = arr_get(v, j);
                    if e < 0.0 { e = 0.0 - e; }
                    total += e;
                    j += 1;
                }
            } else {
                if v < 0.0 { v = 0.0 - v; }
                total += v;
            }
            i += 1;
        }
        return total;
    }
    if g < 0.0 { g = 0.0 - g; }
    return g;
}

# Substrate-resonance scaling factor for a gradient's magnitude.
# Returns in [1 - alpha, 1 + alpha].
fn _prom_harmonic_scale(grad_mag, alpha) {
    # Quantize: round to nearest int, abs.
    h gnorm = grad_mag * 1000.0;     # scale up so attractor table reaches
    if gnorm < 0.0 { gnorm = 0.0 - gnorm; }
    h gi = gnorm + 0.5;
    h gint = gi - (gi - (gi / 1) * 1);   # truncate to int (gi/1*1 - frac)
    # Use the existing attractor_distance builtin.
    h dist = attractor_distance(gint);
    # Smaller dist → more substrate-coherent → boost.
    h reso = 1.0 / (1.0 + dist / 100.0);   # reso ∈ (0, 1]
    return 1.0 + alpha * (reso - 0.5);
}

# Substrate-modulated SGD step. Applies tape_update per param with a
# learning rate scaled by the substrate-coherence of that param's
# gradient magnitude.
fn prom_harmonic_sgd_step(params, lr, alpha) {
    h i = 0;
    while i < arr_len(params) {
        h p = arr_get(params, i);
        h g = tape_grad(p);
        h gmag = _prom_grad_magnitude(g);
        h scale = _prom_harmonic_scale(gmag, alpha);
        tape_update(p, lr * scale);
        i += 1;
    }
}

# ---------------------------------------------------------------------------
# Substrate-cached inference — content-addressed activation memo.
#
# Hash the input + model checkpoint together to form a cache key. If
# the key is in the kernel store, return the cached output. Else
# compute, store the output keyed by the input hash.
#
# This is most useful for inference workloads where identical
# queries recur (RAG, agentic loops, repeated tool-call refinement).
# For training, params change every step so cache misses are the
# rule.
# ---------------------------------------------------------------------------

# Compute a content-addressed key for an inference query.
# input_repr: a string representation of the input batch.
# model_hash: the canonical hash of the model weights (from prom_model_hash).
# Returns a key that uniquely identifies (input, model) pair.
fn prom_cache_key(input_repr, model_hash) {
    h combined = concat_many("prom-infer|", to_string(model_hash), "|", input_repr);
    return fnv1a_hash(combined);
}

# In-memory cache (a dict mapping key → output JSON). For
# cross-process caching, route through omc_msg_recover_compressed
# against omc-kernel.
fn prom_cache_new() {
    return dict_new();
}

fn prom_cache_get(cache, key) {
    h ks = to_string(key);
    if dict_has(cache, ks) {
        return dict_get(cache, ks);
    }
    return null;
}

fn prom_cache_put(cache, key, value) {
    dict_set(cache, to_string(key), value);
}

# ---------------------------------------------------------------------------
# Text generation — autoregressive greedy decoding.
#
# Given a trained model + a starting char index + an integer-vocab
# alphabet, predict the next char by argmax on the model's logits,
# append, and repeat for `length` steps. Returns a list of char-index
# integers; convert to display strings via the caller's alphabet.
#
# Caller supplies the forward fn (so this composes with any model
# topology — MLP today, transformer later).
# ---------------------------------------------------------------------------

# Generate `length` integer-token IDs given:
#   forward_fn : fn(model, x_id) -> logits_id    (caller-defined)
#   model      : the model dict
#   seed_idx   : starting char index (int)
#   length     : number of NEW tokens to generate
#   vocab      : alphabet size
# Returns array of length+1 indices (seed first, then generated).
fn prom_generate_greedy(forward_fn, model, seed_idx, length, vocab) {
    h out = [seed_idx];
    h current = seed_idx;
    h step = 0;
    while step < length {
        h x = prom_one_hot(current, vocab);
        h pred = forward_fn(model, x);
        h logits = tape_value(pred);
        h next_idx = prom_argmax_row(logits);
        arr_push(out, next_idx);
        current = next_idx;
        step += 1;
    }
    return out;
}

# Convert a list of indices to a string given a chars alphabet.
fn prom_decode_indices(indices, chars) {
    h out = "";
    h i = 0;
    while i < arr_len(indices) {
        out = concat_many(out, arr_get(chars, arr_get(indices, i)));
        i += 1;
    }
    return out;
}

# ---------------------------------------------------------------------------
# Softmax + cross-entropy loss — true LM training, not MSE.
#
# Now that tape_softmax + tape_log are shipped, we can compute:
#   loss = -log(softmax(logits)[target_idx])
# which is the standard cross-entropy used in every modern LM.
#
# This unlocks much larger vocabularies + faster convergence than
# MSE-against-one-hot.
# ---------------------------------------------------------------------------

# Cross-entropy loss: -log(softmax(logits)[target_idx])
# logits_id: tape node holding [1, vocab] logits
# target_idx: integer target class
# vocab: size of the alphabet
fn prom_cross_entropy_loss(logits_id, target_idx, vocab) {
    h probs = tape_softmax(logits_id);
    h log_probs = tape_log(probs);
    # Build a one-hot mask with -1 at the target position; rest = 0.
    h mask_row = [];
    h i = 0;
    while i < vocab {
        if i == target_idx { arr_push(mask_row, -1.0); }
        else { arr_push(mask_row, 0.0); }
        i += 1;
    }
    h mask = tape_const([mask_row]);
    h selected = tape_mul(log_probs, mask);
    return tape_sum(selected);
}

# ---------------------------------------------------------------------------
# Attention layer (single-head) with geodesic positional bias.
#
# scores[i, j] = (Q_i · K_j) / sqrt(d) - alpha * geodesic(i, j)
# attn        = softmax(scores)
# out         = attn @ V
#
# This is the fused primitive promised in today's roadmap — substrate-
# native attention that uses the proven 3/3-seed geodesic bias as a
# first-class layer. Single-head, no masking; full implementation
# (multi-head + causal mask) is straightforward composition on top.
# ---------------------------------------------------------------------------

fn prom_attention_new(d_model, seq_len, rng_state) {
    h Q = _prom_random_matrix(d_model, d_model, 0.3, rng_state);
    h K = _prom_random_matrix(d_model, d_model, 0.3, dict_get(Q, "state"));
    h V = _prom_random_matrix(d_model, d_model, 0.3, dict_get(K, "state"));
    h layer = dict_new();
    dict_set(layer, "kind", "attention");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "seq_len", seq_len);
    dict_set(layer, "Q", dict_get(Q, "node"));
    dict_set(layer, "K", dict_get(K, "node"));
    dict_set(layer, "V", dict_get(V, "node"));
    dict_set(layer, "alpha", 0.5);          # geodesic bias strength (fixed for now)
    dict_set(layer, "rng_state", dict_get(V, "state"));
    return layer;
}

# Forward (L0 — standard QKV attention with optional geodesic bias):
# given x as a tape node of shape [seq_len, d_model], returns
# attention output [seq_len, d_model].
# Uses tape_transpose so K's gradient flows properly through the
# score path (fixes the earlier K-frozen bug).
fn prom_attention_forward(layer, x_id) {
    h Q_w = dict_get(layer, "Q");
    h K_w = dict_get(layer, "K");
    h V_w = dict_get(layer, "V");
    h seq_len = dict_get(layer, "seq_len");
    h alpha = dict_get(layer, "alpha");

    h q = tape_matmul(x_id, Q_w);
    h k = tape_matmul(x_id, K_w);
    h v = tape_matmul(x_id, V_w);

    # scores = q @ k^T  — proper differentiable transpose now.
    h kt = tape_transpose(k);
    h scores = tape_matmul(q, kt);

    # Optional geodesic bias subtracted pre-softmax.
    if alpha != 0.0 {
        h bias_matrix = prom_geodesic_bias_matrix(seq_len);
        h neg_bias_scaled = [];
        h i = 0;
        while i < seq_len {
            h row = arr_get(bias_matrix, i);
            h new_row = [];
            h j = 0;
            while j < seq_len {
                arr_push(new_row, 0.0 - alpha * arr_get(row, j));
                j += 1;
            }
            arr_push(neg_bias_scaled, new_row);
            i += 1;
        }
        h bias_node = tape_const(neg_bias_scaled);
        scores = tape_add(scores, bias_node);
    }

    h attn = tape_softmax(scores);
    return tape_matmul(attn, v);
}

# ---------------------------------------------------------------------------
# Substrate-attention variants (L1, L2, L3).
#
# L0: K, Q, V all learned matrices (prom_attention_forward above).
# L1: K replaced by CRT-PE position memory (no learnable K params).
# L2: K + Q both replaced by substrate-derived projections (only V learned).
# L3: K + Q + V all substrate-derived (parameter-free attention block).
#
# Each tests a stronger version of the hypothesis that OMC's substrate
# can REPLACE learned attention rather than just augment it.
# ---------------------------------------------------------------------------

# L1: substrate-K attention. K is fixed at CRT-PE; Q, V trained.
# Compute the per-cell S-MOD modulation matrix from a [N, T] scores
# value snapshot. Each cell: 1 / (1 + alpha * attractor_distance(cell)).
# Used as a non-differentiable const inside the tape's S-MOD path.
#
# v0.8.4 — defers to the Rust builtin `substrate_smod_matrix`. The
# OMC-side inner loop over N×N scores was the v0.8.2 wall-clock
# bottleneck (single-digit ms matmul drowned by tens of seconds in
# this iteration). Wrapping the native call here keeps the public
# signature stable; any caller of this helper picks up the speedup.
fn _prom_smod_matrix(scores_val, alpha) {
    return substrate_smod_matrix(scores_val, alpha);
}

# Per-cell substrate-resample modulation matrix from a [N, D] value
# snapshot. Each cell: 1 / (1 + attractor_distance(cell * scale) / scale).
# Pulls each component toward its nearest Fibonacci attractor; identity
# when already on-attractor. Used as a non-differentiable const inside
# the tape graph, same pattern as _prom_smod_matrix. Won -2.52% val on
# top of L1-MH + S-MOD α=1.0 when applied to V (3/3 seeds).
#
# v0.8.4 — defers to the Rust builtin `substrate_resample_matrix`.
fn _prom_substrate_resample_matrix(v_val, scale) {
    return substrate_resample_matrix(v_val, scale);
}

# Apply post-projection substrate resampling to a tape node. Returns
# a new tape node whose value is `v * modulation(v)` and whose backward
# flows through v unchanged (modulation rides as a const). scale=0.0
# disables (returns v unchanged).
fn prom_substrate_resample(v_id, scale) {
    # v0.8.5 — defers to the fused tape_substrate_resample Rust builtin.
    # Skips the tape_value → modulator_matrix → tape_const round-trip
    # the old composition did (16k f64 cells at d_model=256 seq_len=64
    # being extracted and re-lifted per call).
    return tape_substrate_resample(v_id, scale);
}

# Substrate-modulated softmax. alpha=0.0 returns standard softmax.
# alpha>0.0 applies the S-MOD post-softmax modulation + renormalize,
# the variant that won -4.27% val on TinyShakespeare multi-head.
fn prom_substrate_softmax(scores_id, alpha) {
    h attn = tape_softmax(scores_id);
    if alpha == 0.0 { return attn; }
    # Modulation is computed from the score VALUES (not params), so it
    # rides as a const in the tape graph — no gradient backward through
    # the substrate-distance term itself. The gradient still flows
    # through attn (softmax output) and through tape_div renormalization.
    h scores_val = tape_value(scores_id);
    h mod_mat = _prom_smod_matrix(scores_val, alpha);
    h mod_const = tape_const(mod_mat);
    h attn_unnorm = tape_mul(attn, mod_const);
    h row_sums = tape_row_sum(attn_unnorm);
    return tape_div(attn_unnorm, row_sums);
}

# Substrate-K attention with optional S-MOD softmax.
# smod_alpha=0.0 → standard softmax (legacy behavior).
# smod_alpha>0.0 → S-MOD substrate-modulated softmax (the recommended default).
fn prom_attention_substrate_k_new(d_model, seq_len, rng_state) {
    h Q = _prom_random_matrix(d_model, d_model, 0.3, rng_state);
    h V = _prom_random_matrix(d_model, d_model, 0.3, dict_get(Q, "state"));
    h layer = dict_new();
    dict_set(layer, "kind", "attention");           # reuse for param-collect
    dict_set(layer, "variant", "substrate_k");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "seq_len", seq_len);
    dict_set(layer, "Q", dict_get(Q, "node"));
    dict_set(layer, "V", dict_get(V, "node"));
    # K is precomputed as a [seq_len, d_model] CRT-PE table — no tape_var.
    dict_set(layer, "K_const", prom_crt_pe_matrix(seq_len, d_model));
    dict_set(layer, "alpha", 0.0);          # geodesic bias (unused here)
    # S-MOD modulation strength. α=1.0 won the 3-seed sweep on
    # TinyShakespeare L1-MH (val 3.084 vs 3.301 at α=0, -6.57%).
    # Sweep details: experiments/prometheus_parity/results_torch_smod_alpha_sweep.json
    dict_set(layer, "smod_alpha", 1.0);
    # Post-projection substrate-V resample scale. scale=10.0 won 3/3
    # seeds (-2.52% val on top of S-MOD α=1.0) on TinyShakespeare L1-MH.
    # scale=0.0 disables. Sweep candidate; not yet tuned.
    dict_set(layer, "v_resample_scale", 10.0);
    # Q6 substrate-modulation: q ← q * exp(-γ · log_φπfib(|q·scale|+1)).
    # PyTorch parity confirmed -12.15% val 6/6 seeds at L1-MH. Mode picks
    # between the composed (tape_abs + tape_log) and fused (tape_phi_log)
    # primitive paths — they are mathematically equivalent, so a divergence
    # at training time pinpoints the cost of the abstraction. "off"
    # disables (legacy behavior).
    dict_set(layer, "q6_mode", "off");
    dict_set(layer, "q6_scale", 10.0);
    dict_set(layer, "q6_gamma", 0.5);
    dict_set(layer, "rng_state", dict_get(V, "state"));
    return layer;
}

fn prom_attention_substrate_k_forward(layer, x_id) {
    h Q_w = dict_get(layer, "Q");
    h V_w = dict_get(layer, "V");
    h K_const = dict_get(layer, "K_const");
    h smod_alpha = dict_get(layer, "smod_alpha");
    # Default to 0.0 (off) when the field is absent — older layers
    # loaded from checkpoints predating substrate-V won't have it.
    h v_scale = dict_get(layer, "v_resample_scale");
    if v_scale == null { v_scale = 0.0; }
    h q6_mode = dict_get(layer, "q6_mode");
    if q6_mode == null { q6_mode = "off"; }
    h q6_scale = dict_get(layer, "q6_scale");
    if q6_scale == null { q6_scale = 10.0; }
    h q6_gamma = dict_get(layer, "q6_gamma");
    if q6_gamma == null { q6_gamma = 0.5; }

    h q = tape_matmul(x_id, Q_w);
    # Q6 substrate-modulation on the projected Q. The two modes are
    # mathematically equivalent — the divergence under the optimizer is
    # what we measure.
    h q_mod = prom_q6_modulate(q, q6_scale, q6_gamma, q6_mode);

    h v_raw = tape_matmul(x_id, V_w);
    # Substrate-resample post-projection (v_scale=0.0 → identity).
    h v = prom_substrate_resample(v_raw, v_scale);

    # K is the substrate (CRT-PE table). No learnable params on K side.
    h k = tape_const(K_const);
    h kt = tape_transpose(k);
    h scores = tape_matmul(q_mod, kt);

    # Substrate-modulated softmax (smod_alpha=0.0 falls back to standard).
    h attn = prom_substrate_softmax(scores, smod_alpha);
    return tape_matmul(attn, v);
}

# ---------------------------------------------------------------------------
# Q6 modulation: q_full = q * exp(-γ · log_φπfib(|q·scale|+1))
#
# Three modes:
#   "off"      → identity (legacy behavior)
#   "composed" → tape_abs + tape_log + scalar denom (boring PyTorch-parity)
#   "fused"    → tape_phi_log (substrate-native fused op)
#
# The composed and fused paths compute identical forward values (verified by
# test_composed_equals_fused_forward) and propagate identical analytic
# gradients. Any training-time divergence between them comes from rounding
# accumulation, allocation patterns, or AdamW interactions — NOT from the
# math. Measuring that divergence is exactly what the A/B is for.
# ---------------------------------------------------------------------------

fn _prom_q6_log_distance_composed(q_id, scale) {
    # ln(|q · scale| + 1) / (π · ln φ)
    h scale_c = tape_const(scale);
    h qs = tape_mul(q_id, scale_c);
    h qs_abs = tape_abs(qs);
    h one = tape_const(1.0);
    h qs_abs1 = tape_add(qs_abs, one);
    h ln_qs = tape_log(qs_abs1);
    # π · ln φ = 3.14159... · 0.481211... ≈ 1.511919...
    h denom = tape_const(1.5119192540204373);
    return tape_div(ln_qs, denom);
}

fn _prom_q6_modulation_from_log_d(log_d_id, gamma) {
    # exp(-γ · log_d)
    h neg_gamma = tape_const(0.0 - gamma);
    h scaled = tape_mul(neg_gamma, log_d_id);
    return tape_exp(scaled);
}

fn prom_q6_modulate(q_id, scale, gamma, mode) {
    if mode == "off" { return q_id; }
    h log_d = null;
    if mode == "fused" {
        log_d = tape_phi_log(q_id, scale);
    } else {
        # "composed" (or any unrecognized mode falls through to the boring path)
        log_d = _prom_q6_log_distance_composed(q_id, scale);
    }
    h modulation = _prom_q6_modulation_from_log_d(log_d, gamma);
    return tape_mul(q_id, modulation);
}

# L2: substrate K + Q. Only V is learned.
# Q is derived as: x_pos_concat * fixed projection (use CRT-PE directly).
# In the simplest form: Q = CRT-PE (same as K) so each position queries
# its own substrate address. The attention reduces to "soft positional
# self-similarity" — diagonal-biased by construction.
fn prom_attention_substrate_kq_new(d_model, seq_len, rng_state) {
    h V = _prom_random_matrix(d_model, d_model, 0.3, rng_state);
    h layer = dict_new();
    dict_set(layer, "kind", "attention");
    dict_set(layer, "variant", "substrate_kq");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "seq_len", seq_len);
    dict_set(layer, "V", dict_get(V, "node"));
    h pe = prom_crt_pe_matrix(seq_len, d_model);
    dict_set(layer, "K_const", pe);
    dict_set(layer, "Q_const", pe);
    dict_set(layer, "alpha", 0.0);
    dict_set(layer, "rng_state", dict_get(V, "state"));
    return layer;
}

fn prom_attention_substrate_kq_forward(layer, x_id) {
    h V_w = dict_get(layer, "V");
    h K_const = dict_get(layer, "K_const");
    h Q_const = dict_get(layer, "Q_const");
    h v = tape_matmul(x_id, V_w);
    h q = tape_const(Q_const);
    h k = tape_const(K_const);
    h kt = tape_transpose(k);
    h scores = tape_matmul(q, kt);
    h attn = tape_softmax(scores);
    return tape_matmul(attn, v);
}

# L3: fully substrate attention. Zero learnable params in the layer.
# Q = K = CRT-PE; V = identity transform on x (the input passes
# through unchanged, weighted by substrate-determined attention).
fn prom_attention_substrate_full_new(d_model, seq_len) {
    h layer = dict_new();
    dict_set(layer, "kind", "attention_substrate_full");
    dict_set(layer, "variant", "substrate_full");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "seq_len", seq_len);
    h pe = prom_crt_pe_matrix(seq_len, d_model);
    dict_set(layer, "K_const", pe);
    dict_set(layer, "Q_const", pe);
    dict_set(layer, "alpha", 0.0);
    return layer;
}

fn prom_attention_substrate_full_forward(layer, x_id) {
    h K_const = dict_get(layer, "K_const");
    h Q_const = dict_get(layer, "Q_const");
    h q = tape_const(Q_const);
    h k = tape_const(K_const);
    h kt = tape_transpose(k);
    h scores = tape_matmul(q, kt);
    h attn = tape_softmax(scores);
    # V is x itself — no transformation. The block weights x by
    # substrate-determined attention.
    return tape_matmul(attn, x_id);
}

# ---------------------------------------------------------------------------
# Multi-head substrate-K attention.
#
# PyTorch's L1-MH (-8.94% val) and Q6-MH (-12.15% val) findings need
# multi-head capacity to fire — single-head OMC saw roughly a third of
# those wins (SUBSTRATE_STACK_OMC_XVAL.md). This wraps n_heads independent
# substrate-K heads with per-head W_O projections. Their outputs SUM to
# the final attention output, which is mathematically identical to the
# standard "concat then project" formulation:
#
#   standard:  out = concat(out_1, ..., out_h) @ W_O
#              W_O is [n_h·d_head, d_model] = block-stack of [W_O_1; ...; W_O_h]
#   so:        out = sum_h(out_h @ W_O_h)        ← what we use
#
# Equivalent math, no tape_concat op needed. Each head gets its own
# Q_h, V_h, W_O_h, and per-head substrate K (CRT-PE of width d_head).
# All the single-head toggles (smod_alpha, v_resample_scale, q6_mode)
# are honored per-head; defaults match the single-head layer.
# ---------------------------------------------------------------------------

fn prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, rng_state) {
    if d_model - (d_model / n_heads) * n_heads != 0 {
        # d_model must be divisible by n_heads.
        # (OMC has no error-throw primitive here; fall through and the
        # smaller-than-expected d_head will produce a shape error later.)
    }
    h d_head = d_model / n_heads;
    h heads = [];
    h state = rng_state;
    h hi = 0;
    while hi < n_heads {
        h Q = _prom_random_matrix(d_model, d_head, 0.3, state);
        state = dict_get(Q, "state");
        h V = _prom_random_matrix(d_model, d_head, 0.3, state);
        state = dict_get(V, "state");
        h W_O = _prom_random_matrix(d_head, d_model, 0.3, state);
        state = dict_get(W_O, "state");
        h head = dict_new();
        dict_set(head, "Q", dict_get(Q, "node"));
        dict_set(head, "V", dict_get(V, "node"));
        dict_set(head, "W_O", dict_get(W_O, "node"));
        dict_set(head, "K_const", prom_crt_pe_matrix(seq_len, d_head));
        arr_push(heads, head);
        hi += 1;
    }
    h layer = dict_new();
    dict_set(layer, "kind", "attention");
    dict_set(layer, "variant", "substrate_k_mh");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "d_head", d_head);
    dict_set(layer, "n_heads", n_heads);
    dict_set(layer, "seq_len", seq_len);
    dict_set(layer, "heads", heads);
    # Per-head toggles match the single-head substrate_k_new defaults.
    dict_set(layer, "smod_alpha", 1.0);
    dict_set(layer, "v_resample_scale", 10.0);
    dict_set(layer, "q6_mode", "off");
    dict_set(layer, "q6_scale", 10.0);
    dict_set(layer, "q6_gamma", 0.5);
    dict_set(layer, "rng_state", state);
    return layer;
}

fn prom_attention_substrate_k_mh_forward(layer, x_id) {
    h n_heads = dict_get(layer, "n_heads");
    h heads = dict_get(layer, "heads");
    h smod_alpha = dict_get(layer, "smod_alpha");
    h v_scale = dict_get(layer, "v_resample_scale");
    h q6_mode = dict_get(layer, "q6_mode");
    h q6_scale = dict_get(layer, "q6_scale");
    h q6_gamma = dict_get(layer, "q6_gamma");

    h sum_proj = null;
    h hi = 0;
    while hi < n_heads {
        h head = arr_get(heads, hi);
        h Q_w = dict_get(head, "Q");
        h V_w = dict_get(head, "V");
        h W_O = dict_get(head, "W_O");
        h K_const = dict_get(head, "K_const");

        h q = tape_matmul(x_id, Q_w);                          # [N, d_head]
        h q_mod = prom_q6_modulate(q, q6_scale, q6_gamma, q6_mode);
        h v_raw = tape_matmul(x_id, V_w);                       # [N, d_head]
        h v = prom_substrate_resample(v_raw, v_scale);
        h k = tape_const(K_const);
        h kt = tape_transpose(k);
        h scores = tape_matmul(q_mod, kt);                      # [N, seq_len]
        h attn = prom_substrate_softmax(scores, smod_alpha);
        h out_h = tape_matmul(attn, v);                         # [N, d_head]
        h proj_h = tape_matmul(out_h, W_O);                     # [N, d_model]
        if sum_proj == null {
            sum_proj = proj_h;
        } else {
            sum_proj = tape_add(sum_proj, proj_h);
        }
        hi += 1;
    }
    return sum_proj;
}

fn prom_attention_substrate_k_mh_params(layer) {
    h heads = dict_get(layer, "heads");
    h out = [];
    h hi = 0;
    while hi < arr_len(heads) {
        h head = arr_get(heads, hi);
        arr_push(out, dict_get(head, "Q"));
        arr_push(out, dict_get(head, "V"));
        arr_push(out, dict_get(head, "W_O"));
        hi += 1;
    }
    return out;
}

# Param collectors per variant.
fn prom_attention_substrate_k_params(layer) {
    return [dict_get(layer, "Q"), dict_get(layer, "V")];
}
fn prom_attention_substrate_kq_params(layer) {
    return [dict_get(layer, "V")];
}
fn prom_attention_substrate_full_params(layer) {
    return [];
}

fn prom_attention_params(layer) {
    h out = [];
    arr_push(out, dict_get(layer, "Q"));
    arr_push(out, dict_get(layer, "K"));
    arr_push(out, dict_get(layer, "V"));
    return out;
}

# ---------------------------------------------------------------------------
# AdamW optimizer — the workhorse modern optimizer.
#
# Maintains per-param first & second gradient moments (m, v); applies
# bias-corrected updates with decoupled weight decay. Implementation
# uses the new tape_set_value Rust builtin so the actual update math
# happens in pure OMC space — easy to instrument or replace.
#
#   m_t = β1 · m_{t-1} + (1-β1) · g
#   v_t = β2 · v_{t-1} + (1-β2) · g²
#   θ_t = θ_{t-1} − lr · (m_t/(1-β1^t)) / (sqrt(v_t/(1-β2^t)) + ε)
#          − lr · wd · θ_{t-1}                         (decoupled weight decay)
# ---------------------------------------------------------------------------

fn prom_adamw_new(params, lr, beta1, beta2, eps, weight_decay) {
    h state = dict_new();
    dict_set(state, "params", params);
    dict_set(state, "lr", lr);
    dict_set(state, "beta1", beta1);
    dict_set(state, "beta2", beta2);
    dict_set(state, "eps", eps);
    dict_set(state, "wd", weight_decay);
    dict_set(state, "step", 0);
    # m and v are arrays parallel to params, each storing a value
    # matching the param's shape. Initialized to zeros on first step
    # to avoid having to compute shapes here.
    dict_set(state, "m", []);
    dict_set(state, "v", []);
    return state;
}

# Zero-shaped-like for a numeric value (scalar / 1D / 2D array).
fn _prom_zeros_like(v) {
    if type_of(v) == "array" {
        h out = [];
        h i = 0;
        while i < arr_len(v) {
            h e = arr_get(v, i);
            if type_of(e) == "array" {
                arr_push(out, _prom_zeros_like(e));
            } else {
                arr_push(out, 0.0);
            }
            i += 1;
        }
        return out;
    }
    return 0.0;
}

# Element-wise binary op on values of arbitrary nested shape (scalar/1D/2D).
fn _prom_zip(a, b, op) {
    if type_of(a) == "array" {
        h out = [];
        h i = 0;
        while i < arr_len(a) {
            arr_push(out, _prom_zip(arr_get(a, i), arr_get(b, i), op));
            i += 1;
        }
        return out;
    }
    if op == "add" { return a + b; }
    if op == "sub" { return a - b; }
    if op == "mul" { return a * b; }
    if op == "div" { return a / b; }
    return 0.0;
}

# Element-wise scalar op on a nested-shape value.
fn _prom_scale(v, s, op) {
    if type_of(v) == "array" {
        h out = [];
        h i = 0;
        while i < arr_len(v) {
            arr_push(out, _prom_scale(arr_get(v, i), s, op));
            i += 1;
        }
        return out;
    }
    if op == "mul" { return v * s; }
    if op == "add" { return v + s; }
    if op == "sub" { return v - s; }
    return v;
}

fn _prom_sqrt_eps(v, eps) {
    if type_of(v) == "array" {
        h out = [];
        h i = 0;
        while i < arr_len(v) {
            arr_push(out, _prom_sqrt_eps(arr_get(v, i), eps));
            i += 1;
        }
        return out;
    }
    return sqrt(v) + eps;
}

# One AdamW step. Updates state in-place (mutates dict + tape values).
fn prom_adamw_step(state) {
    h params = dict_get(state, "params");
    h lr = dict_get(state, "lr");
    h b1 = dict_get(state, "beta1");
    h b2 = dict_get(state, "beta2");
    h eps = dict_get(state, "eps");
    h wd = dict_get(state, "wd");
    h step = dict_get(state, "step") + 1;
    dict_set(state, "step", step);

    h m = dict_get(state, "m");
    h v = dict_get(state, "v");

    # Lazy-init m and v on first step using grad shapes.
    if arr_len(m) == 0 {
        h i = 0;
        while i < arr_len(params) {
            h g = tape_grad(arr_get(params, i));
            arr_push(m, _prom_zeros_like(g));
            arr_push(v, _prom_zeros_like(g));
            i += 1;
        }
        dict_set(state, "m", m);
        dict_set(state, "v", v);
    }

    h bias1 = 1.0 - pow(b1, step * 1.0);
    h bias2 = 1.0 - pow(b2, step * 1.0);

    # v0.8.4 fused inner update: substrate_adamw_update is a Rust builtin
    # that replaces ~15 OMC-side elementwise loops per parameter with one
    # tight Rust loop. The m / v OMC arrays are Rc-shared, so the builtin
    # mutates them in place; the returned value is the new parameter.
    # See ADAMW_BUILTIN.md for the wall-clock reasoning. bias1/bias2 are
    # computed inside the builtin from (b1, b2, step) — no need to pass.
    h i = 0;
    while i < arr_len(params) {
        h p = arr_get(params, i);
        h g = tape_grad(p);
        h m_old = arr_get(m, i);
        h v_old = arr_get(v, i);
        h cur = tape_value(p);
        h new_val = substrate_adamw_update(cur, g, m_old, v_old,
                                            lr, b1, b2, eps, wd, step);
        tape_set_value(p, new_val);
        i += 1;
    }
}

# ---------------------------------------------------------------------------
# Embedding layer — direct row lookup.
# table: [vocab, d_model]; forward(token_idx) = table[token_idx, :]
# Built without a tape_embedding_lookup builtin yet — we use
# tape_matmul with a one-hot, which is mathematically equivalent and
# composes with the existing autograd. Will replace with a fused
# Rust op when JIT'd embedding is a bottleneck.
# ---------------------------------------------------------------------------

fn prom_embedding_new(vocab, d_model, rng_state) {
    h table = _prom_random_matrix(vocab, d_model, 0.3, rng_state);
    h layer = dict_new();
    dict_set(layer, "kind", "embedding");
    dict_set(layer, "vocab", vocab);
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "table", dict_get(table, "node"));
    dict_set(layer, "rng_state", dict_get(table, "state"));
    return layer;
}

# Forward: token_idx → [1, d_model] embedding row.
# Uses one-hot @ table internally; result is differentiable into the
# table param so backward updates the relevant row.
fn prom_embedding_forward(layer, token_idx) {
    h vocab = dict_get(layer, "vocab");
    h table = dict_get(layer, "table");
    h x = prom_one_hot(token_idx, vocab);
    return tape_matmul(x, table);
}

fn prom_embedding_params(layer) {
    return [dict_get(layer, "table")];
}

# Batched embedding lookup: token_ids[] → [N, d_model] matrix.
# Implemented via an [N, vocab] one-hot batch then matmul with the
# embedding table. Differentiable end-to-end.
fn prom_embedding_batch(layer, token_ids) {
    # v0.8.5 — defers to the tape_embedding_lookup Rust builtin. Direct
    # row gather instead of building an [N, vocab] one-hot in OMC and
    # matmulling. Backward scatters dL/dout rows back into table grad,
    # which is the same gradient as the one-hot @ table chain produced.
    h table = dict_get(layer, "table");
    return tape_embedding_lookup(table, token_ids);
}

# Batched cross-entropy: logits is [N, vocab], targets is array of N
# integer indices. Returns scalar mean loss (averaged over positions).
#
# v0.8.5 — defers to the fused tape_cross_entropy_batch Rust builtin
# (closed-form (p - one_hot) / N backward, no intermediate tape nodes).
# `vocab` is accepted but unused (the builtin reads it from logits.cols);
# kept in the signature for callers that pass it.
fn prom_cross_entropy_batch(logits_id, targets, vocab) {
    return tape_cross_entropy_batch(logits_id, targets);
}

# ---------------------------------------------------------------------------
# LayerNorm — normalize each row to zero mean / unit variance, then
# scale + shift by learned gamma/beta.
#
# Composed from existing tape ops: subtract row mean, divide by row
# std + eps, multiply by gamma, add beta. Backward is automatic via
# the tape.
# ---------------------------------------------------------------------------

fn prom_layernorm_new(d_model, rng_state) {
    # Initialize gamma=1, beta=0 (identity transform at init).
    h gamma_row = [];
    h beta_row = [];
    h i = 0;
    while i < d_model {
        arr_push(gamma_row, 1.0);
        arr_push(beta_row, 0.0);
        i += 1;
    }
    h gamma = tape_var([gamma_row]);
    h beta = tape_var([beta_row]);
    h layer = dict_new();
    dict_set(layer, "kind", "layernorm");
    dict_set(layer, "d_model", d_model);
    dict_set(layer, "gamma", gamma);
    dict_set(layer, "beta", beta);
    dict_set(layer, "eps", 1e-5);
    dict_set(layer, "rng_state", rng_state);
    return layer;
}

# Forward: x is [N, d_model]; per-row layer norm via the fused
# tape_layernorm Rust op. Works for both single-row [1, d] and
# multi-token [seq, d] shapes — same code path.
fn prom_layernorm_forward(layer, x_id) {
    h gamma = dict_get(layer, "gamma");
    h beta = dict_get(layer, "beta");
    h eps = dict_get(layer, "eps");
    return tape_layernorm(x_id, gamma, beta, eps);
}

fn prom_layernorm_params(layer) {
    return [dict_get(layer, "gamma"), dict_get(layer, "beta")];
}

# ---------------------------------------------------------------------------
# CRT-Fibonacci positional encoding — validated transformerless-LM win.
#
# Today's PyTorch experiments showed:
#   - CRT-PE wins −5.4% on TinyShakespeare (3/3 seeds, train_scale.py)
#   - −2.9% on distractor mix (3/3, train_distractor_mix.py)
#   - Pairs each Fibonacci modulus with a sin/cos pair on a 2π·pos/m circle
#
# Same moduli as the geodesic bias for architectural coherence.
# ---------------------------------------------------------------------------

fn prom_crt_pe_matrix(seq_len, d_model) {
    h moduli = _prom_geodesic_moduli();
    h n_pairs = d_model / 2;
    h table = [];
    h pos = 0;
    while pos < seq_len {
        h row = [];
        h i = 0;
        while i < n_pairs {
            h m = arr_get(moduli, i - (i / arr_len(moduli)) * arr_len(moduli));
            h residue = pos - (pos / m) * m;
            h angle = 6.283185307179586 * residue / (m * 1.0);
            arr_push(row, sin(angle));
            arr_push(row, cos(angle));
            i += 1;
        }
        # If d_model is odd, pad final cell with 0.
        if (n_pairs * 2) < d_model {
            arr_push(row, 0.0);
        }
        arr_push(table, row);
        pos += 1;
    }
    return table;
}

# ---------------------------------------------------------------------------
# Sequential composition — chain layers; collect params automatically.
# ---------------------------------------------------------------------------

fn prom_sequential(layers) {
    h model = dict_new();
    dict_set(model, "kind", "sequential");
    dict_set(model, "layers", layers);
    return model;
}

fn prom_sequential_forward(model, x_id) {
    h layers = dict_get(model, "layers");
    h cur = x_id;
    h i = 0;
    while i < arr_len(layers) {
        h L = arr_get(layers, i);
        h kind = dict_get(L, "kind");
        if kind == "linear" { cur = prom_linear_forward(L, cur); }
        elif kind == "embedding" { cur = prom_embedding_forward(L, cur); }
        elif kind == "layernorm" { cur = prom_layernorm_forward(L, cur); }
        elif kind == "attention" { cur = prom_attention_forward(L, cur); }
        elif kind == "relu" { cur = prom_relu(cur); }
        elif kind == "sigmoid" { cur = prom_sigmoid(cur); }
        i += 1;
    }
    return cur;
}

# Activation pseudo-layers — let users put them inline in a Sequential.
fn prom_relu_layer() {
    h L = dict_new(); dict_set(L, "kind", "relu"); return L;
}
fn prom_sigmoid_layer() {
    h L = dict_new(); dict_set(L, "kind", "sigmoid"); return L;
}

# Collect params from all layers (extends to embedding + layernorm too).
fn prom_collect_params_v2(layers) {
    h out = [];
    h i = 0;
    while i < arr_len(layers) {
        h L = arr_get(layers, i);
        h kind = dict_get(L, "kind");
        h ps = [];
        if kind == "linear" { ps = prom_linear_params(L); }
        elif kind == "embedding" { ps = prom_embedding_params(L); }
        elif kind == "layernorm" { ps = prom_layernorm_params(L); }
        elif kind == "attention" { ps = prom_attention_params(L); }
        h j = 0;
        while j < arr_len(ps) {
            arr_push(out, arr_get(ps, j));
            j += 1;
        }
        i += 1;
    }
    return out;
}

# =============================================================================
# requests bridge for OMC — HTTP in 30 lines
# =============================================================================
# Wraps python's `requests` library. OMC programs gain real HTTP:
# fetch APIs, post JSON, scrape pages, anything you'd do in Python.
#
# Usage:
#   import "examples/lib/requests.omc" as r;
#   h resp = r.get("https://api.github.com/zen");
#   println(r.text(resp));
# =============================================================================

h _RQ_HANDLE = 0;

fn _rq() {
    if _RQ_HANDLE == 0 {
        _RQ_HANDLE = py_import("requests");
    }
    return _RQ_HANDLE;
}

# ---- Verbs (return Response handles) -------------------------------------

fn get(url)              { return py_call(_rq(), "get",    [url]); }
fn post(url, data)       { return py_call(_rq(), "post",   [url, data]); }
fn put(url, data)        { return py_call(_rq(), "put",    [url, data]); }
fn delete(url)           { return py_call(_rq(), "delete", [url]); }
fn head(url)             { return py_call(_rq(), "head",   [url]); }

# ---- Response inspection -------------------------------------------------

fn status(resp)          { return py_get(resp, "status_code"); }
fn text(resp)            { return py_get(resp, "text"); }
fn json(resp)            { return py_call(resp, "json", []); }
fn headers(resp)         { return py_get(resp, "headers"); }
fn url_of(resp)          { return py_get(resp, "url"); }
fn ok(resp) {
    h s = status(resp);
    if s >= 200 {
        if s < 300 {
            return 1;
        }
    }
    return 0;
}

# ---- Convenience: one-line GET-and-parse-JSON ----------------------------
# Returns the parsed JSON as an OMC dict/array, or null on non-200.
fn fetch_json(url) {
    h resp = get(url);
    if ok(resp) == 1 {
        return json(resp);
    }
    return null;
}

# Returns response text or null.
fn fetch_text(url) {
    h resp = get(url);
    if ok(resp) == 1 {
        return text(resp);
    }
    return null;
}

# =============================================================================
# rsi.omc — Recursive Self-Improvement library for OMC
# =============================================================================
#
# Core concepts
# ─────────────
# Candidate  — dict {code: string, score: float, gen: int, note: string}
# Population — Candidate[]
# Fitness fn — fn(code: string) → float   (0.0 = worst, ∞ = best)
#
# Typical loop
# ────────────
#   import "examples/lib/rsi.omc" as rsi
#   h pop  = rsi.rsi_seed(seed_code, 4, fitness_fn)
#   h best = rsi.rsi_run(seed_code, fitness_fn, {})
#   print(best["history"][0]["code"])
#
# ── Candidate primitives ──────────────────────────────────────────────────────

# rsi_make_candidate(code, score, gen, note) → Candidate
fn rsi_make_candidate(code, score, gen, note) {
    return {
        "code":  code,
        "score": score,
        "gen":   gen,
        "note":  note
    }
}

# ── Seeding ───────────────────────────────────────────────────────────────────

# rsi_seed(seed_code, n_variants, fitness_fn) → Candidate[]
# Build an initial population of n_variants from seed_code.
# The first candidate is the seed itself; extras are stub variants tagged by
# their Fibonacci-hash position (no LLM call; deterministic).
fn rsi_seed(seed_code, n_variants, fitness_fn) {
    h pop = []
    h i = 0
    while i < n_variants {
        h code  = seed_code
        h score = fitness_fn(code)
        arr_push(pop, rsi_make_candidate(code, score, 0, "seed"))
        i = i + 1
    }
    return pop
}

# ── Fitness helpers ───────────────────────────────────────────────────────────

# rsi_weighted_fitness(fns, weights) → fitness_fn
# Returns a single fitness function that is a weighted sum of `fns`.
# `weights` need not sum to 1; raw weighted sum is returned.
fn rsi_weighted_fitness(fns, weights) {
    return fn(code) {
        h score = 0.0
        h i = 0
        while i < len(fns) {
            h w = weights[i]
            h f = fns[i]
            score = score + w * f(code)
            i = i + 1
        }
        return score
    }
}

# rsi_substrate_fitness(seed_code) → fn(code) → float
# Returns a fitness function that scores code by structural similarity
# (cosine sim of substrate embeddings) to the seed code.  Score ∈ [0, 1].
fn rsi_substrate_fitness(seed_code) {
    h seed_emb = substrate_embed(seed_code, 16)
    return fn(code) {
        h emb = substrate_embed(code, 16)
        h dot = 0.0
        h i   = 0
        while i < arr_len(seed_emb) {
            dot = dot + seed_emb[i] * emb[i]
            i   = i + 1
        }
        if dot < 0.0 { dot = 0.0 }
        if dot > 1.0 { dot = 1.0 }
        return dot
    }
}

# rsi_composite_fitness(fns, weights) → fn(code) → float
# Normalised weighted average of multiple fitness functions.
# Identical to rsi_weighted_fitness but divides by sum(weights) so the
# result always lies in the same [0,1] range as each component (assuming
# each component also returns [0,1]).
fn rsi_composite_fitness(fns, weights) {
    h total = 0.0
    h wi    = 0
    while wi < len(weights) {
        total = total + weights[wi]
        wi    = wi + 1
    }
    if total == 0.0 { total = 1.0 }
    return fn(code) {
        h score = 0.0
        h i = 0
        while i < len(fns) {
            h w = weights[i]
            h f = fns[i]
            score = score + w * f(code)
            i = i + 1
        }
        return score / total
    }
}

# ── Evaluation ────────────────────────────────────────────────────────────────

# rsi_evaluate(pop, fitness_fn) → Candidate[]
# Re-score every candidate in `pop` using `fitness_fn`.
# Returns a new list with updated scores (originals untouched).
fn rsi_evaluate(pop, fitness_fn) {
    h result = []
    h i = 0
    while i < len(pop) {
        h c         = pop[i]
        h new_score = fitness_fn(c["code"])
        arr_push(result, rsi_make_candidate(c["code"], new_score, c["gen"], c["note"]))
        i = i + 1
    }
    return result
}

# ── Sorting & selection ───────────────────────────────────────────────────────

# rsi_sort_pop(pop) → Candidate[]
# Descending insertion sort by score (best first).
fn rsi_sort_pop(pop) {
    h sorted = []
    h i = 0
    while i < len(pop) {
        arr_push(sorted, pop[i])
        i = i + 1
    }
    h n = arr_len(sorted)
    h ii = 1
    while ii < n {
        h key = sorted[ii]
        h j   = ii - 1
        while j >= 0 {
            if sorted[j]["score"] >= key["score"] {
                j = -1
            } else {
                sorted[j + 1] = sorted[j]
                sorted[j]     = key
                j = j - 1
            }
        }
        ii = ii + 1
    }
    return sorted
}

# rsi_best(pop) → Candidate
# Return the highest-scoring candidate.
fn rsi_best(pop) {
    h sorted = rsi_sort_pop(pop)
    return sorted[0]
}

# rsi_top_k(pop, k) → Candidate[]
# Return up to the top-k candidates by score.
fn rsi_top_k(pop, k) {
    h sorted = rsi_sort_pop(pop)
    h result = []
    h i = 0
    while i < k {
        if i < len(sorted) {
            arr_push(result, sorted[i])
        }
        i = i + 1
    }
    return result
}

# rsi_tournament(pop, k) → Candidate
# Tournament selection: pick k candidates (via harmonic hash spread) and
# return the best among them.
fn rsi_tournament(pop, k) {
    h n    = len(pop)
    h best = pop[0]
    h i    = 0
    while i < k {
        h idx       = harmonic_hash(to_string(i) + best["code"]) % n
        h contender = pop[idx]
        if contender["score"] > best["score"] {
            best = contender
        }
        i = i + 1
    }
    return best
}

# ── Mutation (LLM-backed) ─────────────────────────────────────────────────────

# rsi_mutate(candidate, model, system_prompt) → Candidate
# Ask the LLM to produce one improved variant of candidate["code"].
# Returns a new Candidate with gen incremented and score=-1 (unevaluated).
fn rsi_mutate(candidate, model, system_prompt) {
    h sys   = system_prompt
    if sys == null { sys = "You are an OMC code optimizer. Return ONLY the improved OMC code, no explanation." }
    h prompt = "Improve this OMC function for correctness and performance:\n\n" + candidate["code"]
    h new_code = llm_call(prompt, model, {"system": sys})
    return rsi_make_candidate(new_code, -1.0, candidate["gen"] + 1, "mutated")
}

# rsi_mutate_batch(candidates, model, system_prompt) → Candidate[]
# Mutate a list of candidates in one batch (sequential, respects rate limits).
fn rsi_mutate_batch(candidates, model, system_prompt) {
    h sys = system_prompt
    if sys == null { sys = "You are an OMC code optimizer. Return ONLY the improved OMC code, no explanation." }
    h prompts = []
    h i = 0
    while i < len(candidates) {
        h c = candidates[i]
        arr_push(prompts, {"prompt": "Improve this OMC function:\n\n" + c["code"], "system": sys})
        i = i + 1
    }
    h replies  = batch_llm_call(prompts, model)
    h result   = []
    h j = 0
    while j < len(candidates) {
        h orig = candidates[j]
        arr_push(result, rsi_make_candidate(replies[j], -1.0, orig["gen"] + 1, "mutated"))
        j = j + 1
    }
    return result
}

# ── Structural analysis ───────────────────────────────────────────────────────

# rsi_fingerprints(pop) → dict[]
# Return [{idx, code, score, gen, fingerprint, attractor}] for each candidate.
fn rsi_fingerprints(pop) {
    h result = []
    h i = 0
    while i < len(pop) {
        h c    = pop[i]
        h info = omc_canonical_hash(c["code"])
        h fp   = to_string(omc_code_fingerprint(c["code"]))
        arr_push(result, {
            "idx":         i,
            "code":        c["code"],
            "score":       c["score"],
            "gen":         c["gen"],
            "fingerprint": fp,
            "attractor":   info["attractor"]
        })
        i = i + 1
    }
    return result
}

# rsi_fingerprint(pop) → dict[]
# Alias for rsi_fingerprints (singular/plural both accepted).
fn rsi_fingerprint(pop) {
    return rsi_fingerprints(pop)
}

# rsi_dedupe(pop) → Candidate[]
# Remove structurally duplicate candidates (same canonical fingerprint).
# Keeps the first (highest-scoring if pre-sorted) occurrence.
fn rsi_dedupe(pop) {
    h seen   = {}
    h result = []
    h i = 0
    while i < len(pop) {
        h c  = pop[i]
        h key = c["code"]
        if seen[key] == null {
            seen[key] = 1
            arr_push(result, c)
        }
        i = i + 1
    }
    return result
}

# rsi_diff_report(a, b) → dict
# Structural diff between two candidates (or raw code strings).
# Returns {added, removed, modified, unchanged, similarity}.
fn rsi_diff_report(a, b) {
    h ca = a
    h cb = b
    if type_of(a) == "dict" { ca = a["code"] }
    if type_of(b) == "dict" { cb = b["code"] }
    h diff = omc_code_diff(ca, cb)
    h sim  = omc_code_similarity(ca, cb)
    return {
        "added":     diff["added"],
        "removed":   diff["removed"],
        "modified":  diff["modified"],
        "unchanged": diff["unchanged"],
        "similarity": sim
    }
}

# rsi_summary(pop) → dict
# Population statistics: {size, best_score, worst_score, mean_score, generations}.
fn rsi_summary(pop) {
    h n    = len(pop)
    if n == 0 {
        return {"size": 0, "best_score": 0.0, "worst_score": 0.0, "mean_score": 0.0, "generations_seen": 0}
    }
    h best  = pop[0]["score"]
    h worst = pop[0]["score"]
    h total = 0.0
    h max_g = pop[0]["gen"]
    h i = 0
    while i < n {
        h s = pop[i]["score"]
        h g = pop[i]["gen"]
        if s > best  { best  = s }
        if s < worst { worst = s }
        total = total + s
        if g > max_g { max_g = g }
        i = i + 1
    }
    return {
        "size":        n,
        "best_score":  best,
        "worst_score": worst,
        "mean_score":  total / n,
        "generations_seen": max_g
    }
}

# ── Best-of-N ─────────────────────────────────────────────────────────────────

# rsi_best_of_n(candidate, n, fitness_fn, model, system_prompt) → Candidate
# Generate n LLM mutations, evaluate each, return the best.
fn rsi_best_of_n(candidate, n, fitness_fn, model, system_prompt) {
    h best   = candidate
    h i      = 0
    while i < n {
        h mut   = rsi_mutate(candidate, model, system_prompt)
        h score = fitness_fn(mut["code"])
        h evaled = rsi_make_candidate(mut["code"], score, mut["gen"], mut["note"])
        if score > best["score"] {
            best = evaled
        }
        i = i + 1
    }
    return best
}

# ── Hill-climbing loop ────────────────────────────────────────────────────────

# rsi_hill_climb(pop, fitness_fn, model, opts) → dict
# opts keys (all optional):
#   generations  int    default 5
#   keep         int    default 4   (elites carried per generation)
#   n_mutants    int    default 4   (new mutations per elite)
#   model        str    default "claude-3-5-haiku-20241022"
#   system       str    system prompt for mutations
#
# Returns {best: Candidate, history: Candidate[], gens: int}
fn rsi_hill_climb(pop, fitness_fn, model, opts) {
    h generations = opts["generations"]
    h keep        = opts["keep"]
    h n_mutants   = opts["n_mutants"]
    h sys_prompt  = opts["system"]
    if generations == null { generations = 5 }
    if keep        == null { keep        = 4 }
    if n_mutants   == null { n_mutants   = 4 }
    if model       == null { model       = "claude-3-5-haiku-20241022" }

    h current  = rsi_evaluate(pop, fitness_fn)
    h history  = []
    h g        = 0

    while g < generations {
        h survivors = rsi_top_k(current, keep)
        h next_gen  = []
        h ei        = 0
        while ei < arr_len(survivors) {
            arr_push(next_gen, survivors[ei])
            ei = ei + 1
        }

        # Mutate each survivor n_mutants times
        h mi = 0
        while mi < arr_len(survivors) {
            h elite   = survivors[mi]
            h mutants = []
            h mj      = 0
            while mj < n_mutants {
                arr_push(mutants, rsi_mutate(elite, model, sys_prompt))
                mj = mj + 1
            }
            h evaled = rsi_evaluate(mutants, fitness_fn)
            h ek = 0
            while ek < arr_len(evaled) {
                arr_push(next_gen, evaled[ek])
                ek = ek + 1
            }
            mi = mi + 1
        }

        h gen_best = rsi_best(next_gen)
        arr_push(history, gen_best)
        current = next_gen
        g = g + 1
    }

    return {
        "best":    rsi_best(current),
        "history": history,
        "gens":    g
    }
}

# ── LLM-judge scoring ─────────────────────────────────────────────────────────

# rsi_judge_score(pop, criteria, model) → Candidate[]
# Re-score population using llm_judge (score normalised to [0,1]).
fn rsi_judge_score(pop, criteria, model) {
    h codes = arr_map(pop, fn(c) { return c["code"] })
    h raw   = llm_judge(codes, criteria, model)
    h result = []
    h i = 0
    while i < len(pop) {
        h c     = pop[i]
        h score = raw[i]["score"] / 10.0
        arr_push(result, rsi_make_candidate(c["code"], score, c["gen"], c["note"]))
        i = i + 1
    }
    return result
}

# ── Pruning ───────────────────────────────────────────────────────────────────

# rsi_prune_similar(pop, threshold) → Candidate[]
# Remove candidates that are too similar (omc_code_similarity > threshold)
# to any already-kept candidate.  Keeps the first (best-scoring if sorted).
fn rsi_prune_similar(pop, threshold) {
    h kept   = []
    h i = 0
    while i < len(pop) {
        h c       = pop[i]
        h too_sim = 0
        h j = 0
        while j < arr_len(kept) {
            h sim = omc_code_similarity(c["code"], kept[j]["code"])
            if sim > threshold {
                too_sim = 1
                j = arr_len(kept)   # break
            }
            j = j + 1
        }
        if too_sim == 0 {
            arr_push(kept, c)
        }
        i = i + 1
    }
    return kept
}

# ── Lineage & provenance ──────────────────────────────────────────────────────

# rsi_lineage(pop) → dict[]
# Return [{gen, code, score, note}] as a generation-sorted lineage log.
fn rsi_lineage(pop) {
    h sorted  = rsi_sort_pop(pop)
    h lineage = []
    h i = 0
    while i < arr_len(sorted) {
        h c = sorted[i]
        arr_push(lineage, {
            "gen":   c["gen"],
            "code":  c["code"],
            "score": c["score"],
            "note":  c["note"]
        })
        i = i + 1
    }
    return lineage
}

# rsi_most_similar(candidate, pop) → Candidate
# Find the candidate in `pop` most similar to `candidate` (by substrate embed).
fn rsi_most_similar(candidate, pop) {
    h ref_emb = substrate_embed(candidate["code"], 16)
    h best_c  = pop[0]
    h best_s  = -1.0
    h i       = 0
    while i < len(pop) {
        h c   = pop[i]
        h emb = substrate_embed(c["code"], 16)
        h dot = 0.0
        h di  = 0
        while di < arr_len(ref_emb) {
            dot = dot + ref_emb[di] * emb[di]
            di  = di + 1
        }
        if dot > best_s {
            best_s = dot
            best_c = c
        }
        i = i + 1
    }
    return best_c
}

# ── Top-level run helpers ─────────────────────────────────────────────────────

# rsi_run(seed_code, fitness_fn, opts) → dict
# Complete RSI loop: seed → hill-climb → return best.
# opts: same as rsi_hill_climb plus {n_seed: int} for initial pop size.
fn rsi_run(seed_code, fitness_fn, opts) {
    h n_seed = opts["n_seed"]
    h model  = opts["model"]
    if n_seed == null { n_seed = 4 }
    if model  == null { model  = "claude-3-5-haiku-20241022" }

    h pop = rsi_seed(seed_code, n_seed, fitness_fn)
    return rsi_hill_climb(pop, fitness_fn, model, opts)
}

# rsi_run_with_judge(seed_code, criteria, opts) → dict
# Like rsi_run but uses llm_judge for scoring instead of a fitness function.
fn rsi_run_with_judge(seed_code, criteria, opts) {
    h model     = opts["model"]
    h judge_mod = opts["judge_model"]
    if model     == null { model     = "claude-3-5-haiku-20241022" }
    if judge_mod == null { judge_mod = model }

    return rsi_run(seed_code, fn(code) {
        h scores = llm_judge([code], criteria, judge_mod)
        return scores[0]["score"] / 10.0
    }, opts)
}

# schema.omc — JSON schema validation and coercion

# ── Type checking ───────────────────────────────────────────────────────────

fn schema_type_of(v) {
    if v == null { return "null" }
    if type_of(v) == "bool" { return "boolean" }
    if type_of(v) == "int" or type_of(v) == "float" { return "number" }
    if type_of(v) == "string" { return "string" }
    if type_of(v) == "array" { return "array" }
    if type_of(v) == "dict" { return "object" }
    return "unknown"
}

# ── Core validate ───────────────────────────────────────────────────────────

# validate(value, schema) → {ok: bool, errors: [string]}
fn validate(value, schema) {
    h errors = []
    _validate_node(value, schema, "", errors)
    return {ok: arr_len(errors) == 0, errors: errors}
}

fn _validate_node(value, schema, path, errors) {
    # type check
    if dict_has(schema, "type") {
        h expected_type = schema["type"]
        h actual_type = schema_type_of(value)
        h ok = false
        if type_of(expected_type) == "array" {
            h ti = 0
            while ti < arr_len(expected_type) {
                if expected_type[ti] == actual_type { ok = true }
                if expected_type[ti] == "integer" and actual_type == "number" and type_of(value) == "int" { ok = true }
                ti += 1
            }
        } else {
            if expected_type == actual_type { ok = true }
            if expected_type == "integer" and actual_type == "number" and type_of(value) == "int" { ok = true }
            if expected_type == "number" and (actual_type == "number") { ok = true }
        }
        if !ok {
            h loc = path
            if str_len(loc) == 0 { loc = "(root)" }
            arr_push(errors, str_concat(loc, ": expected ", to_string(expected_type), ", got ", actual_type))
        }
    }

    # enum
    if dict_has(schema, "enum") {
        h allowed = schema["enum"]
        h found = false
        h ei = 0
        while ei < arr_len(allowed) {
            if allowed[ei] == value { found = true }
            ei += 1
        }
        if !found {
            h loc = path
            if str_len(loc) == 0 { loc = "(root)" }
            arr_push(errors, str_concat(loc, ": value not in enum"))
        }
    }

    # const
    if dict_has(schema, "const") {
        if value != schema["const"] {
            h loc = path
            if str_len(loc) == 0 { loc = "(root)" }
            arr_push(errors, str_concat(loc, ": expected const value"))
        }
    }

    # string constraints
    if schema_type_of(value) == "string" {
        if dict_has(schema, "minLength") {
            if str_len(value) < schema["minLength"] {
                arr_push(errors, str_concat(path, ": string too short (min ", to_string(schema["minLength"]), ")"))
            }
        }
        if dict_has(schema, "maxLength") {
            if str_len(value) > schema["maxLength"] {
                arr_push(errors, str_concat(path, ": string too long (max ", to_string(schema["maxLength"]), ")"))
            }
        }
        if dict_has(schema, "pattern") {
            h pat = schema["pattern"]
            if !str_contains(value, pat) {
                arr_push(errors, str_concat(path, ": string does not match pattern"))
            }
        }
    }

    # number constraints
    if schema_type_of(value) == "number" {
        if dict_has(schema, "minimum") {
            if value < schema["minimum"] {
                arr_push(errors, str_concat(path, ": value < minimum (", to_string(schema["minimum"]), ")"))
            }
        }
        if dict_has(schema, "maximum") {
            if value > schema["maximum"] {
                arr_push(errors, str_concat(path, ": value > maximum (", to_string(schema["maximum"]), ")"))
            }
        }
        if dict_has(schema, "exclusiveMinimum") {
            if value <= schema["exclusiveMinimum"] {
                arr_push(errors, str_concat(path, ": value <= exclusiveMinimum"))
            }
        }
        if dict_has(schema, "exclusiveMaximum") {
            if value >= schema["exclusiveMaximum"] {
                arr_push(errors, str_concat(path, ": value >= exclusiveMaximum"))
            }
        }
        if dict_has(schema, "multipleOf") {
            h rem = value % schema["multipleOf"]
            if rem != 0 {
                arr_push(errors, str_concat(path, ": not a multiple of ", to_string(schema["multipleOf"])))
            }
        }
    }

    # array constraints
    if schema_type_of(value) == "array" {
        if dict_has(schema, "minItems") {
            if arr_len(value) < schema["minItems"] {
                arr_push(errors, str_concat(path, ": array too short (min ", to_string(schema["minItems"]), ")"))
            }
        }
        if dict_has(schema, "maxItems") {
            if arr_len(value) > schema["maxItems"] {
                arr_push(errors, str_concat(path, ": array too long (max ", to_string(schema["maxItems"]), ")"))
            }
        }
        if dict_has(schema, "items") {
            h item_schema = schema["items"]
            h ai = 0
            while ai < arr_len(value) {
                _validate_node(value[ai], item_schema, str_concat(path, "[", to_string(ai), "]"), errors)
                ai += 1
            }
        }
        if dict_has(schema, "uniqueItems") and schema["uniqueItems"] {
            h seen = {}
            h ui = 0
            while ui < arr_len(value) {
                h k = to_string(value[ui])
                if dict_has(seen, k) {
                    arr_push(errors, str_concat(path, ": duplicate item at index ", to_string(ui)))
                }
                seen[k] = true
                ui += 1
            }
        }
    }

    # object constraints
    if schema_type_of(value) == "object" {
        if dict_has(schema, "required") {
            h req = schema["required"]
            h ri = 0
            while ri < arr_len(req) {
                if !dict_has(value, req[ri]) {
                    arr_push(errors, str_concat(path, ": missing required field '", req[ri], "'"))
                }
                ri += 1
            }
        }
        if dict_has(schema, "properties") {
            h props = schema["properties"]
            h pkeys = dict_keys(props)
            h pi = 0
            while pi < arr_len(pkeys) {
                h pk = pkeys[pi]
                if dict_has(value, pk) {
                    _validate_node(value[pk], props[pk], str_concat(path, ".", pk), errors)
                }
                pi += 1
            }
        }
        if dict_has(schema, "minProperties") {
            if arr_len(dict_keys(value)) < schema["minProperties"] {
                arr_push(errors, str_concat(path, ": too few properties"))
            }
        }
        if dict_has(schema, "maxProperties") {
            if arr_len(dict_keys(value)) > schema["maxProperties"] {
                arr_push(errors, str_concat(path, ": too many properties"))
            }
        }
    }
}

# ── Coerce ──────────────────────────────────────────────────────────────────

# coerce(value, schema) → value (best-effort type coercion)
fn coerce(value, schema) {
    if !dict_has(schema, "type") { return value }
    h t = schema["type"]
    h actual = schema_type_of(value)
    if t == "string" and actual != "string" { return to_string(value) }
    if t == "number" and actual == "string" {
        h n = str_to_float(value)
        if n != null { return n }
    }
    if t == "integer" and actual == "string" {
        h n = str_to_int(value)
        if n != null { return n }
    }
    if t == "boolean" {
        if value == "true" or value == 1 { return true }
        if value == "false" or value == 0 { return false }
    }
    if t == "array" and actual != "array" { return [value] }
    return value
}

# ── Schema helpers ──────────────────────────────────────────────────────────

fn schema_string(min_len, max_len) {
    h s = {type: "string"}
    if min_len != null { s["minLength"] = min_len }
    if max_len != null { s["maxLength"] = max_len }
    return s
}

fn schema_number(min_val, max_val) {
    h s = {type: "number"}
    if min_val != null { s["minimum"] = min_val }
    if max_val != null { s["maximum"] = max_val }
    return s
}

fn schema_object(required_fields, properties) {
    h s = {type: "object"}
    if required_fields != null { s["required"] = required_fields }
    if properties != null { s["properties"] = properties }
    return s
}

fn schema_array(item_schema, min_items, max_items) {
    h s = {type: "array"}
    if item_schema != null { s["items"] = item_schema }
    if min_items != null { s["minItems"] = min_items }
    if max_items != null { s["maxItems"] = max_items }
    return s
}

fn schema_enum(values) {
    return {enum: values}
}

# ── Validate and throw ──────────────────────────────────────────────────────

# assert_valid(value, schema) — raises error if invalid
fn assert_valid(value, schema) {
    h result = validate(value, schema)
    if !result["ok"] {
        h msg = str_concat("Schema validation failed:\n", arr_join(result["errors"], "\n"))
        error(msg)
    }
}

# =============================================================================
# scikit-learn bridge for OMC — classical ML
# =============================================================================
# Wraps the most common scikit-learn estimators. Pattern: each fn
# returns a fitted-or-untrained MODEL HANDLE; OMC code calls .fit and
# .predict via py_call. Lazy module imports per submodule.
#
# Usage:
#   import "examples/lib/sklearn.omc" as sk;
#   h X = [[1, 2], [3, 4], [5, 6]];
#   h y = [0, 1, 1];
#   h model = sk.kmeans(2);
#   sk.fit(model, X, y);
#   h preds = sk.predict(model, X);
# =============================================================================

h _CLUSTER     = 0;
h _LINEAR      = 0;
h _ENSEMBLE    = 0;
h _MODEL_SEL   = 0;
h _PREPROC     = 0;
h _METRICS     = 0;

fn _cluster()    { if _CLUSTER == 0    { _CLUSTER    = py_import("sklearn.cluster"); }     return _CLUSTER; }
fn _linear()     { if _LINEAR == 0     { _LINEAR     = py_import("sklearn.linear_model"); } return _LINEAR; }
fn _ensemble()   { if _ENSEMBLE == 0   { _ENSEMBLE   = py_import("sklearn.ensemble"); }     return _ENSEMBLE; }
fn _model_sel()  { if _MODEL_SEL == 0  { _MODEL_SEL  = py_import("sklearn.model_selection"); } return _MODEL_SEL; }
fn _preproc()    { if _PREPROC == 0    { _PREPROC    = py_import("sklearn.preprocessing"); } return _PREPROC; }
fn _metrics()    { if _METRICS == 0    { _METRICS    = py_import("sklearn.metrics"); }       return _METRICS; }

# ---- Models (constructors return untrained model handle) -----------------

fn kmeans(n_clusters) {
    h cls = py_get(_cluster(), "KMeans");
    return py_call_fn(cls, [n_clusters]);
}

fn linear_regression() {
    h cls = py_get(_linear(), "LinearRegression");
    return py_call_fn(cls, []);
}

fn logistic_regression() {
    h cls = py_get(_linear(), "LogisticRegression");
    return py_call_fn(cls, []);
}

fn random_forest_classifier(n_estimators) {
    h cls = py_get(_ensemble(), "RandomForestClassifier");
    return py_call_fn(cls, [n_estimators]);
}

fn random_forest_regressor(n_estimators) {
    h cls = py_get(_ensemble(), "RandomForestRegressor");
    return py_call_fn(cls, [n_estimators]);
}

# ---- Universal fit/predict surface ---------------------------------------
# Every sklearn estimator has .fit(X, y) and .predict(X). Some (KMeans,
# clustering) are unsupervised — pass null for y and we'll skip it.

fn fit(model, X, y) {
    if y == null {
        py_call(model, "fit", [X]);
    } else {
        py_call(model, "fit", [X, y]);
    }
    return model;
}

fn predict(model, X) {
    return py_call(model, "predict", [X]);
}

fn score(model, X, y) {
    return py_call(model, "score", [X, y]);
}

# ---- Train/test split ----------------------------------------------------
# Returns [X_train, X_test, y_train, y_test] as OMC arrays.
# test_size is a kwarg in sklearn's API — passing it positionally
# would make it a third array. py_call_fn_kw handles the split.
fn train_test_split(X, y, test_size) {
    h tts = py_get(_model_sel(), "train_test_split");
    return py_call_fn_kw(tts, [X, y], {"test_size": test_size});
}

# ---- Preprocessing -------------------------------------------------------

fn standard_scaler() {
    h cls = py_get(_preproc(), "StandardScaler");
    return py_call_fn(cls, []);
}

fn fit_transform(scaler, X) {
    return py_call(scaler, "fit_transform", [X]);
}

fn transform(scaler, X) {
    return py_call(scaler, "transform", [X]);
}

# ---- Metrics --------------------------------------------------------------

fn accuracy_score(y_true, y_pred) {
    return py_call(_metrics(), "accuracy_score", [y_true, y_pred]);
}

fn r2_score(y_true, y_pred) {
    return py_call(_metrics(), "r2_score", [y_true, y_pred]);
}

fn confusion_matrix(y_true, y_pred) {
    return py_call(_metrics(), "confusion_matrix", [y_true, y_pred]);
}

# ---- Built-in datasets (handy for demos) --------------------------------
# Each load_* returns a Bunch; we extract data + target as OMC arrays.

fn _datasets() { return py_import("sklearn.datasets"); }

fn load_iris() {
    # sklearn returns a Bunch — dict subclass — so py_to_omc auto-
    # converts to an OMC dict. Use dict_get, not py_get.
    h ds = py_call(_datasets(), "load_iris", []);
    return [dict_get(ds, "data"), dict_get(ds, "target")];
}

fn load_wine() {
    h ds = py_call(_datasets(), "load_wine", []);
    return [dict_get(ds, "data"), dict_get(ds, "target")];
