# =============================================================================
# sqlite3 bridge for OMC — embedded database
# =============================================================================
# Wraps python's stdlib sqlite3. OMC programs gain a real SQL database
# with zero install (sqlite ships with Python). Useful for: persisting
# results across runs, dataset triage too big for memory, joining OMC
# computations to existing app data.
#
# Usage:
#   import "examples/lib/sqlite.omc" as db;
#   h conn = db.connect(":memory:");
#   db.execute(conn, "CREATE TABLE users (id INTEGER, name TEXT)");
#   db.execute_with(conn, "INSERT INTO users VALUES (?, ?)", [1, "alice"]);
#   db.commit(conn);
#   h rows = db.query(conn, "SELECT * FROM users");
# =============================================================================

h _SQL_HANDLE = 0;

fn _sql() {
    if _SQL_HANDLE == 0 {
        _SQL_HANDLE = py_import("sqlite3");
    }
    return _SQL_HANDLE;
}

# ---- Connection lifecycle -------------------------------------------------

# `path` can be ":memory:" for an in-memory database or a real file path.
fn connect(path) {
    return py_call(_sql(), "connect", [path]);
}

fn close(conn) {
    return py_call(conn, "close", []);
}

fn commit(conn) {
    return py_call(conn, "commit", []);
}

fn rollback(conn) {
    return py_call(conn, "rollback", []);
}

# ---- Cursor / execute pattern --------------------------------------------

# Execute a SQL statement that doesn't return rows (DDL, INSERT/UPDATE/DELETE
# without RETURNING). Returns null. Caller is responsible for commit.
fn execute(conn, sql) {
    h cur = py_call(conn, "cursor", []);
    py_call(cur, "execute", [sql]);
    py_call(cur, "close", []);
    return null;
}

# Same but with bound parameters. Pass an OMC array; sqlite3 binds via "?".
fn execute_with(conn, sql, params) {
    h cur = py_call(conn, "cursor", []);
    py_call(cur, "execute", [sql, params]);
    py_call(cur, "close", []);
    return null;
}

# Execute many: one SQL with a list of parameter rows.
fn execute_many(conn, sql, rows) {
    h cur = py_call(conn, "cursor", []);
    py_call(cur, "executemany", [sql, rows]);
    py_call(cur, "close", []);
    return null;
}

# ---- Queries (return rows as OMC arrays) ---------------------------------

# Run SELECT, return all rows as an OMC array of arrays.
fn query(conn, sql) {
    h cur = py_call(conn, "cursor", []);
    py_call(cur, "execute", [sql]);
    h rows = py_call(cur, "fetchall", []);
    py_call(cur, "close", []);
    return rows;
}

# Same with bound parameters.
fn query_with(conn, sql, params) {
    h cur = py_call(conn, "cursor", []);
    py_call(cur, "execute", [sql, params]);
    h rows = py_call(cur, "fetchall", []);
    py_call(cur, "close", []);
    return rows;
}

# Single-row helper: returns the first row or null.
fn query_one(conn, sql) {
    h rows = query(conn, sql);
    if arr_len(rows) > 0 { return arr_get(rows, 0); }
    return null;
}

# Schema introspection — useful for "show me what's in this DB" workflows.
fn tables(conn) {
    h rows = query(conn,
        "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name");
    h out = [];
    h i = 0;
    while i < arr_len(rows) {
        arr_push(out, arr_get(arr_get(rows, i), 0));
        i += 1;
    }
    return out;
}

# substrate.omc — high-level wrappers around the O(log_phi_pi_fibonacci N)
# primitives in the OMC native runtime.
#
# Conventions:
#   - Functions named `s_*` are substrate-routed (use the F(k)/phi^(pi*k)
#     probe sequence). They preserve harmonic structure across probes.
#   - Functions named `i_*` are native int-binary equivalents. Use them
#     when raw throughput on uniform data matters more than substrate
#     coherence.
#   - Functions named `h_*` are harmonic-aligned operations (Fibonacci
#     attractor / Zeckendorf operations).

# Build an empty substrate-friendly sorted-int container. Just an alias
# for an empty array — used to signal intent to other readers.
fn s_new() {
    return [];
}

# Add a value into a sorted container, keeping it sorted. Returns the
# insertion index.
fn s_add(container, value) {
    return substrate_insert(container, value);
}

# Substrate-routed exact lookup: returns the index or -1.
fn s_find(container, value) {
    return substrate_search(container, value);
}

# Substrate-routed range count: how many elements in [lo, hi).
fn s_count_range(container, lo, hi) {
    return substrate_count_range(container, lo, hi);
}

# Substrate-routed range slice: array of elements in [lo, hi).
fn s_slice_range(container, lo, hi) {
    return substrate_slice_range(container, lo, hi);
}

# Substrate-routed nearest value lookup.
fn s_nearest(container, value) {
    return substrate_nearest(container, value);
}

# Substrate-routed median (50th percentile).
fn s_median(container) {
    return substrate_quantile(container, 500);
}

# Substrate-routed percentile [0, 100].
fn s_percentile(container, p) {
    return substrate_quantile(container, p * 10);
}

# Snap a value to the nearest Fibonacci attractor.
fn h_snap(value) {
    return harmonic_align(value);
}

# Residual after substrate alignment (non-attractor component).
fn h_residual(value) {
    return harmonic_unalign(value);
}

# Substrate-distance: ln(|a-b|+1) / (pi * ln(phi)).
fn h_distance(a, b) {
    return phi_pi_log_distance(a, b);
}

# Substrate-aligned hash for keying into dict/bloom structures.
fn h_hash(value) {
    return substrate_hash(value);
}

# Zeckendorf weight: number of Fibonacci terms in n's decomposition.
fn h_weight(n) {
    return zeckendorf_weight(n);
}

# Substrate-coherence score for an array (0.0 .. 1.0).
fn h_score(arr) {
    return harmonic_score(arr);
}

# Build a sorted set from an unsorted array via substrate operations.
# Result is sorted, deduplicated, and ready for s_find / s_count_range.
fn s_from_array(arr) {
    h sorted = arr_sort_int(arr);
    return sorted_dedupe(sorted);
}

# std/test — canonical assertion helpers for OMC test suites.
#
# Before this library, every test file under examples/tests/ defined
# its own assert_eq / assert_true. omc-grep counted 64 copies of
# assert_eq alone (the largest cluster in the codebase).
#
# To use:
#   from "lib/test.omc" import assert_eq, assert_true, assert_near, assert_throws
#
# Or import the whole module:
#   import "lib/test.omc"
#
# Conventions:
#   - msg is the diagnostic shown when an assertion fails
#   - test_record_failure is the OMC test-runner hook that flags a fail
#   - assertions short-circuit (return) after recording so a single
#     bad assertion doesn't cascade into noise

fn assert_eq(actual, expected, msg) {
    if actual != expected {
        test_record_failure(msg + ": expected " + to_string(expected) + " got " + to_string(actual));
    }
}

fn assert_ne(actual, unexpected, msg) {
    if actual == unexpected {
        test_record_failure(msg + ": expected != " + to_string(unexpected) + " but got equal");
    }
}

fn assert_true(cond, msg) {
    if !cond {
        test_record_failure(msg);
    }
}

fn assert_false(cond, msg) {
    if cond {
        test_record_failure(msg + ": expected false, got true");
    }
}

# Float equality within an epsilon tolerance. Default eps = 1e-9
# (tight for typical FP work; pass a looser eps for ML/stats tests).
fn assert_near(actual, expected, eps, msg) {
    h diff = actual - expected;
    h abs_diff = diff;
    if abs_diff < 0.0 { abs_diff = 0.0 - abs_diff; }
    if abs_diff > eps {
        test_record_failure(msg + ": expected ~" + to_string(expected) + " (eps=" + to_string(eps) + ") got " + to_string(actual));
    }
}

# Assertion: invoking nullary fn body_fn raises ANY error.
# Use for "this should fail" tests without coupling to the exact
# error message.
fn assert_throws(body_fn, msg) {
    h threw = false;
    try {
        body_fn();
    } catch e {
        threw = true;
    }
    if !threw {
        test_record_failure(msg + ": expected to throw, completed normally");
    }
}

# Like assert_throws but also requires the error message to contain
# a given substring. Use to assert a specific failure mode.
fn assert_throws_with(body_fn, expected_substr, msg) {
    h threw = false;
    h err_text = "";
    try {
        body_fn();
    } catch e {
        threw = true;
        err_text = e;
    }
    if !threw {
        test_record_failure(msg + ": expected to throw, completed normally");
        return;
    }
    if re_match(expected_substr, err_text) != 1 {
        test_record_failure(msg + ": error did not contain `" + expected_substr + "`; got: " + err_text);
    }
}

# Convenience: assert string contains substring.
fn assert_contains(haystack, needle, msg) {
    if re_match(needle, haystack) != 1 {
        test_record_failure(msg + ": expected `" + needle + "` in `" + haystack + "`");
    }
}

# Convenience: assert array length.
fn assert_len(arr, expected_len, msg) {
    h actual = arr_len(arr);
    if actual != expected_len {
        test_record_failure(msg + ": expected len " + to_string(expected_len) + " got " + to_string(actual));
    }
}

# text.omc — text processing: TF-IDF, BM25, edit distance, chunking, tokenizing

# ── Tokenization ────────────────────────────────────────────────────────────

# tokenize(text) → [tokens]
# Simple whitespace + punctuation tokenizer; lowercases.
fn tokenize(text) {
    h lower = str_lower(text)
    h words = str_split(lower, " ")
    h tokens = []
    h i = 0
    while i < arr_len(words) {
        h w = str_trim(words[i])
        h clean = str_replace(w, ".", "")
        clean = str_replace(clean, ",", "")
        clean = str_replace(clean, "!", "")
        clean = str_replace(clean, "?", "")
        clean = str_replace(clean, ";", "")
        clean = str_replace(clean, ":", "")
        clean = str_replace(clean, "\"", "")
        clean = str_replace(clean, "'", "")
        clean = str_replace(clean, "(", "")
        clean = str_replace(clean, ")", "")
        if str_len(clean) > 0 {
            arr_push(tokens, clean)
        }
        i += 1
    }
    return tokens
}

# term_freq(tokens) → {token: count}
fn term_freq(tokens) {
    h freq = {}
    h i = 0
    while i < arr_len(tokens) {
        h t = tokens[i]
        if dict_has(freq, t) {
            freq[t] = freq[t] + 1
        } else {
            freq[t] = 1
        }
        i += 1
    }
    return freq
}

# ── TF-IDF ──────────────────────────────────────────────────────────────────

# tfidf_corpus(docs) → corpus object for scoring
# docs: [string, ...]
fn tfidf_corpus(docs) {
    h n = arr_len(docs)
    h doc_freqs = {}
    h tokenized = []
    h i = 0
    while i < n {
        h tokens = tokenize(docs[i])
        h freq = term_freq(tokens)
        arr_push(tokenized, freq)
        h seen = {}
        h keys = dict_keys(freq)
        h j = 0
        while j < arr_len(keys) {
            h k = keys[j]
            if !dict_has(seen, k) {
                seen[k] = true
                if dict_has(doc_freqs, k) {
                    doc_freqs[k] = doc_freqs[k] + 1
                } else {
                    doc_freqs[k] = 1
                }
            }
            j += 1
        }
        i += 1
    }
    return {n: n, doc_freqs: doc_freqs, tokenized: tokenized, docs: docs}
}

# tfidf_score(corpus, query) → [{doc_idx, score}, ...] sorted desc
fn tfidf_score(corpus, query) {
    h q_tokens = tokenize(query)
    h scores = []
    h i = 0
    while i < corpus["n"] {
        h freq = corpus["tokenized"][i]
        h doc_len = 0
        h keys = dict_keys(freq)
        h j = 0
        while j < arr_len(keys) {
            doc_len += freq[keys[j]]
            j += 1
        }
        h score = 0.0
        h qi = 0
        while qi < arr_len(q_tokens) {
            h term = q_tokens[qi]
            if dict_has(freq, term) {
                h tf = freq[term] / doc_len
                h df = 1
                if dict_has(corpus["doc_freqs"], term) {
                    df = corpus["doc_freqs"][term]
                }
                h idf = math_log((corpus["n"] + 1) / (df + 1))
                score += tf * idf
            }
            qi += 1
        }
        arr_push(scores, {doc_idx: i, score: score})
        i += 1
    }
    # sort by score desc (bubble sort — small corpora)
    h n = arr_len(scores)
    h si = 0
    while si < n {
        h sj = si + 1
        while sj < n {
            if scores[sj]["score"] > scores[si]["score"] {
                h tmp = scores[si]
                scores[si] = scores[sj]
                scores[sj] = tmp
            }
            sj += 1
        }
        si += 1
    }
    return scores
}

# ── BM25 ────────────────────────────────────────────────────────────────────

# bm25_corpus(docs, k1?, b?) → corpus object
fn bm25_corpus(docs, k1, b) {
    h K1 = k1
    if K1 == null { K1 = 1.5 }
    h B = b
    if B == null { B = 0.75 }
    h n = arr_len(docs)
    h doc_freqs = {}
    h tokenized = []
    h lengths = []
    h total_len = 0
    h i = 0
    while i < n {
        h tokens = tokenize(docs[i])
        h freq = term_freq(tokens)
        h dl = arr_len(tokens)
        arr_push(tokenized, freq)
        arr_push(lengths, dl)
        total_len += dl
        h seen = {}
        h keys = dict_keys(freq)
        h j = 0
        while j < arr_len(keys) {
            h k = keys[j]
            if !dict_has(seen, k) {
                seen[k] = true
                if dict_has(doc_freqs, k) {
                    doc_freqs[k] = doc_freqs[k] + 1
                } else {
                    doc_freqs[k] = 1
                }
            }
            j += 1
        }
        i += 1
    }
    h avgdl = total_len / n
    return {n: n, doc_freqs: doc_freqs, tokenized: tokenized, lengths: lengths, avgdl: avgdl, k1: K1, b: B, docs: docs}
}

# bm25_score(corpus, query) → [{doc_idx, score}, ...] sorted desc
fn bm25_score(corpus, query) {
    h q_tokens = tokenize(query)
    h scores = []
    h i = 0
    while i < corpus["n"] {
        h freq = corpus["tokenized"][i]
        h dl = corpus["lengths"][i]
        h score = 0.0
        h qi = 0
        while qi < arr_len(q_tokens) {
            h term = q_tokens[qi]
            h tf = 0
            if dict_has(freq, term) { tf = freq[term] }
            h df = 1
            if dict_has(corpus["doc_freqs"], term) {
                df = corpus["doc_freqs"][term]
            }
            h idf = math_log((corpus["n"] - df + 0.5) / (df + 0.5) + 1)
            h norm = corpus["k1"] * (1 - corpus["b"] + corpus["b"] * dl / corpus["avgdl"])
            score += idf * (tf * (corpus["k1"] + 1)) / (tf + norm)
            qi += 1
        }
        arr_push(scores, {doc_idx: i, score: score})
        i += 1
    }
    # sort desc
    h n = arr_len(scores)
    h si = 0
    while si < n {
        h sj = si + 1
        while sj < n {
            if scores[sj]["score"] > scores[si]["score"] {
                h tmp = scores[si]
                scores[si] = scores[sj]
                scores[sj] = tmp
            }
            sj += 1
        }
        si += 1
    }
    return scores
}

# ── Edit distance (Levenshtein) ──────────────────────────────────────────────

# levenshtein(a, b) → int
fn levenshtein(a, b) {
    h la = str_len(a)
    h lb = str_len(b)
    if la == 0 { return lb }
    if lb == 0 { return la }
    # dp row
    h prev = []
    h i = 0
    while i <= lb {
        arr_push(prev, i)
        i += 1
    }
    h row = 0
    while row < la {
        h curr = [row + 1]
        h col = 0
        while col < lb {
            h cost = 1
            if str_slice(a, row, row + 1) == str_slice(b, col, col + 1) {
                cost = 0
            }
            h del = prev[col + 1] + 1
            h ins = curr[col] + 1
            h sub = prev[col] + cost
            h min_val = del
            if ins < min_val { min_val = ins }
            if sub < min_val { min_val = sub }
            arr_push(curr, min_val)
            col += 1
        }
        prev = curr
        row += 1
    }
    return prev[lb]
}

# similarity(a, b) → 0.0..1.0 (1 = identical)
fn text_similarity(a, b) {
    h dist = levenshtein(a, b)
    h max_len = str_len(a)
    if str_len(b) > max_len { max_len = str_len(b) }
    if max_len == 0 { return 1.0 }
    return 1.0 - (dist / max_len)
}

# closest(query, candidates) → {match, score, idx}
fn closest(query, candidates) {
    h best = null
    h best_score = -1.0
    h best_idx = -1
    h i = 0
    while i < arr_len(candidates) {
        h s = text_similarity(query, candidates[i])
        if s > best_score {
            best_score = s
            best = candidates[i]
            best_idx = i
        }
        i += 1
    }
    return {text_match: best, score: best_score, idx: best_idx}
}

# ── Chunking ─────────────────────────────────────────────────────────────────

# chunk_fixed(text, size, overlap?) → [string chunks]
fn chunk_fixed(text, size, overlap) {
    h ov = overlap
    if ov == null { ov = 0 }
    h tokens = tokenize(text)
    h chunks = []
    h i = 0
    while i < arr_len(tokens) {
        h end = i + size
        if end > arr_len(tokens) { end = arr_len(tokens) }
        h chunk_tokens = arr_slice(tokens, i, end)
        h chunk_str = ""
        h j = 0
        while j < arr_len(chunk_tokens) {
            if j > 0 { chunk_str = str_concat(chunk_str, " ") }
            chunk_str = str_concat(chunk_str, chunk_tokens[j])
            j += 1
        }
        arr_push(chunks, chunk_str)
        h step = size - ov
        if step <= 0 { step = 1 }
        i += step
    }
    return chunks
}

# chunk_sentences(text, max_per_chunk?) → [string chunks]
fn chunk_sentences(text, max_per_chunk) {
    h max_s = max_per_chunk
    if max_s == null { max_s = 3 }
    h sentences = str_split(text, ". ")
    h chunks = []
    h i = 0
    while i < arr_len(sentences) {
        h end = i + max_s
        if end > arr_len(sentences) { end = arr_len(sentences) }
        h chunk = ""
        h j = i
        while j < end {
            if j > i { chunk = str_concat(chunk, ". ") }
            chunk = str_concat(chunk, sentences[j])
            j += 1
        }
        arr_push(chunks, str_trim(chunk))
        i += max_s
    }
    return chunks
}

# ── n-grams ──────────────────────────────────────────────────────────────────

# ngrams(tokens, n) → [[token, ...], ...]
fn ngrams(tokens, n) {
    h result = []
    h i = 0
    while i <= arr_len(tokens) - n {
        h gram = arr_slice(tokens, i, i + n)
        arr_push(result, gram)
        i += 1
    }
    return result
}

# =============================================================================
# PyTorch bridge for OMC — neural networks in OMC
# =============================================================================
# Minimal but real surface: tensors, basic ops, nn.Linear, optimizer
# step, loss. Enough to write a forward/backward loop in OMC.
#
# Note: torch is heavy (~1GB install). This file is included for the
# pattern, not as a daily-use library — most data science doesn't
