    h text = "four score and seven years ago our fathers brought forth on this continent a new nation conceived in liberty and dedicated to the proposition that all men are created equal now we are engaged in a great civil war testing whether that nation or any nation so conceived and so dedicated can long endure";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h lr = 0.005;
    h steps = 300;
    h seeds = [42, 7, 123, 2026, 99, 1];

    print(concat_many("d_model=", to_string(d_model),
        "  ff=", to_string(ff_dim),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("Run with OMC_GPU_BACKEND=wgpu (and OMC_GPU_SUBSTRATE_QUANT=1 in one arm).");
    print("");

    h losses = [];
    h si = 0;
    while si < arr_len(seeds) {
        h seed = arr_get(seeds, si);
        h L = train(vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        arr_push(losses, L);
        print(concat_many("  seed=", to_string(seed), "  loss=", to_string(L)));
        si += 1;
    }
    h mu = mean_arr(losses);
    print(concat_many("mean=", to_string(mu)));
}

