    assert_eq(arr_get(r0, 2), 6, "3+3");
    assert_eq(arr_get(r1, 0), 11, "10+1");
    assert_eq(arr_get(r1, 2), 33, "30+3");
    assert_eq(arr_get(r2, 0), 101, "100+1");
    assert_eq(arr_get(r2, 2), 303, "300+3");
}

