    assert_eq(fact(0), 1, "0! = 1");
}

# Mutual recursion
fn is_even(n) {
    if n == 0 { return 1; }
    return is_odd(n - 1);
}

fn is_odd(n) {
    if n == 0 { return 0; }
    return is_even(n - 1);
}

fn test_mutual_recursion() {
