# ---- finally semantics ----

fn test_finally_runs_on_success() {
    h ran = 0;
    try {
        # No throw
    } catch e {
        ran = 99;
    } finally {
        ran = 1;
    }
    assert_eq(ran, 1, "finally runs after successful try");
}

fn test_finally_runs_on_failure() {
    h ran_catch = 0;
    h ran_finally = 0;
    try {
