    h outer = 0;
    h inner = 0;
    try {
        try {
            throw "inner";
        } catch e {
            inner = 1;
        }
    } catch e {
        outer = 99;
    }
    assert_eq(inner, 1, "inner catch ran");
    assert_eq(outer, 0, "outer catch did NOT run (inner consumed)");
}

