fn test_semantic_fold_picks_closest_substrate_pair() {
    # Build a tier with 4 entries where two are very close in hash
    # space and two are far. _fibtier_pick_fold_pair("semantic") must
    # return the closest pair, not [0, 1].
    h mem = fibtier_new_with_strategy(4, "semantic");
    h tier = [
        _fibtier_make_entry("aaa", [0]),
        _fibtier_make_entry("zzz", [0]),
        _fibtier_make_entry("aaa", [0]),    # exact-hash twin of index 0
        _fibtier_make_entry("qqq", [0])
    ];
    h pair = _fibtier_pick_fold_pair(tier, "semantic");
    h ia = arr_get(pair, 0);
    h ib = arr_get(pair, 1);
    # The twins are at indices 0 and 2 — closest pair has distance 0.
    assert_true((ia == 0 && ib == 2) || (ia == 2 && ib == 0),
                "semantic strategy picked the hash-identical twins");
}

