fn squares_to(n) {
    h i = 1;
    while i <= n {
        yield i * i;
        i += 1;
    }
}

fn fib_gen(limit) {
    h a = 0;
    h b = 1;
    while a < limit {
        yield a;
        h t = a + b;
        a = b;
        b = t;
    }
}

