# ── augmented-assign → style lint ─────────────────────────────────────────────

fn test_augmented_assign_flagged() {
    h r = omc_spawn("sh", ["-c",
        "printf 'fn f(n) { h i = 0; while i < n { i = i + 1 } return i }\\n' > /tmp/_lint_aug.omc"])
    h result = check_file("/tmp/_lint_aug.omc")
    assert_false(result["ok"], "i = i + 1 fails check")
    assert_true(str_contains(result["stdout"], "style"), "style hint emitted")
    assert_true(str_contains(result["stdout"], "+="), "+= suggested in output")
}

