# At x=0: u=1, sigmoid(1) ≈ 0.7310586,
# sigmoid'(1) ≈ 0.196612, dy/dx = 0.196612 * 2 ≈ 0.393224

fn test_chain_rule() {
    tape_reset();
    h x = tape_var(0.0);
    h two = tape_const(2.0);
    h one = tape_const(1.0);
