fn tokenize(source) {
    h n = str_len(source);
    h tokens = arr_new(0, 0);
    h pos = 0;

    while pos < n {
        pos = skip_ws(source, pos);
        if pos >= n { break; }

        h c = str_slice(source, pos, pos + 1);

        # --- f-string detection: f"..." or F"..." ---
        if c == "f" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "\"" {
                    h tok = read_fstring(source, pos + 1);
                    arr_push(tokens, ["FSTRING", arr_get(tok, 1)]);
                    pos = arr_get(tok, 2);
                    continue;
                }
                if next == "'" {
                    h tok = read_fstring(source, pos + 1);
                    arr_push(tokens, ["FSTRING", arr_get(tok, 1)]);
                    pos = arr_get(tok, 2);
                    continue;
                }
            }
        }
        if c == "F" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "\"" {
                    h tok = read_fstring(source, pos + 1);
                    arr_push(tokens, ["FSTRING", arr_get(tok, 1)]);
                    pos = arr_get(tok, 2);
                    continue;
                }
                if next == "'" {
                    h tok = read_fstring(source, pos + 1);
                    arr_push(tokens, ["FSTRING", arr_get(tok, 1)]);
                    pos = arr_get(tok, 2);
                    continue;
                }
            }
        }

        # --- Identifiers and keywords ---
        if is_alpha(c) == 1 {
            h tok = read_ident(source, pos);
            arr_push(tokens, [arr_get(tok, 0), arr_get(tok, 1)]);
            pos = arr_get(tok, 2);
            continue;
        }

        # --- Numeric literals ---
        if is_digit(c) == 1 {
            h tok = read_number(source, pos);
            arr_push(tokens, [arr_get(tok, 0), arr_get(tok, 1)]);
            pos = arr_get(tok, 2);
            continue;
        }

        # --- String literals ---
        if c == "\"" {
            # Triple-quoted string check
            if pos + 2 < n {
                h three = str_slice(source, pos, pos + 3);
                if three == "\"\"\"" {
                    h tok = read_triple_string(source, pos);
                    arr_push(tokens, [arr_get(tok, 0), arr_get(tok, 1)]);
                    pos = arr_get(tok, 2);
                    continue;
                }
            }
            h tok = read_string_literal(source, pos);
            arr_push(tokens, [arr_get(tok, 0), arr_get(tok, 1)]);
            pos = arr_get(tok, 2);
            continue;
        }
        if c == "'" {
            h tok = read_string_literal(source, pos);
            arr_push(tokens, [arr_get(tok, 0), arr_get(tok, 1)]);
            pos = arr_get(tok, 2);
            continue;
        }

        # --- Operators (multi-char first, longest match wins) ---

        # + +=
        if c == "+" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["PLUSEQ", "+="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["PLUS", "+"]);
            pos += 1;
            continue;
        }

        # - -= ->
        if c == "-" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == ">" {
                    arr_push(tokens, ["ARROW", "->"]);
                    pos += 2;
                    continue;
                }
                if next == "=" {
                    arr_push(tokens, ["MINUSEQ", "-="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["MINUS", "-"]);
            pos += 1;
            continue;
        }

        # * ** **= *=
        if c == "*" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "*" {
                    if pos + 2 < n {
                        h next2 = str_slice(source, pos + 2, pos + 3);
                        if next2 == "=" {
                            arr_push(tokens, ["STARSTAREQ", "**="]);
                            pos += 3;
                            continue;
                        }
                    }
                    arr_push(tokens, ["STARSTAR", "**"]);
                    pos += 2;
                    continue;
                }
                if next == "=" {
                    arr_push(tokens, ["STAREQ", "*="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["STAR", "*"]);
            pos += 1;
            continue;
        }

        # / /=
        if c == "/" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["SLASHEQ", "/="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["SLASH", "/"]);
            pos += 1;
            continue;
        }

        # % %=
        if c == "%" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["PERCENTEQ", "%="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["PERCENT", "%"]);
            pos += 1;
            continue;
        }

        # = == =>
        if c == "=" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["EQEQ", "=="]);
                    pos += 2;
                    continue;
                }
                if next == ">" {
                    arr_push(tokens, ["FATARROW", "=>"]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["EQ", "="]);
            pos += 1;
            continue;
        }

        # ! !=
        if c == "!" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["NE", "!="]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["NOT", "!"]);
            pos += 1;
            continue;
        }

        # < <= <<
        if c == "<" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["LE", "<="]);
                    pos += 2;
                    continue;
                }
                if next == "<" {
                    arr_push(tokens, ["SHL", "<<"]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["LT", "<"]);
            pos += 1;
            continue;
        }

        # > >= >>
        if c == ">" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "=" {
                    arr_push(tokens, ["GE", ">="]);
                    pos += 2;
                    continue;
                }
                if next == ">" {
                    arr_push(tokens, ["SHR", ">>"]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["GT", ">"]);
            pos += 1;
            continue;
        }

        # & &&
        if c == "&" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "&" {
                    arr_push(tokens, ["AND", "&&"]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["BITAND", "&"]);
            pos += 1;
            continue;
        }

        # | ||
        if c == "|" {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "|" {
                    arr_push(tokens, ["OR", "||"]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["BITOR", "|"]);
            pos += 1;
            continue;
        }

        # . ..
        if c == "." {
            if pos + 1 < n {
                h next = str_slice(source, pos + 1, pos + 2);
                if next == "." {
                    arr_push(tokens, ["DOTDOT", ".."]);
                    pos += 2;
                    continue;
                }
            }
            arr_push(tokens, ["DOT", "."]);
            pos += 1;
            continue;
        }

        # --- Single-char delimiters and operators ---
        if c == "(" { arr_push(tokens, ["LPAREN",   "("]); pos += 1; continue; }
        if c == ")" { arr_push(tokens, ["RPAREN",   ")"]); pos += 1; continue; }
        if c == "{" { arr_push(tokens, ["LBRACE",   "{"]); pos += 1; continue; }
        if c == "}" { arr_push(tokens, ["RBRACE",   "}"]); pos += 1; continue; }
        if c == "[" { arr_push(tokens, ["LBRACKET", "["]); pos += 1; continue; }
        if c == "]" { arr_push(tokens, ["RBRACKET", "]"]); pos += 1; continue; }
        if c == ";" { arr_push(tokens, ["SEMI",     ";"]); pos += 1; continue; }
        if c == "," { arr_push(tokens, ["COMMA",    ","]); pos += 1; continue; }
        if c == ":" { arr_push(tokens, ["COLON",    ":"]); pos += 1; continue; }
        if c == "@" { arr_push(tokens, ["AT",       "@"]); pos += 1; continue; }
        if c == "^" { arr_push(tokens, ["BITXOR",   "^"]); pos += 1; continue; }
        if c == "~" { arr_push(tokens, ["BITNOT",   "~"]); pos += 1; continue; }

        # Unknown character
        arr_push(tokens, ["UNKNOWN", c]);
        pos += 1;
    }

    arr_push(tokens, ["EOF", ""]);
    return tokens;
}

fn print_tokens(tokens) {
    h i = 0;
    h n = arr_len(tokens);
    while i < n {
        h t = arr_get(tokens, i);
        h kind = arr_get(t, 0);
        h value = arr_get(t, 1);
        print(concat_many("  [", i, "] ", kind, " ", value));
        i += 1;
    }
}

fn tok_kind(tokens, i) -> string {
    h t = arr_get(tokens, i);
    return arr_get(t, 0);
}

fn tok_val(tokens, i) -> string {
    h t = arr_get(tokens, i);
    return arr_get(t, 1);
}

fn test_keywords() {
    h src = "h fn if else elif while for in return break continue print range import from as load res fold safe try catch finally throw match class extends yield assert";
    h toks = tokenize(src);
    h expected = ["H", "FN", "IF", "ELSE", "ELIF", "WHILE", "FOR", "IN", "RETURN", "BREAK", "CONTINUE", "PRINT", "RANGE", "IMPORT", "FROM", "AS", "LOAD", "RES", "FOLD", "SAFE", "TRY", "CATCH", "FINALLY", "THROW", "MATCH", "CLASS", "EXTENDS", "YIELD", "ASSERT", "EOF"];
    h i = 0;
    h n = arr_len(expected);
    while i < n {
        h got = tok_kind(toks, i);
        h want = arr_get(expected, i);
        assert got == want, concat_many("keyword[", i, "]: got ", got, " want ", want);
        i += 1;
    }
}

fn test_operators() {
    h src = "+ - * / % = == != < <= > >= -> << >> && || & | ^ ~ ** += -= *= /= %= **= => ..";
    h toks = tokenize(src);
    h expected = ["PLUS", "MINUS", "STAR", "SLASH", "PERCENT", "EQ", "EQEQ", "NE", "LT", "LE", "GT", "GE", "ARROW", "SHL", "SHR", "AND", "OR", "BITAND", "BITOR", "BITXOR", "BITNOT", "STARSTAR", "PLUSEQ", "MINUSEQ", "STAREQ", "SLASHEQ", "PERCENTEQ", "STARSTAREQ", "FATARROW", "DOTDOT", "EOF"];
    h i = 0;
    h n = arr_len(expected);
    while i < n {
        h got = tok_kind(toks, i);
        h want = arr_get(expected, i);
        assert got == want, concat_many("op[", i, "]: got ", got, " want ", want);
        i += 1;
    }
}

fn test_delimiters() {
    h src = "( ) { } [ ] ; , : @ .";
    h toks = tokenize(src);
    h expected = ["LPAREN", "RPAREN", "LBRACE", "RBRACE", "LBRACKET", "RBRACKET", "SEMI", "COMMA", "COLON", "AT", "DOT", "EOF"];
    h i = 0;
    h n = arr_len(expected);
    while i < n {
        h got = tok_kind(toks, i);
        h want = arr_get(expected, i);
