fn test_literals() {
    h src = "42 3.14 \"hello\" 'world'";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "NUMBER", "int kind";
    assert tok_val(toks, 0) == "42", "int val";
    assert tok_kind(toks, 1) == "FLOAT", "float kind";
    assert tok_val(toks, 1) == "3.14", "float val";
    assert tok_kind(toks, 2) == "STRING", "str1 kind";
    assert tok_val(toks, 2) == "hello", "str1 val";
    assert tok_kind(toks, 3) == "STRING", "str2 kind";
    assert tok_val(toks, 3) == "world", "str2 val";
}

fn test_fstring() {
    h src = "f\"x={n+1} done\"";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "FSTRING", "fstring kind";
    h parts = tok_val(toks, 0);
    # parts should be [["LIT","x="], ["EXPR","n+1"], ["LIT"," done"]]
    assert arr_len(parts) == 3, "fstring parts count";
    h p0 = arr_get(parts, 0);
    assert arr_get(p0, 0) == "LIT", "fstring p0 tag";
    assert arr_get(p0, 1) == "x=", "fstring p0 val";
    h p1 = arr_get(parts, 1);
    assert arr_get(p1, 0) == "EXPR", "fstring p1 tag";
    assert arr_get(p1, 1) == "n+1", "fstring p1 val";
    h p2 = arr_get(parts, 2);
    assert arr_get(p2, 0) == "LIT", "fstring p2 tag";
    assert arr_get(p2, 1) == " done", "fstring p2 val";
}

fn test_pragma() {
    h src = "@hbit @safe";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "AT", "pragma @ 1";
    assert tok_kind(toks, 1) == "IDENT", "pragma hbit";
    assert tok_val(toks, 1) == "hbit", "pragma hbit val";
    assert tok_kind(toks, 2) == "AT", "pragma @ 2";
    # 'safe' is a keyword, so it tokenizes as SAFE, not IDENT
    assert tok_kind(toks, 3) == "SAFE", "pragma safe is SAFE keyword";
}

fn test_compound_expr() {
    h src = "x += 1; y -= 2; z *= 3; w /= 4; v %= 5; u **= 6;";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "IDENT", "compound x";
    assert tok_kind(toks, 1) == "PLUSEQ", "compound +=";
    assert tok_kind(toks, 5) == "MINUSEQ", "compound -=";
    assert tok_kind(toks, 9) == "STAREQ", "compound *=";
    assert tok_kind(toks, 13) == "SLASHEQ", "compound /=";
    assert tok_kind(toks, 17) == "PERCENTEQ", "compound %=";
    assert tok_kind(toks, 21) == "STARSTAREQ", "compound **=";
}

fn test_match_expr() {
    h src = "match x { 0..9 => print(x); }";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "MATCH", "match kw";
    assert tok_kind(toks, 3) == "NUMBER", "match 0";
    assert tok_kind(toks, 4) == "DOTDOT", "match ..";
    assert tok_kind(toks, 5) == "NUMBER", "match 9";
    assert tok_kind(toks, 6) == "FATARROW", "match =>";
}

fn test_type_annotation() {
    h src = "fn add(x: int, y: int) -> int { return x + y; }";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "FN", "fn kw";
    assert tok_kind(toks, 1) == "IDENT", "fn name";
    assert tok_kind(toks, 3) == "IDENT", "param x";
    assert tok_kind(toks, 4) == "COLON", "colon";
    assert tok_kind(toks, 5) == "IDENT", "type int";
    assert tok_kind(toks, 11) == "ARROW", "return arrow";
    assert tok_kind(toks, 12) == "IDENT", "return type";
}

fn test_comments() {
    h src = "h x = 1; # comment\nh y = 2;";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "H", "comment h1";
    assert tok_kind(toks, 5) == "H", "comment h2 after comment";
    assert tok_val(toks, 6) == "y", "comment y after comment";
}

fn test_pragma_fixed() {
    h src = "@hbit @safe";
    h toks = tokenize(src);
    assert tok_kind(toks, 0) == "AT", "pragma @ 1";
    assert tok_kind(toks, 1) == "IDENT", "pragma hbit";
    assert tok_val(toks, 1) == "hbit", "pragma hbit val";
    assert tok_kind(toks, 2) == "AT", "pragma @ 2";
    assert tok_kind(toks, 3) == "SAFE", "pragma safe is SAFE keyword";
}

fn p_tok_kind(tokens, pos) -> string {
    h t = arr_get(tokens, pos);
    return arr_get(t, 0);
}

fn p_tok_val(tokens, pos) -> string {
    h t = arr_get(tokens, pos);
    return arr_get(t, 1);
}

fn p_expect(tokens, pos, want) -> int {
    h got = p_tok_kind(tokens, pos);
    if got == want {
        return pos + 1;
    }
    print(concat_many("[parse error] expected ", want, " got ", got, " at pos ", pos));
    return pos + 1;
}

fn p_eat_semi(tokens, pos) -> int {
    if p_tok_kind(tokens, pos) == "SEMI" {
        return pos + 1;
    }
    return pos;
}

fn parse_primary(tokens, pos) {
    h kind = p_tok_kind(tokens, pos);
    h value = p_tok_val(tokens, pos);

    # Unary bitwise NOT: ~x
    if kind == "BITNOT" {
        h r = parse_primary(tokens, pos + 1);
        return [["BIT_NOT", arr_get(r, 0)], arr_get(r, 1)];
    }

    # Unary minus: -x → 0 - x
    if kind == "MINUS" {
        h r = parse_primary(tokens, pos + 1);
        return [["SUB", ["NUMBER", 0], arr_get(r, 0)], arr_get(r, 1)];
    }

    if kind == "NUMBER" {
        return [["NUMBER", value], pos + 1];
    }
    if kind == "FLOAT" {
        return [["FLOAT", value], pos + 1];
    }
    if kind == "STRING" {
        return [["STRING", value], pos + 1];
    }
    if kind == "BOOL" {
        if value == "true" {
            return [["BOOL", "true"], pos + 1];
        }
        return [["BOOL", "false"], pos + 1];
    }

    # f-string → concat_many desugaring
    if kind == "FSTRING" {
        h parts = p_tok_val(tokens, pos);
        h args = arr_new(0, 0);
        h pi = 0;
        h pn = arr_len(parts);
        while pi < pn {
            h part = arr_get(parts, pi);
            h ptag = arr_get(part, 0);
            h pval = arr_get(part, 1);
            if ptag == "LIT" {
                arr_push(args, ["STRING", pval]);
            } else {
                # EXPR segment — tokenize and parse the sub-expression
                h sub_tokens = tokenize(pval);
                h sub_r = parse_expression(sub_tokens, 0);
                arr_push(args, arr_get(sub_r, 0));
            }
            pi += 1;
        }
        if arr_len(args) == 0 {
            return [["STRING", ""], pos + 1];
        }
        return [["CALL", "concat_many", args, ["POS", 0, 0]], pos + 1];
    }

    # Array literal: [e1, e2, ...]
    if kind == "LBRACKET" {
        h np = pos + 1;
        h elems = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RBRACKET" {
            h r = parse_expression(tokens, np);
            arr_push(elems, arr_get(r, 0));
            np = arr_get(r, 1);
            if p_tok_kind(tokens, np) == "COMMA" {
                np += 1;
            }
        }
        np = p_expect(tokens, np, "RBRACKET");
        return [["ARRAY", elems], np];
    }

    # Dict literal: {k: v, ...}
    if kind == "LBRACE" {
        h np = pos + 1;
        h pairs = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RBRACE" {
            # Bare ident followed by colon → string key (JS-style)
            h key_node = 0;
            if p_tok_kind(tokens, np) == "IDENT" {
                h ident_val = p_tok_val(tokens, np);
                if p_tok_kind(tokens, np + 1) == "COLON" {
                    key_node = ["STRING", ident_val];
                    np += 1;
                } else {
                    h kr = parse_expression(tokens, np);
                    key_node = arr_get(kr, 0);
                    np = arr_get(kr, 1);
                }
            } else {
                h kr = parse_expression(tokens, np);
                key_node = arr_get(kr, 0);
                np = arr_get(kr, 1);
            }
            np = p_expect(tokens, np, "COLON");
            h vr = parse_expression(tokens, np);
            arr_push(pairs, [key_node, arr_get(vr, 0)]);
            np = arr_get(vr, 1);
            if p_tok_kind(tokens, np) == "COMMA" {
                np += 1;
            }
        }
        np = p_expect(tokens, np, "RBRACE");
        return [["DICT", pairs], np];
    }

    # Parenthesized expression
    if kind == "LPAREN" {
        h r = parse_expression(tokens, pos + 1);
        h ast = arr_get(r, 0);
        h np = p_expect(tokens, arr_get(r, 1), "RPAREN");
        return [ast, np];
    }

    # res(expr) — Resonance
    if kind == "RES" {
        h np = p_expect(tokens, pos + 1, "LPAREN");
        h args = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RPAREN" {
            h r = parse_expression(tokens, np);
            arr_push(args, arr_get(r, 0));
            np = arr_get(r, 1);
            if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
        }
        np = p_expect(tokens, np, "RPAREN");
        if arr_len(args) == 1 {
            return [["RESONANCE", arr_get(args, 0)], np];
        }
        return [["CALL", "res", args, ["POS", 0, 0]], np];
    }

    # fold(expr) — Fold
    if kind == "FOLD" {
        h np = p_expect(tokens, pos + 1, "LPAREN");
        h args = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RPAREN" {
            h r = parse_expression(tokens, np);
            arr_push(args, arr_get(r, 0));
            np = arr_get(r, 1);
            if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
        }
        np = p_expect(tokens, np, "RPAREN");
        if arr_len(args) == 1 {
            return [["FOLD", arr_get(args, 0)], np];
        }
        return [["CALL", "fold", args, ["POS", 0, 0]], np];
    }

    # range(...) as expression (outside for-loop context)
    if kind == "RANGE" {
        h np = p_expect(tokens, pos + 1, "LPAREN");
        h args = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RPAREN" {
            h r = parse_expression(tokens, np);
            arr_push(args, arr_get(r, 0));
            np = arr_get(r, 1);
            if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
        }
        np = p_expect(tokens, np, "RPAREN");
        return [["CALL", "range", args, ["POS", 0, 0]], np];
    }

    # if-as-expression: if cond { stmts } else { stmts }
    if kind == "IF" {
        h np = pos + 1;
        h cr = parse_expression(tokens, np);
        h cond = arr_get(cr, 0);
        np = p_expect(tokens, arr_get(cr, 1), "LBRACE");
        h br = parse_block(tokens, np);
        h then_body = arr_get(br, 0);
        np = arr_get(br, 1);
        h else_body = 0;
        if p_tok_kind(tokens, np) == "ELSE" {
            np += 1;
            if p_tok_kind(tokens, np) == "IF" {
                # else if → nested IfExpr
                h nested_r = parse_primary(tokens, np);
                else_body = [["EXPRSTMT", arr_get(nested_r, 0)]];
                np = arr_get(nested_r, 1);
            } else {
                np = p_expect(tokens, np, "LBRACE");
                h ebr = parse_block(tokens, np);
                else_body = arr_get(ebr, 0);
                np = arr_get(ebr, 1);
            }
        }
        return [["IF_EXPR", cond, then_body, else_body], np];
    }

    # Identifier (variable, call, index, dot-access)
    if kind == "IDENT" {
        return parse_ident_expr(tokens, pos);
    }

    print(concat_many("[parse error] unexpected primary token ", kind, " at pos ", pos));
    return [["ERR", kind], pos + 1];
}

fn parse_ident_expr(tokens, pos) {
    h name = p_tok_val(tokens, pos);
    h np = pos + 1;

    # Handle dot-chained names: obj.method.field
    while p_tok_kind(tokens, np) == "DOT" {
        np += 1;
        h part_kind = p_tok_kind(tokens, np);
        h part_val = p_tok_val(tokens, np);
        if part_kind == "IDENT" {
            name = concat_many(name, ".", part_val);
            np += 1;
        } else {
            if part_kind == "RES" {
                name = concat_many(name, ".res");
                np += 1;
            } else {
                if part_kind == "FOLD" {
                    name = concat_many(name, ".fold");
                    np += 1;
                } else {
                    print(concat_many("[parse error] expected method name after '.', got ", part_kind));
                    break;
                }
            }
        }
    }

    h next_kind = p_tok_kind(tokens, np);

    # Function call: name(args)
    if next_kind == "LPAREN" {
        np += 1;
        h args = arr_new(0, 0);
        while p_tok_kind(tokens, np) != "RPAREN" {
            h r = parse_expression(tokens, np);
            arr_push(args, arr_get(r, 0));
            np = arr_get(r, 1);
            if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
        }
        np = p_expect(tokens, np, "RPAREN");
        h expr = ["CALL", name, args, ["POS", 0, 0]];
        # Postfix chains: f(x)[i], f(x)(y), etc.
        return parse_postfix(tokens, np, expr);
    }

    # Index: name[expr]
    if next_kind == "LBRACKET" {
        np += 1;
        h ir = parse_expression(tokens, np);
        h idx = arr_get(ir, 0);
        np = p_expect(tokens, arr_get(ir, 1), "RBRACKET");
        h expr = ["INDEX", name, idx];
        # Postfix chains: a[i][j], a[i](args), etc.
        return parse_postfix(tokens, np, expr);
    }

    # Plain variable
    return [["VAR", name], np];
}

fn parse_postfix(tokens, pos, expr) {
    h np = pos;
    h cur = expr;
    h going = 1;
    while going == 1 {
        if p_tok_kind(tokens, np) == "LBRACKET" {
            np += 1;
            h ir = parse_expression(tokens, np);
            h idx = arr_get(ir, 0);
            np = p_expect(tokens, arr_get(ir, 1), "RBRACKET");
            cur = ["CHAINED_INDEX", cur, idx];
        } else {
            if p_tok_kind(tokens, np) == "LPAREN" {
                np += 1;
                h args = arr_new(0, 0);
                while p_tok_kind(tokens, np) != "RPAREN" {
                    h r = parse_expression(tokens, np);
                    arr_push(args, arr_get(r, 0));
                    np = arr_get(r, 1);
                    if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
                }
                np = p_expect(tokens, np, "RPAREN");
                cur = ["CALL_EXPR", cur, args, ["POS", 0, 0]];
            } else {
                going = 0;
            }
        }
    }
    return [cur, np];
}

fn parse_power(tokens, pos) {
    h br = parse_primary(tokens, pos);
    h base = arr_get(br, 0);
    h np = arr_get(br, 1);
    if p_tok_kind(tokens, np) == "STARSTAR" {
        h er = parse_power(tokens, np + 1);
        return [["POWER", base, arr_get(er, 0)], arr_get(er, 1)];
    }
    return [base, np];
}

fn parse_multiplicative(tokens, pos) {
    h lr = parse_power(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    h going = 1;
    while going == 1 {
        h k = p_tok_kind(tokens, np);
        if k == "STAR" {
            h r = parse_power(tokens, np + 1);
            left = ["MUL", left, arr_get(r, 0)];
            np = arr_get(r, 1);
        } else {
            if k == "SLASH" {
                h r = parse_power(tokens, np + 1);
                left = ["DIV", left, arr_get(r, 0)];
                np = arr_get(r, 1);
            } else {
                if k == "PERCENT" {
                    h r = parse_power(tokens, np + 1);
                    left = ["MOD", left, arr_get(r, 0)];
                    np = arr_get(r, 1);
                } else {
                    going = 0;
                }
            }
        }
    }
    return [left, np];
}

fn parse_additive(tokens, pos) {
    h lr = parse_multiplicative(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    h going = 1;
    while going == 1 {
        h k = p_tok_kind(tokens, np);
        if k == "PLUS" {
            h r = parse_multiplicative(tokens, np + 1);
            left = ["ADD", left, arr_get(r, 0)];
            np = arr_get(r, 1);
        } else {
            if k == "MINUS" {
                h r = parse_multiplicative(tokens, np + 1);
                left = ["SUB", left, arr_get(r, 0)];
                np = arr_get(r, 1);
            } else {
                going = 0;
            }
        }
    }
    return [left, np];
}

fn parse_shift(tokens, pos) {
    h lr = parse_additive(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    h going = 1;
    while going == 1 {
        h k = p_tok_kind(tokens, np);
        if k == "SHL" {
            h r = parse_additive(tokens, np + 1);
            left = ["SHL", left, arr_get(r, 0)];
            np = arr_get(r, 1);
        } else {
            if k == "SHR" {
                h r = parse_additive(tokens, np + 1);
                left = ["SHR", left, arr_get(r, 0)];
                np = arr_get(r, 1);
            } else {
                going = 0;
            }
        }
    }
    return [left, np];
}

fn parse_comparison(tokens, pos) {
    h lr = parse_shift(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    h going = 1;
    while going == 1 {
        h k = p_tok_kind(tokens, np);
        if k == "EQEQ" {
            h r = parse_shift(tokens, np + 1);
            left = ["EQ", left, arr_get(r, 0)];
            np = arr_get(r, 1);
        } else {
            if k == "NE" {
                h r = parse_shift(tokens, np + 1);
                left = ["NE", left, arr_get(r, 0)];
                np = arr_get(r, 1);
            } else {
                if k == "LT" {
                    h r = parse_shift(tokens, np + 1);
                    left = ["LT", left, arr_get(r, 0)];
                    np = arr_get(r, 1);
                } else {
                    if k == "LE" {
                        h r = parse_shift(tokens, np + 1);
                        left = ["LE", left, arr_get(r, 0)];
                        np = arr_get(r, 1);
                    } else {
                        if k == "GT" {
                            h r = parse_shift(tokens, np + 1);
                            left = ["GT", left, arr_get(r, 0)];
                            np = arr_get(r, 1);
                        } else {
                            if k == "GE" {
                                h r = parse_shift(tokens, np + 1);
                                left = ["GE", left, arr_get(r, 0)];
                                np = arr_get(r, 1);
                            } else {
                                going = 0;
                            }
                        }
                    }
                }
            }
        }
    }
    return [left, np];
}

fn parse_bit_and(tokens, pos) {
    h lr = parse_comparison(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    while p_tok_kind(tokens, np) == "BITAND" {
        h r = parse_comparison(tokens, np + 1);
        left = ["BIT_AND", left, arr_get(r, 0)];
        np = arr_get(r, 1);
    }
    return [left, np];
}

fn parse_bit_xor(tokens, pos) {
    h lr = parse_bit_and(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    while p_tok_kind(tokens, np) == "BITXOR" {
        h r = parse_bit_and(tokens, np + 1);
        left = ["BIT_XOR", left, arr_get(r, 0)];
        np = arr_get(r, 1);
    }
    return [left, np];
}

fn parse_bit_or(tokens, pos) {
    h lr = parse_bit_xor(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    while p_tok_kind(tokens, np) == "BITOR" {
        h r = parse_bit_xor(tokens, np + 1);
        left = ["BIT_OR", left, arr_get(r, 0)];
        np = arr_get(r, 1);
    }
    return [left, np];
}

fn parse_not(tokens, pos) {
    if p_tok_kind(tokens, pos) == "NOT" {
        h r = parse_not(tokens, pos + 1);
        return [["NOT", arr_get(r, 0)], arr_get(r, 1)];
    }
    return parse_bit_or(tokens, pos);
}

fn parse_and(tokens, pos) {
    h lr = parse_not(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    while p_tok_kind(tokens, np) == "AND" {
        h r = parse_not(tokens, np + 1);
        left = ["AND", left, arr_get(r, 0)];
        np = arr_get(r, 1);
    }
    return [left, np];
}

fn parse_or(tokens, pos) {
    h lr = parse_and(tokens, pos);
    h left = arr_get(lr, 0);
    h np = arr_get(lr, 1);
    while p_tok_kind(tokens, np) == "OR" {
        h r = parse_and(tokens, np + 1);
        left = ["OR", left, arr_get(r, 0)];
        np = arr_get(r, 1);
    }
    return [left, np];
}

fn parse_expression(tokens, pos) {
    # safe <expr>
    if p_tok_kind(tokens, pos) == "SAFE" {
        h r = parse_or(tokens, pos + 1);
        return [["SAFE", arr_get(r, 0)], arr_get(r, 1)];
    }
    # Lambda: fn(params) { body }
    if p_tok_kind(tokens, pos) == "FN" {
        if p_tok_kind(tokens, pos + 1) == "LPAREN" {
            return parse_lambda(tokens, pos + 1);
        }
    }
    return parse_or(tokens, pos);
}

fn parse_lambda(tokens, pos) {
    h np = pos + 1;
    h params = arr_new(0, 0);
    while p_tok_kind(tokens, np) != "RPAREN" {
        if p_tok_kind(tokens, np) == "IDENT" {
            arr_push(params, p_tok_val(tokens, np));
            np += 1;
        }
        if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
    }
    np = p_expect(tokens, np, "RPAREN");
    # Optional -> type annotation (skip)
    if p_tok_kind(tokens, np) == "ARROW" {
        np += 2;
    }
    # Body
    if p_tok_kind(tokens, np) == "LBRACE" {
        np += 1;
        h br = parse_block(tokens, np);
        h body = arr_get(br, 0);
        np = arr_get(br, 1);
        return [["LAMBDA", params, body], np];
    } else {
        h er = parse_expression(tokens, np);
        h body = [["RETURN", arr_get(er, 0)]];
        return [["LAMBDA", params, body], arr_get(er, 1)];
    }
}

fn parse_block(tokens, pos) {
    h stmts = arr_new(0, 0);
    h np = pos;
    while p_tok_kind(tokens, np) != "RBRACE" {
        if p_tok_kind(tokens, np) == "EOF" { break; }
        h r = parse_statement(tokens, np);
        arr_push(stmts, arr_get(r, 0));
        np = arr_get(r, 1);
    }
    np = p_expect(tokens, np, "RBRACE");
    return [stmts, np];
}

fn parse_pattern_atom(tokens, pos) {
    h kind = p_tok_kind(tokens, pos);
    h value = p_tok_val(tokens, pos);

    if kind == "NUMBER" {
        # Check for range pattern: 0..9
        if p_tok_kind(tokens, pos + 1) == "DOTDOT" {
            h hi = p_tok_val(tokens, pos + 2);
            return [["PAT_RANGE_INT", value, hi], pos + 3];
        }
        return [["PAT_LIT_INT", value], pos + 1];
    }
    if kind == "FLOAT" {
        return [["PAT_LIT_FLOAT", value], pos + 1];
    }
    if kind == "STRING" {
        # Check for string range: "a".."z"
        if p_tok_kind(tokens, pos + 1) == "DOTDOT" {
            h hi = p_tok_val(tokens, pos + 2);
            return [["PAT_RANGE_STR", value, hi], pos + 3];
        }
        return [["PAT_LIT_STR", value], pos + 1];
    }
    if kind == "BOOL" {
        return [["PAT_LIT_BOOL", value], pos + 1];
    }
    if kind == "IDENT" {
        if value == "_" {
            return [["PAT_WILDCARD"], pos + 1];
        }
        if value == "true" {
            return [["PAT_LIT_BOOL", "true"], pos + 1];
        }
        if value == "false" {
            return [["PAT_LIT_BOOL", "false"], pos + 1];
        }
        if value == "null" {
            return [["PAT_LIT_NULL"], pos + 1];
        }
        # Type-tag patterns
        if value == "int" { return [["PAT_TYPE", "int"], pos + 1]; }
        if value == "float" { return [["PAT_TYPE", "float"], pos + 1]; }
        if value == "string" { return [["PAT_TYPE", "string"], pos + 1]; }
        if value == "bool" { return [["PAT_TYPE", "bool"], pos + 1]; }
        if value == "array" { return [["PAT_TYPE", "array"], pos + 1]; }
        if value == "dict" { return [["PAT_TYPE", "dict"], pos + 1]; }
        if value == "function" { return [["PAT_TYPE", "function"], pos + 1]; }
        if value == "null_t" { return [["PAT_TYPE", "null_t"], pos + 1]; }
        if value == "singularity" { return [["PAT_TYPE", "singularity"], pos + 1]; }
        # Bind pattern
        return [["PAT_BIND", value], pos + 1];
    }
    print(concat_many("[parse error] expected pattern, got ", kind, " at pos ", pos));
    return [["PAT_WILDCARD"], pos + 1];
}

fn parse_pattern(tokens, pos) {
    h fr = parse_pattern_atom(tokens, pos);
    h first = arr_get(fr, 0);
    h np = arr_get(fr, 1);
    if p_tok_kind(tokens, np) != "BITOR" {
        return [first, np];
    }
    h alts = arr_new(0, 0);
    arr_push(alts, first);
    while p_tok_kind(tokens, np) == "BITOR" {
        np += 1;
        h ar = parse_pattern_atom(tokens, np);
        arr_push(alts, arr_get(ar, 0));
        np = arr_get(ar, 1);
    }
    return [["PAT_OR", alts], np];
}

fn parse_statement(tokens, pos) {
    h kind = p_tok_kind(tokens, pos);
    h np = pos;

    # --- Pragma handling: @pragma[name] or @name ---
    if kind == "AT" {
        h pragmas = arr_new(0, 0);
        while p_tok_kind(tokens, np) == "AT" {
            np += 1;
            h pk = p_tok_kind(tokens, np);
            h pv = p_tok_val(tokens, np);
            if pk == "IDENT" {
                if pv == "pragma" {
                    np += 1;
                    np = p_expect(tokens, np, "LBRACKET");
                    h pname = p_tok_val(tokens, np);
                    np += 1;
                    np = p_expect(tokens, np, "RBRACKET");
                    arr_push(pragmas, pname);
                } else {
                    arr_push(pragmas, pv);
                    np += 1;
                }
            } else {
                # safe keyword after @ — treat as pragma name
                if pk == "SAFE" {
                    arr_push(pragmas, "safe");
                    np += 1;
                } else {
                    print(concat_many("[parse error] expected pragma name after @, got ", pk));
                    np += 1;
                }
            }
        }
        # The next statement must be a fn def
        h sr = parse_statement(tokens, np);
        h stmt = arr_get(sr, 0);
        np = arr_get(sr, 1);
        # Attach pragmas to the function def
        if arr_get(stmt, 0) == "FNDEF" {
            h existing = arr_get(stmt, 6);
            h merged = arr_new(0, 0);
            h pi = 0;
            while pi < arr_len(pragmas) {
                arr_push(merged, arr_get(pragmas, pi));
                pi += 1;
            }
            pi = 0;
            while pi < arr_len(existing) {
                arr_push(merged, arr_get(existing, pi));
                pi += 1;
            }
            return [["FNDEF", arr_get(stmt, 1), arr_get(stmt, 2), arr_get(stmt, 3), arr_get(stmt, 4), arr_get(stmt, 5), merged], np];
        }
        return [stmt, np];
    }

    # --- Docstring: bare string literal at statement position ---
    if kind == "STRING" {
        h er = parse_expression(tokens, np);
        h expr = arr_get(er, 0);
        np = arr_get(er, 1);
        np = p_eat_semi(tokens, np);
        return [["EXPRSTMT", expr], np];
    }

    # --- Harmonic variable declaration: h name = value; or h[N] name; ---
    if kind == "H" {
        np += 1;
        # h[N] name; → arr_new(N, 0)
        if p_tok_kind(tokens, np) == "LBRACKET" {
            np += 1;
            h sr = parse_expression(tokens, np);
            h size_expr = arr_get(sr, 0);
            np = p_expect(tokens, arr_get(sr, 1), "RBRACKET");
            h vname = p_tok_val(tokens, np);
            np += 1;
            np = p_eat_semi(tokens, np);
            return [["VARDECL", vname, ["CALL", "arr_new", [size_expr, ["NUMBER", 0]], ["POS", 0, 0]], 1], np];
        }
        h vname = p_tok_val(tokens, np);
        np += 1;
        np = p_expect(tokens, np, "EQ");
        h vr = parse_expression(tokens, np);
        h val = arr_get(vr, 0);
        np = arr_get(vr, 1);
        np = p_eat_semi(tokens, np);
        return [["VARDECL", vname, val, 1], np];
    }

    # --- If statement ---
    if kind == "IF" {
        return parse_if_stmt(tokens, np);
    }

    # --- While statement ---
    if kind == "WHILE" {
        np += 1;
        h cr = parse_expression(tokens, np);
        h cond = arr_get(cr, 0);
        np = p_expect(tokens, arr_get(cr, 1), "LBRACE");
        h br = parse_block(tokens, np);
        return [["WHILE", cond, arr_get(br, 0)], arr_get(br, 1)];
    }

    # --- For statement ---
    if kind == "FOR" {
        return parse_for_stmt(tokens, np);
    }

    # --- Function definition ---
    if kind == "FN" {
        return parse_function_def(tokens, np);
    }

    # --- Class definition ---
    if kind == "CLASS" {
        return parse_class_def(tokens, np);
    }

    # --- Try/catch/finally ---
    if kind == "TRY" {
        return parse_try_stmt(tokens, np);
    }

    # --- Throw ---
    if kind == "THROW" {
        np += 1;
        h er = parse_expression(tokens, np);
        np = p_eat_semi(tokens, arr_get(er, 1));
        return [["THROW", arr_get(er, 0)], np];
    }

    # --- Yield ---
    if kind == "YIELD" {
        np += 1;
        h er = parse_expression(tokens, np);
        np = p_eat_semi(tokens, arr_get(er, 1));
        return [["YIELD", arr_get(er, 0)], np];
    }

    # --- Assert: desugar to if (not cond) { throw msg; } ---
    if kind == "ASSERT" {
        np += 1;
        h cr = parse_expression(tokens, np);
        h cond = arr_get(cr, 0);
        np = arr_get(cr, 1);
        h msg = ["STRING", "Assertion failed"];
        if p_tok_kind(tokens, np) == "COMMA" {
            np += 1;
            h mr = parse_expression(tokens, np);
            msg = arr_get(mr, 0);
            np = arr_get(mr, 1);
        }
        np = p_eat_semi(tokens, np);
        return [["IF", ["NOT", cond], [["THROW", msg]], [], 0], np];
    }

    # --- Match statement ---
    if kind == "MATCH" {
        return parse_match_stmt(tokens, np);
    }

    # --- Import / Load ---
    if kind == "IMPORT" {
        np += 1;
        h mod_name = p_tok_val(tokens, np);
        np += 1;
        h alias = 0;
        if p_tok_kind(tokens, np) == "AS" {
            np += 1;
            alias = p_tok_val(tokens, np);
            np += 1;
        }
        np = p_eat_semi(tokens, np);
        return [["IMPORT", mod_name, alias, 0], np];
    }
    if kind == "LOAD" {
        np += 1;
        h mod_name = p_tok_val(tokens, np);
        np += 1;
        h alias = 0;
        if p_tok_kind(tokens, np) == "AS" {
            np += 1;
            alias = p_tok_val(tokens, np);
            np += 1;
        }
        np = p_eat_semi(tokens, np);
        return [["IMPORT", mod_name, alias, 0], np];
    }

    # --- From ... import ... ---
    if kind == "FROM" {
        np += 1;
        h mod_name = p_tok_val(tokens, np);
        np += 1;
        np = p_expect(tokens, np, "IMPORT");
        h names = arr_new(0, 0);
        arr_push(names, p_tok_val(tokens, np));
        np += 1;
        while p_tok_kind(tokens, np) == "COMMA" {
            np += 1;
            arr_push(names, p_tok_val(tokens, np));
            np += 1;
        }
        np = p_eat_semi(tokens, np);
        return [["IMPORT", mod_name, 0, names], np];
    }

    # --- Return ---
    if kind == "RETURN" {
        np += 1;
        if p_tok_kind(tokens, np) == "SEMI" {
            np += 1;
            return [["RETURN", 0], np];
        }
        h er = parse_expression(tokens, np);
        np = p_eat_semi(tokens, arr_get(er, 1));
        return [["RETURN", arr_get(er, 0)], np];
    }

    # --- Break ---
    if kind == "BREAK" {
        np += 1;
        np = p_eat_semi(tokens, np);
        return [["BREAK"], np];
    }

    # --- Continue ---
    if kind == "CONTINUE" {
        np += 1;
        np = p_eat_semi(tokens, np);
        return [["CONTINUE"], np];
    }

    # --- Print ---
    if kind == "PRINT" {
        np += 1;
        np = p_expect(tokens, np, "LPAREN");
        h er = parse_expression(tokens, np);
        np = p_expect(tokens, arr_get(er, 1), "RPAREN");
        np = p_eat_semi(tokens, np);
        return [["PRINT", arr_get(er, 0)], np];
    }

    # --- Identifier: assignment, compound assignment, index assignment, or expression ---
    if kind == "IDENT" {
        h ident_name = p_tok_val(tokens, np);
        h next = p_tok_kind(tokens, np + 1);

        # Simple assignment: name = value;
        if next == "EQ" {
            np += 2;
            h vr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(vr, 1));
            return [["ASSIGN", ident_name, arr_get(vr, 0)], np];
        }

        # Compound assignment: += -= *= /= %= **=
        if next == "PLUSEQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["ADD", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }
        if next == "MINUSEQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["SUB", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }
        if next == "STAREQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["MUL", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }
        if next == "SLASHEQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["DIV", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }
        if next == "PERCENTEQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["MOD", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }
        if next == "STARSTAREQ" {
            np += 2;
            h rr = parse_expression(tokens, np);
            np = p_eat_semi(tokens, arr_get(rr, 1));
            return [["ASSIGN", ident_name, ["POWER", ["VAR", ident_name], arr_get(rr, 0)]], np];
        }

        # Index assignment: name[idx] = val; or name[i][j] = val;
        if next == "LBRACKET" {
            # Parse the index
            h idx_r = parse_expression(tokens, np + 2);
            h idx_expr = arr_get(idx_r, 0);
            h after_idx = p_expect(tokens, arr_get(idx_r, 1), "RBRACKET");

            if p_tok_kind(tokens, after_idx) == "EQ" {
                # Simple index assignment: name[idx] = val;
                h vr = parse_expression(tokens, after_idx + 1);
                h after_val = p_eat_semi(tokens, arr_get(vr, 1));
                return [["IDX_ASSIGN", ident_name, idx_expr, arr_get(vr, 0)], after_val];
            }
            if p_tok_kind(tokens, after_idx) == "LBRACKET" {
                # Might be chained index assignment: name[i][j] = val;
                h idx2_r = parse_expression(tokens, after_idx + 1);
                h idx2_expr = arr_get(idx2_r, 0);
                h after_idx2 = p_expect(tokens, arr_get(idx2_r, 1), "RBRACKET");
                if p_tok_kind(tokens, after_idx2) == "EQ" {
                    h vr = parse_expression(tokens, after_idx2 + 1);
                    h after_val = p_eat_semi(tokens, arr_get(vr, 1));
                    return [["CHAIN_IDX_ASSIGN", ident_name, idx_expr, idx2_expr, arr_get(vr, 0)], after_val];
                }
            }
            # Fall through to expression statement
        }

        # Expression statement (function call, etc.)
        h er = parse_expression(tokens, np);
        np = p_eat_semi(tokens, arr_get(er, 1));
        return [["EXPRSTMT", arr_get(er, 0)], np];
    }

    # --- Default: expression statement ---
    h er = parse_expression(tokens, np);
    np = p_eat_semi(tokens, arr_get(er, 1));
    return [["EXPRSTMT", arr_get(er, 0)], np];
}

fn parse_if_stmt(tokens, pos) {
    h np = pos + 1;
    h cr = parse_expression(tokens, np);
    h cond = arr_get(cr, 0);
    np = p_expect(tokens, arr_get(cr, 1), "LBRACE");
    h br = parse_block(tokens, np);
    h then_body = arr_get(br, 0);
    np = arr_get(br, 1);

    h elif_parts = arr_new(0, 0);
    h else_body = 0;
    h done = 0;

    while done == 0 {
        if p_tok_kind(tokens, np) == "ELIF" {
            np += 1;
            h ecr = parse_expression(tokens, np);
            h elif_cond = arr_get(ecr, 0);
            np = p_expect(tokens, arr_get(ecr, 1), "LBRACE");
            h ebr = parse_block(tokens, np);
            arr_push(elif_parts, [elif_cond, arr_get(ebr, 0)]);
            np = arr_get(ebr, 1);
        } else {
            if p_tok_kind(tokens, np) == "ELSE" {
                np += 1;
                if p_tok_kind(tokens, np) == "IF" {
                    np += 1;
                    h ecr = parse_expression(tokens, np);
                    h elif_cond = arr_get(ecr, 0);
                    np = p_expect(tokens, arr_get(ecr, 1), "LBRACE");
                    h ebr = parse_block(tokens, np);
                    arr_push(elif_parts, [elif_cond, arr_get(ebr, 0)]);
                    np = arr_get(ebr, 1);
                } else {
                    np = p_expect(tokens, np, "LBRACE");
                    h ebr = parse_block(tokens, np);
                    else_body = arr_get(ebr, 0);
                    np = arr_get(ebr, 1);
                    done = 1;
                }
            } else {
                done = 1;
            }
        }
    }

    return [["IF", cond, then_body, elif_parts, else_body], np];
}

fn parse_for_stmt(tokens, pos) {
    h np = pos + 1;
    h var_name = p_tok_val(tokens, np);
    np += 1;
    np = p_expect(tokens, np, "IN");

    h iterable = 0;

    if p_tok_kind(tokens, np) == "RANGE" {
        np += 1;
        np = p_expect(tokens, np, "LPAREN");
        h fr = parse_expression(tokens, np);
        h first = arr_get(fr, 0);
        np = arr_get(fr, 1);

        if p_tok_kind(tokens, np) == "COMMA" {
            np += 1;
            h sr = parse_expression(tokens, np);
            h second = arr_get(sr, 0);
            np = arr_get(sr, 1);

            if p_tok_kind(tokens, np) == "COMMA" {
                # range(start, end, step) → Expr(Call("range", ...))
                np += 1;
                h tr = parse_expression(tokens, np);
                h step = arr_get(tr, 0);
                np = arr_get(tr, 1);
                np = p_expect(tokens, np, "RPAREN");
                iterable = ["FOR_EXPR", ["CALL", "range", [first, second, step], ["POS", 0, 0]]];
            } else {
                np = p_expect(tokens, np, "RPAREN");
                iterable = ["FOR_RANGE", first, second];
            }
        } else {
            np = p_expect(tokens, np, "RPAREN");
            iterable = ["FOR_RANGE", ["NUMBER", 0], first];
        }
    } else {
        h er = parse_expression(tokens, np);
        iterable = ["FOR_EXPR", arr_get(er, 0)];
        np = arr_get(er, 1);
    }

    np = p_expect(tokens, np, "LBRACE");
    h br = parse_block(tokens, np);
    return [["FOR", var_name, iterable, arr_get(br, 0)], arr_get(br, 1)];
}

fn parse_function_def(tokens, pos) {
    h np = pos + 1;
    h fname = p_tok_val(tokens, np);
    np += 1;
    np = p_expect(tokens, np, "LPAREN");

    h params = arr_new(0, 0);
    h param_types = arr_new(0, 0);

    while p_tok_kind(tokens, np) != "RPAREN" {
        h pname = p_tok_val(tokens, np);
        np += 1;
        # Optional : type annotation
        h ptype = 0;
        if p_tok_kind(tokens, np) == "COLON" {
            np += 1;
            ptype = p_tok_val(tokens, np);
            np += 1;
        }
        arr_push(params, pname);
        arr_push(param_types, ptype);
        if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
    }
    np = p_expect(tokens, np, "RPAREN");

    # Optional -> return_type
    h return_type = 0;
    if p_tok_kind(tokens, np) == "ARROW" {
        np += 1;
        return_type = p_tok_val(tokens, np);
        np += 1;
    }

    # Postfix pragmas after return type: @name, @name:value
    h pragmas = arr_new(0, 0);
    while p_tok_kind(tokens, np) == "AT" {
        np += 1;
        h pname = p_tok_val(tokens, np);
        np += 1;
        # Optional :value parameter
        if p_tok_kind(tokens, np) == "COLON" {
            np += 1;
            h pval = p_tok_val(tokens, np);
            np += 1;
            pname = concat_many(pname, ":", pval);
        }
        arr_push(pragmas, pname);
    }

    np = p_expect(tokens, np, "LBRACE");
    h br = parse_block(tokens, np);
    return [["FNDEF", fname, params, param_types, arr_get(br, 0), return_type, pragmas], arr_get(br, 1)];
}

fn parse_class_def(tokens, pos) {
    h np = pos + 1;
    h cname = p_tok_val(tokens, np);
    np += 1;

    # Optional extends Parent
    h parent = 0;
    if p_tok_kind(tokens, np) == "EXTENDS" {
        np += 1;
        parent = p_tok_val(tokens, np);
        np += 1;
    }

    np = p_expect(tokens, np, "LBRACE");
    h fields = arr_new(0, 0);
    h methods = arr_new(0, 0);

    while p_tok_kind(tokens, np) != "RBRACE" {
        if p_tok_kind(tokens, np) == "FN" {
            h mr = parse_function_def(tokens, np);
            arr_push(methods, arr_get(mr, 0));
            np = arr_get(mr, 1);
        } else {
            # Field declaration: field_name;
            arr_push(fields, p_tok_val(tokens, np));
            np += 1;
            np = p_eat_semi(tokens, np);
        }
    }
    np = p_expect(tokens, np, "RBRACE");
    return [["CLASSDEF", cname, parent, fields, methods], np];
}

fn parse_try_stmt(tokens, pos) {
    h np = pos + 1;
    np = p_expect(tokens, np, "LBRACE");
    h br = parse_block(tokens, np);
    h body = arr_get(br, 0);
    np = arr_get(br, 1);
    np = p_expect(tokens, np, "CATCH");
    h err_var = p_tok_val(tokens, np);
    np += 1;
    np = p_expect(tokens, np, "LBRACE");
    h hr = parse_block(tokens, np);
    h handler = arr_get(hr, 0);
    np = arr_get(hr, 1);
    h finally_body = 0;
    if p_tok_kind(tokens, np) == "FINALLY" {
        np += 1;
        np = p_expect(tokens, np, "LBRACE");
        h fr = parse_block(tokens, np);
        finally_body = arr_get(fr, 0);
        np = arr_get(fr, 1);
    }
    return [["TRY", body, err_var, handler, finally_body], np];
}

fn parse_match_stmt(tokens, pos) {
    h np = pos + 1;
    h sr = parse_expression(tokens, np);
    h scrutinee = arr_get(sr, 0);
    np = p_expect(tokens, arr_get(sr, 1), "LBRACE");

    h arms = arr_new(0, 0);
    while p_tok_kind(tokens, np) != "RBRACE" {
        h pr = parse_pattern(tokens, np);
        h pat = arr_get(pr, 0);
        np = p_expect(tokens, arr_get(pr, 1), "FATARROW");

        h arm_body = 0;
        if p_tok_kind(tokens, np) == "LBRACE" {
            np = p_expect(tokens, np, "LBRACE");
            h br = parse_block(tokens, np);
            arm_body = arr_get(br, 0);
            np = arr_get(br, 1);
        } else {
            # Single statement arm
            h sr = parse_statement(tokens, np);
            arm_body = [arr_get(sr, 0)];
            np = arr_get(sr, 1);
        }
        arr_push(arms, ["MATCH_ARM", pat, arm_body]);
        # Optional comma between arms
        if p_tok_kind(tokens, np) == "COMMA" { np += 1; }
    }
    np = p_expect(tokens, np, "RBRACE");
    return [["MATCH", scrutinee, arms], np];
}

fn parse_program(tokens) {
    h stmts = arr_new(0, 0);
    h np = 0;
    while p_tok_kind(tokens, np) != "EOF" {
        h r = parse_statement(tokens, np);
        arr_push(stmts, arr_get(r, 0));
        np = arr_get(r, 1);
    }
    return stmts;
}

fn parse(source) {
    h tokens = tokenize(source);
    return parse_program(tokens);
}

fn ast_to_string(node) -> string {
    h tag = arr_get(node, 0);
    if tag == "NUMBER" { return concat_many("(NUM ", arr_get(node, 1), ")"); }
    if tag == "FLOAT" { return concat_many("(FLOAT ", arr_get(node, 1), ")"); }
    if tag == "STRING" { return concat_many("(STR \"", arr_get(node, 1), "\")"); }
    if tag == "BOOL" { return concat_many("(BOOL ", arr_get(node, 1), ")"); }
    if tag == "VAR" { return concat_many("(VAR ", arr_get(node, 1), ")"); }
    if tag == "ADD" { return concat_many("(+ ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "SUB" { return concat_many("(- ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "MUL" { return concat_many("(* ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "DIV" { return concat_many("(/ ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "MOD" { return concat_many("(% ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "EQ" { return concat_many("(== ", ast_to_string(arr_get(node, 1)), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "CALL" { return concat_many("(CALL ", arr_get(node, 1), " ...)"); }
    if tag == "VARDECL" { return concat_many("(VARDECL ", arr_get(node, 1), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "ASSIGN" { return concat_many("(ASSIGN ", arr_get(node, 1), " ", ast_to_string(arr_get(node, 2)), ")"); }
    if tag == "FNDEF" { return concat_many("(FNDEF ", arr_get(node, 1), " ...)"); }
    if tag == "IF" { return "(IF ...)"; }
    if tag == "WHILE" { return "(WHILE ...)"; }
    if tag == "FOR" { return "(FOR ...)"; }
    if tag == "RETURN" { return "(RETURN ...)"; }
    if tag == "PRINT" { return concat_many("(PRINT ", ast_to_string(arr_get(node, 1)), ")"); }
    if tag == "EXPRSTMT" { return concat_many("(EXPRSTMT ", ast_to_string(arr_get(node, 1)), ")"); }
    return concat_many("(", tag, " ...)");
}

