fn reset_search_stats() {
    _explicit_searches = 0;
    _explicit_comparisons = 0;
    _background_searches = 0;
    _background_comparisons = 0;
}

fn _get_fib(idx) {
    h fib_len = len(FIBONACCI);
    if idx >= fib_len {
        return FIBONACCI[fib_len - 1];
    }
    return FIBONACCI[idx];
}

fn _find_fib_index(n) {
    h i = 0;
    while i < len(FIBONACCI) {
        if FIBONACCI[i] >= n {
            return i;
        }
        i = i + 1;
    }
    return len(FIBONACCI) - 1;
}

fn fibonacci_index_of(n) {
    h m = abs(n);
    h i = 0;
    while i < len(FIBONACCI) {
        if FIBONACCI[i] == m {
            return i;
        }
        if FIBONACCI[i] > m {
            return -1;
        }
        i = i + 1;
    }
    return -1;
}

fn zeckendorf_indices(n) {
    if n == 0 {
        return [];
    }
    h out = [];
    h rem = n;
    h i = len(FIBONACCI);
    while i > 0 && rem > 0 {
        i = i - 1;
        if FIBONACCI[i] <= rem && FIBONACCI[i] > 0 {
            rem = rem - FIBONACCI[i];
            arr_push(out, i);
            if i > 0 {
                i = i - 1;
            }
        }
    }
    return out;
}

fn from_zeckendorf_indices(indices) {
    h acc = 0;
    h i = 0;
    while i < len(indices) {
        acc = acc + _get_fib(indices[i]);
        i = i + 1;
    }
    return acc;
}

fn _fibonacci_search_categorised(arr, target, explicit) {
    h arr_len = len(arr);
    if arr_len == 0 {
        return {"found": false, "index": 0};
    }

    if explicit {
        _explicit_searches = _explicit_searches + 1;
    } else {
        _background_searches = _background_searches + 1;
    }

    h fib_idx = _find_fib_index(arr_len);
    h offset = 0;
    h comparisons = 0;

    while fib_idx > 0 {
        comparisons = comparisons + 1;

        h fib_val = _get_fib(fib_idx);
        h remaining = arr_len - offset - 1;
        h fv = fib_val;
        if fv > remaining {
            fv = remaining;
        }
        h mid = offset + fv;
        if mid > arr_len - 1 {
            mid = arr_len - 1;
        }

        if arr[mid] == target {
            if explicit {
                _explicit_comparisons = _explicit_comparisons + comparisons;
            } else {
                _background_comparisons = _background_comparisons + comparisons;
            }
            return {"found": true, "index": mid};
        }

        if arr[mid] < target {
            offset = mid + 1;
            if fib_idx >= 2 {
                fib_idx = fib_idx - 2;
            } else {
                fib_idx = 0;
            }
        } else {
            if fib_idx >= 1 {
                fib_idx = fib_idx - 1;
            } else {
                fib_idx = 0;
            }
        }

        if offset >= arr_len {
            break;
        }
    }

    if explicit {
        _explicit_comparisons = _explicit_comparisons + comparisons;
    } else {
        _background_comparisons = _background_comparisons + comparisons;
    }
    return {"found": false, "index": offset};
}

fn fibonacci_search(arr, target) {
    return _fibonacci_search_categorised(arr, target, true);
}

fn fibonacci_search_internal(arr, target) {
    return _fibonacci_search_categorised(arr, target, false);
}

fn fibonacci_search_with_trace(arr, target) {
    h probes = [];
    h arr_len = len(arr);
    if arr_len == 0 {
        return {"result": {"found": false, "index": 0}, "probes": probes};
    }

    _explicit_searches = _explicit_searches + 1;

    h fib_idx = _find_fib_index(arr_len);
    h offset = 0;
    h comparisons = 0;

    while fib_idx > 0 {
        comparisons = comparisons + 1;

        h fib_val = _get_fib(fib_idx);
        h remaining = arr_len - offset - 1;
        h fv = fib_val;
        if fv > remaining {
            fv = remaining;
        }
        h mid = offset + fv;
        if mid > arr_len - 1 {
            mid = arr_len - 1;
        }
        arr_push(probes, mid);

        if arr[mid] == target {
            _explicit_comparisons = _explicit_comparisons + comparisons;
            return {"result": {"found": true, "index": mid}, "probes": probes};
        }

        if arr[mid] < target {
            offset = mid + 1;
            if fib_idx >= 2 {
                fib_idx = fib_idx - 2;
            } else {
                fib_idx = 0;
            }
        } else {
            if fib_idx >= 1 {
                fib_idx = fib_idx - 1;
            } else {
                fib_idx = 0;
            }
        }

        if offset >= arr_len {
            break;
        }
    }

    _explicit_comparisons = _explicit_comparisons + comparisons;
    return {"result": {"found": false, "index": offset}, "probes": probes};
}

fn phi_pi_fib_search_v2(arr, target) {
    h arr_len = len(arr);
    if arr_len == 0 {
        return {"found": false, "index": 0};
    }

    _explicit_searches = _explicit_searches + 1;

    h low = 0;
    h high = arr_len;
    h k = 1;
    h comparisons = 0;

    # Phase 1: phi-pi-fib probe-offset iterations
    while low + 1 < high {
        h rng = (high - low) * 1.0;
        h fib_k = 0.0;
        if k < len(FIBONACCI) {
            fib_k = FIBONACCI[k] * 1.0;
        } else {
            fib_k = FIBONACCI[len(FIBONACCI) - 1] * 1.0;
        }
        h denom = exp(PI * (k * 1.0) * log(PHI));
        h frac = fib_k / denom;
        if frac < 0.0 {
            frac = 0.0;
        }
        if frac > 0.999 {
            frac = 0.999;
        }
        h offset = round(rng * frac);
        if offset == 0 {
            break;
        }
        h mid = low + offset;
        if mid > high - 1 {
            mid = high - 1;
        }

        comparisons = comparisons + 1;
        if arr[mid] == target {
            _explicit_comparisons = _explicit_comparisons + comparisons;
            return {"found": true, "index": mid};
        }
        if arr[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
        k = k + 1;
    }

    # Phase 2: binary search on remaining range
    while low < high {
        comparisons = comparisons + 1;
        h mid = low + floor((high - low) / 2);
        if arr[mid] == target {
            _explicit_comparisons = _explicit_comparisons + comparisons;
            return {"found": true, "index": mid};
        }
        if arr[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    _explicit_comparisons = _explicit_comparisons + comparisons;
    return {"found": false, "index": low};
}

fn binary_search(arr, target) {
    h arr_len = len(arr);
    h low = 0;
    h high = arr_len;
    h comparisons = 0;

    _explicit_searches = _explicit_searches + 1;

    while low < high {
        comparisons = comparisons + 1;
        h mid = low + floor((high - low) / 2);

        if arr[mid] == target {
            _explicit_comparisons = _explicit_comparisons + comparisons;
            return {"found": true, "index": mid};
        }
        if arr[mid] < target {
            low = mid + 1;
        } else {
            high = mid;
        }
    }

    _explicit_comparisons = _explicit_comparisons + comparisons;
    return {"found": false, "index": low};
}

fn nearest_attractor_with_dist(value) {
    h abs_v = abs(value);
    if abs_v == 0 {
        return {"attractor": 0, "distance": 0};
    }
    # Fast path for very small values (0, 1, 2, 3 are all attractors)
    if abs_v <= 3 {
        h signed = abs_v;
        if value < 0 {
            signed = -abs_v;
        }
        return {"attractor": signed, "distance": 0};
    }

    h target = abs_v;
    h r = fibonacci_search_internal(FIBONACCI, target);

    h nearest_abs = 0;
    h min_dist = 0;

    if r["found"] {
        nearest_abs = FIBONACCI[r["index"]];
        min_dist = 0;
    } else {
        h insert_pos = r["index"];
        h n = len(FIBONACCI);
        if insert_pos == 0 {
            nearest_abs = FIBONACCI[0];
            min_dist = abs(abs_v - nearest_abs);
        } else {
            if insert_pos >= n {
                nearest_abs = FIBONACCI[n - 1];
                min_dist = abs(abs_v - nearest_abs);
            } else {
                h left = FIBONACCI[insert_pos - 1];
                h right = FIBONACCI[insert_pos];
                h left_d = abs(abs_v - left);
                h right_d = abs(right - abs_v);
                if left_d <= right_d {
                    nearest_abs = left;
                    min_dist = left_d;
                } else {
                    nearest_abs = right;
                    min_dist = right_d;
                }
            }
        }
    }

    h signed = nearest_abs;
    if value < 0 {
        signed = -nearest_abs;
    }
    return {"attractor": signed, "distance": min_dist};
}

fn fold_to_nearest_attractor(value) {
    h r = nearest_attractor_with_dist(value);
    return r["attractor"];
}

fn is_on_fibonacci_attractor(value) {
    h r = nearest_attractor_with_dist(value);
    return r["distance"] == 0;
}

fn log_phi_pi_fibonacci(n) {
    return log(n) / (PI * log(PHI));
}

fn largest_attractor_at_most(value) {
    h abs_v = abs(value);
    if abs_v == 0 {
        return 0;
    }
    h found = 0;
    h i = len(FIBONACCI) - 1;
    while i >= 0 {
        if FIBONACCI[i] <= abs_v {
            found = FIBONACCI[i];
            break;
        }
        i = i - 1;
    }
    if value < 0 {
        return -found;
    }
    return found;
}

fn substrate_search(arr, target) {
    h r = phi_pi_fib_search_v2(arr, target);
    if r["found"] {
        return r["index"];
    }
    return -1;
}

fn substrate_lower_bound(arr, target) {
    h n = len(arr);
    if n == 0 {
        return 0;
    }
    h r = phi_pi_fib_search_v2(arr, target);
    h i = r["index"];
    if i > n {
        i = n;
    }
    while i > 0 && arr[i - 1] >= target {
        i = i - 1;
    }
    while i < n && arr[i] < target {
        i = i + 1;
    }
    return i;
}

fn substrate_upper_bound(arr, target) {
    h n = len(arr);
    if n == 0 {
        return 0;
    }
    h r = phi_pi_fib_search_v2(arr, target);
    h i = r["index"];
    if i > n {
        i = n;
    }
    while i > 0 && arr[i - 1] > target {
        i = i - 1;
    }
    while i < n && arr[i] <= target {
        i = i + 1;
    }
    return i;
}

fn attractor_bucket(value) {
    h r = nearest_attractor_with_dist(value);
    h attr = abs(r["attractor"]);
    h i = 0;
    while i < len(FIBONACCI) {
        if FIBONACCI[i] == attr {
            return i;
        }
        i = i + 1;
    }
    return 0;
}

