fn fibonacci(n) {
    if n <= 1 {
        return n;
    }
    h a = 0;
    h b = 1;
    h i = 2;
    while i <= n {
        h temp = a + b;
        a = b;
        b = temp;
        i = i + 1;
    }
    return b;
}

fn value_is_fibonacci(n) {
    return is_fibonacci(n);
}

fn compute_resonance(value) {
    h min_dist = attractor_distance(value);
    h abs_val = abs(value);
    if min_dist == 0 {
        return 1.0;
    }
    h denom = abs_val;
    if denom < 1 {
        denom = 1;
    }
    return 1.0 - (min_dist * 1.0) / (denom * 1.0 + 1.0);
}

fn compute_him(value) {
    h v = value * 1.0;
    h product = v * PHI;
    h frac_part = product - floor(product);
    h abs_frac = abs(frac_part);
    h complement = 1.0 - abs_frac;
    if abs_frac < complement {
        return abs_frac;
    }
    return complement;
}

fn hint_new(value) {
    h resonance = compute_resonance(value);
    h him_score = compute_him(value);
    h result = {};
    dict_set(result, "_type", "HInt");
    dict_set(result, "value", value);
    dict_set(result, "resonance", resonance);
    dict_set(result, "him_score", him_score);
    dict_set(result, "is_singularity", 0);
    return result;
}

