    dict_set(result, "_type", "String");
    dict_set(result, "value", s);
    return result;
}

fn value_bool(b) {
    h result = {};
    dict_set(result, "_type", "Bool");
    dict_set(result, "value", b);
    return result;
}

fn value_array(items) {
