}

fn value_null() {
    h result = {};
    dict_set(result, "_type", "Null");
    return result;
}

fn value_type(v) {
    return dict_get(v, "_type");
}

fn value_is_int(v) {
    return dict_get(v, "_type") == "HInt";
}

fn value_is_float(v) {
    return dict_get(v, "_type") == "HFloat";
}

fn value_is_string(v) {
    return dict_get(v, "_type") == "String";
}

fn value_is_bool(v) {
    return dict_get(v, "_type") == "Bool";
}

fn value_is_array(v) {
    return dict_get(v, "_type") == "HArray";
}

fn value_is_null(v) {
    return dict_get(v, "_type") == "Null";
}

fn value_is_singularity(v) {
    if dict_get(v, "_type") == "HInt" {
        return dict_get(v, "is_singularity") == 1;
    }
    return 0;
}

fn value_is_numeric(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return 1;
    }
    if t == "HFloat" {
        return 1;
    }
    return 0;
}

fn value_to_int(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return dict_get(v, "value");
    }
    if t == "HFloat" {
        return floor(dict_get(v, "value"));
    }
    if t == "String" {
        return to_int(dict_get(v, "value"));
    }
    if t == "Bool" {
        if dict_get(v, "value") {
            return 1;
        }
        return 0;
    }
    return 0;
}

fn value_to_float(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return dict_get(v, "value") * 1.0;
    }
    if t == "HFloat" {
        return dict_get(v, "value");
    }
    if t == "String" {
        return to_float(dict_get(v, "value"));
    }
    if t == "Bool" {
        if dict_get(v, "value") {
            return 1.0;
        }
        return 0.0;
    }
    return 0.0;
}

fn value_to_bool(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return dict_get(v, "value") != 0;
    }
    if t == "HFloat" {
        return dict_get(v, "value") != 0.0;
    }
    if t == "String" {
        return str_len(dict_get(v, "value")) > 0;
    }
    if t == "Bool" {
        return dict_get(v, "value");
    }
    if t == "HArray" {
        return arr_len(dict_get(v, "items")) > 0;
    }
    if t == "Null" {
        return 0;
    }
    return 1;
}

fn value_to_string(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return hint_to_string(v);
    }
    if t == "HFloat" {
        return to_string(dict_get(v, "value"));
    }
    if t == "String" {
        return dict_get(v, "value");
    }
    if t == "Bool" {
        return to_string(dict_get(v, "value"));
    }
    if t == "HArray" {
        return "[array]";
    }
    if t == "Null" {
        return "null";
    }
    return "unknown";
}

fn value_to_display_string(v) {
    h t = dict_get(v, "_type");
    if t == "HInt" {
        return to_string(dict_get(v, "value"));
    }
    if t == "HFloat" {
        return to_string(dict_get(v, "value"));
    }
    if t == "String" {
        return dict_get(v, "value");
    }
    if t == "Bool" {
        return to_string(dict_get(v, "value"));
    }
    if t == "Null" {
        return "null";
    }
    return value_to_string(v);
}

