    )
    return strip_fences(omc_ask(prompt))
}

fn improve_to_convergence(code, goal, max_rounds) {
    h rounds = max_rounds
    if rounds == null { rounds = 3 }

    h cache_key = str_concat(code, "|", goal)
    h cached = lru_get(MEMO_CACHE, cache_key)
    if cached != null { return cached }

    h current = code
    h trace = [{round: 0, code: current}]

    h r = 0
    while r < rounds {
        h criticism = critique(current, goal)
        h improved = apply_critique(current, criticism)

        if improved == current {
            print(str_concat("  Converged at round ", to_str(r + 1)))
            break
        }

        current = improved
        arr_push(trace, {round: r + 1, code: current, critique: criticism})
        r = r + 1
    }

    h result = {code: current, rounds: r, trace: trace}
    lru_put(MEMO_CACHE, cache_key, result)
    return result
}

fn memoize(f) {
    h store = {}
    h memo_wrapper = fn(arg) {
        h key = to_string(arg)
        if dict_has(store, key) {
            return store[key]
        }
        h result = f(arg)
        store[key] = result
        return result
    }
    return memo_wrapper
}

fn memoize2(f) {
    h store = {}
    h memo2_wrapper = fn(a, b) {
        h key = str_concat(to_string(a), "|", to_string(b))
        if dict_has(store, key) {
            return store[key]
        }
        h result = f(a, b)
        store[key] = result
        return result
    }
    return memo2_wrapper
}

fn lru_new(capacity) {
    return {
        capacity: capacity,
        store: {},
        order: [],
        hits: 0,
        misses: 0
    }
}

fn _lru_evict(lru) {
    if arr_len(lru["order"]) >= lru["capacity"] {
        h oldest = lru["order"][0]
        lru["order"] = arr_slice(lru["order"], 1, arr_len(lru["order"]))
        if dict_has(lru["store"], oldest) {
            dict_delete(lru["store"], oldest)
        }
    }
}

fn _lru_touch(lru, key) {
    h new_order = []
    h i = 0
    while i < arr_len(lru["order"]) {
        if lru["order"][i] != key {
            arr_push(new_order, lru["order"][i])
        }
        i = i + 1
    }
    arr_push(new_order, key)
    lru["order"] = new_order
}

fn lru_get(lru, key) {
    h k = to_string(key)
    if dict_has(lru["store"], k) {
        _lru_touch(lru, k)
        lru["hits"] = lru["hits"] + 1
        return lru["store"][k]
    }
    lru["misses"] = lru["misses"] + 1
    return null
}

fn lru_put(lru, key, value) {
    h k = to_string(key)
    if !dict_has(lru["store"], k) {
        _lru_evict(lru)
        arr_push(lru["order"], k)
    } else {
        _lru_touch(lru, k)
    }
    lru["store"][k] = value
}

fn lru_stats(lru) {
    h total = lru["hits"] + lru["misses"]
    h rate = 0.0
    if total > 0 { rate = lru["hits"] / total }
    return {
        hits: lru["hits"],
        misses: lru["misses"],
        size: arr_len(lru["order"]),
        capacity: lru["capacity"],
        hit_rate: rate
    }
}

fn lru_memoize(f, capacity) {
    h cache = lru_new(capacity)
    h lru_wrapper = fn(arg) {
        h key = to_string(arg)
        h cached = lru_get(cache, key)
        if cached != null { return cached }
        h result = f(arg)
        lru_put(cache, key, result)
        return result
    }
    return lru_wrapper
}

fn ttl_new(ttl_seconds) {
    return {ttl: ttl_seconds, store: {}, expires: {}, hits: 0, misses: 0}
}

fn ttl_get(cache, key) {
    h k = to_string(key)
    if !dict_has(cache["store"], k) {
        cache["misses"] = cache["misses"] + 1
        return null
    }
    h now = unix_time()
    if now > cache["expires"][k] {
        dict_delete(cache["store"], k)
        dict_delete(cache["expires"], k)
        cache["misses"] = cache["misses"] + 1
        return null
    }
    cache["hits"] = cache["hits"] + 1
    return cache["store"][k]
}

fn ttl_put(cache, key, value) {
    h k = to_string(key)
    h now = unix_time()
    cache["store"][k] = value
    cache["expires"][k] = now + cache["ttl"]
}

fn ttl_memoize(f, ttl) {
    h cache = ttl_new(ttl)
    h ttl_wrapper = fn(arg) {
        h key = to_string(arg)
        h cached = ttl_get(cache, key)
        if cached != null { return cached }
        h result = f(arg)
        ttl_put(cache, key, result)
        return result
    }
    return ttl_wrapper
}

