fn _prom_geodesic_moduli() {
    return [5, 8, 13, 21, 34, 55, 89, 144];
}

fn _prom_circular_dist(a, b, m) {
    h d = a - b;
    if d < 0 { d = 0 - d; }
    h alt = m - d;
    if alt < d { return alt; }
    return d;
}

fn prom_geodesic_distance(i, j) {
    h moduli = _prom_geodesic_moduli();
    h k = 0;
    h total = 0.0;
    while k < arr_len(moduli) {
        h m = arr_get(moduli, k);
        h ri = i - (i / m) * m;
        h rj = j - (j / m) * m;
        h d_circ = _prom_circular_dist(ri, rj, m);
        # Force float division — OMC int/int truncates.
        total = total + (d_circ * 1.0) / (m * 1.0);
        k = k + 1;
    }
    return total;
}

fn prom_geodesic_bias_matrix(seq_len) {
    h table = [];
    h i = 0;
    h offdiag_sum = 0.0;
    h offdiag_count = 0;
    while i < seq_len {
        h row = [];
        h j = 0;
        while j < seq_len {
            h d = prom_geodesic_distance(i, j);
            arr_push(row, d);
            if i != j {
                offdiag_sum = offdiag_sum + d;
                offdiag_count = offdiag_count + 1;
            }
            j = j + 1;
        }
        arr_push(table, row);
        i = i + 1;
    }
    h mean_off = 1.0;
    if offdiag_count > 0 {
        mean_off = offdiag_sum / offdiag_count;
    }
    # Normalize.
    h normed = [];
    i = 0;
    while i < seq_len {
        h row = arr_get(table, i);
        h nr = [];
        h j = 0;
        while j < seq_len {
            arr_push(nr, arr_get(row, j) / mean_off);
            j = j + 1;
        }
        arr_push(normed, nr);
        i = i + 1;
    }
    return normed;
}

fn _prom_grad_magnitude(g) {
    if type_of(g) == "array" {
        h total = 0.0;
        h i = 0;
        while i < arr_len(g) {
            h v = arr_get(g, i);
            if type_of(v) == "array" {
                h j = 0;
                while j < arr_len(v) {
                    h e = arr_get(v, j);
                    if e < 0.0 { e = 0.0 - e; }
                    total = total + e;
                    j = j + 1;
                }
            } else {
                if v < 0.0 { v = 0.0 - v; }
                total = total + v;
            }
            i = i + 1;
        }
        return total;
    }
    if g < 0.0 { g = 0.0 - g; }
    return g;
}

fn _prom_harmonic_scale(grad_mag, alpha) {
    # Quantize: round to nearest int, abs.
    h gnorm = grad_mag * 1000.0;     # scale up so attractor table reaches
    if gnorm < 0.0 { gnorm = 0.0 - gnorm; }
    h gi = gnorm + 0.5;
    h gint = gi - (gi - (gi / 1) * 1);   # truncate to int (gi/1*1 - frac)
    # Use the existing attractor_distance builtin.
    h dist = attractor_distance(gint);
    # Smaller dist → more substrate-coherent → boost.
    h reso = 1.0 / (1.0 + dist / 100.0);   # reso ∈ (0, 1]
    return 1.0 + alpha * (reso - 0.5);
}

