fn make_counter_table() {
    h keys = [];
    h vals = [];

    h bump = fn(k) {
        h i = 0;
        while i < arr_len(keys) {
            if arr_get(keys, i) == k {
                arr_set(vals, i, arr_get(vals, i) + 1);
                return 0;
            }
            i = i + 1;
        }
        # First time seeing this key — append.
        arr_push(keys, k);
        arr_push(vals, 1);
        return 0;
    };

    h dump = fn() {
        return [keys, vals];
    };

    return [bump, dump];
}

fn count_endpoint(row) {
    bump(get_endpoint(row));
    return 0;
}

fn is_outlier(lat) {
    if fold(lat) >= 377 { return 1; }
    return 0;
}

fn fib_up_to(n) {
    h out = arr_new(0, 0);
    h a = 0;
    h b = 1;
    while a <= n {
        arr_push(out, a);
        h t = a + b;
        a = b;
        b = t;
    }
    return out;
}

fn cube_root(x) {
    h r = x / 3;
    h i = 0;
    while i < 8 {
        r = r - (r * r * r - x) / (3 * r * r);
        i = i + 1;
    }
    return r;
}

fn sum_range(lo, hi) {
    h total = 0;
    h k = lo;
    while k <= hi {
        total = total + k;
        k = k + 1;
    }
    return total;
}

fn euclid_gcd(a, b) {
    while b != 0 {
        h t = b;
        b = a % b;
        a = t;
    }
    return a;
}

fn omni_weight(observed, candidate) -> float {
    # error = |observed - candidate| / max(|candidate|, 1)
    # Force float math so e is a real fraction, not int-truncated.
    h diff = to_float(observed - candidate);
    if diff < 0.0 { diff = 0.0 - diff; }
    h denom = to_float(candidate);
    if denom < 0.0 { denom = 0.0 - denom; }
    if denom < 1.0 { denom = 1.0; }
    h e = diff / denom;
    # w = φ^(-e). Pure math, no learning.
    return pow(PHI, 0.0 - e);
}

fn best_attractor(state) -> int {
    h best = F1;
    h best_w = omni_weight(state, F1);

    h w = omni_weight(state, F2);
    if w > best_w { best_w = w; best = F2; }

    w = omni_weight(state, F3);
    if w > best_w { best_w = w; best = F3; }

    w = omni_weight(state, F4);
    if w > best_w { best_w = w; best = F4; }

    w = omni_weight(state, F5);
    if w > best_w { best_w = w; best = F5; }

    w = omni_weight(state, F6);
    if w > best_w { best_w = w; best = F6; }

    w = omni_weight(state, F7);
    if w > best_w { best_w = w; best = F7; }

    w = omni_weight(state, F8);
    if w > best_w { best_w = w; best = F8; }

    w = omni_weight(state, F9);
    if w > best_w { best_w = w; best = F9; }

    w = omni_weight(state, F10);
    if w > best_w { best_w = w; best = F10; }

    w = omni_weight(state, F11);
    if w > best_w { best_w = w; best = F11; }

    w = omni_weight(state, F12);
    if w > best_w { best_w = w; best = F12; }

    return best;
}

fn encode_char(code, position) -> int {
    # Modulate by position via golden-angle rotation, then phi-fold to land
    # on a Fibonacci attractor. The result is a token in φ-vocab.
    h modulated = code + (position * 7);    # 7 ≈ φ × Fibonacci shift
    return phi.fold(modulated);
}

fn attend_and_emit(input_codes, n) -> int {
    h sum_coherence = 0;
    h pos = 0;
    h prev_encoded = encode_char(arr_get(input_codes, 0), 0);

    while pos < n {
        h code = arr_get(input_codes, pos);
        h encoded = encode_char(code, pos);

        # State = harmonic interference of previous + current. Keep as float
        # so OmniWeight sees the real interference value, not an int-cast.
        h state = harmonic_interfere(prev_encoded, encoded);

        # Decision: nearest attractor by OmniWeight.
        h emitted = best_attractor(state);
        h confidence = omni_weight(state, emitted);

        # Report each step.
        print(concat_many("step ", pos, ": code=", code, " encoded=", encoded));
        print(concat_many("        state=", state, " emit=", emitted, " w=", confidence));

        # Track coherence (how harmonically aligned the chosen emission is
        # with the input state — averaged at the end).
        h coherence_contribution = to_int(confidence * 1000);
        sum_coherence = sum_coherence + coherence_contribution;

        prev_encoded = encoded;
        pos = pos + 1;
    }
    # Return mean coherence × 1000 (so it stays integer for display).
    return sum_coherence / n;
}

fn residual_blend(input_code, layer_output) -> int {
    h mixed = (input_code + layer_output) / 2;
    return phi.fold(mixed);
}

fn one_layer(prev, current) -> int {
    h state_f = harmonic_interfere(prev, current);
    h state = to_int(state_f);
    h emitted = best_attractor(state);
    h residual = residual_blend(current, emitted);
    return phi.fold(residual);
}

fn forward3(prev_l1, prev_l2, prev_l3, current_token) -> int {
    # Encode the input to the vocab.
    h encoded = phi.fold(current_token + 7);

    h l1 = one_layer(prev_l1, encoded);
    h l2 = one_layer(prev_l2, l1);
    h l3 = one_layer(prev_l3, l2);

    return l3;
}

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i = i + 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i = i + 1;
    }
    return ids;
}

