fn l1_diff(a, b, n) {
    h s = 0.0;
    h i = 0;
    while i < n {
        h ra = arr_get(a, i);
        h rb = arr_get(b, i);
        h j = 0;
        while j < n {
            h diff = arr_get(ra, j) - arr_get(rb, j);
            if diff < 0.0 { diff = 0.0 - diff; }
            s = s + diff;
            j = j + 1;
        }
        i = i + 1;
    }
    return s;
}

fn attn_forward_with_grad_mod(layer, x_id, gm_scale, gm_alpha, use_q6) {
    h Q_w = dict_get(layer, "Q");
    h V_w = dict_get(layer, "V");
    h K_const = dict_get(layer, "K_const");
    h smod_alpha = dict_get(layer, "smod_alpha");
    h v_scale = dict_get(layer, "v_resample_scale");
    if v_scale == null { v_scale = 0.0; }

    # Wrap Q and V param tape nodes — biases backward flow into them.
    h Q_mod = tape_substrate_grad_mod(Q_w, gm_scale, gm_alpha);
    h V_mod = tape_substrate_grad_mod(V_w, gm_scale, gm_alpha);

    h q = tape_matmul(x_id, Q_mod);
    h q_mod = q;
    if use_q6 {
        q_mod = prom_q6_modulate(q, 10.0, 0.5, "fused");
    }
    h v_raw = tape_matmul(x_id, V_mod);
    h v = prom_substrate_resample(v_raw, v_scale);

    h k = tape_const(K_const);
    h kt = tape_transpose(k);
    h scores = tape_matmul(q_mod, kt);
    h attn = prom_substrate_softmax(scores, smod_alpha);
    return tape_matmul(attn, v);
}

fn snap_all_params(params, scale) {
    if scale == 0.0 { return; }
    h i = 0;
    while i < arr_len(params) {
        h node = arr_get(params, i);
        h v = tape_value(node);
        # tape_value may return scalar (1x1) or 1D row; substrate_snap_matrix
        # only handles arrays, so guard.
        if dict_has(_value_type_dispatch(v), "ok") {
            h snapped = substrate_snap_matrix(v, scale);
            tape_set_value(node, snapped);
        }
        i = i + 1;
    }
}

fn _value_type_dispatch(v) {
    h out = dict_new();
    # Try arr_len; if v is a float/int we'd error. OMC has no try/catch,
    # so check by attempted indirection — instead just use a sentinel
    # approach: bias matrices are 1D arrays, Q/V/W are 2D, both work
    # with substrate_snap_matrix. Always return ok; if v is scalar the
    # builtin's error message is the bug we'll see in practice.
    dict_set(out, "ok", 1);
    return out;
}

fn model_params(model) {
    return prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);
}

fn add_pe(x_id, pe_row) {
    h pe = tape_const([pe_row]);
    return tape_add(x_id, pe);
}

fn build_transformer(vocab_size, d_model, ff_dim, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s1);
    h ff_up = prom_linear_new(d_model, ff_dim, s1 + 17);
    h s2 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s2);
    h s3 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s3);
    h head = prom_linear_new(d_model, vocab_size, s3 + 23);

    h m = dict_new();
    dict_set(m, "emb", emb);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn load_ratings(path) {
    h raw = read_file(path);
    h lines = str_split(raw, "\n");
    h out = [];
    h i = 1;   # skip header
    while i < arr_len(lines) {
        h ln = arr_get(lines, i);
        if str_len(ln) > 0 {
            h parts = str_split(ln, ",");
            if arr_len(parts) >= 4 {
                arr_push(out, [
                    to_int(arr_get(parts, 0)),
                    to_int(arr_get(parts, 1)),
                    to_float(arr_get(parts, 2)),
                    to_int(arr_get(parts, 3))
                ]);
            }
        }
        i = i + 1;
    }
    return out;
}

fn aggregate_by_movie(ratings) {
    h agg = {};
    h i = 0;
    while i < arr_len(ratings) {
        h row = arr_get(ratings, i);
        h movie = arr_get(row, 1);
        h rating = arr_get(row, 2);
        h k = concat_many("", movie);
        h cur = dict_get(agg, k, [0, 0.0]);
        dict_set(agg, k, [
            arr_get(cur, 0) + 1,
            arr_get(cur, 1) + rating
        ]);
        i = i + 1;
    }
    return agg;
}

fn agg_to_rows(agg) {
    h ks = dict_keys(agg);
    h rows = [];
    h i = 0;
    while i < arr_len(ks) {
        h k = arr_get(ks, i);
        h pair = dict_get(agg, k);
        h cnt = arr_get(pair, 0);
        h sum = arr_get(pair, 1);
        h avg = sum / cnt;
        arr_push(rows, [to_int(k), cnt, avg]);
        i = i + 1;
    }
    return rows;
}

fn build_harmonic_engine(movie_rows) {
    h idx = hidx_new();
    h i = 0;
    while i < arr_len(movie_rows) {
        h row = arr_get(movie_rows, i);
        h avg = arr_get(row, 2);
        h key = to_int(avg * 100);
        idx = hidx_insert(idx, key, row);
        i = i + 1;
    }
    return idx;
}

fn linear_recommend(movie_rows, target_rating, delta) {
    h hits = [];
    h i = 0;
    while i < arr_len(movie_rows) {
        h row = arr_get(movie_rows, i);
        h avg = arr_get(row, 2);
        h diff = avg - target_rating;
        if diff < 0 { diff = 0 - diff; }
        if diff <= delta {
            arr_push(hits, row);
        }
        i = i + 1;
    }
    return hits;
}

fn harmonic_recommend(idx, target_rating) {
    h key = to_int(target_rating * 100);
    h pairs = hidx_lookup(idx, key);
    h rows = [];
    h i = 0;
    while i < arr_len(pairs) {
        arr_push(rows, arr_get(arr_get(pairs, i), 1));
        i = i + 1;
    }
    return rows;
}

