    h t3 = now_ms();
    println(concat_many("  aggregate:       ", t3 - t2, " ms  (",
        dict_len(agg), " unique movies)"));

    h t4 = now_ms();
    h rows = agg_to_rows(agg);
    h t5 = now_ms();
    println(concat_many("  agg_to_rows:     ", t5 - t4, " ms"));

    h t6 = now_ms();
    h hidx = build_harmonic_engine(rows);
    h t7 = now_ms();
    println(concat_many("  build_hidx:      ", t7 - t6,
        " ms  (", hidx_size(hidx), " entries, ", dict_len(hidx),
        " attractor buckets)"));

    # Query both engines for "movies near rating 4.0"
    h target = 4.0;
    h delta = 0.1;

    h t8 = now_ms();
    h linear_hits = linear_recommend(rows, target, delta);
    h t9 = now_ms();
    println(concat_many("  linear  (R≈", target, " ±", delta, "):  ",
        t9 - t8, " ms  (", arr_len(linear_hits), " hits)"));

    h t10 = now_ms();
    h harmonic_hits = harmonic_recommend(hidx, target);
    h t11 = now_ms();
    println(concat_many("  harmonic (R≈", target, " by attractor):  ",
        t11 - t10, " ms  (", arr_len(harmonic_hits), " hits)"));

    # Show a sample hit so we can sanity-check
    if arr_len(harmonic_hits) > 0 {
        h sample = arr_get(harmonic_hits, 0);
        println(concat_many("  sample hit:  movie_id=", arr_get(sample, 0),
            " count=", arr_get(sample, 1), " avg=", arr_get(sample, 2)));
    }
}

fn is_digit_b(c) {
    return str_contains("0123456789", c);
}

fn is_alpha_b(c) {
    if str_contains("abcdefghijklmnopqrstuvwxyz", c) == 1 { return 1; }
    if str_contains("ABCDEFGHIJKLMNOPQRSTUVWXYZ", c) == 1 { return 1; }
    if c == "_" { return 1; }
    return 0;
}

fn is_alnum_b(c) {
    if is_alpha_b(c) == 1 { return 1; }
    if is_digit_b(c) == 1 { return 1; }
    return 0;
}

fn is_space_b(c) {
    if c == " "  { return 1; }
    if c == "\n" { return 1; }
    if c == "\t" { return 1; }
    if c == "\r" { return 1; }
    return 0;
}

fn skip_ws_b(source, pos) {
    h n = str_chars(source);
    h p = pos;
    h moved = 1;
    # V.8b: loop until neither whitespace nor a `#`-comment advances `p`.
    while moved == 1 {
        moved = 0;
        # whitespace
        while p < n {
            h c = str_slice(source, p, p + 1);
            if is_space_b(c) == 1 {
                p = p + 1;
                moved = 1;
            } else { break; }
        }
        # line comment
        if p < n {
            h c2 = str_slice(source, p, p + 1);
            if c2 == "#" {
                while p < n {
                    h cc = str_slice(source, p, p + 1);
                    if cc == "\n" { break; }
                    p = p + 1;
                }
                moved = 1;
            }
        }
    }
    return p;
}

fn classify_b(word) -> string {
    if word == "h"      { return "H"; }
    if word == "if"     { return "IF"; }
    if word == "else"   { return "ELSE"; }
    if word == "while"  { return "WHILE"; }
    if word == "print"  { return "PRINT"; }
    if word == "fn"     { return "FN"; }
    if word == "return" { return "RETURN"; }
    if word == "break"  { return "BREAK"; }
    return "IDENT";
}

fn match_multichar_b(source, pos) {
    h n = str_chars(source);
    if pos + 1 >= n { return ["", 0]; }
    h two = str_slice(source, pos, pos + 2);
    if two == "==" { return ["EQEQ", 2]; }
    if two == "!=" { return ["NE",   2]; }
    if two == "<=" { return ["LE",   2]; }
    if two == ">=" { return ["GE",   2]; }
    return ["", 0];
}

fn punct_kind_b(c) -> string {
    if c == "(" { return "LPAREN"; }
    if c == ")" { return "RPAREN"; }
    if c == "{" { return "LBRACE"; }
    if c == "}" { return "RBRACE"; }
    if c == "[" { return "LBRACKET"; }
    if c == "]" { return "RBRACKET"; }
    if c == ";" { return "SEMI"; }
    if c == "," { return "COMMA"; }
    if c == "=" { return "EQ"; }
    if c == "+" { return "PLUS"; }
    if c == "-" { return "MINUS"; }
    if c == "*" { return "STAR"; }
    if c == "/" { return "SLASH"; }
    if c == "%" { return "PERCENT"; }
    if c == "<" { return "LT"; }
    if c == ">" { return "GT"; }
    return "";
}

fn decode_escape(nx) -> string {
    if nx == "n"  { return "\n"; }
    if nx == "t"  { return "\t"; }
    if nx == "r"  { return "\r"; }
    if nx == "\"" { return "\""; }
    if nx == "\\" { return "\\"; }
    return nx;
}

fn scan_string(source, pos) {
    h n = str_chars(source);
    h end = pos + 1;
    h s = "";
    h done = 0;
    while done == 0 {
        if end >= n { done = 1; }
        if done == 0 {
            h cc = str_slice(source, end, end + 1);
            if cc == "\"" {
                end = end + 1;
                done = 1;
            } else {
                if cc == "\\" {
                    if end + 1 < n {
                        h nx = str_slice(source, end + 1, end + 2);
                        s = str_concat(s, decode_escape(nx));
                        end = end + 2;
                    } else { end = end + 1; }
                } else {
                    s = str_concat(s, cc);
                    end = end + 1;
                }
            }
        }
    }
    return [s, end];
}

fn tokenize_b(source) {
    h n = str_chars(source);
    h tokens = arr_new(0, 0);
    h pos = 0;
    while pos < n {
        pos = skip_ws_b(source, pos);
        if pos >= n { break; }
        h c = str_slice(source, pos, pos + 1);
        if c == "\"" {
            h r = scan_string(source, pos);
            arr_push(tokens, ["STRING", arr_get(r, 0)]);
            pos = arr_get(r, 1);
        } else {
            if is_alpha_b(c) == 1 {
                h end = pos;
                while end < n {
                    h cc = str_slice(source, end, end + 1);
                    if is_alnum_b(cc) == 1 { end = end + 1; } else { break; }
                }
                h word = str_slice(source, pos, end);
                arr_push(tokens, [classify_b(word), word]);
                pos = end;
            } else {
                if is_digit_b(c) == 1 {
                    h end = pos;
                    while end < n {
                        h cc = str_slice(source, end, end + 1);
                        if is_digit_b(cc) == 1 { end = end + 1; } else { break; }
                    }
                    arr_push(tokens, ["NUMBER", str_slice(source, pos, end)]);
                    pos = end;
                } else {
                    h mm = match_multichar_b(source, pos);
                    h mm_kind = arr_get(mm, 0);
                    h mm_len = arr_get(mm, 1);
                    if str_len(mm_kind) > 0 {
                        arr_push(tokens, [mm_kind, str_slice(source, pos, pos + mm_len)]);
                        pos = pos + mm_len;
                    } else {
                        h kind = punct_kind_b(c);
                        if str_len(kind) > 0 {
                            arr_push(tokens, [kind, c]);
                        } else {
                            arr_push(tokens, ["UNKNOWN", c]);
                        }
                        pos = pos + 1;
                    }
                }
            }
        }
    }
    arr_push(tokens, ["EOF", ""]);
    return tokens;
}

fn tkind(toks, p) -> string {
    h t = arr_get(toks, p);
    return arr_get(t, 0);
}

fn tval(toks, p) -> string {
    h t = arr_get(toks, p);
    return arr_get(t, 1);
}

fn p_args(toks, p) {
    h args = arr_new(0, 0);
    h np = p + 1;   # skip LPAREN
    if tkind(toks, np) == "RPAREN" {
        return [args, np + 1];
    }
    h done = 0;
    while done == 0 {
        h r = p_expr(toks, np);
        arr_push(args, arr_get(r, 0));
        np = arr_get(r, 1);
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [args, np + 1];
}

fn p_array_lit(toks, p) {
    # called with p pointing at LBRACKET
    h elems = arr_new(0, 0);
    h np = p + 1;
    if tkind(toks, np) == "RBRACKET" {
        return [["ARR", elems], np + 1];
    }
    h done = 0;
    while done == 0 {
        h r = p_expr(toks, np);
        arr_push(elems, arr_get(r, 0));
        np = arr_get(r, 1);
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [["ARR", elems], np + 1];   # consume RBRACKET
}

fn p_primary(toks, p) {
    h k = tkind(toks, p);
    if k == "NUMBER"   { return [["NUM", tval(toks, p)], p + 1]; }
    if k == "STRING"   { return [["STR", tval(toks, p)], p + 1]; }
    if k == "LBRACKET" { return p_array_lit(toks, p); }
    if k == "IDENT"  {
        if tkind(toks, p + 1) == "LPAREN" {
            h name = tval(toks, p);
            h r = p_args(toks, p + 1);
            return [["CALL", name, arr_get(r, 0)], arr_get(r, 1)];
        }
        return [["VAR", tval(toks, p)], p + 1];
    }
    if k == "LPAREN" {
        h r = p_expr(toks, p + 1);
        return [arr_get(r, 0), arr_get(r, 1) + 1];
    }
    return [["ERR", k], p + 1];
}

fn p_mul(toks, p) {
    h r = p_primary(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        if k == "STAR" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "*", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "SLASH" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "/", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "PERCENT" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "%", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }}}
    }
    return [left, np];
}

fn p_add(toks, p) {
    h r = p_mul(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        if k == "PLUS" {
            h r2 = p_mul(toks, np + 1);
            left = ["BIN", "+", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "MINUS" {
            h r2 = p_mul(toks, np + 1);
            left = ["BIN", "-", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }}
    }
    return [left, np];
}

fn p_cmp(toks, p) {
    h r = p_add(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        h op = "";
        if k == "EQEQ" { op = "=="; }
        if k == "NE"   { op = "!="; }
        if k == "LT"   { op = "<"; }
        if k == "LE"   { op = "<="; }
        if k == "GT"   { op = ">"; }
        if k == "GE"   { op = ">="; }
        if str_len(op) > 0 {
            h r2 = p_add(toks, np + 1);
            left = ["BIN", op, left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }
    }
    return [left, np];
}

fn p_expr(toks, p) {
    return p_cmp(toks, p);
}

fn p_params(toks, p) {
    h params = arr_new(0, 0);
    h np = p + 1;
    if tkind(toks, np) == "RPAREN" {
        return [params, np + 1];
    }
    h done = 0;
    while done == 0 {
        arr_push(params, tval(toks, np));
        np = np + 1;
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [params, np + 1];
}

fn p_stmt(toks, p) {
    h k = tkind(toks, p);
    if k == "H" {
        h name = tval(toks, p + 1);
        h r = p_expr(toks, p + 3);
        h np = arr_get(r, 1) + 1;
        return [["DECL", name, arr_get(r, 0)], np];
    }
    if k == "PRINT" {
        h r = p_expr(toks, p + 2);
        h np = arr_get(r, 1) + 1 + 1;
        return [["PRT", arr_get(r, 0)], np];
    }
    if k == "WHILE" {
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        h body_r = p_block(toks, np);
        return [["WHL", arr_get(r, 0), arr_get(body_r, 0)], arr_get(body_r, 1)];
    }
    if k == "IF" {
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        h then_r = p_block(toks, np);
        np = arr_get(then_r, 1);
        h else_body = arr_new(0, 0);
        if tkind(toks, np) == "ELSE" {
            np = np + 2;
            h eb = p_block(toks, np);
            else_body = arr_get(eb, 0);
            np = arr_get(eb, 1);
        }
        return [["IF", arr_get(r, 0), arr_get(then_r, 0), else_body], np];
    }
    if k == "FN" {
        h name = tval(toks, p + 1);
        h params_r = p_params(toks, p + 2);
        h params = arr_get(params_r, 0);
        h np = arr_get(params_r, 1);
        # V.8b: optional `-> IDENT` return-type annotation. Tokens are
        # MINUS GT IDENT. Annotation is documentation only — no runtime
        # effect — so we just skip past it.
        if tkind(toks, np) == "MINUS" {
            if tkind(toks, np + 1) == "GT" {
                np = np + 3;
            }
        }
        np = np + 1;   # consume LBRACE
        h body_r = p_block(toks, np);
        return [["FN", name, params, arr_get(body_r, 0)], arr_get(body_r, 1)];
    }
    if k == "RETURN" {
        if tkind(toks, p + 1) == "SEMI" {
            return [["RET", ["NULL"]], p + 2];
        }
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        return [["RET", arr_get(r, 0)], np];
    }
    if k == "BREAK" {
        # `break ;` — consumes BREAK and SEMI.
        return [["BREAK"], p + 2];
    }
    if k == "IDENT" {
        h k1 = tkind(toks, p + 1);
        if k1 == "EQ" {
            h name = tval(toks, p);
            h r = p_expr(toks, p + 2);
            h np = arr_get(r, 1) + 1;
            return [["ASN", name, arr_get(r, 0)], np];
        }
        if k1 == "LPAREN" {
            h r = p_expr(toks, p);
            h np = arr_get(r, 1) + 1;
            return [["EXPR", arr_get(r, 0)], np];
        }
    }
    print(concat_many("p_stmt: don't know how to handle kind=", k));
    return [["ERR", k], p + 1];
}

fn p_block(toks, p) {
    h body = arr_new(0, 0);
    h np = p;
    h done = 0;
    while done == 0 {
        h k = tkind(toks, np);
        if k == "RBRACE" {
            np = np + 1;
            done = 1;
        } else {
            if k == "EOF" {
                done = 1;
            } else {
                h r = p_stmt(toks, np);
                arr_push(body, arr_get(r, 0));
                np = arr_get(r, 1);
            }
        }
    }
    return [body, np];
}

fn p_program(toks) {
    h stmts = arr_new(0, 0);
    h pos = 0;
    h done = 0;
    while done == 0 {
        if tkind(toks, pos) == "EOF" {
            done = 1;
        } else {
            h r = p_stmt(toks, pos);
            arr_push(stmts, arr_get(r, 0));
            pos = arr_get(r, 1);
        }
    }
    return stmts;
}

fn arr_concat(a, b) {
    h i = 0;
    h n = arr_len(b);
    while i < n {
        arr_push(a, arr_get(b, i));
        i = i + 1;
    }
    return a;
}

fn is_builtin(name) {
    if name == "arr_new"      { return 1; }
    if name == "arr_get"      { return 1; }
    if name == "arr_len"      { return 1; }
    if name == "str_len"      { return 1; }
    if name == "str_chars"    { return 1; }
    if name == "str_slice"    { return 1; }
    if name == "str_contains" { return 1; }
    if name == "str_concat"   { return 1; }
    if name == "concat_many"  { return 1; }
    if name == "to_int"       { return 1; }
    if name == "to_string"    { return 1; }
    return 0;
}

fn enc_expr(ast) {
    h out = arr_new(0, 0);
    h tag = arr_get(ast, 0);
    if tag == "NUM" {
        arr_push(out, ["LOAD_INT", arr_get(ast, 1)]);
        return out;
    }
    if tag == "STR" {
        arr_push(out, ["LOAD_STR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "VAR" {
        arr_push(out, ["LOAD_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "ARR" {
        h elems = arr_get(ast, 1);
        h i = 0;
        h n = arr_len(elems);
        while i < n {
            out = arr_concat(out, enc_expr(arr_get(elems, i)));
            i = i + 1;
        }
        arr_push(out, ["MAKE_ARR", n]);
        return out;
    }
    if tag == "BIN" {
        h op = arr_get(ast, 1);
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        out = arr_concat(out, enc_expr(arr_get(ast, 3)));
        if op == "+"  { arr_push(out, ["ADD"]); return out; }
        if op == "-"  { arr_push(out, ["SUB"]); return out; }
        if op == "*"  { arr_push(out, ["MUL"]); return out; }
        if op == "/"  { arr_push(out, ["DIV"]); return out; }
        if op == "%"  { arr_push(out, ["MOD"]); return out; }
        if op == "==" { arr_push(out, ["EQ"]);  return out; }
        if op == "!=" { arr_push(out, ["NE"]);  return out; }
        if op == "<"  { arr_push(out, ["LT"]);  return out; }
        if op == "<=" { arr_push(out, ["LE"]);  return out; }
        if op == ">"  { arr_push(out, ["GT"]);  return out; }
        if op == ">=" { arr_push(out, ["GE"]);  return out; }
        return out;
    }
    if tag == "CALL" {
        h name = arr_get(ast, 1);
        h args = arr_get(ast, 2);
        # Specialised named-mutation forms — only when the first arg is a
        # bare variable. Anything fancier (e.g. arr_push(arr_get(x,0), v))
        # falls through to CALL_BUILTIN and loses the mutation, same as a
        # tree-walk caller would.
        if name == "arr_push" {
            if arr_len(args) == 2 {
                h target = arr_get(args, 0);
                if arr_get(target, 0) == "VAR" {
                    out = arr_concat(out, enc_expr(arr_get(args, 1)));
                    arr_push(out, ["ARR_PUSH_NAMED", arr_get(target, 1)]);
                    return out;
                }
            }
        }
        if name == "arr_set" {
            if arr_len(args) == 3 {
                h target = arr_get(args, 0);
                if arr_get(target, 0) == "VAR" {
                    out = arr_concat(out, enc_expr(arr_get(args, 1)));   # idx
                    out = arr_concat(out, enc_expr(arr_get(args, 2)));   # value
                    arr_push(out, ["ARR_SET_NAMED", arr_get(target, 1)]);
                    return out;
                }
            }
        }
        h i = 0;
        h n = arr_len(args);
        while i < n {
            out = arr_concat(out, enc_expr(arr_get(args, i)));
            i = i + 1;
        }
        if is_builtin(name) == 1 {
            arr_push(out, ["CALL_BUILTIN", name, n]);
        } else {
            arr_push(out, ["CALL", name, n]);
        }
        return out;
    }
    arr_push(out, ["UNKNOWN_EXPR", tag]);
    return out;
}

fn enc_stmt(ast) {
    h out = arr_new(0, 0);
    h tag = arr_get(ast, 0);
    if tag == "DECL" {
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        arr_push(out, ["STORE_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "ASN" {
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        arr_push(out, ["STORE_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "PRT" {
        out = arr_concat(out, enc_expr(arr_get(ast, 1)));
        arr_push(out, ["PRINT"]);
        return out;
    }
    if tag == "EXPR" {
        out = arr_concat(out, enc_expr(arr_get(ast, 1)));
        arr_push(out, ["POP"]);
        return out;
    }
    if tag == "RET" {
        h e = arr_get(ast, 1);
        if arr_get(e, 0) == "NULL" {
            arr_push(out, ["LOAD_INT", "0"]);
        } else {
            out = arr_concat(out, enc_expr(e));
        }
        arr_push(out, ["RETURN"]);
        return out;
    }
    if tag == "BREAK" {
        # V.8b: placeholder; the enclosing WHL encoder patches the delta
        # to land just after the trailing back-jump. A loose JUMP_BREAK
        # (break outside any while) would never get patched and trigger
        # an "unknown opcode" at runtime — same as tree-walk would error.
        arr_push(out, ["JUMP_BREAK", 0]);
        return out;
    }
    if tag == "WHL" {
        h cond_ops = enc_expr(arr_get(ast, 1));
        h body_ops = enc_block(arr_get(ast, 2));
        h c_len = arr_len(cond_ops);
        h b_len = arr_len(body_ops);
        # V.8b: patch any JUMP_BREAK placeholders inside body_ops. A break
        # at position k inside body_ops should jump to immediately AFTER
        # the trailing back-jump — which is at the end of the assembled
        # while block. Layout:
        #
        #   [cond ops]            length c_len, indices 0..c_len-1
        #   JUMP_IF_FALSE         index c_len
        #   [body ops]            length b_len, indices c_len+1..c_len+b_len
        #   JUMP back             index c_len + b_len + 1
        #   <-- break target -->  index c_len + b_len + 2
        #
        # A JUMP_BREAK at body_ops index k sits at absolute index c_len+1+k.
        # Its target is c_len+b_len+2, so delta = b_len + 1 - k.
        # Relative jumps survive concatenation, so we patch body_ops in place.
        h k = 0;
        while k < b_len {
            h opk = arr_get(body_ops, k);
            if arr_get(opk, 0) == "JUMP_BREAK" {
                arr_set(body_ops, k, ["JUMP", b_len + 1 - k]);
            }
            k = k + 1;
        }
        out = arr_concat(out, cond_ops);
        arr_push(out, ["JUMP_IF_FALSE", b_len + 2]);
        out = arr_concat(out, body_ops);
        arr_push(out, ["JUMP", 0 - (c_len + b_len + 1)]);
        return out;
    }
    if tag == "IF" {
        h cond_ops = enc_expr(arr_get(ast, 1));
        h then_ops = enc_block(arr_get(ast, 2));
        h else_body = arr_get(ast, 3);
        h has_else = 0;
        if arr_len(else_body) > 0 { has_else = 1; }
        out = arr_concat(out, cond_ops);
        if has_else == 1 {
            h else_ops = enc_block(else_body);
            h t_len = arr_len(then_ops);
            h e_len = arr_len(else_ops);
            arr_push(out, ["JUMP_IF_FALSE", t_len + 2]);
            out = arr_concat(out, then_ops);
            arr_push(out, ["JUMP", e_len + 1]);
            out = arr_concat(out, else_ops);
        } else {
            h t_len = arr_len(then_ops);
            arr_push(out, ["JUMP_IF_FALSE", t_len + 1]);
            out = arr_concat(out, then_ops);
        }
        return out;
    }
    if tag == "FN" {
        h name = arr_get(ast, 1);
        h params = arr_get(ast, 2);
        h body = arr_get(ast, 3);
        h body_ops = enc_block(body);
        arr_push(body_ops, ["LOAD_INT", "0"]);
        arr_push(body_ops, ["RETURN"]);
        h b_len = arr_len(body_ops);
        arr_push(out, ["DEF_FN", name, b_len, params]);
        out = arr_concat(out, body_ops);
        return out;
    }
    arr_push(out, ["UNKNOWN_STMT", tag]);
    return out;
}

fn enc_block(stmts) {
    h out = arr_new(0, 0);
    h i = 0;
    h n = arr_len(stmts);
    while i < n {
        out = arr_concat(out, enc_stmt(arr_get(stmts, i)));
        i = i + 1;
    }
    return out;
}

fn encode_program(stmts) {
    h out = enc_block(stmts);
    arr_push(out, ["HALT"]);
    return out;
}

fn print_bytecode(prog) {
    h i = 0;
    h n = arr_len(prog);
    while i < n {
        h op = arr_get(prog, i);
        h kind = arr_get(op, 0);
        h line = concat_many("  ", i, ": ", kind);
        h ol = arr_len(op);
        if kind == "LOAD_STR" {
            line = concat_many(line, " \"", arr_get(op, 1), "\"");
        } else {
            if ol >= 2 { line = concat_many(line, " ", arr_get(op, 1)); }
            if ol >= 3 { line = concat_many(line, " ", arr_get(op, 2)); }
        }
        if kind == "DEF_FN" {
            if ol >= 4 {
                line = concat_many(line, " [params=", arr_len(arr_get(op, 3)), "]");
            }
        }
        print(line);
        i = i + 1;
    }
    return 0;
}

fn scope_get(scope, name) {
    h i = 0;
    h n = arr_len(scope);
    while i < n {
        h pair = arr_get(scope, i);
        if arr_get(pair, 0) == name {
            return arr_get(pair, 1);
        }
        i = i + 1;
    }
    return 0;
}

fn scope_set(scope, name, value) {
    h i = 0;
    h n = arr_len(scope);
    while i < n {
        h pair = arr_get(scope, i);
        if arr_get(pair, 0) == name {
            arr_set(scope, i, [name, value]);
            return scope;
        }
        i = i + 1;
    }
    arr_push(scope, [name, value]);
    return scope;
}

fn parse_int(s) {
    return to_int(s);
}

fn pop1(stack) {
    h n = arr_len(stack);
    h top = arr_get(stack, n - 1);
    h ns = arr_new(0, 0);
    h i = 0;
    while i < n - 1 {
        arr_push(ns, arr_get(stack, i));
        i = i + 1;
    }
    return [top, ns];
}

fn pop_n_ordered(stack, n) {
    h reverse = arr_new(0, 0);
    h s = stack;
    h k = 0;
    while k < n {
        h pr = pop1(s);
        arr_push(reverse, arr_get(pr, 0));
        s = arr_get(pr, 1);
        k = k + 1;
    }
    h ordered = arr_new(0, 0);
    h j = n - 1;
    while j >= 0 {
        arr_push(ordered, arr_get(reverse, j));
        j = j - 1;
    }
    return [ordered, s];
}

fn call_builtin(name, args) {
    if name == "arr_new" {
        if arr_len(args) >= 2 {
            return arr_new(arr_get(args, 0), arr_get(args, 1));
        }
        return arr_new(0, 0);
    }
    if name == "arr_get" {
        return arr_get(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "arr_len" {
        return arr_len(arr_get(args, 0));
    }
    if name == "str_len" {
        return str_len(arr_get(args, 0));
    }
    if name == "str_chars" {
        return str_chars(arr_get(args, 0));
    }
    if name == "str_slice" {
        return str_slice(arr_get(args, 0), arr_get(args, 1), arr_get(args, 2));
    }
    if name == "str_contains" {
        return str_contains(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "str_concat" {
        return str_concat(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "concat_many" {
        # Use to_string per arg so ints render via Display ("42") not Debug
        # ("HInt(42, φ=…)"). Without this, bytecode-VM output for the same
        # expression diverges cosmetically from tree-walk — which broke the
        # V.7b cosmetic-only test and was the only blocker on the V.8
        # round-trip for embedded_program.
        h n = arr_len(args);
        if n == 0 { return ""; }
        h s = to_string(arr_get(args, 0));
        h i = 1;
        while i < n {
            s = str_concat(s, to_string(arr_get(args, i)));
            i = i + 1;
        }
        return s;
    }
    if name == "to_int" {
        return to_int(arr_get(args, 0));
    }
    if name == "to_string" {
        return to_string(arr_get(args, 0));
    }
    print(concat_many("call_builtin: unknown builtin ", name));
    return 0;
}

fn collect_fns(prog) {
    h table = arr_new(0, 0);
    h i = 0;
    h n = arr_len(prog);
    while i < n {
        h op = arr_get(prog, i);
        if arr_get(op, 0) == "DEF_FN" {
            h name = arr_get(op, 1);
            h params = arr_get(op, 3);
            arr_push(table, [name, i + 1, params]);
        }
        i = i + 1;
    }
    return table;
}

fn fn_lookup(table, name) {
    h i = 0;
    h n = arr_len(table);
    while i < n {
        h row = arr_get(table, i);
        if arr_get(row, 0) == name {
            return row;
        }
        i = i + 1;
    }
    return ["", 0 - 1, arr_new(0, 0)];
}

fn nearest_fib(n) {
    h fibs = fib_table();
    h abs_n = n;
    if abs_n < 0 { abs_n = 0 - abs_n; }
    h nearest = arr_get(fibs, 0);
    h min_dist = abs_n;
    h i = 0;
    while i < arr_len(fibs) {
        h f = arr_get(fibs, i);
        h d = f - abs_n;
        if d < 0 { d = 0 - d; }
        if d < min_dist {
            min_dist = d;
            nearest = f;
        }
        i = i + 1;
    }
    h result = nearest;
    if n < 0 { result = 0 - nearest; }
    if result == 0 { result = 1; }
    return result;
}

fn edit_distance(a, b) {
    h la = str_chars(a);
    h lb = str_chars(b);
    # Row of length lb+1, initialised to [0, 1, 2, ..., lb].
    h prev = arr_new(0, 0);
    h k = 0;
    while k <= lb {
        arr_push(prev, k);
        k = k + 1;
    }
    h i = 1;
    while i <= la {
        h curr = arr_new(0, 0);
        arr_push(curr, i);
        h ca = str_slice(a, i - 1, i);
        h j = 1;
        while j <= lb {
            h cb = str_slice(b, j - 1, j);
            h cost = 1;
            if ca == cb { cost = 0; }
            h del  = arr_get(prev, j) + 1;
            h ins  = arr_get(curr, j - 1) + 1;
            h subs = arr_get(prev, j - 1) + cost;
            arr_push(curr, min3(del, ins, subs));
            j = j + 1;
        }
        prev = curr;
        i = i + 1;
    }
    return arr_get(prev, lb);
}

fn names_contains(table, name) {
    h i = 0;
    while i < arr_len(table) {
        if arr_get(table, i) == name { return 1; }
        i = i + 1;
    }
    return 0;
}

fn closest_name(name, table) {
    h best = "";
    h best_d = 3;
    h i = 0;
    while i < arr_len(table) {
        h cand = arr_get(table, i);
        h d = edit_distance(name, cand);
        if d < best_d {
            best_d = d;
            best = cand;
        }
        i = i + 1;
    }
    return best;
}

fn collect_defined(stmts) {
    h names = arr_new(0, 0);
    # Built-ins are always in scope.
    arr_push(names, "print");
    arr_push(names, "arr_new");
    arr_push(names, "arr_get");
    arr_push(names, "arr_set");
    arr_push(names, "arr_push");
    arr_push(names, "arr_len");
    arr_push(names, "str_len");
    arr_push(names, "str_chars");
    arr_push(names, "str_slice");
    arr_push(names, "str_concat");
    arr_push(names, "str_contains");
    arr_push(names, "concat_many");
    arr_push(names, "to_int");
    arr_push(names, "to_string");
    arr_push(names, "harmony_value");
    arr_push(names, "fold_escape");
    arr_push(names, "value_danger");
    h i = 0;
    while i < arr_len(stmts) {
        h s = arr_get(stmts, i);
        h tag = arr_get(s, 0);
        if tag == "FN"   { arr_push(names, arr_get(s, 1)); }
        if tag == "DECL" { arr_push(names, arr_get(s, 1)); }
        i = i + 1;
    }
    return names;
}

fn heal_expr(ast, names, diags) {
    h tag = arr_get(ast, 0);
    if tag == "NUM" {
        h raw = arr_get(ast, 1);
        h n = to_int(raw);
        # Two-stage check:
        #   (a) is_fibonacci(n) == 1 → already on the φ-geodesic, ignore.
        #   (b) else, compute nearest Fibonacci and the distance. If the
        #       distance is small (≤ 3), this is a close-miss typo —
        #       flag it. If the distance is large, the value is probably
        #       intentional and not a typo, so leave it.
        #
        # harmony_value's gradient is too gentle to distinguish 144 from
        # 145 alone (0.99 vs 1.00). Pairing is_fibonacci with a hard
        # proximity threshold catches off-by-one / transposition typos
        # without flagging arbitrary off-Fibonacci constants.
        if is_fibonacci(n) == 0 {
            h suggest = nearest_fib(n);
            h delta = suggest - n;
            if delta < 0 { delta = 0 - delta; }
            if delta <= 3 {
                h score = harmony_value(n);
                h sscore = harmony_value(suggest);
                arr_push(diags, concat_many(
                    "  harmonic: ", n, " (harmony ", score,
                    ", not Fibonacci) → ", suggest,
                    " (harmony ", sscore, ", Fibonacci attractor; |Δ|=",
                    delta, ")"));
                return [["NUM", to_string(suggest)], diags];
            }
        }
        return [ast, diags];
    }
    if tag == "VAR" {
        h name = arr_get(ast, 1);
        if names_contains(names, name) == 1 {
            return [ast, diags];
        }
        h sugg = closest_name(name, names);
        if str_chars(sugg) > 0 {
            h d = edit_distance(name, sugg);
            arr_push(diags, concat_many(
                "  identifier: '", name, "' unknown → '", sugg,
                "' (edit distance ", d, ")"));
            return [["VAR", sugg], diags];
        }
        return [ast, diags];
    }
    if tag == "STR" { return [ast, diags]; }
    if tag == "ARR" {
        h elems = arr_get(ast, 1);
        h new_elems = arr_new(0, 0);
        h i = 0;
        while i < arr_len(elems) {
            h r = heal_expr(arr_get(elems, i), names, diags);
            arr_push(new_elems, arr_get(r, 0));
            diags = arr_get(r, 1);
            i = i + 1;
        }
        return [["ARR", new_elems], diags];
    }
    if tag == "BIN" {
        h op = arr_get(ast, 1);
        h r1 = heal_expr(arr_get(ast, 2), names, diags);
        h left = arr_get(r1, 0);
        diags = arr_get(r1, 1);
        h r2 = heal_expr(arr_get(ast, 3), names, diags);
        h right = arr_get(r2, 0);
        diags = arr_get(r2, 1);
        return [["BIN", op, left, right], diags];
    }
    if tag == "CALL" {
        h name = arr_get(ast, 1);
        h args = arr_get(ast, 2);
        h fixed_name = name;
        if names_contains(names, name) == 0 {
            h sugg = closest_name(name, names);
            if str_chars(sugg) > 0 {
                h d = edit_distance(name, sugg);
                arr_push(diags, concat_many(
                    "  call: '", name, "(...)' unknown → '", sugg,
                    "(...)' (edit distance ", d, ")"));
                fixed_name = sugg;
            }
        }
        h new_args = arr_new(0, 0);
        h i = 0;
        while i < arr_len(args) {
            h r = heal_expr(arr_get(args, i), names, diags);
            arr_push(new_args, arr_get(r, 0));
            diags = arr_get(r, 1);
            i = i + 1;
        }
        return [["CALL", fixed_name, new_args], diags];
    }
    return [ast, diags];
}

fn heal_stmt(ast, names, diags) {
    h tag = arr_get(ast, 0);
    if tag == "DECL" {
        h r = heal_expr(arr_get(ast, 2), names, diags);
        return [["DECL", arr_get(ast, 1), arr_get(r, 0)], arr_get(r, 1)];
    }
    if tag == "ASN" {
        h r = heal_expr(arr_get(ast, 2), names, diags);
        return [["ASN", arr_get(ast, 1), arr_get(r, 0)], arr_get(r, 1)];
    }
    if tag == "PRT" {
        h r = heal_expr(arr_get(ast, 1), names, diags);
        return [["PRT", arr_get(r, 0)], arr_get(r, 1)];
    }
    if tag == "EXPR" {
        h r = heal_expr(arr_get(ast, 1), names, diags);
        return [["EXPR", arr_get(r, 0)], arr_get(r, 1)];
    }
    if tag == "RET" {
        h e = arr_get(ast, 1);
        if arr_get(e, 0) == "NULL" {
            return [ast, diags];
        }
        h r = heal_expr(e, names, diags);
        return [["RET", arr_get(r, 0)], arr_get(r, 1)];
    }
    if tag == "WHL" {
        h rc = heal_expr(arr_get(ast, 1), names, diags);
        diags = arr_get(rc, 1);
        h rb = heal_block(arr_get(ast, 2), names, diags);
        return [["WHL", arr_get(rc, 0), arr_get(rb, 0)], arr_get(rb, 1)];
    }
    if tag == "IF" {
        h rc = heal_expr(arr_get(ast, 1), names, diags);
        diags = arr_get(rc, 1);
        h rt = heal_block(arr_get(ast, 2), names, diags);
        diags = arr_get(rt, 1);
        h re = heal_block(arr_get(ast, 3), names, diags);
        return [["IF", arr_get(rc, 0), arr_get(rt, 0), arr_get(re, 0)],
                arr_get(re, 1)];
    }
    if tag == "FN" {
        # Extend the names table with the function's parameters for the
        # duration of the body walk.
        h params = arr_get(ast, 2);
        h local_names = arr_new(0, 0);
        h k = 0;
        while k < arr_len(names) {
            arr_push(local_names, arr_get(names, k));
            k = k + 1;
        }
        h pk = 0;
        while pk < arr_len(params) {
            arr_push(local_names, arr_get(params, pk));
            pk = pk + 1;
        }
        h rb = heal_block(arr_get(ast, 3), local_names, diags);
        return [["FN", arr_get(ast, 1), params, arr_get(rb, 0)],
                arr_get(rb, 1)];
    }
    if tag == "BREAK" { return [ast, diags]; }
    return [ast, diags];
}

fn heal_block(stmts, names, diags) {
    h out = arr_new(0, 0);
    # Inside a block, DECLs of new vars also extend the visible names so
    # later statements can reference them without a typo flag. This is the
    # "names visible at point of use" rule, single-pass.
    h local_names = arr_new(0, 0);
    h k = 0;
    while k < arr_len(names) {
        arr_push(local_names, arr_get(names, k));
        k = k + 1;
    }
    h i = 0;
    while i < arr_len(stmts) {
        h s = arr_get(stmts, i);
        if arr_get(s, 0) == "DECL" {
            arr_push(local_names, arr_get(s, 1));
        }
        if arr_get(s, 0) == "FN" {
            arr_push(local_names, arr_get(s, 1));
        }
        h r = heal_stmt(s, local_names, diags);
        arr_push(out, arr_get(r, 0));
        diags = arr_get(r, 1);
        i = i + 1;
    }
    return [out, diags];
}

fn heal_program(stmts) {
    h names = collect_defined(stmts);
    h diags = arr_new(0, 0);
    h r = heal_block(stmts, names, diags);
    return [arr_get(r, 0), arr_get(r, 1)];
}

fn indent_of_h(level) {
    h s = "";
    h i = 0;
    while i < level {
        s = str_concat(s, "    ");
        i = i + 1;
    }
    return s;
}

fn emit_expr_h(ast) {
    h tag = arr_get(ast, 0);
    if tag == "NUM" { return arr_get(ast, 1); }
    if tag == "STR" { return concat_many("\"", arr_get(ast, 1), "\""); }
    if tag == "VAR" { return arr_get(ast, 1); }
    if tag == "BIN" {
        h op = arr_get(ast, 1);
        h left = emit_expr_h(arr_get(ast, 2));
        h right = emit_expr_h(arr_get(ast, 3));
        return concat_many("(", left, " ", op, " ", right, ")");
    }
    if tag == "CALL" {
        h name = arr_get(ast, 1);
        h args = arr_get(ast, 2);
        h out = concat_many(name, "(");
        h i = 0;
        while i < arr_len(args) {
            if i > 0 { out = str_concat(out, ", "); }
            out = str_concat(out, emit_expr_h(arr_get(args, i)));
            i = i + 1;
        }
        return str_concat(out, ")");
    }
    if tag == "ARR" {
        h elems = arr_get(ast, 1);
        h out = "[";
        h i = 0;
        while i < arr_len(elems) {
            if i > 0 { out = str_concat(out, ", "); }
            out = str_concat(out, emit_expr_h(arr_get(elems, i)));
            i = i + 1;
        }
        return str_concat(out, "]");
    }
    return concat_many("/* UNKNOWN_EXPR ", tag, " */");
}

fn emit_stmt_h(ast, level) {
    h pad = indent_of_h(level);
    h tag = arr_get(ast, 0);
    if tag == "DECL" {
        return concat_many(pad, "h ", arr_get(ast, 1), " = ",
                           emit_expr_h(arr_get(ast, 2)), ";\n");
    }
    if tag == "ASN" {
        return concat_many(pad, arr_get(ast, 1), " = ",
                           emit_expr_h(arr_get(ast, 2)), ";\n");
    }
    if tag == "PRT" {
        return concat_many(pad, "print(",
                           emit_expr_h(arr_get(ast, 1)), ");\n");
    }
    if tag == "EXPR" {
        return concat_many(pad, emit_expr_h(arr_get(ast, 1)), ";\n");
    }
    if tag == "RET" {
        h e = arr_get(ast, 1);
        if arr_get(e, 0) == "NULL" {
            return concat_many(pad, "return;\n");
        }
        return concat_many(pad, "return ", emit_expr_h(e), ";\n");
    }
    if tag == "BREAK" {
        return concat_many(pad, "break;\n");
    }
    if tag == "WHL" {
        h cond = emit_expr_h(arr_get(ast, 1));
        h body = emit_block_h(arr_get(ast, 2), level + 1);
        return concat_many(pad, "while ", cond, " {\n", body, pad, "}\n");
    }
    if tag == "IF" {
        h cond = emit_expr_h(arr_get(ast, 1));
        h then_b = emit_block_h(arr_get(ast, 2), level + 1);
        h else_body = arr_get(ast, 3);
        h out = concat_many(pad, "if ", cond, " {\n", then_b, pad, "}");
        if arr_len(else_body) > 0 {
            h eb = emit_block_h(else_body, level + 1);
            out = concat_many(out, " else {\n", eb, pad, "}");
        }
        return str_concat(out, "\n");
    }
    if tag == "FN" {
        h name = arr_get(ast, 1);
        h params = arr_get(ast, 2);
        h body = emit_block_h(arr_get(ast, 3), level + 1);
        h plist = "";
        h i = 0;
        while i < arr_len(params) {
            if i > 0 { plist = str_concat(plist, ", "); }
            plist = str_concat(plist, arr_get(params, i));
            i = i + 1;
        }
        return concat_many(pad, "fn ", name, "(", plist, ") {\n",
                           body, pad, "}\n");
    }
    return concat_many(pad, "/* UNKNOWN_STMT ", tag, " */\n");
}

fn emit_block_h(stmts, level) {
    h out = "";
    h i = 0;
    while i < arr_len(stmts) {
        out = str_concat(out, emit_stmt_h(arr_get(stmts, i), level));
        i = i + 1;
    }
    return out;
}

fn emit_source(stmts) {
    return emit_block_h(stmts, 0);
}

fn heal_until_fixpoint(stmts, max_iter) {
    h current = stmts;
    h trajectory = arr_new(0, 0);
    h prev_count = 0 - 1;
    h iter = 0;
    while iter < max_iter {
        h hr = heal_program(current);
        h healed = arr_get(hr, 0);
        h diags = arr_get(hr, 1);
        h count = arr_len(diags);
        arr_push(trajectory, concat_many(
            "  iter ", iter + 1, ": ", count, " diagnostics"));
        if count == 0 {
            return [current, trajectory, "converged", iter];
        }
        if count == prev_count {
            # Same count two iterations in a row — the healer can't make
            # further progress on what's left. Stop and surface to caller.
            return [healed, trajectory, "stuck", iter + 1];
        }
        prev_count = count;
        current = healed;
        iter = iter + 1;
    }
    return [current, trajectory, "exhausted", max_iter];
}

