fn token_count_kind(toks, kind) {
    h n = 0;
    h i = 0;
    while i < arr_len(toks) {
        if arr_get(arr_get(toks, i), 0) == kind { n = n + 1; }
        i = i + 1;
    }
    return n;
}

fn balance_closers(toks, open_kind, close_kind, close_value, label, diags) {
    h opens = token_count_kind(toks, open_kind);
    h closes = token_count_kind(toks, close_kind);
    if opens <= closes {
        return [toks, diags];
    }
    h delta = opens - closes;
    arr_push(diags, concat_many(
        "  token-balance: ", delta, " missing '", close_value,
        "' (", label, "); appending before EOF"));
    h eof_idx = arr_len(toks) - 1;
    h out = arr_new(0, 0);
    h i = 0;
    while i < eof_idx {
        arr_push(out, arr_get(toks, i));
        i = i + 1;
    }
    h k = 0;
    while k < delta {
        arr_push(out, [close_kind, close_value]);
        k = k + 1;
    }
    arr_push(out, arr_get(toks, eof_idx));
    return [out, diags];
}

fn is_expr_terminator_kind(k) {
    if k == "NUMBER"   { return 1; }
    if k == "STRING"   { return 1; }
    if k == "RPAREN"   { return 1; }
    if k == "RBRACKET" { return 1; }
    return 0;
}

fn is_stmt_starter_kind(k) {
    if k == "H"      { return 1; }
    if k == "FN"     { return 1; }
    if k == "IF"     { return 1; }
    if k == "WHILE"  { return 1; }
    if k == "RETURN" { return 1; }
    if k == "BREAK"  { return 1; }
    if k == "PRINT"  { return 1; }
    return 0;
}

fn insert_missing_semi(toks, diags) {
    h n = arr_len(toks);
    if n < 2 { return [toks, diags]; }
    h out = arr_new(0, 0);
    h inserted = 0;
    h i = 0;
    while i < n - 1 {
        h cur = arr_get(toks, i);
        h nxt = arr_get(toks, i + 1);
        arr_push(out, cur);
        h ck = arr_get(cur, 0);
        h nk = arr_get(nxt, 0);
        # Narrow rule: clear-expression-terminator followed by clear-
        # statement-starter, no intervening SEMI. Skip if next is already
        # SEMI (no insertion needed). Also fires when the next token is
        # EOF and current is an expr terminator — covers a trailing
        # statement at end-of-file with no closing semicolon.
        if nk != "SEMI" {
            if is_expr_terminator_kind(ck) == 1 {
                if is_stmt_starter_kind(nk) == 1 {
                    arr_push(out, ["SEMI", ";"]);
                    inserted = inserted + 1;
                } else {
                    if nk == "EOF" {
                        arr_push(out, ["SEMI", ";"]);
                        inserted = inserted + 1;
                    }
                }
            }
        }
        i = i + 1;
    }
    # Append the EOF (last token).
    arr_push(out, arr_get(toks, n - 1));
    if inserted > 0 {
        arr_push(diags, concat_many(
            "  token-recovery: ", inserted,
            " missing ';' inferred between statements"));
    }
    return [out, diags];
}

fn token_heal(toks) {
