# =============================================================================
# Phase H.4: `safe` keyword — runtime self-healing as user syntax
# =============================================================================
# H.1-H.3 healed STATIC bugs: harmonic violations, identifier typos,
# divide-by-singularity where the divisor is a LITERAL the healer can
# statically inspect, missing braces/parens/semicolons. All compile-time.
#
# H.4 surfaces self-healing as a USER-DECLARED RUNTIME intent. A new
# keyword `safe` wraps an expression and signals: "this expression must
# be evaluated under self-healing semantics even when the inputs are
# DYNAMIC". The compiler unconditionally rewrites `safe a / b` to
# `safe_divide(a, b)` — even when `b` is a variable whose value isn't
# known until runtime. The static healer can't fire on dynamic divisors;
# `safe` is the user's escape hatch.
#
# Why this matters: in real programs (LLM-generated, hand-written, both)
# the dangerous divisors are almost always dynamic. A static literal `0`
# is an obvious bug that any compiler flags. The hard case is `x / count`
# where `count` could be zero at runtime for inputs the author didn't
# anticipate. `safe` lets the user opt into runtime guards without
# writing the boilerplate `if b == 0 { ... } else { ... }` plumbing
# every conventional language requires.
#
# Three layers in the H arc now:
#
#   H.1/H.2/H.3 — compile-time analysis. Statically-detectable bugs.
#                 Rewrites the AST before execution.
#   H.4        — user-declared runtime intent. Expressions the USER
#                 marks as needing self-healing at evaluation time.
#                 The compiler converts the syntax to ONN primitives.
#
# The full Phase H pipeline:
#
#   source → tokenize_b → token_heal (H.3)
#                            ↓
#                        p_program (parses `safe` prefix into SAFE_EXPR)
#                            ↓
#                       heal_until_fixpoint (H.1/H.2)
#                            ↓
#                        encode_program (rewrites SAFE_EXPR → safe_divide)
#                            ↓
#                          execute
#
# ---- H.3 (preserved) ----
# H.1 caught AST-level bugs (harmonic violations, identifier typos). H.2
# added divide-by-singularity and wrapped both in an iteration loop. H.3
# adds the missing layer below: TOKEN-LEVEL recovery that runs BEFORE the
# parser sees anything. Three repair classes at this layer:
#
#   4. UNBALANCED BRACES — count LBRACE vs RBRACE in the token stream.
#      Difference = missing closers. Insert them before EOF. The parser
#      sees a balanced stream and succeeds.
#
#   5. UNBALANCED PARENS — same shape, LPAREN vs RPAREN.
#
#   6. MISSING SEMI — scan adjacent token pairs. When a clear expression
#      terminator (NUMBER, STRING, RPAREN, RBRACKET) is immediately
#      followed by a clear statement starter (H, FN, IF, WHILE, RETURN,
#      BREAK, PRINT) without an intervening SEMI, insert one.
#
# These repairs operate on the TOKEN STREAM, not the AST. They run as a
# pre-pass to parsing; the recovered stream then feeds tokenize_b's
# downstream consumers exactly as if the original source had been clean.
#
# Why this is a different STAGE from H.1/H.2's AST-level healing: the
# parser needs a syntactically valid stream to produce a meaningful AST.
# If braces are unbalanced, the parser falls off a cliff and never reaches
# the AST walker. Token-level recovery has to come first.
#
# The full pipeline now looks like:
#
#   source → tokenize_b → token_heal → tokens'
#                                       ↓
#                                   p_program
#                                       ↓
#                                      AST
#                                       ↓
#                              heal_until_fixpoint
#                                       ↓
#                                   healed AST
#                                       ↓
#                                  emit_source
#                                       ↓
#                                  healed source
#
# Two stages of repair, both reporting diagnostics, both contributing to
# the final corrected output. The iteration loop wraps the AST stage; the
# token stage runs once (it's a static count-and-insert pass with no
# fixpoint to converge on).
#
# Original H.2 header preserved below for context.
#
# ---- H.2 (preserved) ----
# H.1 built a single-pass scanner that catches harmonic violations and
# identifier typos and emits a healed source. H.2 wraps that pass in a
# convergence loop AND adds a third diagnostic class:
#
#   3. DIVIDE-BY-SINGULARITY — a `/` BIN expression where the right
#      operand is a literal whose `value_danger > 0.5` (i.e. near zero).
#      The host primitive `safe_divide` already does exactly the right
#      thing: it fold_escape's the divisor away from the danger zone
#      before dividing. The healer rewrites `a / 0` to `safe_divide(a, 0)`,
#      preserving the original numerator and using the host's predictive
#      self-healing arithmetic for the division itself.
#
# The autofix-and-retry loop:
#
#   heal_until_fixpoint(stmts, max_iter):
#     for iter in 1..max_iter:
#       (healed_ast, diags) = heal_program(current)
#       record (iter, |diags|) in trajectory
#       if |diags| == 0:  return (current, trajectory, "converged", iter-1)
#       if |diags| == previous_count:  return (current, trajectory, "stuck", iter)
#       current = healed_ast
#     return (current, trajectory, "exhausted", max_iter)
#
# Three terminal states:
#   * "converged"  — diagnostics dropped to zero. Healed source is stable.
#   * "stuck"      — same diagnostic count two iterations in a row.
#                    The healer can't make further progress; report and stop.
#   * "exhausted"  — hit the iteration bound. Likely a divergent cycle or
#                    a pathologically large source.
#
# Why iteration matters even when H.1 already runs all checks in one pass:
# the loop is the right shape for future checks that DON'T run in parallel
# (e.g. parse-level recovery in H.3, or runtime-guarded primitives in H.4
# that need re-evaluation after each rewrite). H.2 lands the infrastructure
# now so the additions in H.3/H.4 plug in cleanly.
# =============================================================================

# =============================================================================
#                              PART I: LEXER
# Adds STRING literals (with \n \t \r \" \\ escapes), LBRACKET, RBRACKET.
# =============================================================================

fn is_digit_b(c) {
    return str_contains("0123456789", c);
}

fn is_alpha_b(c) {
    if str_contains("abcdefghijklmnopqrstuvwxyz", c) == 1 { return 1; }
    if str_contains("ABCDEFGHIJKLMNOPQRSTUVWXYZ", c) == 1 { return 1; }
    if c == "_" { return 1; }
    return 0;
}

fn is_alnum_b(c) {
    if is_alpha_b(c) == 1 { return 1; }
    if is_digit_b(c) == 1 { return 1; }
    return 0;
}

fn is_space_b(c) {
    if c == " "  { return 1; }
    if c == "\n" { return 1; }
    if c == "\t" { return 1; }
    if c == "\r" { return 1; }
    return 0;
}

fn skip_ws_b(source, pos) {
    h n = str_chars(source);
    h p = pos;
    h moved = 1;
    # V.8b: loop until neither whitespace nor a `#`-comment advances `p`.
    while moved == 1 {
        moved = 0;
        # whitespace
        while p < n {
            h c = str_slice(source, p, p + 1);
            if is_space_b(c) == 1 {
                p = p + 1;
                moved = 1;
            } else { break; }
        }
        # line comment
        if p < n {
            h c2 = str_slice(source, p, p + 1);
            if c2 == "#" {
                while p < n {
                    h cc = str_slice(source, p, p + 1);
                    if cc == "\n" { break; }
                    p = p + 1;
                }
                moved = 1;
            }
        }
    }
    return p;
}

fn classify_b(word) -> string {
    if word == "h"      { return "H"; }
    if word == "if"     { return "IF"; }
    if word == "else"   { return "ELSE"; }
    if word == "while"  { return "WHILE"; }
    if word == "print"  { return "PRINT"; }
    if word == "fn"     { return "FN"; }
    if word == "return" { return "RETURN"; }
    if word == "break"  { return "BREAK"; }
    if word == "safe"   { return "SAFE"; }
    return "IDENT";
}

fn match_multichar_b(source, pos) {
    h n = str_chars(source);
    if pos + 1 >= n { return ["", 0]; }
    h two = str_slice(source, pos, pos + 2);
    if two == "==" { return ["EQEQ", 2]; }
    if two == "!=" { return ["NE",   2]; }
    if two == "<=" { return ["LE",   2]; }
    if two == ">=" { return ["GE",   2]; }
    return ["", 0];
}

fn punct_kind_b(c) -> string {
    if c == "(" { return "LPAREN"; }
    if c == ")" { return "RPAREN"; }
    if c == "{" { return "LBRACE"; }
    if c == "}" { return "RBRACE"; }
    if c == "[" { return "LBRACKET"; }
    if c == "]" { return "RBRACKET"; }
    if c == ";" { return "SEMI"; }
    if c == "," { return "COMMA"; }
    if c == "=" { return "EQ"; }
    if c == "+" { return "PLUS"; }
    if c == "-" { return "MINUS"; }
    if c == "*" { return "STAR"; }
    if c == "/" { return "SLASH"; }
    if c == "%" { return "PERCENT"; }
    if c == "<" { return "LT"; }
    if c == ">" { return "GT"; }
    return "";
}

# Decode a single backslash-escape into its in-string character.
fn decode_escape(nx) -> string {
    if nx == "n"  { return "\n"; }
    if nx == "t"  { return "\t"; }
    if nx == "r"  { return "\r"; }
    if nx == "\"" { return "\""; }
    if nx == "\\" { return "\\"; }
    return nx;
}

# Scan a `"..."` string literal starting at `pos` (which points at the
# opening quote). Returns [decoded_string, new_pos_past_closing_quote].
fn scan_string(source, pos) {
    h n = str_chars(source);
    h end = pos + 1;
    h s = "";
    h done = 0;
    while done == 0 {
        if end >= n { done = 1; }
        if done == 0 {
            h cc = str_slice(source, end, end + 1);
            if cc == "\"" {
                end = end + 1;
                done = 1;
            } else {
                if cc == "\\" {
                    if end + 1 < n {
                        h nx = str_slice(source, end + 1, end + 2);
                        s = str_concat(s, decode_escape(nx));
                        end = end + 2;
                    } else { end = end + 1; }
                } else {
                    s = str_concat(s, cc);
                    end = end + 1;
                }
            }
        }
    }
    return [s, end];
}

fn tokenize_b(source) {
    h n = str_chars(source);
    h tokens = arr_new(0, 0);
    h pos = 0;
    while pos < n {
        pos = skip_ws_b(source, pos);
        if pos >= n { break; }
        h c = str_slice(source, pos, pos + 1);
        if c == "\"" {
            h r = scan_string(source, pos);
            arr_push(tokens, ["STRING", arr_get(r, 0)]);
            pos = arr_get(r, 1);
        } else {
            if is_alpha_b(c) == 1 {
                h end = pos;
                while end < n {
                    h cc = str_slice(source, end, end + 1);
                    if is_alnum_b(cc) == 1 { end = end + 1; } else { break; }
                }
                h word = str_slice(source, pos, end);
                arr_push(tokens, [classify_b(word), word]);
                pos = end;
            } else {
                if is_digit_b(c) == 1 {
                    h end = pos;
                    while end < n {
                        h cc = str_slice(source, end, end + 1);
                        if is_digit_b(cc) == 1 { end = end + 1; } else { break; }
                    }
                    arr_push(tokens, ["NUMBER", str_slice(source, pos, end)]);
                    pos = end;
                } else {
                    h mm = match_multichar_b(source, pos);
                    h mm_kind = arr_get(mm, 0);
                    h mm_len = arr_get(mm, 1);
                    if str_len(mm_kind) > 0 {
                        arr_push(tokens, [mm_kind, str_slice(source, pos, pos + mm_len)]);
                        pos = pos + mm_len;
                    } else {
                        h kind = punct_kind_b(c);
                        if str_len(kind) > 0 {
                            arr_push(tokens, [kind, c]);
                        } else {
                            arr_push(tokens, ["UNKNOWN", c]);
                        }
                        pos = pos + 1;
                    }
                }
            }
        }
    }
    arr_push(tokens, ["EOF", ""]);
    return tokens;
}

# =============================================================================
#                              PART II: PARSER
# Adds STR primary, ARR primary ([a, b, c]).
# =============================================================================

fn tkind(toks, p) -> string {
    h t = arr_get(toks, p);
    return arr_get(t, 0);
}
fn tval(toks, p) -> string {
    h t = arr_get(toks, p);
    return arr_get(t, 1);
}

fn p_args(toks, p) {
    h args = arr_new(0, 0);
    h np = p + 1;   # skip LPAREN
    if tkind(toks, np) == "RPAREN" {
        return [args, np + 1];
    }
    h done = 0;
    while done == 0 {
        h r = p_expr(toks, np);
        arr_push(args, arr_get(r, 0));
        np = arr_get(r, 1);
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [args, np + 1];
}

fn p_array_lit(toks, p) {
    # called with p pointing at LBRACKET
    h elems = arr_new(0, 0);
    h np = p + 1;
    if tkind(toks, np) == "RBRACKET" {
        return [["ARR", elems], np + 1];
    }
    h done = 0;
    while done == 0 {
        h r = p_expr(toks, np);
        arr_push(elems, arr_get(r, 0));
        np = arr_get(r, 1);
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [["ARR", elems], np + 1];   # consume RBRACKET
}

fn p_primary(toks, p) {
    h k = tkind(toks, p);
    if k == "NUMBER"   { return [["NUM", tval(toks, p)], p + 1]; }
    if k == "STRING"   { return [["STR", tval(toks, p)], p + 1]; }
    if k == "LBRACKET" { return p_array_lit(toks, p); }
    if k == "IDENT"  {
        if tkind(toks, p + 1) == "LPAREN" {
            h name = tval(toks, p);
            h r = p_args(toks, p + 1);
            return [["CALL", name, arr_get(r, 0)], arr_get(r, 1)];
        }
        return [["VAR", tval(toks, p)], p + 1];
    }
    if k == "LPAREN" {
        h r = p_expr(toks, p + 1);
        return [arr_get(r, 0), arr_get(r, 1) + 1];
    }
    return [["ERR", k], p + 1];
}

fn p_mul(toks, p) {
    h r = p_primary(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        if k == "STAR" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "*", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "SLASH" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "/", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "PERCENT" {
            h r2 = p_primary(toks, np + 1);
            left = ["BIN", "%", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }}}
    }
    return [left, np];
}

fn p_add(toks, p) {
    h r = p_mul(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        if k == "PLUS" {
            h r2 = p_mul(toks, np + 1);
            left = ["BIN", "+", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { if k == "MINUS" {
            h r2 = p_mul(toks, np + 1);
            left = ["BIN", "-", left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }}
    }
    return [left, np];
}

fn p_cmp(toks, p) {
    h r = p_add(toks, p);
    h left = arr_get(r, 0);
    h np = arr_get(r, 1);
    h go = 1;
    while go == 1 {
        h k = tkind(toks, np);
        h op = "";
        if k == "EQEQ" { op = "=="; }
        if k == "NE"   { op = "!="; }
        if k == "LT"   { op = "<"; }
        if k == "LE"   { op = "<="; }
        if k == "GT"   { op = ">"; }
        if k == "GE"   { op = ">="; }
        if str_len(op) > 0 {
            h r2 = p_add(toks, np + 1);
            left = ["BIN", op, left, arr_get(r2, 0)];
            np = arr_get(r2, 1);
        } else { go = 0; }
    }
    return [left, np];
}

fn p_expr(toks, p) {
    # H.4: `safe EXPR` prefix wraps the rest of the expression as
    # ["SAFE_EXPR", inner_ast]. The encoder later rewrites SAFE_EXPR
    # containing a BIN / to a CALL of safe_divide, regardless of whether
    # the divisor is a literal. This is the user's runtime self-healing
    # opt-in for DYNAMIC singularities the static healer can't catch.
    if tkind(toks, p) == "SAFE" {
        h r = p_cmp(toks, p + 1);
        return [["SAFE_EXPR", arr_get(r, 0)], arr_get(r, 1)];
    }
    return p_cmp(toks, p);
}

fn p_params(toks, p) {
    h params = arr_new(0, 0);
    h np = p + 1;
    if tkind(toks, np) == "RPAREN" {
        return [params, np + 1];
    }
    h done = 0;
    while done == 0 {
        arr_push(params, tval(toks, np));
        np = np + 1;
        if tkind(toks, np) == "COMMA" {
            np = np + 1;
        } else { done = 1; }
    }
    return [params, np + 1];
}

fn p_stmt(toks, p) {
    h k = tkind(toks, p);
    if k == "H" {
        h name = tval(toks, p + 1);
        h r = p_expr(toks, p + 3);
        h np = arr_get(r, 1) + 1;
        return [["DECL", name, arr_get(r, 0)], np];
    }
    if k == "PRINT" {
        h r = p_expr(toks, p + 2);
        h np = arr_get(r, 1) + 1 + 1;
        return [["PRT", arr_get(r, 0)], np];
    }
    if k == "WHILE" {
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        h body_r = p_block(toks, np);
        return [["WHL", arr_get(r, 0), arr_get(body_r, 0)], arr_get(body_r, 1)];
    }
    if k == "IF" {
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        h then_r = p_block(toks, np);
        np = arr_get(then_r, 1);
        h else_body = arr_new(0, 0);
        if tkind(toks, np) == "ELSE" {
            np = np + 2;
            h eb = p_block(toks, np);
            else_body = arr_get(eb, 0);
            np = arr_get(eb, 1);
        }
        return [["IF", arr_get(r, 0), arr_get(then_r, 0), else_body], np];
    }
    if k == "FN" {
        h name = tval(toks, p + 1);
        h params_r = p_params(toks, p + 2);
        h params = arr_get(params_r, 0);
        h np = arr_get(params_r, 1);
        # V.8b: optional `-> IDENT` return-type annotation. Tokens are
        # MINUS GT IDENT. Annotation is documentation only — no runtime
        # effect — so we just skip past it.
        if tkind(toks, np) == "MINUS" {
            if tkind(toks, np + 1) == "GT" {
                np = np + 3;
            }
        }
        np = np + 1;   # consume LBRACE
        h body_r = p_block(toks, np);
        return [["FN", name, params, arr_get(body_r, 0)], arr_get(body_r, 1)];
    }
    if k == "RETURN" {
        if tkind(toks, p + 1) == "SEMI" {
            return [["RET", ["NULL"]], p + 2];
        }
        h r = p_expr(toks, p + 1);
        h np = arr_get(r, 1) + 1;
        return [["RET", arr_get(r, 0)], np];
    }
    if k == "BREAK" {
        # `break ;` — consumes BREAK and SEMI.
        return [["BREAK"], p + 2];
    }
    if k == "IDENT" {
        h k1 = tkind(toks, p + 1);
        if k1 == "EQ" {
            h name = tval(toks, p);
            h r = p_expr(toks, p + 2);
            h np = arr_get(r, 1) + 1;
            return [["ASN", name, arr_get(r, 0)], np];
        }
        if k1 == "LPAREN" {
            h r = p_expr(toks, p);
            h np = arr_get(r, 1) + 1;
            return [["EXPR", arr_get(r, 0)], np];
        }
    }
    print(concat_many("p_stmt: don't know how to handle kind=", k));
    return [["ERR", k], p + 1];
}

fn p_block(toks, p) {
    h body = arr_new(0, 0);
    h np = p;
    h done = 0;
    while done == 0 {
        h k = tkind(toks, np);
        if k == "RBRACE" {
            np = np + 1;
            done = 1;
        } else {
            if k == "EOF" {
                done = 1;
            } else {
                h r = p_stmt(toks, np);
                arr_push(body, arr_get(r, 0));
                np = arr_get(r, 1);
            }
        }
    }
    return [body, np];
}

fn p_program(toks) {
    h stmts = arr_new(0, 0);
    h pos = 0;
    h done = 0;
    while done == 0 {
        if tkind(toks, pos) == "EOF" {
            done = 1;
        } else {
            h r = p_stmt(toks, pos);
            arr_push(stmts, arr_get(r, 0));
            pos = arr_get(r, 1);
        }
    }
    return stmts;
}

# =============================================================================
#                           PART III: BYTECODE ENCODER
# Adds LOAD_STR, MAKE_ARR, CALL_BUILTIN (for the read-only builtin set).
# =============================================================================

fn arr_concat(a, b) {
    h i = 0;
    h n = arr_len(b);
    while i < n {
        arr_push(a, arr_get(b, i));
        i = i + 1;
    }
    return a;
}

# Builtins that ride through CALL_BUILTIN (value-in, value-out only).
fn is_builtin(name) {
    if name == "arr_new"      { return 1; }
    if name == "arr_get"      { return 1; }
    if name == "arr_len"      { return 1; }
    if name == "str_len"      { return 1; }
    if name == "str_chars"    { return 1; }
    if name == "str_slice"    { return 1; }
    if name == "str_contains" { return 1; }
    if name == "str_concat"   { return 1; }
    if name == "concat_many"  { return 1; }
    if name == "to_int"       { return 1; }
    if name == "to_string"    { return 1; }
    # H.2: ONN primitives reachable at runtime in healed code.
    if name == "safe_divide"   { return 1; }
    if name == "fold_escape"   { return 1; }
    if name == "value_danger"  { return 1; }
    if name == "harmony_value" { return 1; }
    if name == "is_fibonacci"  { return 1; }
    return 0;
}

fn enc_expr(ast) {
    h out = arr_new(0, 0);
    h tag = arr_get(ast, 0);
    if tag == "NUM" {
        arr_push(out, ["LOAD_INT", arr_get(ast, 1)]);
        return out;
    }
    if tag == "STR" {
        arr_push(out, ["LOAD_STR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "VAR" {
        arr_push(out, ["LOAD_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "ARR" {
        h elems = arr_get(ast, 1);
        h i = 0;
        h n = arr_len(elems);
        while i < n {
            out = arr_concat(out, enc_expr(arr_get(elems, i)));
            i = i + 1;
        }
        arr_push(out, ["MAKE_ARR", n]);
        return out;
    }
    if tag == "BIN" {
        h op = arr_get(ast, 1);
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        out = arr_concat(out, enc_expr(arr_get(ast, 3)));
        if op == "+"  { arr_push(out, ["ADD"]); return out; }
        if op == "-"  { arr_push(out, ["SUB"]); return out; }
        if op == "*"  { arr_push(out, ["MUL"]); return out; }
        if op == "/"  { arr_push(out, ["DIV"]); return out; }
        if op == "%"  { arr_push(out, ["MOD"]); return out; }
        if op == "==" { arr_push(out, ["EQ"]);  return out; }
        if op == "!=" { arr_push(out, ["NE"]);  return out; }
        if op == "<"  { arr_push(out, ["LT"]);  return out; }
        if op == "<=" { arr_push(out, ["LE"]);  return out; }
        if op == ">"  { arr_push(out, ["GT"]);  return out; }
        if op == ">=" { arr_push(out, ["GE"]);  return out; }
        return out;
    }
    if tag == "CALL" {
        h name = arr_get(ast, 1);
        h args = arr_get(ast, 2);
        # Specialised named-mutation forms — only when the first arg is a
        # bare variable. Anything fancier (e.g. arr_push(arr_get(x,0), v))
        # falls through to CALL_BUILTIN and loses the mutation, same as a
        # tree-walk caller would.
        if name == "arr_push" {
            if arr_len(args) == 2 {
                h target = arr_get(args, 0);
                if arr_get(target, 0) == "VAR" {
                    out = arr_concat(out, enc_expr(arr_get(args, 1)));
                    arr_push(out, ["ARR_PUSH_NAMED", arr_get(target, 1)]);
                    return out;
                }
            }
        }
        if name == "arr_set" {
            if arr_len(args) == 3 {
                h target = arr_get(args, 0);
                if arr_get(target, 0) == "VAR" {
                    out = arr_concat(out, enc_expr(arr_get(args, 1)));   # idx
                    out = arr_concat(out, enc_expr(arr_get(args, 2)));   # value
                    arr_push(out, ["ARR_SET_NAMED", arr_get(target, 1)]);
                    return out;
                }
            }
        }
        h i = 0;
        h n = arr_len(args);
        while i < n {
            out = arr_concat(out, enc_expr(arr_get(args, i)));
            i = i + 1;
        }
        if is_builtin(name) == 1 {
            arr_push(out, ["CALL_BUILTIN", name, n]);
        } else {
            arr_push(out, ["CALL", name, n]);
        }
        return out;
    }
    if tag == "SAFE_EXPR" {
        # H.4: convert user-declared safety wrappers to ONN primitives at
        # encode time. Currently the only meaningful rewrite is for `/`;
        # other expressions wrapped in `safe` encode as their inner form
        # (no-op), reserving the slot for future runtime guards (e.g.
        # fold_escape on function-call return values, value_danger
        # threshold on arithmetic chains).
        h inner = arr_get(ast, 1);
        if arr_get(inner, 0) == "BIN" {
            if arr_get(inner, 1) == "/" {
                h left = arr_get(inner, 2);
                h right = arr_get(inner, 3);
                out = arr_concat(out, enc_expr(left));
                out = arr_concat(out, enc_expr(right));
                arr_push(out, ["CALL_BUILTIN", "safe_divide", 2]);
                return out;
            }
        }
        # No special rewrite for this shape — encode the inner directly.
        out = arr_concat(out, enc_expr(inner));
        return out;
    }
    arr_push(out, ["UNKNOWN_EXPR", tag]);
    return out;
}

fn enc_stmt(ast) {
    h out = arr_new(0, 0);
    h tag = arr_get(ast, 0);
    if tag == "DECL" {
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        arr_push(out, ["STORE_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "ASN" {
        out = arr_concat(out, enc_expr(arr_get(ast, 2)));
        arr_push(out, ["STORE_VAR", arr_get(ast, 1)]);
        return out;
    }
    if tag == "PRT" {
        out = arr_concat(out, enc_expr(arr_get(ast, 1)));
        arr_push(out, ["PRINT"]);
        return out;
    }
    if tag == "EXPR" {
        out = arr_concat(out, enc_expr(arr_get(ast, 1)));
        arr_push(out, ["POP"]);
        return out;
    }
    if tag == "RET" {
        h e = arr_get(ast, 1);
        if arr_get(e, 0) == "NULL" {
            arr_push(out, ["LOAD_INT", "0"]);
        } else {
            out = arr_concat(out, enc_expr(e));
        }
        arr_push(out, ["RETURN"]);
        return out;
    }
    if tag == "BREAK" {
        # V.8b: placeholder; the enclosing WHL encoder patches the delta
        # to land just after the trailing back-jump. A loose JUMP_BREAK
        # (break outside any while) would never get patched and trigger
        # an "unknown opcode" at runtime — same as tree-walk would error.
        arr_push(out, ["JUMP_BREAK", 0]);
        return out;
    }
    if tag == "WHL" {
        h cond_ops = enc_expr(arr_get(ast, 1));
        h body_ops = enc_block(arr_get(ast, 2));
        h c_len = arr_len(cond_ops);
        h b_len = arr_len(body_ops);
        # V.8b: patch any JUMP_BREAK placeholders inside body_ops. A break
        # at position k inside body_ops should jump to immediately AFTER
        # the trailing back-jump — which is at the end of the assembled
        # while block. Layout:
        #
        #   [cond ops]            length c_len, indices 0..c_len-1
        #   JUMP_IF_FALSE         index c_len
        #   [body ops]            length b_len, indices c_len+1..c_len+b_len
        #   JUMP back             index c_len + b_len + 1
        #   <-- break target -->  index c_len + b_len + 2
        #
        # A JUMP_BREAK at body_ops index k sits at absolute index c_len+1+k.
        # Its target is c_len+b_len+2, so delta = b_len + 1 - k.
        # Relative jumps survive concatenation, so we patch body_ops in place.
        h k = 0;
        while k < b_len {
            h opk = arr_get(body_ops, k);
            if arr_get(opk, 0) == "JUMP_BREAK" {
                arr_set(body_ops, k, ["JUMP", b_len + 1 - k]);
            }
            k = k + 1;
        }
        out = arr_concat(out, cond_ops);
        arr_push(out, ["JUMP_IF_FALSE", b_len + 2]);
        out = arr_concat(out, body_ops);
        arr_push(out, ["JUMP", 0 - (c_len + b_len + 1)]);
        return out;
    }
    if tag == "IF" {
        h cond_ops = enc_expr(arr_get(ast, 1));
        h then_ops = enc_block(arr_get(ast, 2));
        h else_body = arr_get(ast, 3);
        h has_else = 0;
        if arr_len(else_body) > 0 { has_else = 1; }
        out = arr_concat(out, cond_ops);
        if has_else == 1 {
            h else_ops = enc_block(else_body);
            h t_len = arr_len(then_ops);
            h e_len = arr_len(else_ops);
            arr_push(out, ["JUMP_IF_FALSE", t_len + 2]);
            out = arr_concat(out, then_ops);
            arr_push(out, ["JUMP", e_len + 1]);
            out = arr_concat(out, else_ops);
        } else {
            h t_len = arr_len(then_ops);
            arr_push(out, ["JUMP_IF_FALSE", t_len + 1]);
            out = arr_concat(out, then_ops);
        }
        return out;
    }
    if tag == "FN" {
        h name = arr_get(ast, 1);
        h params = arr_get(ast, 2);
        h body = arr_get(ast, 3);
        h body_ops = enc_block(body);
        arr_push(body_ops, ["LOAD_INT", "0"]);
        arr_push(body_ops, ["RETURN"]);
        h b_len = arr_len(body_ops);
        arr_push(out, ["DEF_FN", name, b_len, params]);
        out = arr_concat(out, body_ops);
        return out;
    }
    arr_push(out, ["UNKNOWN_STMT", tag]);
    return out;
}

fn enc_block(stmts) {
    h out = arr_new(0, 0);
    h i = 0;
    h n = arr_len(stmts);
    while i < n {
        out = arr_concat(out, enc_stmt(arr_get(stmts, i)));
        i = i + 1;
    }
    return out;
}

fn encode_program(stmts) {
    h out = enc_block(stmts);
    arr_push(out, ["HALT"]);
    return out;
}

# A compact disassembler. For LOAD_STR we quote the value so embedded
# spaces and newlines stay legible. For DEF_FN we summarise params count.
fn print_bytecode(prog) {
    h i = 0;
    h n = arr_len(prog);
    while i < n {
        h op = arr_get(prog, i);
        h kind = arr_get(op, 0);
        h line = concat_many("  ", i, ": ", kind);
        h ol = arr_len(op);
        if kind == "LOAD_STR" {
            line = concat_many(line, " \"", arr_get(op, 1), "\"");
        } else {
            if ol >= 2 { line = concat_many(line, " ", arr_get(op, 1)); }
            if ol >= 3 { line = concat_many(line, " ", arr_get(op, 2)); }
        }
        if kind == "DEF_FN" {
            if ol >= 4 {
                line = concat_many(line, " [params=", arr_len(arr_get(op, 3)), "]");
            }
        }
        print(line);
        i = i + 1;
    }
    return 0;
}

# =============================================================================
#                           PART IV: BYTECODE EXECUTOR
# Adds LOAD_STR, MAKE_ARR, CALL_BUILTIN.
# =============================================================================

fn scope_get(scope, name) {
    h i = 0;
    h n = arr_len(scope);
    while i < n {
        h pair = arr_get(scope, i);
        if arr_get(pair, 0) == name {
            return arr_get(pair, 1);
        }
        i = i + 1;
    }
    return 0;
}

fn scope_set(scope, name, value) {
    h i = 0;
    h n = arr_len(scope);
    while i < n {
        h pair = arr_get(scope, i);
        if arr_get(pair, 0) == name {
            arr_set(scope, i, [name, value]);
            return scope;
        }
        i = i + 1;
    }
    arr_push(scope, [name, value]);
    return scope;
}

fn parse_int(s) {
    return to_int(s);
}

fn pop1(stack) {
    h n = arr_len(stack);
    h top = arr_get(stack, n - 1);
    h ns = arr_new(0, 0);
    h i = 0;
    while i < n - 1 {
        arr_push(ns, arr_get(stack, i));
        i = i + 1;
    }
    return [top, ns];
}

# Pop `n` values from the stack, returning [values_in_push_order, new_stack].
# Push order means: args[0] was pushed first (deepest), args[n-1] was pushed
# last (top). This matches the order in the source-level argument list.
fn pop_n_ordered(stack, n) {
    h reverse = arr_new(0, 0);
    h s = stack;
    h k = 0;
    while k < n {
        h pr = pop1(s);
        arr_push(reverse, arr_get(pr, 0));
        s = arr_get(pr, 1);
        k = k + 1;
    }
    h ordered = arr_new(0, 0);
    h j = n - 1;
    while j >= 0 {
        arr_push(ordered, arr_get(reverse, j));
        j = j - 1;
    }
    return [ordered, s];
}

# Dispatch a host builtin. Returns the value to push onto the value stack.
fn call_builtin(name, args) {
    if name == "arr_new" {
        if arr_len(args) >= 2 {
            return arr_new(arr_get(args, 0), arr_get(args, 1));
        }
        return arr_new(0, 0);
    }
    if name == "arr_get" {
        return arr_get(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "arr_len" {
        return arr_len(arr_get(args, 0));
    }
    if name == "str_len" {
        return str_len(arr_get(args, 0));
    }
    if name == "str_chars" {
        return str_chars(arr_get(args, 0));
    }
    if name == "str_slice" {
        return str_slice(arr_get(args, 0), arr_get(args, 1), arr_get(args, 2));
    }
    if name == "str_contains" {
        return str_contains(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "str_concat" {
        return str_concat(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "concat_many" {
        # Use to_string per arg so ints render via Display ("42") not Debug
        # ("HInt(42, φ=…)"). Without this, bytecode-VM output for the same
        # expression diverges cosmetically from tree-walk — which broke the
        # V.7b cosmetic-only test and was the only blocker on the V.8
        # round-trip for embedded_program.
        h n = arr_len(args);
        if n == 0 { return ""; }
        h s = to_string(arr_get(args, 0));
        h i = 1;
        while i < n {
            s = str_concat(s, to_string(arr_get(args, i)));
            i = i + 1;
        }
        return s;
    }
    if name == "to_int" {
        return to_int(arr_get(args, 0));
    }
    if name == "to_string" {
        return to_string(arr_get(args, 0));
    }
    if name == "safe_divide" {
        return safe_divide(arr_get(args, 0), arr_get(args, 1));
    }
    if name == "fold_escape" {
        return fold_escape(arr_get(args, 0));
    }
    if name == "value_danger" {
        return value_danger(arr_get(args, 0));
    }
    if name == "harmony_value" {
        return harmony_value(arr_get(args, 0));
    }
    if name == "is_fibonacci" {
        return is_fibonacci(arr_get(args, 0));
    }
    print(concat_many("call_builtin: unknown builtin ", name));
    return 0;
}

fn collect_fns(prog) {
    h table = arr_new(0, 0);
    h i = 0;
    h n = arr_len(prog);
    while i < n {
        h op = arr_get(prog, i);
        if arr_get(op, 0) == "DEF_FN" {
            h name = arr_get(op, 1);
            h params = arr_get(op, 3);
            arr_push(table, [name, i + 1, params]);
        }
        i = i + 1;
    }
    return table;
}

fn fn_lookup(table, name) {
    h i = 0;
    h n = arr_len(table);
    while i < n {
        h row = arr_get(table, i);
        if arr_get(row, 0) == name {
            return row;
        }
        i = i + 1;
    }
    return ["", 0 - 1, arr_new(0, 0)];
}

fn execute(prog) {
    h stack = arr_new(0, 0);
    h scope = arr_new(0, 0);
    h scope_stack = arr_new(0, 0);
    h pc_stack = arr_new(0, 0);
    h fn_table = collect_fns(prog);
    h pc = 0;
    h n = arr_len(prog);

    h running = 1;
    while running == 1 {
        if pc >= n {
            running = 0;
        }
        if running == 1 {
            h op = arr_get(prog, pc);
            h kind = arr_get(op, 0);
            h handled = 0;

            if kind == "HALT" {
                running = 0;
                handled = 1;
            }
            if kind == "NOP" {
                pc = pc + 1;
                handled = 1;
            }
            if kind == "POP" {
                h pr = pop1(stack); stack = arr_get(pr, 1);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "LOAD_INT" {
                arr_push(stack, parse_int(arr_get(op, 1)));
                pc = pc + 1;
                handled = 1;
            }
            if kind == "LOAD_STR" {
                arr_push(stack, arr_get(op, 1));
                pc = pc + 1;
                handled = 1;
            }
            if kind == "LOAD_VAR" {
                arr_push(stack, scope_get(scope, arr_get(op, 1)));
                pc = pc + 1;
                handled = 1;
            }
            if kind == "STORE_VAR" {
                h pr = pop1(stack);
                h v = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                scope = scope_set(scope, arr_get(op, 1), v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "ARR_PUSH_NAMED" {
                # Pop the value, look up the named array in current scope,
                # arr_push, store back. Leaves the (mutated) array on the
                # stack as the expression's result.
                h pr = pop1(stack); h val = arr_get(pr, 0); stack = arr_get(pr, 1);
                h name = arr_get(op, 1);
                h arr = scope_get(scope, name);
                arr_push(arr, val);
                scope = scope_set(scope, name, arr);
                arr_push(stack, arr);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "ARR_SET_NAMED" {
                # Pop value, then index. Look up named array, arr_set,
                # store back. Same convention as ARR_PUSH_NAMED.
                h pr1 = pop1(stack); h val = arr_get(pr1, 0); stack = arr_get(pr1, 1);
                h pr2 = pop1(stack); h idx = arr_get(pr2, 0); stack = arr_get(pr2, 1);
                h name = arr_get(op, 1);
                h arr = scope_get(scope, name);
                arr_set(arr, idx, val);
                scope = scope_set(scope, name, arr);
                arr_push(stack, arr);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "MAKE_ARR" {
                h len = to_int(arr_get(op, 1));
                h pr = pop_n_ordered(stack, len);
                h elems = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                # Materialise as a real array by copying elements over.
                h arr = arr_new(0, 0);
                h i = 0;
                while i < len {
                    arr_push(arr, arr_get(elems, i));
                    i = i + 1;
                }
                arr_push(stack, arr);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "ADD" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                arr_push(stack, l + r);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "SUB" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                arr_push(stack, l - r);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "MUL" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                arr_push(stack, l * r);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "DIV" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                arr_push(stack, l / r);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "MOD" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                arr_push(stack, l % r);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "LT" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l < r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "LE" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l <= r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "GT" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l > r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "GE" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l >= r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "EQ" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l == r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "NE" {
                h pr = pop1(stack); h r = arr_get(pr, 0); stack = arr_get(pr, 1);
                h pl = pop1(stack); h l = arr_get(pl, 0); stack = arr_get(pl, 1);
                h v = 0;
                if l != r { v = 1; }
                arr_push(stack, v);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "JUMP" {
                pc = pc + to_int(arr_get(op, 1));
                handled = 1;
            }
            if kind == "JUMP_IF_FALSE" {
                h pr = pop1(stack);
                h top = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                if top == 0 {
                    pc = pc + to_int(arr_get(op, 1));
                } else {
                    pc = pc + 1;
                }
                handled = 1;
            }
            if kind == "PRINT" {
                h pr = pop1(stack);
                h top = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                print(top);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "DEF_FN" {
                pc = pc + 1 + to_int(arr_get(op, 2));
                handled = 1;
            }
            if kind == "CALL_BUILTIN" {
                h name = arr_get(op, 1);
                h num_args = to_int(arr_get(op, 2));
                h pr = pop_n_ordered(stack, num_args);
                h args = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                h result = call_builtin(name, args);
                arr_push(stack, result);
                pc = pc + 1;
                handled = 1;
            }
            if kind == "CALL" {
                h name = arr_get(op, 1);
                h num_args = to_int(arr_get(op, 2));
                h row = fn_lookup(fn_table, name);
                h entry = to_int(arr_get(row, 1));
                h params = arr_get(row, 2);
                h pr = pop_n_ordered(stack, num_args);
                h args = arr_get(pr, 0);
                stack = arr_get(pr, 1);
                h new_scope = arr_new(0, 0);
                h j = 0;
                while j < num_args {
                    h pname = arr_get(params, j);
                    h pval = arr_get(args, j);
                    arr_push(new_scope, [pname, pval]);
                    j = j + 1;
                }
                arr_push(scope_stack, scope);
                arr_push(pc_stack, pc + 1);
                scope = new_scope;
                pc = entry;
                handled = 1;
            }
            if kind == "RETURN" {
                h sp_idx = arr_len(scope_stack) - 1;
                h pc_idx = arr_len(pc_stack) - 1;
                if sp_idx < 0 {
                    running = 0;
                    handled = 1;
                } else {
                    scope = arr_get(scope_stack, sp_idx);
                    h saved_pc = arr_get(pc_stack, pc_idx);
                    h new_ss = arr_new(0, 0);
                    h s_i = 0;
                    while s_i < sp_idx {
                        arr_push(new_ss, arr_get(scope_stack, s_i));
                        s_i = s_i + 1;
                    }
                    scope_stack = new_ss;
                    h new_ps = arr_new(0, 0);
                    h p_i = 0;
                    while p_i < pc_idx {
                        arr_push(new_ps, arr_get(pc_stack, p_i));
                        p_i = p_i + 1;
                    }
                    pc_stack = new_ps;
                    pc = to_int(saved_pc);
                    handled = 1;
                }
            }

            if handled == 0 {
                print(concat_many("execute: unknown opcode ", kind));
                running = 0;
            }
        }
    }
    # V.8: surface the bytecode VM's answer to the outer driver by
    # returning the value bound to __result in the final scope. Programs
    # that don't bind __result get 0 (the scope_get fallback).
    return scope_get(scope, "__result");
}

# =============================================================================
#         PART IV.5: TOKEN-LEVEL RECOVERY (H.3)
# =============================================================================
# Operates on the token stream BEFORE parsing. Three repair classes:
#   - brace balance: insert missing RBRACE before EOF when LBRACE > RBRACE
#   - paren balance: same shape for LPAREN/RPAREN
#   - missing SEMI:  scan adjacent pairs (expression terminator → statement
#                    starter) and insert SEMI between
# Each function returns [healed_tokens, diagnostics]. token_heal composes
# all three. The caller runs token_heal once before invoking tokenize_b's
# downstream consumers (p_program, heal_until_fixpoint).
# =============================================================================

fn token_count_kind(toks, kind) {
    h n = 0;
    h i = 0;
    while i < arr_len(toks) {
        if arr_get(arr_get(toks, i), 0) == kind { n = n + 1; }
        i = i + 1;
    }
    return n;
}

# Generic "append N closing tokens before EOF" — works for both brace and
# paren imbalances. `extras` (RBRACE > LBRACE or RPAREN > LPAREN) are not
# handled here; they'd indicate a different kind of bug that simple appending
# can't fix. Logged as a future refinement.
fn balance_closers(toks, open_kind, close_kind, close_value, label, diags) {
    h opens = token_count_kind(toks, open_kind);
    h closes = token_count_kind(toks, close_kind);
    if opens <= closes {
        return [toks, diags];
    }
    h delta = opens - closes;
    arr_push(diags, concat_many(
        "  token-balance: ", delta, " missing '", close_value,
        "' (", label, "); appending before EOF"));
    h eof_idx = arr_len(toks) - 1;
    h out = arr_new(0, 0);
    h i = 0;
    while i < eof_idx {
        arr_push(out, arr_get(toks, i));
        i = i + 1;
    }
    h k = 0;
    while k < delta {
        arr_push(out, [close_kind, close_value]);
        k = k + 1;
    }
    arr_push(out, arr_get(toks, eof_idx));
    return [out, diags];
}

fn is_expr_terminator_kind(k) {
    if k == "NUMBER"   { return 1; }
    if k == "STRING"   { return 1; }
    if k == "RPAREN"   { return 1; }
    if k == "RBRACKET" { return 1; }
    return 0;
}

fn is_stmt_starter_kind(k) {
    if k == "H"      { return 1; }
    if k == "FN"     { return 1; }
    if k == "IF"     { return 1; }
    if k == "WHILE"  { return 1; }
    if k == "RETURN" { return 1; }
    if k == "BREAK"  { return 1; }
    if k == "PRINT"  { return 1; }
    return 0;
}

fn insert_missing_semi(toks, diags) {
    h n = arr_len(toks);
    if n < 2 { return [toks, diags]; }
    h out = arr_new(0, 0);
    h inserted = 0;
    h i = 0;
    while i < n - 1 {
        h cur = arr_get(toks, i);
        h nxt = arr_get(toks, i + 1);
        arr_push(out, cur);
        h ck = arr_get(cur, 0);
        h nk = arr_get(nxt, 0);
        # Narrow rule: clear-expression-terminator followed by clear-
        # statement-starter, no intervening SEMI. Skip if next is already
        # SEMI (no insertion needed). Also fires when the next token is
        # EOF and current is an expr terminator — covers a trailing
        # statement at end-of-file with no closing semicolon.
        if nk != "SEMI" {
            if is_expr_terminator_kind(ck) == 1 {
                if is_stmt_starter_kind(nk) == 1 {
                    arr_push(out, ["SEMI", ";"]);
                    inserted = inserted + 1;
                } else {
                    if nk == "EOF" {
                        arr_push(out, ["SEMI", ";"]);
                        inserted = inserted + 1;
                    }
                }
            }
        }
        i = i + 1;
    }
    # Append the EOF (last token).
    arr_push(out, arr_get(toks, n - 1));
    if inserted > 0 {
        arr_push(diags, concat_many(
            "  token-recovery: ", inserted,
            " missing ';' inferred between statements"));
    }
    return [out, diags];
}

# Compose all three token-level repairs. Order matters: SEMI insertion
# first (so brace/paren counting works on a clean stream), then brace,
# then paren.
fn token_heal(toks) {
    h diags = arr_new(0, 0);
    h r1 = insert_missing_semi(toks, diags);
    h toks1 = arr_get(r1, 0);
    diags = arr_get(r1, 1);
    h r2 = balance_closers(toks1, "LBRACE", "RBRACE", "}", "brace", diags);
    h toks2 = arr_get(r2, 0);
    diags = arr_get(r2, 1);
    h r3 = balance_closers(toks2, "LPAREN", "RPAREN", ")", "paren", diags);
    return [arr_get(r3, 0), arr_get(r3, 1)];
}

fn compile_and_run(label, source) {
    print(concat_many("==== ", label, " ===="));
    print("source:");
    print(source);
    print("");

    h toks = tokenize_b(source);
    h ast = p_program(toks);
    h prog = encode_program(ast);

    print("bytecode:");
    print_bytecode(prog);
    print("");
    print("executing on OMC executor:");
    execute(prog);
    print("");
    return 0;
}

fn indent_of(level) -> string {
    h s = "";
    h i = 0;
    while i < level {
        s = str_concat(s, "    ");
        i = i + 1;
    }
    return s;
}

fn escape_for_source(s) -> string {
    h out = "";
    h n = str_len(s);
    h i = 0;
    while i < n {
        h c = str_slice(s, i, i + 1);
        if c == "\n" {
            out = str_concat(out, "\\n");
        } else {
            if c == "\t" {
                out = str_concat(out, "\\t");
            } else {
                if c == "\r" {
                    out = str_concat(out, "\\r");
                } else {
                    if c == "\"" {
                        out = str_concat(out, "\\\"");
                    } else {
                        if c == "\\" {
                            out = str_concat(out, "\\\\");
                        } else {
                            out = str_concat(out, c);
                        }
                    }
                }
            }
        }
        i = i + 1;
    }
    return out;
}

fn emit_expr(ast) -> string {
    h tag = arr_get(ast, 0);

    if tag == "NUMBER" {
        return arr_get(ast, 1);
    }
    if tag == "FLOAT" {
        return arr_get(ast, 1);
    }
    if tag == "STRING" {
        h body = escape_for_source(arr_get(ast, 1));
        return concat_many("\"", body, "\"");
    }
    if tag == "BOOL" {
        return arr_get(ast, 1);
    }
    if tag == "VAR" {
        return arr_get(ast, 1);
    }
    if tag == "BINOP" {
        h op = arr_get(ast, 1);
        h left = emit_expr(arr_get(ast, 2));
        h right = emit_expr(arr_get(ast, 3));
        return concat_many("(", left, " ", op, " ", right, ")");
    }
    if tag == "CALL" {
        h name = arr_get(ast, 1);
        h args = arr_get(ast, 2);
        h out = str_concat(name, "(");
        h i = 0;
        h n = arr_len(args);
        while i < n {
            if i > 0 { out = str_concat(out, ", "); }
            out = str_concat(out, emit_expr(arr_get(args, i)));
            i = i + 1;
        }
        return str_concat(out, ")");
    }
    return concat_many("/* UNKNOWN_EXPR ", tag, " */");
}

fn emit_stmt(ast, level) -> string {
    h pad = indent_of(level);
    h tag = arr_get(ast, 0);

    if tag == "VARDECL" {
        h name = arr_get(ast, 1);
        h v = emit_expr(arr_get(ast, 2));
        return concat_many(pad, "h ", name, " = ", v, ";\n");
    }
    if tag == "ASSIGN" {
        h name = arr_get(ast, 1);
        h v = emit_expr(arr_get(ast, 2));
        return concat_many(pad, name, " = ", v, ";\n");
    }
    if tag == "EXPRSTMT" {
        h e = emit_expr(arr_get(ast, 1));
        return concat_many(pad, e, ";\n");
    }
    if tag == "RETURN" {
        h v = arr_get(ast, 1);
        if v == "null" {
            return concat_many(pad, "return;\n");
        }
        return concat_many(pad, "return ", emit_expr(v), ";\n");
    }
    if tag == "PRINT" {
        h e = emit_expr(arr_get(ast, 1));
        return concat_many(pad, "print(", e, ");\n");
    }
    if tag == "IF" {
        h cond = emit_expr(arr_get(ast, 1));
        h then_body = emit_block(arr_get(ast, 2), level + 1);
        h else_body = arr_get(ast, 3);
        h out = concat_many(pad, "if ", cond, " {\n", then_body, pad, "}");
        if arr_len(else_body) > 0 {
            h eb = emit_block(else_body, level + 1);
            out = concat_many(out, " else {\n", eb, pad, "}");
        }
        return str_concat(out, "\n");
    }
    if tag == "WHILE" {
        h cond = emit_expr(arr_get(ast, 1));
        h body = emit_block(arr_get(ast, 2), level + 1);
        return concat_many(pad, "while ", cond, " {\n", body, pad, "}\n");
    }
    if tag == "FNDEF" {
        h name = arr_get(ast, 1);
        h params = arr_get(ast, 2);
        h body = emit_block(arr_get(ast, 3), level + 1);
        h plist = "";
        h i = 0;
        h pn = arr_len(params);
        while i < pn {
            if i > 0 { plist = str_concat(plist, ", "); }
            plist = str_concat(plist, arr_get(params, i));
            i = i + 1;
        }
        return concat_many(pad, "fn ", name, "(", plist, ") {\n", body, pad, "}\n");
    }
    return concat_many(pad, "/* UNKNOWN_STMT ", tag, " */\n");
}

fn emit_block(stmts, level) -> string {
    h out = "";
    h i = 0;
    h n = arr_len(stmts);
    while i < n {
        out = str_concat(out, emit_stmt(arr_get(stmts, i), level));
        i = i + 1;
    }
    return out;
}

fn emit_program(stmts) -> string {
    return emit_block(stmts, 0);
}

fn is_alpha(c) {
    if str_contains("abcdefghijklmnopqrstuvwxyz", c) == 1 { return 1; }
    if str_contains("ABCDEFGHIJKLMNOPQRSTUVWXYZ", c) == 1 { return 1; }
    if c == "_" { return 1; }
    return 0;
}

fn is_alnum(c) {
    if is_alpha(c) == 1 { return 1; }
    if is_digit(c) == 1 { return 1; }
    return 0;
}

fn is_space(c) {
    if c == " "  { return 1; }
    if c == "\n" { return 1; }
    if c == "\t" { return 1; }
    if c == "\r" { return 1; }
    return 0;
}

fn classify_word(word) -> string {
    if word == "h"        { return "H"; }
    if word == "fn"       { return "FN"; }
    if word == "if"       { return "IF"; }
    if word == "else"     { return "ELSE"; }
    if word == "while"    { return "WHILE"; }
    if word == "for"      { return "FOR"; }
    if word == "in"       { return "IN"; }
    if word == "return"   { return "RETURN"; }
    if word == "break"    { return "BREAK"; }
    if word == "continue" { return "CONTINUE"; }
    if word == "print"    { return "PRINT"; }
    if word == "import"   { return "IMPORT"; }
    if word == "and"      { return "AND"; }
    if word == "or"       { return "OR"; }
    if word == "not"      { return "NOT"; }
    if word == "res"      { return "RES"; }
    if word == "fold"     { return "FOLD"; }
    if word == "true"     { return "BOOL"; }
    if word == "false"    { return "BOOL"; }
    return "IDENT";
}

fn read_ident(source, pos) {
    h n = str_len(source);
    h end = pos;
    while end < n {
        h c = str_slice(source, end, end + 1);
        if is_alnum(c) == 1 { end = end + 1; } else { break; }
    }
    h word = str_slice(source, pos, end);
    return [classify_word(word), word, end];
}

fn read_number(source, pos) {
    h n = str_len(source);
    h end = pos;
    h is_float = 0;
    while end < n {
        h c = str_slice(source, end, end + 1);
        if is_digit(c) == 1 { end = end + 1; } else { break; }
    }
    if end < n {
        h c = str_slice(source, end, end + 1);
        if c == "." {
            if end + 1 < n {
                h after_dot = str_slice(source, end + 1, end + 2);
                if is_digit(after_dot) == 1 {
                    is_float = 1;
                    end = end + 1;
                    while end < n {
                        h cd = str_slice(source, end, end + 1);
                        if is_digit(cd) == 1 { end = end + 1; } else { break; }
                    }
                }
            }
        }
    }
    h text = str_slice(source, pos, end);
    if is_float == 1 { return ["FLOAT", text, end]; }
    return ["NUMBER", text, end];
}

fn read_string_literal(source, pos) {
    h n = str_len(source);
    h end = pos + 1;
    h out = "";
    while end < n {
        h c = str_slice(source, end, end + 1);
        if c == "\"" { return ["STRING", out, end + 1]; }
        if c == "\\" {
            if end + 1 < n {
                h esc = str_slice(source, end + 1, end + 2);
                if esc == "n"  { out = str_concat(out, "\n"); }
                if esc == "t"  { out = str_concat(out, "\t"); }
                if esc == "r"  { out = str_concat(out, "\r"); }
                if esc == "\"" { out = str_concat(out, "\""); }
                if esc == "\\" { out = str_concat(out, "\\"); }
                end = end + 2;
            } else {
                end = end + 1;
            }
        } else {
            out = str_concat(out, c);
            end = end + 1;
        }
    }
    return ["STRING_UNCLOSED", out, end];
}

fn match_multichar(source, pos) {
    h n = str_len(source);
    if pos + 1 >= n { return ["", 0]; }
    h two = str_slice(source, pos, pos + 2);
    if two == "==" { return ["EQEQ", 2]; }
    if two == "!=" { return ["NE",   2]; }
    if two == "<=" { return ["LE",   2]; }
    if two == ">=" { return ["GE",   2]; }
    if two == "->" { return ["ARROW",2]; }
    if two == "<<" { return ["SHL",  2]; }
    if two == ">>" { return ["SHR",  2]; }
    if two == "&&" { return ["AAND", 2]; }
    if two == "||" { return ["OOR",  2]; }
    return ["", 0];
}

fn punct_kind(c) -> string {
    if c == "(" { return "LPAREN"; }
    if c == ")" { return "RPAREN"; }
    if c == "{" { return "LBRACE"; }
    if c == "}" { return "RBRACE"; }
    if c == "[" { return "LBRACKET"; }
    if c == "]" { return "RBRACKET"; }
    if c == ";" { return "SEMI"; }
    if c == "," { return "COMMA"; }
    if c == "=" { return "EQ"; }
    if c == "+" { return "PLUS"; }
    if c == "-" { return "MINUS"; }
    if c == "*" { return "STAR"; }
    if c == "/" { return "SLASH"; }
    if c == "%" { return "PERCENT"; }
    if c == "<" { return "LT"; }
    if c == ">" { return "GT"; }
    if c == "." { return "DOT"; }
    if c == ":" { return "COLON"; }
    if c == "@" { return "AT"; }
    if c == "&" { return "AMP"; }
    if c == "|" { return "PIPE"; }
    if c == "^" { return "CARET"; }
    if c == "~" { return "TILDE"; }
    if c == "!" { return "BANG"; }
    return "";
}

fn tok_value(tokens, pos) -> string {
    h t = arr_get(tokens, pos);
