}

fn expect(tokens, pos, want) -> int {
    h got = tok_kind(tokens, pos);
    if got == want { return pos + 1; }
    print(concat_many("    [parse error] expected ", want, " got ", got, " at pos ", pos));
    return pos + 1;
}

fn run_fixpoint(label, source) {
    print(concat_many("==== ", label, " ===="));
    print("source₁:");
    print(source);
    print("");

    # Pass 1: source → AST₁
    h tokens1 = tokenize(source);
    h ast1 = parse_program(tokens1);

    # Pass 1 emit: AST₁ → source₂
    h source2 = emit_program(ast1);
    print("source₂ (emitted from AST₁):");
    print(source2);

    # Pass 2: source₂ → AST₂
    h tokens2 = tokenize(source2);
    h ast2 = parse_program(tokens2);

    # Pass 2 emit: AST₂ → source₃
    h source3 = emit_program(ast2);

    # Pass 3: source₃ → AST₃
    h tokens3 = tokenize(source3);
    h ast3 = parse_program(tokens3);

    h pass_1_to_2 = ast1 == ast2;
    h pass_2_to_3 = ast2 == ast3;
    h source_fixpoint = source2 == source3;

    print("--- Verification ---");
    print(concat_many("  AST₁ == AST₂           :  ", pass_1_to_2));
    print(concat_many("  AST₂ == AST₃           :  ", pass_2_to_3));
    print(concat_many("  source₂ == source₃     :  ", source_fixpoint));

    if pass_1_to_2 == 1 {
        if pass_2_to_3 == 1 {
            if source_fixpoint == 1 {
                print("  RESULT                 :  FIXPOINT REACHED ✓");
                return 1;
            }
        }
    }
    print("  RESULT                 :  fixpoint NOT reached");
    return 0;
}

fn print_ast(ast, indent) {
    h tag = arr_get(ast, 0);
    h prefix = "";
    h i = 0;
    while i < indent {
        prefix = str_concat(prefix, "  ");
        i = i + 1;
    }

    if tag == "NUMBER" {
        print(concat_many(prefix, "NUMBER ", arr_get(ast, 1)));
        return 0;
    }
    if tag == "FLOAT" {
        print(concat_many(prefix, "FLOAT ", arr_get(ast, 1)));
        return 0;
    }
    if tag == "STRING" {
        print(concat_many(prefix, "STRING \"", arr_get(ast, 1), "\""));
        return 0;
    }
    if tag == "VAR" {
        print(concat_many(prefix, "VAR ", arr_get(ast, 1)));
        return 0;
    }
    if tag == "BINOP" {
        print(concat_many(prefix, "BINOP ", arr_get(ast, 1)));
        print_ast(arr_get(ast, 2), indent + 1);
        print_ast(arr_get(ast, 3), indent + 1);
        return 0;
    }
    if tag == "CALL" {
        print(concat_many(prefix, "CALL ", arr_get(ast, 1)));
        h args = arr_get(ast, 2);
        h j = 0;
        while j < arr_len(args) {
            print_ast(arr_get(args, j), indent + 1);
            j = j + 1;
        }
        return 0;
    }
    if tag == "VARDECL" {
        print(concat_many(prefix, "VARDECL ", arr_get(ast, 1), " ="));
        print_ast(arr_get(ast, 2), indent + 1);
        return 0;
    }
    if tag == "ASSIGN" {
        print(concat_many(prefix, "ASSIGN ", arr_get(ast, 1), " ="));
        print_ast(arr_get(ast, 2), indent + 1);
        return 0;
    }
    if tag == "RETURN" {
        print(concat_many(prefix, "RETURN"));
        h v = arr_get(ast, 1);
        if v == "null" {
            print(concat_many(prefix, "  (no value)"));
        } else {
            print_ast(v, indent + 1);
        }
        return 0;
    }
    if tag == "PRINT" {
        print(concat_many(prefix, "PRINT"));
        print_ast(arr_get(ast, 1), indent + 1);
        return 0;
    }
    if tag == "IF" {
        print(concat_many(prefix, "IF"));
        print_ast(arr_get(ast, 1), indent + 1);
        print(concat_many(prefix, "  then:"));
        h tb = arr_get(ast, 2);
        h ti = 0;
        while ti < arr_len(tb) {
            print_ast(arr_get(tb, ti), indent + 2);
            ti = ti + 1;
        }
        h eb = arr_get(ast, 3);
        if arr_len(eb) > 0 {
            print(concat_many(prefix, "  else:"));
            h ei = 0;
            while ei < arr_len(eb) {
                print_ast(arr_get(eb, ei), indent + 2);
                ei = ei + 1;
            }
        }
        return 0;
    }
    if tag == "WHILE" {
        print(concat_many(prefix, "WHILE"));
        print_ast(arr_get(ast, 1), indent + 1);
        print(concat_many(prefix, "  body:"));
        h b = arr_get(ast, 2);
        h bi = 0;
        while bi < arr_len(b) {
            print_ast(arr_get(b, bi), indent + 2);
            bi = bi + 1;
        }
        return 0;
    }
    if tag == "FNDEF" {
        print(concat_many(prefix, "FNDEF ", arr_get(ast, 1)));
        h ps = arr_get(ast, 2);
        h pi = 0;
        while pi < arr_len(ps) {
            print(concat_many(prefix, "  param: ", arr_get(ps, pi)));
            pi = pi + 1;
        }
        print(concat_many(prefix, "  body:"));
        h b = arr_get(ast, 3);
        h bi = 0;
        while bi < arr_len(b) {
            print_ast(arr_get(b, bi), indent + 2);
            bi = bi + 1;
        }
        return 0;
    }
    if tag == "EXPRSTMT" {
        print(concat_many(prefix, "EXPRSTMT"));
        print_ast(arr_get(ast, 1), indent + 1);
        return 0;
    }
    print(concat_many(prefix, "UNKNOWN ", tag));
    return 0;
}

fn arr_equal_flat(a, b) {
