}

fn mini_enc(ast) {
    h out = arr_new(0, 0);
    h tag = arr_get(ast, 0);
    if tag == "NUM" {
        arr_push(out, concat_many("LOAD_INT ", arr_get(ast, 1)));
        return out;
    }
    if tag == "VAR" {
        arr_push(out, concat_many("LOAD_VAR ", arr_get(ast, 1)));
        return out;
    }
    if tag == "BIN" {
        h op = arr_get(ast, 1);
        out = arr_concat_b(out, mini_enc(arr_get(ast, 2)));
        out = arr_concat_b(out, mini_enc(arr_get(ast, 3)));
        if op == "+"  { arr_push(out, "ADD"); }
        if op == "-"  { arr_push(out, "SUB"); }
        if op == "*"  { arr_push(out, "MUL"); }
        if op == "==" { arr_push(out, "EQ"); }
        return out;
    }
    arr_push(out, concat_many("UNKNOWN ", tag));
    return out;
}

