fn test_neuron_dydx() {
    h w = 0.5;
    h b = 0.0;
    h x = dual(2.0, 1.0);   # seed for d/dx
    h z = dual_add(dual_mul(w, x), b);   # w*x + b ; dz/dx = w = 0.5
    h y = dual_sigmoid(z);
    # dy/dz = sigmoid(1)*(1-sigmoid(1)) ≈ 0.196612 ; dy/dx = 0.196612*0.5
    assert_true(approx_eq(dual_d(y), 0.098306, 0.001), "neuron dy/dx");
}

