    h diff = dual_sub(y_hat, y_target);  # 1  ; ddiff/dw = 2
    h L = dual_mul(diff, diff);           # 1  ; dL/dw = 2*1*2 = 4
    assert_true(approx_eq(dual_v(L), 1.0, 0.001), "loss = 1");
    assert_true(approx_eq(dual_d(L), 4.0, 0.001), "dL/dw = 4");
}

