    if pick == 0 { return 55; }
    return 89;
}

fn sample_hard_ood_value() -> int {
    h tier = random_int(0, 99);
    if tier < 10 {
        h pick = random_int(0, 4);
        if pick == 0 { return 1; }
        if pick == 1 { return 2; }
        if pick == 2 { return 3; }
        if pick == 3 { return 5; }
        return 8;
    }
    if tier < 40 {
        h pick = random_int(0, 2);
        if pick == 0 { return 13; }
        if pick == 1 { return 21; }
        return 34;
    }
