# ===========================================================================
# (ii) Sublinear scaling — comparisons per search across growing libraries.
#
# We synthesise sorted arrays of length N over consecutive integers, then
# run M random nearest-key lookups against each. For phi_pi_fib_search
# this should scale roughly as M * log_phi(N) comparisons.
# ===========================================================================

fn build_sorted_n(n) -> array {
    h arr = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(arr, i, i * 2 + 1);   # 1, 3, 5, ..., 2n-1
        i = i + 1;
    }
    return arr;
}

fn measure_avg_compares(arr, n_queries) -> float {
    h n = arr_len(arr);
    h max_target = arr_get(arr, n - 1) + 5;
    phi_pi_fib_reset();
    h k = 0;
    while k < n_queries {
        h target = random_int(0, max_target);
        h _idx = phi_pi_fib_nearest(arr, target);
        k = k + 1;
    }
    h s = phi_pi_fib_stats();
    return to_float(arr_get(s, 1)) / to_float(arr_get(s, 0));
}

