fn aggregate(which) -> array {
    h total_compares = 0;
    h total_coherent_steps = 0;
    h total_steps = 0;
    h q = 0;
    while q < 200 {
        h x = random_int(0, 700);
        h pres = arr_new(3, 0);
        if which == 0 { pres = phi_fold_linear(x); }
        if which == 1 { pres = phi_fold_binary(x); }
        if which == 2 { pres = phi_fold_fibstep(x); }
        total_compares = total_compares + arr_get(pres, 1);
        h probes = arr_get(pres, 2);
        h np = arr_len(probes);
        h pi = 1;
        while pi < np {
            h s = arr_get(probes, pi) - arr_get(probes, pi - 1);
            if s < 0 { s = 0 - s; }
            if is_fibonacci_number(s) == 1 {
                total_coherent_steps = total_coherent_steps + 1;
            }
            total_steps = total_steps + 1;
            pi = pi + 1;
        }
        q = q + 1;
    }
    h out = arr_new(3, 0);
    arr_set(out, 0, total_compares);
    arr_set(out, 1, total_coherent_steps);
    arr_set(out, 2, total_steps);
    return out;
}

