}

# Compare with the ground truth
fn count_hits(picks, truth_set) {
    h hits = 0;
    h k = 0;
    while k < arr_len(picks) {
        h key = concat_many("", arr_get(picks, k));
        if dict_has(truth_set, key) == 1 { hits = hits + 1; }
        k = k + 1;
    }
    return hits;
}

h truth = {};
