# Titanic survival prediction — OMC + pandas + sklearn end-to-end
# =============================================================================
# Real Kaggle classic, 891 passengers, mix of numerical and categorical
# features, missing values everywhere. The full data-science loop in
# 50 lines of OMC.
#
# Pipeline:
#   seaborn.load_dataset("titanic")       — load real CSV with nulls
#   pandas fillna + one-hot                — clean + encode
#   OMC harmonic feature engineering       — fare_attractor, age_group
#   sklearn train/test split + RF          — fit + predict
#   accuracy + confusion matrix            — report
#
# Run:
#   ./target/release/omnimcode-standalone examples/datascience/titanic.omc
# =============================================================================

import "examples/lib/pd.omc" as pd;
import "examples/lib/sklearn.omc" as sk;
import "examples/lib/np.omc" as np;

println("=== Titanic survival prediction ===");
println("");

# ---- 1. Load via seaborn ---------------------------------------------------

h sns = py_import("seaborn");
h df = py_call(sns, "load_dataset", ["titanic"]);
println(concat_many("loaded ", pd.nrows(df), " passengers, ",
    pd.ncols(df), " columns"));

# ---- 2. Clean: fill missing ages with the median, drop other-null rows ---

h ages_full = pd.col(df, "age");
# numpy's nanmedian skips NaN entries (the form pandas-nulls take
# after py_to_omc conversion). Avoids a manual filter loop.
h age_median = np.nanmedian(ages_full);
println(concat_many("median age (after skipping nulls): ", age_median));

h df1 = pd.fillna_col(df, "age", age_median);
h df2 = pd.fillna_col(df1, "fare", 0.0);

# ---- 3. Harmonic feature engineering --------------------------------------
# Two new features:
#   age_attractor  — fold(age) snaps each passenger to a Fibonacci age
#                    cohort (8/13/21/34/55). Captures "natural age band"
#                    independent of the raw value.
#   fare_class     — fold(fare * 10) buckets fares onto attractors
#                    (cheap third-class fares cluster on 8-21 attractors;
#                    expensive cabins on 144-377).
#
# Both are computed by OMC fns called from Python via apply_omc — the
# Python ↔ OMC bridge running ON the pandas DataFrame.

fn age_attractor(age) {
    return fold(to_int(age));
}
fn fare_class(fare) {
    return fold(to_int(fare * 10));
}

h t0 = now_ms();
h age_attr = pd.apply_omc(df2, "age", "age_attractor");
h fare_attr = pd.apply_omc(df2, "fare", "fare_class");
h t1 = now_ms();
println(concat_many("computed harmonic features for ", arr_len(age_attr),
    " rows in ", t1 - t0, " ms (Python apply, OMC callbacks)"));

# ---- 4. Build feature matrix ----------------------------------------------
# Columns: pclass, sex_male (0/1), age, fare, sibsp, parch, age_attr, fare_attr

h pclass = pd.col(df2, "pclass");
h sex    = pd.col(df2, "sex");
h age    = pd.col(df2, "age");
h fare   = pd.col(df2, "fare");
h sibsp  = pd.col(df2, "sibsp");
h parch  = pd.col(df2, "parch");
h y      = pd.col(df2, "survived");

# Encode sex as 0/1.
fn sex_to_int(s) {
    if s == "male" { return 1; }
    return 0;
}
h sex_enc = arr_map(sex, sex_to_int);

# Stitch into per-row feature vectors.
fn build_X(includes_harmonic) {
    h n = arr_len(pclass);
    h X = [];
    h i = 0;
    while i < n {
        h row = [
            arr_get(pclass, i),
            arr_get(sex_enc, i),
            arr_get(age, i),
            arr_get(fare, i),
            arr_get(sibsp, i),
            arr_get(parch, i)
        ];
        if includes_harmonic == 1 {
            row = arr_concat(row, [arr_get(age_attr, i), arr_get(fare_attr, i)]);
        }
        arr_push(X, row);
        i = i + 1;
    }
    return X;
}

h X_base = build_X(0);
h X_aug  = build_X(1);
println(concat_many("feature matrix: ", arr_len(X_base), " rows, ",
    arr_len(arr_get(X_base, 0)), " base features, ",
    arr_len(arr_get(X_aug, 0)), " with harmonic"));
println("");

# ---- 5. Train + evaluate baseline vs harmonic-augmented -------------------

fn run_model(X, y, label) {
    h split = sk.train_test_split(X, y, 0.3);
    h X_train = arr_get(split, 0);
    h X_test  = arr_get(split, 1);
    h y_train = arr_get(split, 2);
    h y_test  = arr_get(split, 3);

    h model = sk.random_forest_classifier(100);
    sk.fit(model, X_train, y_train);
    h preds = sk.predict(model, X_test);
    h acc = sk.accuracy_score(y_test, preds);
    println(concat_many("  ", label, ":  accuracy = ", acc));
    return acc;
}

println("=== Random Forest results ===");
h acc_base = run_model(X_base, y, "baseline (6 features)        ");
h acc_aug  = run_model(X_aug,  y, "with harmonic feats (8)      ");
println("");

h delta = acc_aug - acc_base;
h verdict = "tie";
if delta > 0 { verdict = "harmonic helps"; }
if delta < 0 { verdict = "harmonic hurts"; }
println(concat_many("delta: ", delta, "   (", verdict, ")"));

println("");
println("=== Done ===");

# agent_swarm.omc — Parallel agent swarm for recursive self-improvement
#
# Architecture:
#   - Orchestrator decomposes a goal into N sub-tasks
#   - Swarm of worker agents processes tasks in parallel (batch_llm_call)
#   - Results are aggregated and synthesized
#   - Output is evaluated, lowest-scoring results are revised
#   - Loop repeats for multiple rounds
#
# Requires: ANTHROPIC_API_KEY or LLM_PROVIDER=anthropic

print("=== OMC Agent Swarm: Recursive Self-Improvement ===")
print("")

# ── Configuration ─────────────────────────────────────────────────────────────

h MODEL = "claude-3-5-haiku-20241022"
h SWARM_SIZE = 4
h ROUNDS = 2

# ── Orchestrator: decompose goal into tasks ───────────────────────────────────

fn decompose_goal(goal, n, model) {
    h prompt = str_format(
        "Break this goal into exactly {n} parallel independent sub-tasks. Each task should be completable in one LLM call.\n\nGoal: {goal}\n\nRespond with JSON: {{\"tasks\": [\"task1\", \"task2\", ...]}}",
        {goal: goal, n: to_str(n)}
    )
    h raw = llm_call(prompt, model)
    h parsed = json_extract(raw)
    if parsed == null {
        return arr_fill(goal, n)
    }
    h tasks = parsed["tasks"]
    if tasks == null { return arr_fill(goal, n) }
    return tasks
}

# ── Worker: execute a single task ─────────────────────────────────────────────

fn worker_execute(task, context, model) {
    h prompt = str_concat("Your task: ", task, "\n\nProvide a detailed, concrete response.")
    if str_len(context) > 0 {
        prompt = str_format(
            "Context:\n{ctx}\n\nYour task: {task}\n\nProvide a detailed, concrete response.",
            {ctx: context, task: task}
        )
    }
    return prompt
}

# ── Evaluator: score outputs ───────────────────────────────────────────────────

fn evaluate_output(task, output, model) {
    h prompt = str_format(
        "Rate this output for the task (0-10). Be strict.\n\nTask: {task}\n\nOutput: {out}\n\nRespond with JSON: {{\"score\": N, \"issues\": [\"...\"]}}",
        {task: task, out: str_slice(output, 0, 300)}
    )
    h raw = llm_call(prompt, model)
    h parsed = json_extract(raw)
    if parsed == null { return {score: 5, issues: []} }
    return parsed
}

# ── Synthesizer: combine all outputs ─────────────────────────────────────────

fn synthesize_outputs(goal, tasks, outputs, model) {
    h parts = []
    h i = 0
    while i < arr_len(tasks) {
        arr_push(parts, str_format("TASK {n}: {t}\nOUTPUT: {o}", {
            n: to_str(i + 1),
            t: tasks[i],
            o: outputs[i]
        }))
        i = i + 1
    }
    h combined = arr_join(parts, "\n\n---\n\n")
    h prompt = str_format(
        "Goal: {goal}\n\nYou have {n} completed sub-tasks:\n\n{combined}\n\nSynthesize all outputs into a coherent final result:",
        {goal: goal, n: to_str(arr_len(tasks)), combined: combined}
    )
    return llm_call(prompt, model)
}

# ── Repair: fix low-scoring outputs ──────────────────────────────────────────

fn repair_output(task, output, issues, model) {
    h issues_text = arr_join(issues, "\n- ")
    h prompt = str_format(
        "Fix this output addressing the issues.\n\nTask: {task}\n\nCurrent output: {out}\n\nIssues:\n- {issues}\n\nFixed output:",
        {task: task, out: output, issues: issues_text}
    )
    return llm_call(prompt, model)
}

# ── Main Swarm Loop ───────────────────────────────────────────────────────────

fn run_swarm(goal, swarm_size, rounds, model) {
    print(str_concat("Goal: ", goal))
    print(str_concat("Swarm size: ", to_str(swarm_size), " workers, ", to_str(rounds), " rounds"))
    print("")

    # Decompose
    print("Phase 1: Decomposing goal into sub-tasks...")
    h tasks = decompose_goal(goal, swarm_size, model)
    print(str_concat("  Created ", to_str(arr_len(tasks)), " tasks"))
    h i = 0
    while i < arr_len(tasks) {
        print(str_concat("  [", to_str(i + 1), "] ", str_slice(tasks[i], 0, 70)))
        i = i + 1
    }
    print("")

    # Round loop
    h outputs = arr_fill("", swarm_size)
    h round = 0
    while round < rounds {
        print(str_concat("Phase 2.", to_str(round + 1), ": Parallel execution (swarm)..."))

        # Build prompts for all workers
        h context = if round == 0 { "" } else {
            str_concat("Previous round context: ", str_slice(arr_join(outputs, " | "), 0, 200))
        }
        h prompts = par_map(tasks, fn(task) {
            return worker_execute(task, context, model)
        })

        # Run all workers in parallel
        h new_outputs = batch_llm_call(prompts, model)
        outputs = new_outputs

        print(str_concat("  Got ", to_str(arr_len(outputs)), " outputs"))

        if round < rounds - 1 {
            # Evaluate and repair low-scoring outputs
            print("Phase 3: Evaluating and repairing...")
            h eval_prompts = []
            h j = 0
            while j < arr_len(tasks) {
                arr_push(eval_prompts, str_format(
                    "Rate (0-10) and list issues. Task: {t}\nOutput: {o}\nJSON: {{\"score\":N,\"issues\":[]}}",
                    {t: tasks[j], o: str_slice(outputs[j], 0, 200)}
                ))
                j = j + 1
            }
            h eval_raws = batch_llm_call(eval_prompts, model)
            h evals = par_map(eval_raws, fn(raw) {
                h j = json_extract(raw)
                if j != null { return j }
                return {score: 7, issues: []}
            })

            h repair_prompts = []
            h k = 0
            while k < arr_len(tasks) {
                h ev = evals[k]
                h score = to_float(to_str(ev["score"]))
                if score < 6.0 {
                    h issues = ev["issues"]
                    h issues_text = if issues != null { arr_join(issues, "; ") } else { "Needs improvement" }
                    arr_push(repair_prompts, {
                        idx: k,
                        prompt: str_format(
                            "Fix this output.\nTask: {t}\nOutput: {o}\nIssues: {i}\nFixed:",
                            {t: tasks[k], o: str_slice(outputs[k], 0, 200), i: issues_text}
                        )
                    })
                    print(str_concat("  Repairing task ", to_str(k + 1), " (score=", to_str(score), ")"))
                }
                k = k + 1
            }

            if arr_len(repair_prompts) > 0 {
                h repair_ps = par_map(repair_prompts, fn(r) { return r["prompt"] })
                h repaired = batch_llm_call(repair_ps, model)
                h m = 0
                while m < arr_len(repair_prompts) {
                    h idx = repair_prompts[m]["idx"]
                    outputs[idx] = repaired[m]
                    m = m + 1
                }
            }
        }
        round = round + 1
    }

    # Synthesize
    print("")
    print("Phase 4: Synthesizing final result...")
    h final = synthesize_outputs(goal, tasks, outputs, model)
    print("Done!")
    return {
        final: final,
        tasks: tasks,
        outputs: outputs
    }
}

# ── Run the swarm ─────────────────────────────────────────────────────────────

h goal = "Design a complete OMC program that implements a self-improving code optimizer"

h result = run_swarm(goal, SWARM_SIZE, ROUNDS, MODEL)

print("")
print("=== FINAL SYNTHESIZED RESULT ===")
print(result["final"])

# auto_improve_daemon.omc
# Continuous 24/7 self-improvement daemon.
# Cycles through OMC programs in a directory, improves each, saves results,
# and tracks improvement history. Run with OMC_DAEMON=1 for continuous mode.

import "examples/lib/llm.omc"
import "examples/lib/cache.omc"

h MODEL = "claude-opus-4-5"
h IMPROVE_DIR = "examples/demos"
h LOG_FILE = "/tmp/omc_daemon.log"
h IMPROVEMENT_CACHE = lru_new(50)

# ── Logging ──────────────────────────────────────────────────────────────────

fn log(msg) {
    h ts = unix_time()
    h line = str_concat("[", to_str(ts), "] ", msg, "\n")
    file_append(LOG_FILE, line)
    print(msg)
}

# ── Code quality scoring ─────────────────────────────────────────────────────

fn score_code(code) {
    h lines = str_split(code, "\n")
    h line_count = arr_len(lines)
    h fn_count = 0
    h comment_count = 0
    h error_handling = 0
    h i = 0
    while i < line_count {
        h line = str_trim(lines[i])
        if str_starts_with(line, "fn ") { fn_count = fn_count + 1 }
        if str_starts_with(line, "#") { comment_count = comment_count + 1 }
        if str_contains(line, "error(") { error_handling = error_handling + 1 }
        i = i + 1
    }
    h score = 0.0
    if line_count > 0 { score = fn_count * 10.0 + comment_count * 2.0 + error_handling * 5.0 }
    return {
        score: score,
        lines: line_count,
        functions: fn_count,
        comments: comment_count,
        error_handling: error_handling
    }
}

# ── Improvement proposal generation ──────────────────────────────────────────

fn propose_improvement(code, history) {
    h hist_summary = ""
    if arr_len(history) > 0 {
        h last = history[arr_len(history) - 1]
        hist_summary = str_concat(
            "\nPrevious improvement round score: ", to_str(last["score"]),
            "\nPrevious issues fixed: ", to_str(last["issues"])
        )
    }
    h prompt = str_concat(
        "Analyze this OMC code and propose ONE specific improvement:\n\n",
        code, "\n",
        hist_summary, "\n",
        "Respond with JSON: {\"issue\": \"description\", \"fix\": \"what to do\"}"
    )
    h response = llm_call(prompt, MODEL, "Respond with valid JSON only, no markdown.")
    h parsed = json_parse(response)
    if parsed == null {
        return {issue: "unknown", fix: "improve overall quality"}
    }
    return parsed
}

fn apply_improvement(code, proposal) {
    h sys = "You write OMC code. Return ONLY the corrected code, no explanation, no markdown."
    h prompt = str_concat(
        "Apply this improvement to the OMC code:\n\n",
        "Issue: ", proposal["issue"], "\n",
        "Fix: ", proposal["fix"], "\n\n",
        "Code:\n", code, "\n\n",
        "Return only the improved code."
    )
    h result = llm_call(prompt, MODEL, sys)
    if str_contains(result, "```") {
        h parts = str_split(result, "```")
        if arr_len(parts) >= 3 { return str_trim(parts[1]) }
    }
    return str_trim(result)
}

# ── Per-file improvement cycle ────────────────────────────────────────────────

fn improve_file(path, rounds) {
    h code = file_read(path)
    if code == null {
        log(str_concat("  SKIP: cannot read ", path))
        return null
    }

    log(str_concat("  File: ", path, " (", to_str(str_len(code)), " bytes)"))

    h cache_key = str_concat(path, "|", to_str(str_len(code)))
    h cached = lru_get(IMPROVEMENT_CACHE, cache_key)
    if cached != null {
        log("  Cache hit — skipping")
        return cached
    }

    h initial_score = score_code(code)
    log(str_concat("  Initial score: ", to_str(initial_score["score"])))

    h current = code
    h history = []
    h r = 0
    while r < rounds {
        h proposal = propose_improvement(current, history)
        log(str_concat("  Round ", to_str(r + 1), ": ", proposal["issue"]))

        h improved = apply_improvement(current, proposal)
        h new_score = score_code(improved)

        arr_push(history, {
            round: r + 1,
            issue: proposal["issue"],
            score: new_score["score"],
            issues: 1
        })

        if new_score["score"] >= initial_score["score"] {
            current = improved
        }
        r = r + 1
    }

    h final_score = score_code(current)
    h improvement = final_score["score"] - initial_score["score"]
    log(str_concat("  Final score: ", to_str(final_score["score"]), " (delta: +", to_str(improvement), ")"))

    h result = {
        path: path,
        original: code,
        improved: current,
        initial_score: initial_score,
        final_score: final_score,
        improvement: improvement,
        history: history
    }

    lru_put(IMPROVEMENT_CACHE, cache_key, result)

    if improvement > 0 {
        h backup = str_concat(path, ".bak")
        file_write(backup, code)
        log(str_concat("  Saved backup to ", backup))
    }

    return result
}

# ── Daemon loop ───────────────────────────────────────────────────────────────

fn daemon_cycle(files, rounds_per_file, continuous) {
    h iteration = 0
    h keep_running = true

    while keep_running {
        iteration = iteration + 1
        log(str_concat("=== Daemon Cycle ", to_str(iteration), " ==="))

        h results = []
        h fi = 0
        while fi < arr_len(files) {
            h result = improve_file(files[fi], rounds_per_file)
            if result != null {
                arr_push(results, result)
            }
            fi = fi + 1
        }

        # Summary
        h total_improvement = 0.0
        h ri = 0
        while ri < arr_len(results) {
            total_improvement = total_improvement + results[ri]["improvement"]
            ri = ri + 1
        }
        log(str_concat("  Cycle ", to_str(iteration), " complete. Total improvement delta: ", to_str(total_improvement)))

        if not continuous { keep_running = false }
    }

    return {iterations: iteration}
}

# ── Main ──────────────────────────────────────────────────────────────────────

