# Harmonic SGD A/B — substrate-modulated gradient steps vs vanilla SGD.
#
# Hypothesis: gradients whose magnitude lands near a Fibonacci attractor
# represent substrate-coherent direction; amplifying their step (and
# damping off-attractor ones) speeds convergence and/or improves final
# loss. The architectural rule from today (substrate metric on
# integer-aggregated quantities) is honored: we hash + quantize the
# gradient magnitude to an integer before applying attractor_distance,
# we don't apply substrate to raw float activations.
#
# Setup: train the same tiny LM (bigram next-char prediction on
# "abcabc...") 3 times with different RNG seeds. Each seed runs
# both vanilla SGD and harmonic SGD; compare final loss.
#
# Stop condition: either harmonic wins on majority of seeds (≥2/3 lower
# final loss → log + celebrate), OR it loses cleanly (≥2/3 higher loss
# → fail-forward writeup explaining what we learned).

import "examples/lib/prometheus.omc";

fn make_corpus() {
    h chars = ["a", "b", "c"];
    h text = "abcabcabcabcabcabcabcabcabc";
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        h idx = 0;
        if ch == "a" { idx = 0; }
        elif ch == "b" { idx = 1; }
        elif ch == "c" { idx = 2; }
        arr_push(ids, idx);
        i = i + 1;
    }
    h corpus = dict_new();
    dict_set(corpus, "vocab", 3);
    dict_set(corpus, "ids", ids);
    return corpus;
}

fn build_model(vocab, hidden, rng_state) {
    h L1 = prom_linear_new(vocab, hidden, rng_state);
    h L2 = prom_linear_new(hidden, vocab, dict_get(L1, "rng_state"));
    h model = dict_new();
    dict_set(model, "L1", L1);
    dict_set(model, "L2", L2);
    return model;
}

fn forward(model, x_id) {
    h L1 = dict_get(model, "L1");
    h L2 = dict_get(model, "L2");
    h h_pre = prom_linear_forward(L1, x_id);
    h h_post = prom_relu(h_pre);
    h logits = prom_linear_forward(L2, h_post);
    return logits;
}

# Returns final-loss-average over last 20 steps (smoother signal than
# the noisy single-step final value).
fn train_run(seed, optimizer_kind, alpha) {
    h corpus = make_corpus();
    h vocab = dict_get(corpus, "vocab");
    h ids = dict_get(corpus, "ids");
    h n_pairs = arr_len(ids) - 1;

    tape_reset();
    h model = build_model(vocab, 8, seed);
    h params = prom_collect_params([dict_get(model, "L1"), dict_get(model, "L2")]);

    h lr = 0.05;
    h steps = 200;
    h tail_losses = [];
    h step = 0;
    while step < steps {
        h k = step % n_pairs;
        h x = prom_one_hot(arr_get(ids, k), vocab);
        h target = prom_one_hot(arr_get(ids, k + 1), vocab);
        h pred = forward(model, x);
        h loss = prom_mse_loss(pred, target);
        tape_backward(loss);
        if optimizer_kind == "harmonic" {
            prom_harmonic_sgd_step(params, lr, alpha);
        } else {
            prom_sgd_step(params, lr);
        }
        if step >= steps - 20 {
            arr_push(tail_losses, tape_value(loss));
        }
        step = step + 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) {
        sum = sum + arr_get(tail_losses, i);
        i = i + 1;
    }
    return sum / arr_len(tail_losses);
}

fn main() {
    print("=== Harmonic SGD vs Vanilla SGD ===");
    print("3 seeds × 2 optimizers, tinyLM bigram task, 200 steps each");
    print("");

    h seeds = [42, 7, 123];
    h alpha = 0.3;   # harmonic strength: ±30% lr modulation per param

    print(concat_many("harmonic alpha: ", to_string(alpha)));
    print("");

    h vanilla_results = [];
    h harmonic_results = [];
    h s = 0;
    while s < arr_len(seeds) {
        h seed = arr_get(seeds, s);
        h v = train_run(seed, "vanilla", 0.0);
        h hv = train_run(seed, "harmonic", alpha);
        arr_push(vanilla_results, v);
        arr_push(harmonic_results, hv);
        h delta = hv - v;
        h marker = "(harmonic worse)";
        if hv < v { marker = "(harmonic better)"; }
        print(concat_many("seed ", to_string(seed),
            "  vanilla=", to_string(v),
            "  harmonic=", to_string(hv),
            "  delta=", to_string(delta), "  ", marker));
        s = s + 1;
    }
    print("");

    # Tally.
    h v_mean = 0.0;
    h h_mean = 0.0;
    h wins = 0;
    h i = 0;
    while i < arr_len(seeds) {
        v_mean = v_mean + arr_get(vanilla_results, i);
        h_mean = h_mean + arr_get(harmonic_results, i);
        if arr_get(harmonic_results, i) < arr_get(vanilla_results, i) {
            wins = wins + 1;
        }
        i = i + 1;
    }
    v_mean = v_mean / arr_len(seeds);
    h_mean = h_mean / arr_len(seeds);
    print(concat_many("vanilla   mean: ", to_string(v_mean)));
    print(concat_many("harmonic  mean: ", to_string(h_mean)));
    h rel = (h_mean - v_mean) / v_mean * 100.0;
    print(concat_many("harmonic vs vanilla: ", to_string(rel), "%"));
    print(concat_many("harmonic wins: ", to_string(wins), "/", to_string(arr_len(seeds))));

    print("");
    if wins >= 2 {
        print("[WIN] Harmonic SGD beats vanilla on majority of seeds.");
        print("      Substrate-modulated gradients earn their keep on this task.");
        print("      🥂 Champagne uncorked.");
    } elif wins == 0 {
        print("[FAIL-FORWARD] Harmonic loses 0/3.");
        print("               What we learned: substrate modulation of per-param");
        print("               lr based on grad-magnitude→attractor distance does");
        print("               not help on the tinyLM bigram task. Possible reasons:");
        print("                 - signal-to-noise too low at this model scale");
        print("                 - grad magnitudes don't naturally land near attractors");
        print("                 - alpha may need different sign or magnitude");
        print("               Next attempt: alpha sweep, or per-layer modulation.");
    } else {
        print("[INCONCLUSIVE] 1/3 wins — within noise.");
        print("               Need more seeds or larger model to call.");
    }
}

main();

# MH + Q6 compound test (#3 — validates v0.8.8 finding in multi-head setting).
#
# v0.8.5 saw MH at d_model=32 win -0.25% vs SH (single-head). v0.8.8 saw
# Q6 push attention 8.31x toward substrate positions after training. If
# Q6 sculpts attention per-head, the MH+Q6 combo should beat plain MH by
# more than the SH+Q6 combo beat plain SH.
#
# Four arms at d_model=64, n_heads=4, 3 seeds, 400 steps:
#   A. MH off  (substrate-K + S-MOD + V, Q6 off)
#   B. MH+Q6 fused (same + Q6 fused)
#   C. SH off  (single-head, Q6 off) — reference
#   D. SH+Q6 fused — reference

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) { dict_set(seen, ch, arr_len(chars)); arr_push(chars, ch); }
        i = i + 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i = i + 1;
    }
    return ids;
}

fn build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if arm == "SH" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    } elif arm == "SHQ6" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        dict_set(attn, "q6_mode", "fused");
        s2 = dict_get(attn, "rng_state");
    } elif arm == "MH" {
        attn = prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, s2);
        s2 = dict_get(attn, "rng_state");
    } else {  # MHQ6
        attn = prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, s2);
        dict_set(attn, "q6_mode", "fused");
        s2 = dict_get(attn, "rng_state");
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "arm", arm);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(arm, attn, x_id) {
    if arm == "MH" { return prom_attention_substrate_k_mh_forward(attn, x_id); }
    if arm == "MHQ6" { return prom_attention_substrate_k_mh_forward(attn, x_id); }
    return prom_attention_substrate_k_forward(attn, x_id);
}

fn attn_params(arm, attn) {
    if arm == "MH" { return prom_attention_substrate_k_mh_params(attn); }
    if arm == "MHQ6" { return prom_attention_substrate_k_mh_params(attn); }
    return prom_attention_substrate_k_params(attn);
}

fn forward_window(model, token_ids, pe_table) {
    h arm = dict_get(model, "arm");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) { arr_push(pe_rows, arr_get(pe_table, i)); i = i + 1; }
    x = tape_add(x, tape_const(pe_rows));
    h attn_out = attn_forward(arm, dict_get(model, "attn"), x);
    h x_post = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post);
    h up = prom_linear_forward(dict_get(model, "ff_up"), n1);
    h down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    h x_ff = tape_add(x_post, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h arm = dict_get(model, "arm");
    h attn_p = attn_params(arm, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i = i + 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i = i + 1; }
    return out;
}

fn train(arm, vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed) {
    tape_reset();
    h model = build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k = k + 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 30 { arr_push(tail, tape_value(loss)); }
        step = step + 1;
    }
    h s = 0.0; h i = 0;
    while i < arr_len(tail) { s = s + arr_get(tail, i); i = i + 1; }
    return s / arr_len(tail);
}

fn mean_arr(xs) {
    h s = 0.0; h i = 0;
    while i < arr_len(xs) { s = s + arr_get(xs, i); i = i + 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== MH+Q6 compound test (#3) ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver beneath the stars";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h n_heads = 4;
    h lr = 0.005;
    h steps = 250;
    h seeds = [42, 7, 123];

    print(concat_many("d_model=", to_string(d_model),
        "  n_heads=", to_string(n_heads),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("");

    h arms = ["SH", "SHQ6", "MH", "MHQ6"];
    h labels = dict_new();
    dict_set(labels, "SH",   "SH         ");
    dict_set(labels, "SHQ6", "SH + Q6    ");
    dict_set(labels, "MH",   "MH (4h)    ");
    dict_set(labels, "MHQ6", "MH (4h) + Q6");

    h results = dict_new();
    h ai = 0;
    while ai < arr_len(arms) {
        h arm = arr_get(arms, ai);
        h losses = [];
        h si = 0;
        while si < arr_len(seeds) {
            h seed = arr_get(seeds, si);
            h L = train(arm, vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed);
            arr_push(losses, L);
            si = si + 1;
        }
        dict_set(results, arm, losses);
        h mu = mean_arr(losses);
        print(concat_many(dict_get(labels, arm), "  mean=", to_string(mu)));
        ai = ai + 1;
    }

    print("");
    print("=== compound analysis ===");
    h sh_mu = mean_arr(dict_get(results, "SH"));
    h shq6_mu = mean_arr(dict_get(results, "SHQ6"));
    h mh_mu = mean_arr(dict_get(results, "MH"));
    h mhq6_mu = mean_arr(dict_get(results, "MHQ6"));
    print(concat_many("SH→SHQ6  Δ=", to_string(shq6_mu - sh_mu),
        " (", to_string((shq6_mu - sh_mu) / sh_mu * 100.0), "%)"));
    print(concat_many("MH→MHQ6  Δ=", to_string(mhq6_mu - mh_mu),
        " (", to_string((mhq6_mu - mh_mu) / mh_mu * 100.0), "%)"));
    print(concat_many("SH→MH    Δ=", to_string(mh_mu - sh_mu),
        " (", to_string((mh_mu - sh_mu) / sh_mu * 100.0), "%)"));
    print(concat_many("SH→MHQ6  Δ=", to_string(mhq6_mu - sh_mu),
        " (", to_string((mhq6_mu - sh_mu) / sh_mu * 100.0), "%) ← compound"));
}

main();

# Multi-head substrate-K cross-validation (task #5 / item v0.8.5 #5).
# PyTorch's L1-MH (-8.94%) and Q6-MH (-12.15%) findings need multi-head
# capacity. Single-head OMC saw ~-2.47% / -0.28%; MH should narrow that.
#
# Compares: single-head L1+SMOD+V vs multi-head L1+SMOD+V (n_heads=4)
# at d_model=32. 3 seeds, 400 steps.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i = i + 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i = i + 1;
    }
    return ids;
}

fn build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = null;
    h s2 = s1 + 11;
    if arm == "SH" {
        attn = prom_attention_substrate_k_new(d_model, seq_len, s2);
        s2 = dict_get(attn, "rng_state");
    } else {
        attn = prom_attention_substrate_k_mh_new(d_model, seq_len, n_heads, s2);
        s2 = dict_get(attn, "rng_state");
    }
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "arm", arm);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn attn_forward(arm, attn, x_id) {
    if arm == "SH" { return prom_attention_substrate_k_forward(attn, x_id); }
    return prom_attention_substrate_k_mh_forward(attn, x_id);
}

fn attn_params(arm, attn) {
    if arm == "SH" { return prom_attention_substrate_k_params(attn); }
    return prom_attention_substrate_k_mh_params(attn);
}

fn forward_window(model, token_ids, pe_table) {
    h arm = dict_get(model, "arm");
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i = i + 1;
    }
    x = tape_add(x, tape_const(pe_rows));
    h attn_out = attn_forward(arm, dict_get(model, "attn"), x);
    h x_post = tape_add(x, attn_out);
    h n1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post);
    h up = prom_linear_forward(dict_get(model, "ff_up"), n1);
    h down = prom_linear_forward(dict_get(model, "ff_down"), prom_relu(up));
    h x_ff = tape_add(x_post, down);
    h n2 = prom_layernorm_forward(dict_get(model, "ln2"), x_ff);
    return prom_linear_forward(dict_get(model, "head"), n2);
}

fn collect_all(model) {
    h arm = dict_get(model, "arm");
    h attn_p = attn_params(arm, dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i = i + 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i = i + 1; }
    return out;
}

fn train(arm, vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed) {
    tape_reset();
    h model = build_model(arm, vocab_size, d_model, ff_dim, seq_len, n_heads, seed);
    h params = collect_all(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;
    h tail = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k = k + 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 30 { arr_push(tail, tape_value(loss)); }
        step = step + 1;
    }
    h s = 0.0;
    h i = 0;
    while i < arr_len(tail) { s = s + arr_get(tail, i); i = i + 1; }
    return s / arr_len(tail);
}

fn mean_arr(xs) {
    h s = 0.0;
    h i = 0;
    while i < arr_len(xs) { s = s + arr_get(xs, i); i = i + 1; }
    return s / arr_len(xs);
}

fn main() {
    print("=== multi-head substrate-K cross-validation (#5) ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver beneath the stars while waves crash against rocky shores carrying secrets older than time itself across the deep blue ocean toward the horizon where dreams meet reality";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 16;
    h d_model = 32;
    h ff_dim = 64;
    h n_heads = 4;
    h lr = 0.005;
    h steps = 400;
    h seeds = [42, 7, 123];

    print(concat_many("d_model=", to_string(d_model),
        "  n_heads=", to_string(n_heads),
        "  d_head=", to_string(d_model / n_heads),
        "  steps=", to_string(steps),
        "  seeds=", to_string(arr_len(seeds))));
    print("");

    h sh_losses = [];
    h mh_losses = [];
    h si = 0;
    while si < arr_len(seeds) {
        h seed = arr_get(seeds, si);
        h SH = train("SH", vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed);
        h MH = train("MH", vocab_size, ids, seq_len, d_model, ff_dim, n_heads, lr, steps, seed);
        arr_push(sh_losses, SH);
        arr_push(mh_losses, MH);
        h marker = "SH wins";
        if MH < SH { marker = "MH wins"; }
        print(concat_many("seed=", to_string(seed),
            "  SH=", to_string(SH),
            "  MH=", to_string(MH),
            "  Δ=", to_string(MH - SH), "  ", marker));
        si = si + 1;
    }

    print("");
    h SH_mean = mean_arr(sh_losses);
    h MH_mean = mean_arr(mh_losses);
    h delta = MH_mean - SH_mean;
    h pct = (delta / SH_mean) * 100.0;
    h wins = 0;
    si = 0;
    while si < arr_len(seeds) {
        if arr_get(mh_losses, si) < arr_get(sh_losses, si) { wins = wins + 1; }
        si = si + 1;
    }
    print(concat_many("SH (1 head)   mean=", to_string(SH_mean)));
    print(concat_many("MH (", to_string(n_heads), " heads) mean=", to_string(MH_mean),
        "   Δ=", to_string(delta), "  (", to_string(pct), "%)",
        "   wins ", to_string(wins), "/", to_string(arr_len(seeds))));
}

main();

# Q6 substrate-modulation A/B in pure-OMC Prometheus.
#
# Trains the substrate-K transformer three ways:
#   "off"      → Q passes through unmodulated (baseline)
#   "composed" → Q6 via tape_abs + tape_log + scalar denom
#   "fused"    → Q6 via tape_phi_log (substrate-native primitive)
#
# Composed and fused are mathematically equivalent (test_q6_modulate.omc
# locks that in at the unit level). The end-to-end training comparison
# answers a different question: does the fused primitive give identical
# results once thousands of forward/backward passes have accumulated, or
# does abstraction cost (allocation patterns, accumulation order) show up
# at training time?
#
# Both Q6 paths compared to "off" also gives an OMC-side cross-validation
# of the PyTorch -12.15% Q6 finding at small scale.

import "examples/lib/prometheus.omc";

fn build_vocab(text) {
    h seen = dict_new();
    h chars = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        if !dict_has(seen, ch) {
            dict_set(seen, ch, arr_len(chars));
            arr_push(chars, ch);
        }
        i = i + 1;
    }
    h v = dict_new();
    dict_set(v, "chars", chars);
    dict_set(v, "lookup", seen);
    return v;
}

fn encode(text, vocab) {
    h lookup = dict_get(vocab, "lookup");
    h ids = [];
    h i = 0;
    while i < str_len(text) {
        h ch = str_slice(text, i, i + 1);
        arr_push(ids, dict_get(lookup, ch));
        i = i + 1;
    }
    return ids;
}

fn build_model(q6_mode, vocab_size, d_model, ff_dim, seq_len, seed) {
    h emb = prom_embedding_new(vocab_size, d_model, seed);
    h s1 = dict_get(emb, "rng_state");
    h attn = prom_attention_substrate_k_new(d_model, seq_len, s1 + 11);
    dict_set(attn, "q6_mode", q6_mode);
    h s2 = dict_get(attn, "rng_state");
    h ln1 = prom_layernorm_new(d_model, s2);
    h ff_up = prom_linear_new(d_model, ff_dim, s2 + 13);
    h s3 = dict_get(ff_up, "rng_state");
    h ff_down = prom_linear_new(ff_dim, d_model, s3);
    h s4 = dict_get(ff_down, "rng_state");
    h ln2 = prom_layernorm_new(d_model, s4);
    h head = prom_linear_new(d_model, vocab_size, s4 + 17);
    h m = dict_new();
    dict_set(m, "q6_mode", q6_mode);
    dict_set(m, "emb", emb);
    dict_set(m, "attn", attn);
    dict_set(m, "ln1", ln1);
    dict_set(m, "ff_up", ff_up);
    dict_set(m, "ff_down", ff_down);
    dict_set(m, "ln2", ln2);
    dict_set(m, "head", head);
    return m;
}

fn forward_window(model, token_ids, pe_table) {
    h x = prom_embedding_batch(dict_get(model, "emb"), token_ids);
    h pe_rows = [];
    h i = 0;
    while i < arr_len(token_ids) {
        arr_push(pe_rows, arr_get(pe_table, i));
        i = i + 1;
    }
    h pe_const = tape_const(pe_rows);
    x = tape_add(x, pe_const);
    h attn_out = prom_attention_substrate_k_forward(dict_get(model, "attn"), x);
    h x_post_attn = tape_add(x, attn_out);
    h normed1 = prom_layernorm_forward(dict_get(model, "ln1"), x_post_attn);
    h up = prom_linear_forward(dict_get(model, "ff_up"), normed1);
    h activated = prom_relu(up);
    h down = prom_linear_forward(dict_get(model, "ff_down"), activated);
    h x_post_ff = tape_add(x_post_attn, down);
    h normed2 = prom_layernorm_forward(dict_get(model, "ln2"), x_post_ff);
    return prom_linear_forward(dict_get(model, "head"), normed2);
}

fn collect_all_params(model) {
    h attn_p = prom_attention_substrate_k_params(dict_get(model, "attn"));
    h other = prom_collect_params_v2([
        dict_get(model, "emb"),
        dict_get(model, "ln1"),
        dict_get(model, "ff_up"),
        dict_get(model, "ff_down"),
        dict_get(model, "ln2"),
        dict_get(model, "head"),
    ]);
    h out = [];
    h i = 0;
    while i < arr_len(attn_p) { arr_push(out, arr_get(attn_p, i)); i = i + 1; }
    i = 0;
    while i < arr_len(other) { arr_push(out, arr_get(other, i)); i = i + 1; }
    return out;
}

fn train_arm(q6_mode, vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed) {
    tape_reset();
    h model = build_model(q6_mode, vocab_size, d_model, ff_dim, seq_len, seed);
    h params = collect_all_params(model);
    h opt = prom_adamw_new(params, lr, 0.9, 0.999, 1e-8, 0.0);
    h pe_table = prom_crt_pe_matrix(seq_len, d_model);
    h n_windows = arr_len(ids) - seq_len - 1;

    h tail_losses = [];
    h step = 0;
    while step < steps {
        h start = step - (step / n_windows) * n_windows;
        h window = [];
        h targets = [];
        h k = 0;
        while k < seq_len {
            arr_push(window, arr_get(ids, start + k));
            arr_push(targets, arr_get(ids, start + k + 1));
            k = k + 1;
        }
        h logits = forward_window(model, window, pe_table);
        h loss = prom_cross_entropy_batch(logits, targets, vocab_size);
        tape_backward(loss);
        prom_adamw_step(opt);
        if step >= steps - 10 { arr_push(tail_losses, tape_value(loss)); }
        step = step + 1;
    }
    h sum = 0.0;
    h i = 0;
    while i < arr_len(tail_losses) { sum = sum + arr_get(tail_losses, i); i = i + 1; }
    return sum / arr_len(tail_losses);
}

fn mean_arr(xs) {
    h sum = 0.0;
    h i = 0;
    while i < arr_len(xs) { sum = sum + arr_get(xs, i); i = i + 1; }
    return sum / arr_len(xs);
}

fn main() {
    print("=== OMC Q6 A/B (off vs composed vs fused) ===");
    h text = "the rain in spain falls mainly on the plain and the sun rises in the east while the moon hides behind the mountain peaks of distant lands where ancient creatures sleep in caves of silver";
    h vocab = build_vocab(text);
    h vocab_size = arr_len(dict_get(vocab, "chars"));
    h ids = encode(text, vocab);
    h seq_len = 6;
    h d_model = 8;
    h ff_dim = 16;
    h lr = 0.01;
    h steps = 80;
    h seeds = [42, 7, 123];

    print(concat_many("vocab: ", to_string(vocab_size),
        "  seq_len: ", to_string(seq_len),
        "  d_model: ", to_string(d_model),
        "  ff: ", to_string(ff_dim),
        "  steps: ", to_string(steps),
        "  seeds: ", to_string(arr_len(seeds))));
    print("");

    h off_losses = [];
    h composed_losses = [];
    h fused_losses = [];

    h s = 0;
    while s < arr_len(seeds) {
        h seed = arr_get(seeds, s);
        print(concat_many("seed=", to_string(seed)));

        h loff = train_arm("off", vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        h lcomp = train_arm("composed", vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);
        h lfus = train_arm("fused", vocab_size, ids, seq_len, d_model, ff_dim, lr, steps, seed);

        print(concat_many("  off=     ", to_string(loff)));
        print(concat_many("  composed=", to_string(lcomp)));
        print(concat_many("  fused=   ", to_string(lfus)));

        arr_push(off_losses, loff);
        arr_push(composed_losses, lcomp);
        arr_push(fused_losses, lfus);
        s = s + 1;
    }

    print("");
    print("=== aggregate ===");
    h moff = mean_arr(off_losses);
    h mcomp = mean_arr(composed_losses);
    h mfus = mean_arr(fused_losses);
    print(concat_many("mean off=     ", to_string(moff)));
    print(concat_many("mean composed=", to_string(mcomp), "   Δ vs off: ", to_string(mcomp - moff)));
    print(concat_many("mean fused=   ", to_string(mfus),  "   Δ vs off: ", to_string(mfus - moff)));
    print(concat_many("composed vs fused divergence: ", to_string(mfus - mcomp)));
    print("");
    print("Interpretation:");
    print("  | composed - fused | small (~1e-6) → fused primitive matches math (expected)");
    print("  Q6 modes vs off → does Q6 help at small scale in OMC?");
    print("  PyTorch-side -12.15% baseline was at multi-head TinyShakespeare; small-scale");
    print("  single-head OMC may show smaller or noisier signal — what we want to confirm");
    print("  is that the fused path doesn't introduce its own training-time divergence.");
}

