fn push(self, v) {
        h xs = dict_get(self, "items");
        arr_push(xs, v);
        return self;
    }

fn pop(self) {
        h xs = dict_get(self, "items");
        h n = arr_len(xs);
        if n == 0 { return null; }
        h v = arr_get(xs, n - 1);
        # No arr_pop builtin; use arr_slice to drop last
        h new = arr_slice(xs, 0, n - 1);
        dict_set(self, "items", new);
        return v;
    }

