fn test_break() {
    h n = 0;
    while n < 100 {
        if n == 5 { break; }
        n += 1;
    }
    assert_eq(n, 5, "broke at 5");
}

fn test_continue() {
    h sum = 0;
    h i = 0;
    while i < 10 {
        i += 1;
        if i == 5 { continue; }
        sum += i;
    }
    # 1+2+3+4+6+7+8+9+10 = 50
    assert_eq(sum, 50, "skipped 5");
}

