fn is_even(n) {
    if n == 0 { return 1; }
    return is_odd(n - 1);
}

fn is_odd(n) {
    if n == 0 { return 0; }
    return is_even(n - 1);
}

fn test_mutual_recursion() {
    assert_eq(is_even(4), 1, "4 is even");
    assert_eq(is_odd(7), 1, "7 is odd");
}

fn make_counter() {
    h count = 0;
    return fn() {
        count += 1;
        return count;
    };
}

fn test_closure_state() {
