fn first_positive(arr) {
    h i = 0;
    while i < arr_len(arr) {
        if arr_get(arr, i) > 0 { return arr_get(arr, i); }
        i += 1;
    }
    return 0 - 1;
}

fn test_early_return() {
    assert_eq(first_positive([0 - 5, 0 - 2, 7, 9]), 7, "found 7");
    assert_eq(first_positive([0 - 5, 0 - 2]), 0 - 1, "none found");
}

