fn _grad_nonzero(g) {
    if type_of(g) == "array" {
        h i = 0;
        while i < arr_len(g) {
            if _grad_nonzero(arr_get(g, i)) { return true; }
            i += 1;
        }
        return false;
    }
    return g != 0.0;
}

