fn test_scalar_square_grad() {
    tape_reset();
    h x = tape_var(3.0);
    h y = tape_mul(x, x);
    tape_backward(y);
    h g = tape_grad(x);
    assert_true(approx_eq(g, 6.0, 0.001), "d(x^2)/dx at 3 = 6");
}

fn test_multi_parameter_grads() {
    tape_reset();
    h a = tape_var(2.0);
    h b = tape_var(5.0);
    h ab = tape_mul(a, b);
    h aa = tape_mul(a, a);
    h y = tape_add(ab, aa);
    tape_backward(y);
    h ga = tape_grad(a);
    h gb = tape_grad(b);
    assert_true(approx_eq(ga, 9.0, 0.001), "df/da = b+2a = 9");
    assert_true(approx_eq(gb, 2.0, 0.001), "df/db = a = 2");
}

fn test_relu_grad_branches() {
    tape_reset();
    h xp = tape_var(2.0);
    h xn = tape_var(0 - 3.0);
    h yp = tape_relu(xp);
    h yn = tape_relu(xn);
    h y = tape_add(yp, yn);
    tape_backward(y);
    assert_true(approx_eq(tape_grad(xp), 1.0, 0.001), "relu' on positive = 1");
    assert_true(approx_eq(tape_grad(xn), 0.0, 0.001), "relu' on negative = 0");
}

fn test_chain_rule() {
    tape_reset();
