fn linear_search(arr, target) {
    h n = arr_len(arr);
    h i = 0;
    while i < n {
        if arr_get(arr, i) == target {
            return i;
        }
        i = i + 1;
    }
    return -1;
}

fn binary_search_omc(arr, target) {
    h lo = 0;
    h hi = arr_len(arr) - 1;
    while lo <= hi {
        h mid = (lo + hi) / 2;
        h v = arr_get(arr, mid);
        if v == target {
            return mid;
        }
        if v < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

