fn list_error_categories(patterns) {
    h seen = {};
    h result = [];
    h i = 0;
    h n = arr_len(patterns);
    while i < n {
        h pat = arr_get(patterns, i);
        h cat = dict_get(pat, "category");
        if dict_has(seen, cat) == false {
            dict_set(seen, cat, 1);
            arr_push(result, cat);
        }
        i = i + 1;
    }
    return result;
}

