fn bsearch(arr, target) {
    h lo = 0
    h hi = arr_len(arr) - 1
    while lo <= hi {
        h mid = (lo + hi) / 2
        if arr[mid] == target { return mid }
        if arr[mid] < target { lo = mid + 1 }
        else { hi = mid - 1 }
    }
    return -1
}

