    }
    h t1 = time_ms();
    h ms = t1 - t0;
    return ms;
}

fn decide_action(pv, pn, hl, al) {
    h flee = hl * (pn + pv);
    h attack = pn * (1 - hl);
    h chase = pv * (1 - pn) * (1 - flee);

    if flee { return 4; }
    if attack { return 3; }
    if chase { return 2; }
    return 1;
}

fn otape_new() {
