fn otape_mse(tape, pred_id, target_id) {
    h pred   = arr_get(dict_get(tape, "vals"), pred_id);
    h target = arr_get(dict_get(tape, "vals"), target_id);
    h loss   = _mat_mse_scalar(pred, target);
    return _otape_push(tape, [[loss]], 5, pred_id, target_id);
}

fn _mat_set_elem(mat, i, j, v) {
    # Set mat[i][j] = v in-place (exploits Rc-shared row references).
    h row = arr_get(mat, i);
    row[j] = v;
}

fn _mat_add_into(dst, src) {
    # dst[i][j] += src[i][j] in-place.
    h rows = arr_len(dst);
    h i = 0;
    while i < rows {
        h dr = arr_get(dst, i);
        h sr = arr_get(src, i);
        h j = 0;
        while j < arr_len(dr) {
            dr[j] = arr_get(dr, j) + arr_get(sr, j);
            j += 1;
        }
        i += 1;
    }
}

fn _mat_zeros_like(m) {
    h out = [];
    h i = 0;
    while i < arr_len(m) {
        h src = arr_get(m, i);
        h row = [];
        h j = 0;
        while j < arr_len(src) { arr_push(row, 0.0); j += 1; }
        arr_push(out, row);
        i += 1;
    }
    return out;
}

fn _mat_zeros(rows, cols) {
    h out = [];
    h i = 0;
    while i < rows {
        h row = [];
        h j = 0;
        while j < cols { arr_push(row, 0.0); j += 1; }
        arr_push(out, row);
        i += 1;
    }
    return out;
}

fn _mat_add(a, b) {
    h out = [];
    h i = 0;
    while i < arr_len(a) {
        h ra = arr_get(a, i);
        h rb = arr_get(b, i);
        h row = [];
        h j = 0;
        while j < arr_len(ra) { arr_push(row, arr_get(ra, j) + arr_get(rb, j)); j += 1; }
        arr_push(out, row);
        i += 1;
    }
    return out;
}

fn _mat_sub(a, b) {
    h out = [];
    h i = 0;
    while i < arr_len(a) {
        h ra = arr_get(a, i);
        h rb = arr_get(b, i);
        h row = [];
        h j = 0;
        while j < arr_len(ra) { arr_push(row, arr_get(ra, j) - arr_get(rb, j)); j += 1; }
        arr_push(out, row);
        i += 1;
    }
    return out;
}

fn _mat_transpose(a) {
    h rows = arr_len(a);
    h cols = arr_len(arr_get(a, 0));
    h out = [];
    h j = 0;
    while j < cols {
        h row = [];
        h i = 0;
        while i < rows { arr_push(row, arr_get(arr_get(a, i), j)); i += 1; }
        arr_push(out, row);
        j += 1;
    }
    return out;
}

fn _mat_scale(a, s) {
    h out = [];
    h i = 0;
    while i < arr_len(a) {
        h ra = arr_get(a, i);
        h row = [];
        h j = 0;
        while j < arr_len(ra) { arr_push(row, arr_get(ra, j) * s); j += 1; }
        arr_push(out, row);
        i += 1;
    }
    return out;
}

fn _tape_uniform(s, bound) {
    h s2 = _tape_lcg(s);
    h f = (s2 - (s2 / 1000000) * 1000000) / 500000.0 - 1.0;
    if f < 0.0 { f = 0.0 - f; }
    h v = f * bound * 2.0 - bound;
    h r = dict_new();
    dict_set(r, "v", v);
    dict_set(r, "s", s2);
    return r;
}

fn _sgd_update(mat, grad, lr) {
    h rows = arr_len(mat);
    h r = 0;
    while r < rows {
        h mr = arr_get(mat, r);
        h gr = arr_get(grad, r);
        h j = 0;
        while j < arr_len(mr) {
            mr[j] = arr_get(mr, j) - lr * arr_get(gr, j);
            j += 1;
        }
        r += 1;
    }
}

