fn merge(left, right) {
    h n_left = arr_len(left);
    h n_right = arr_len(right);
    h result = arr_new(n_left + n_right, 0);
    h i = 0;
    h j = 0;
    h k = 0;
    while i < n_left && j < n_right {
        if arr_get(left, i) <= arr_get(right, j) {
            arr_set(result, k, arr_get(left, i));
            i = i + 1;
        } else {
            arr_set(result, k, arr_get(right, j));
            j = j + 1;
        }
        k = k + 1;
    }
    while i < n_left {
        arr_set(result, k, arr_get(left, i));
        i = i + 1;
        k = k + 1;
    }
    while j < n_right {
        arr_set(result, k, arr_get(right, j));
        j = j + 1;
        k = k + 1;
    }
    return result;
}

fn merge_sort(arr) {
    h n = arr_len(arr);
    if n <= 1 {
        return arr;
    }
    h mid = n / 2;
    h left = arr_new(mid, 0);
    h right = arr_new(n - mid, 0);
    h i = 0;
    while i < mid {
        arr_set(left, i, arr_get(arr, i));
        i = i + 1;
    }
    h j = 0;
    while j < n - mid {
        arr_set(right, j, arr_get(arr, mid + j));
        j = j + 1;
    }
    return merge(merge_sort(left), merge_sort(right));
}

fn bubble_sort(arr) {
    h n = arr_len(arr);
    h i = 0;
    while i < n {
        h j = 0;
        while j < n - i - 1 {
            if arr_get(arr, j) > arr_get(arr, j + 1) {
                h tmp = arr_get(arr, j);
                arr_set(arr, j, arr_get(arr, j + 1));
                arr_set(arr, j + 1, tmp);
            }
            j = j + 1;
        }
        i = i + 1;
    }
    return arr;
}

fn insertion_sort(arr) {
    h n = arr_len(arr);
    h i = 1;
    while i < n {
        h key = arr_get(arr, i);
        h j = i - 1;
        while j >= 0 && arr_get(arr, j) > key {
            arr_set(arr, j + 1, arr_get(arr, j));
            j = j - 1;
        }
        arr_set(arr, j + 1, key);
        i = i + 1;
    }
    return arr;
}

fn partition(arr, lo, hi) {
    h pivot = arr_get(arr, hi);
    h i = lo - 1;
    h j = lo;
    while j < hi {
        if arr_get(arr, j) <= pivot {
            i = i + 1;
            h tmp = arr_get(arr, i);
            arr_set(arr, i, arr_get(arr, j));
            arr_set(arr, j, tmp);
        }
        j = j + 1;
    }
    h tmp2 = arr_get(arr, i + 1);
    arr_set(arr, i + 1, arr_get(arr, hi));
    arr_set(arr, hi, tmp2);
    return i + 1;
}

fn quick_sort_inner(arr, lo, hi) {
    if lo < hi {
        h p = partition(arr, lo, hi);
        quick_sort_inner(arr, lo, p - 1);
        quick_sort_inner(arr, p + 1, hi);
    }
    return arr;
}

fn quick_sort(arr) {
    return quick_sort_inner(arr, 0, arr_len(arr) - 1);
}

fn arr_sum(arr) {
    h acc = 0;
    h i = 0;
    while i < arr_len(arr) {
        acc = acc + arr_get(arr, i);
        i = i + 1;
    }
    return acc;
}

fn arr_product(arr) {
    h acc = 1;
    h i = 0;
    while i < arr_len(arr) {
        acc = acc * arr_get(arr, i);
        i = i + 1;
    }
    return acc;
}

fn arr_reverse(arr) {
    h n = arr_len(arr);
    h result = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(result, i, arr_get(arr, n - 1 - i));
        i = i + 1;
    }
    return result;
}

fn is_prime(n) {
    if n < 2 { return 0; }
    h i = 2;
    while i * i <= n {
        if n % i == 0 { return 0; }
        i = i + 1;
    }
    return 1;
}

fn gcd(a, b) {
    while b != 0 {
        h tmp = b;
        b = a % b;
        a = tmp;
    }
    return a;
}

fn lcm(a, b) {
    return a / gcd(a, b) * b;
}

fn int_pow(base, exp) {
    h result = 1;
    while exp > 0 {
        if exp % 2 == 1 {
            result = result * base;
        }
        base = base * base;
        exp = exp / 2;
    }
    return result;
}

fn arr_find_max(arr) {
    h best = arr_get(arr, 0);
    h i = 1;
    while i < arr_len(arr) {
        if arr_get(arr, i) > best {
            best = arr_get(arr, i);
        }
        i = i + 1;
    }
    return best;
}

fn arr_find_min(arr) {
    h best = arr_get(arr, 0);
    h i = 1;
    while i < arr_len(arr) {
        if arr_get(arr, i) < best {
            best = arr_get(arr, i);
        }
        i = i + 1;
    }
    return best;
}

fn arr_contains(arr, val) {
    h i = 0;
    while i < arr_len(arr) {
        if arr_get(arr, i) == val { return 1; }
        i = i + 1;
    }
    return 0;
}

fn sigmoid(x) {
    return 1.0 / (1.0 + exp(-x));
}

fn arr_mean(arr) {
    h s = 0.0;
    h n = arr_len(arr);
    h i = 0;
    while i < n {
        s = s + arr_get(arr, i);
        i = i + 1;
    }
    return s / to_float(n);
}

fn arr_variance(arr) {
    h m = arr_mean(arr);
    h acc = 0.0;
    h n = arr_len(arr);
    h i = 0;
    while i < n {
        h d = arr_get(arr, i) - m;
        acc = acc + d * d;
        i = i + 1;
    }
    return acc / to_float(n);
}

fn clamp(x, lo, hi) {
    if x < lo { return lo; }
    if x > hi { return hi; }
    return x;
}

fn lerp(a, b, t) {
    return a + (b - a) * t;
}

fn str_repeat(s, n) {
    h result = "";
    h i = 0;
    while i < n {
        result = result + s;
        i = i + 1;
    }
    return result;
}

fn swap_arr(arr, i, j) {
    h tmp = arr_get(arr, i);
    arr_set(arr, i, arr_get(arr, j));
    arr_set(arr, j, tmp);
}

fn arr_range(start, end) {
    h n = end - start;
    h result = arr_new(n, 0);
    h i = 0;
    while i < n {
        arr_set(result, i, start + i);
        i = i + 1;
    }
    return result;
}
